def batch10_final1_meta_text(slug: str, lang: str, *, revised: bool) -> str:
    """Return the independently fixed pre/final1 metadata text for 36 targets."""
    old_period, new_period = BATCH10_FINAL1_META_PERIODS[slug]
    old_prefix, new_prefix = BATCH10_FINAL1_META_PREFIXES[lang]
    return f"{new_prefix if revised else old_prefix}{new_period if revised else old_period} · 2026-07-14"


