for _filename, _repair in FOURTH_PASS_SEMANTIC_REPAIRS.items():
    _contract = CASE_SEMANTIC_CONTRACTS[_filename]
    _fact_ids = tuple(item[0] for item in _contract["timeline"])
    if len(_fact_ids) != len(_repair["timeline"]):
        raise RuntimeError(f"{_filename}: fourth-pass timeline repair length mismatch")
    _contract["timeline"] = tuple(
        (fact_id, *values) for fact_id, values in zip(_fact_ids, _repair["timeline"])
    )
    _dispute_id = _contract["disputes"][0][0]
    _contract["disputes"] = ((
        _dispute_id,
        ("fact", "inference-subject", "official-response", "response-gap", "accountability"),
        *_repair["dispute"],
    ),)

