def card_issues(text_override: str | None = None) -> list[str]:
    text = text_override if text_override is not None else (ROOT / "script.js").read_text(encoding="utf-8")
    issues = []
    if re.search(r"Hong Kong[’']sono|effective relief|aiuto efficace", text, re.I):
        issues.append("homepage card contains a forbidden translation or legal-remedy phrase")
    entries = re.findall(r"\{[^{}]*?url:\s*\"posts/([^\"]+)\"[^{}]*?\}", text, re.S)
    for path in FILES:
        name = path.name
        pattern = re.compile(r"\{[^{}]*?url:\s*\"posts/" + re.escape(name) + r"\"[^{}]*?\}", re.S)
        match = pattern.search(text)
        if not match:
            issues.append(f"script.js: missing card for {name}")
            continue
        card = match.group(0)
        english_title = None
        for lang in LANGS:
            title = re.search(rf"title_{lang}:\s*\"([^\"]*)\"", card)
            excerpt = re.search(rf"excerpt_{lang}:\s*\"([^\"]*)\"", card)
            if not title or not excerpt or not title.group(1).strip() or not excerpt.group(1).strip():
                issues.append(f"script.js: {name} lacks {lang} title or excerpt")
                continue
            if lang == "en":
                english_title = title.group(1).strip()
            elif english_title and title.group(1).strip() == english_title:
                issues.append(f"script.js: {name} {lang} title falls back to English")
            if BANNED.search(title.group(1) + " " + excerpt.group(1)):
                issues.append(f"script.js: {name} {lang} card contains prohibited editorial wording")
            if contains_public_directive(title.group(1) + " " + excerpt.group(1), lang):
                issues.append(f"script.js: {name} {lang} card contains an editorial directive")
            semantic_pattern = CARD_CASE_PATTERNS.get(name)
            if semantic_pattern and not semantic_pattern.search(title.group(1) + " " + excerpt.group(1)):
                issues.append(f"script.js: {name} {lang} card lost its case-specific visible fact chain")
            if name == "liu-xia.html" and re.search(r"\bolder brother\b|\bmale poet\b", title.group(1) + " " + excerpt.group(1), re.I):
                issues.append(f"script.js: {name} {lang} card misstates Liu Xia's gender or Liu Hui relationship")
    return issues


REPORT_CARD_BASELINE_COLUMNS = (
    "batch_tag", "card_index", "slug", "scope", "field",
    "before_value", "after_value", "changed", "integrity_result",
)


def extract_report_cards(text: str) -> tuple[list[dict[str, str]], list[str]]:
    """Extract every literal report-card field in source order.

    Values remain in their JavaScript-literal spelling because the persistent
    ledger captured that exact spelling before the batch.  This function is an
    integrity parser, not a translation-quality oracle.
    """
    cards: list[dict[str, str]] = []
    issues: list[str] = []
    pattern = re.compile(r'\{[^{}]*?url:\s*"posts/([^"]+)"[^{}]*?\}', re.S)
    for match in pattern.finditer(text):
        filename = match.group(1)
        block = match.group(0)
        slug = filename.removesuffix(".html")
        values = {"slug": slug}
        for field in REPORT_CARD_FIELDS[1:]:
            field_match = re.search(rf'{re.escape(field)}:\s*"([^"]*)"', block)
            if field_match is None:
                issues.append(f"script.js: card {slug} lacks literal field {field}")
                values[field] = ""
            else:
                values[field] = field_match.group(1)
        cards.append(values)
    if len(cards) != EXPECTED_FILES:
        issues.append(f"script.js: expected {EXPECTED_FILES} report cards, found {len(cards)}")
    slugs = [card.get("slug", "") for card in cards]
    if len(slugs) != len(set(slugs)):
        issues.append("script.js: report-card slug/URL values are not unique")
    return cards, issues



def batch14_baseline_card_view(
    cards: list[dict[str, str]],
) -> list[dict[str, str]]:
    """The report-card list as every pre-batch14 gate knew it.

    Batch fourteen inserted ten cards at source position 45, which shifts every
    later card's index.  Removing exactly those ten restores the 54-card
    sequence the batch-nine, -ten, -eleven and -twelve baselines were captured
    against, so each of those gates replays its assertions unchanged instead of
    being re-anchored or relaxed.  batch14_release_issues separately proves the
    ten removed cards exist, are contiguous, and are in order, so this view
    cannot hide a missing or reordered batch-14 card.
    """
    return [
        card for card in cards
        if card.get("slug", "") not in BATCH14_NEW_SLUG_SET
    ]

def load_report_card_baseline() -> tuple[list[dict[str, str]], list[str]]:
    if not REPORT_CARD_BASELINE_PATH.exists():
        return [], [f"report-card baseline missing: {REPORT_CARD_BASELINE_PATH}"]
    with REPORT_CARD_BASELINE_PATH.open(encoding="utf-8", newline="") as handle:
        reader = csv.DictReader(handle, delimiter="\t")
        rows = list(reader)
        fields = tuple(reader.fieldnames or ())
    issues: list[str] = []
    if fields != REPORT_CARD_BASELINE_COLUMNS:
        issues.append("report-card baseline columns or column order changed")
        return rows, issues
    payload = "\x1e".join(
        "\x1f".join(
            (row.get("card_index", ""), row.get("slug", ""), row.get("field", ""), row.get("before_value", ""))
        )
        for row in rows
    ).encode("utf-8")
    if sha256_bytes(payload) != REPORT_CARD_PRE_BATCH_SHA256:
        issues.append("report-card baseline pre-batch values were rewritten")
    return rows, issues


def report_card_integrity_issues(
    text_override: str | None = None,
    rows_override: list[dict[str, str]] | None = None,
) -> list[str]:
    """Compare all 54×23 card fields with the pre/post batch-nine ledger."""
    text = text_override if text_override is not None else (ROOT / "script.js").read_text(encoding="utf-8")
    cards, issues = extract_report_cards(text)
    cards = batch14_baseline_card_view(cards)
    if rows_override is None:
        rows, load_issues = load_report_card_baseline()
        issues.extend(load_issues)
    else:
        rows = rows_override
    expected_rows = POST_BATCH9_BASELINE_FILES * len(REPORT_CARD_FIELDS)
    if len(rows) != expected_rows:
        issues.append(f"report-card baseline has {len(rows)} rows, expected {expected_rows}")
    keyed: dict[tuple[int, str], dict[str, str]] = {}
    per_index: dict[int, list[dict[str, str]]] = defaultdict(list)
    for row in rows:
        try:
            index = int(row.get("card_index", ""))
        except ValueError:
            issues.append("report-card baseline contains a non-numeric card index")
            continue
        key = (index, row.get("field", ""))
        if key in keyed:
            issues.append(f"report-card baseline duplicates card {index} field {key[1]}")
        keyed[key] = row
        per_index[index].append(row)
        if row.get("batch_tag") != "reread:batch9":
            issues.append(f"report-card baseline card {index} lacks reread:batch9 tag")
    if set(per_index) != set(range(1, POST_BATCH9_BASELINE_FILES + 1)):
        issues.append("report-card baseline card-index coverage or order changed")
    for index in range(1, min(len(cards), POST_BATCH9_BASELINE_FILES) + 1):
        card = cards[index - 1]
        rows_here = per_index.get(index, [])
        row_slugs = {row.get("slug", "") for row in rows_here}
        if len(row_slugs) != 1:
            issues.append(f"report-card baseline card {index} has inconsistent slug labels")
            continue
        expected_slug = next(iter(row_slugs))
        expected_scope = "target" if expected_slug in BATCH9_TARGET_SLUGS else "non-target"
        if card.get("slug") != expected_slug:
            issues.append(f"script.js: card {index} slug/URL changed from {expected_slug}")
        actual_fields = {row.get("field", "") for row in rows_here}
        if actual_fields != set(REPORT_CARD_FIELDS):
            issues.append(f"report-card baseline card {index} field coverage changed")
        for field in REPORT_CARD_FIELDS:
            row = keyed.get((index, field))
            if row is None:
                continue
            if row.get("scope") != expected_scope:
                issues.append(f"report-card baseline card {index} scope is wrong")
            before = row.get("before_value", "")
            after = row.get("after_value", "")
            changed = before != after
            expected_changed = "YES" if changed else "NO"
            expected_result = "PASS_CHANGED" if changed else "PASS_UNCHANGED"
            if not after:
                issues.append(f"report-card baseline card {index} {field} lacks its post-batch value")
            if row.get("changed") != expected_changed:
                issues.append(f"report-card baseline card {index} {field} has a false changed marker")
            if row.get("integrity_result") != expected_result:
                issues.append(f"report-card baseline card {index} {field} has a false integrity result")
            if (
                card.get(field, "") != after
                and (expected_slug, field) not in FINAL2_CARD_CHANGED_KEYS
                and expected_slug not in BATCH10_TARGET_SLUGS
                and not (expected_slug in BATCH11_CARD_SLUGS and field in BATCH11_CARD_FIELDS)
                and not (
                    expected_slug in BATCH12_CARD_SLUGS
                    and field.startswith(("title_", "excerpt_"))
                )
            ):
                issues.append(f"script.js: card {expected_slug} field {field} differs from the post-batch baseline")
            if expected_scope == "non-target" and before != after:
                issues.append(f"script.js: non-target card {expected_slug} field {field} changed in batch nine")
    return issues


def load_final2_card_delta() -> tuple[list[dict[str, str]], list[str]]:
    if not FINAL2_CARD_DELTA_PATH.exists():
        return [], [f"batch9-final2 card delta missing: {FINAL2_CARD_DELTA_PATH}"]
    with FINAL2_CARD_DELTA_PATH.open(encoding="utf-8", newline="") as handle:
        reader = csv.DictReader(handle, delimiter="\t")
        rows = list(reader)
        fields = tuple(reader.fieldnames or ())
    if fields != REPORT_CARD_BASELINE_COLUMNS:
        return rows, ["batch9-final2 card delta columns or column order changed"]
    return rows, []


def final2_card_delta_issues(
    text_override: str | None = None,
    rows_override: list[dict[str, str]] | None = None,
) -> list[str]:
    """Authenticate and independently replay the 54×23 final1→final2 card delta."""
    text_value = text_override if text_override is not None else (ROOT / "script.js").read_text(encoding="utf-8")
    cards, issues = extract_report_cards(text_value)
    cards = batch14_baseline_card_view(cards)
    if rows_override is None:
        rows, load_issues = load_final2_card_delta()
        issues.extend(load_issues)
    else:
        rows = rows_override
    expected_rows = POST_BATCH9_BASELINE_FILES * len(REPORT_CARD_FIELDS)
    if len(rows) != expected_rows:
        issues.append(f"batch9-final2 card delta has {len(rows)} rows, expected {expected_rows}")
    payload = "\x1e".join(
        "\x1f".join(
            (row.get("card_index", ""), row.get("slug", ""), row.get("field", ""), row.get("before_value", ""))
        )
        for row in rows
    ).encode("utf-8")
    if sha256_bytes(payload) != FINAL2_CARD_PRE_EDIT_SHA256:
        issues.append("batch9-final2 card delta rewrote the authenticated final1 values")
    per_index: dict[int, list[dict[str, str]]] = defaultdict(list)
    keyed: dict[tuple[int, str], dict[str, str]] = {}
    changed_keys: set[tuple[str, str]] = set()
    for row in rows:
        try:
            index = int(row.get("card_index", ""))
        except ValueError:
            issues.append("batch9-final2 card delta contains a non-numeric card index")
            continue
        field = row.get("field", "")
        key = (index, field)
        if key in keyed:
            issues.append(f"batch9-final2 card delta duplicates card {index} field {field}")
        keyed[key] = row
        per_index[index].append(row)
        if row.get("batch_tag") != "reread:batch9-final2":
            issues.append(f"batch9-final2 card delta card {index} has the wrong batch tag")
        before = row.get("before_value", "")
        after = row.get("after_value", "")
        changed = before != after
        if row.get("changed") != ("YES" if changed else "NO"):
            issues.append(f"batch9-final2 card delta card {index} {field} has a false changed marker")
        if row.get("integrity_result") != ("PASS_CHANGED" if changed else "PASS_UNCHANGED"):
            issues.append(f"batch9-final2 card delta card {index} {field} has a false integrity result")
        if changed:
            changed_keys.add((row.get("slug", ""), field))
    if changed_keys != FINAL2_CARD_CHANGED_KEYS:
        issues.append(
            "batch9-final2 card delta must prove exactly the three authorized Hong Kong excerpt changes"
        )
    if set(per_index) != set(range(1, POST_BATCH9_BASELINE_FILES + 1)):
        issues.append("batch9-final2 card delta card-index coverage changed")
    for index in range(1, min(len(cards), POST_BATCH9_BASELINE_FILES) + 1):
        card = cards[index - 1]
        rows_here = per_index.get(index, [])
        if {row.get("field", "") for row in rows_here} != set(REPORT_CARD_FIELDS):
            issues.append(f"batch9-final2 card delta card {index} field coverage changed")
        row_slugs = {row.get("slug", "") for row in rows_here}
        if row_slugs != {card.get("slug", "")}:
            issues.append(f"batch9-final2 card delta card {index} slug/order differs from script.js")
        expected_scope = "target" if card.get("slug", "") == "hong-kong-nsl" else "non-target"
        for field in REPORT_CARD_FIELDS:
            row = keyed.get((index, field))
            if row is None:
                continue
            if row.get("scope", "") != expected_scope:
                issues.append(f"batch9-final2 card delta card {index} has the wrong scope")
            if (
                row.get("after_value", "") != card.get(field, "")
                and card.get("slug", "") not in BATCH10_TARGET_SLUGS
                and not (
                    card.get("slug", "") in BATCH11_CARD_SLUGS
                    and field in BATCH11_CARD_FIELDS
                )
                and not (
                    card.get("slug", "") in BATCH12_CARD_SLUGS
                    and field.startswith(("title_", "excerpt_"))
                )
            ):
                issues.append(f"script.js: final2 card delta differs for {card.get('slug')} field {field}")
            if expected_scope == "non-target" and row.get("before_value", "") != row.get("after_value", ""):
                issues.append(f"script.js: non-target card {card.get('slug')} changed in batch9-final2")
    return issues


