def final1_public_forbidden_issues(
    *,
    page_overrides: dict[str, BeautifulSoup] | None = None,
    script_override: str | None = None,
) -> list[str]:
    """Scan every visible node on the five dossiers and every target card field."""
    issues: list[str] = []
    for filename in sorted(BATCH9_TARGET_FILENAMES):
        slug = filename.removesuffix(".html")
        soup = (page_overrides or {}).get(slug)
        if soup is None:
            soup = BeautifulSoup(
                    batch13_historical_post_text(filename.removesuffix(".html")),
                    "html.parser",
                )
        visible = public_visible_text(soup)
        for label, pattern in FINAL1_PUBLIC_FORBIDDEN_PATTERNS:
            match = pattern.search(visible)
            if match:
                issues.append(f"posts/{filename}: final1 visible {label}: {match.group(0)!r}")
    script_text = script_override if script_override is not None else (ROOT / "script.js").read_text(encoding="utf-8")
    cards, card_parse_issues = extract_report_cards(script_text)
    cards = batch14_baseline_card_view(cards)
    issues.extend(card_parse_issues)
    for card in cards:
        slug = card.get("slug", "")
        if slug not in BATCH9_TARGET_SLUGS:
            continue
        visible = " ".join(card.get(field, "") for field in REPORT_CARD_FIELDS if field not in {"slug", "url"})
        for label, pattern in FINAL1_PUBLIC_FORBIDDEN_PATTERNS:
            match = pattern.search(visible)
            if match:
                issues.append(f"script.js/{slug}: final1 visible {label}: {match.group(0)!r}")
    return issues


