def final2_source_metadata_issues(
    page_overrides: dict[str, BeautifulSoup] | None = None,
) -> list[str]:
    """Freeze source ID/type/date/URL/order for all 30 final2 language columns."""
    issues: list[str] = []
    for slug, expected_digest in FINAL2_SOURCE_METADATA_SHA256.items():
        soup = (page_overrides or {}).get(slug)
        if soup is None:
            soup = BeautifulSoup(batch13_historical_post_text(slug), "html.parser")
        records: list[str] = []
        for lang in LANGS:
            body = body_for(soup, lang)
            if body is None:
                records.append("\x1f".join((lang, "MISSING", "", "", "", "")))
                continue
            for order, source in enumerate(body.select("ul.source-list > li[data-source-id]"), start=1):
                anchor = source.find("a")
                records.append(
                    "\x1f".join(
                        (
                            lang, str(order), source.get("data-source-id", ""),
                            source.get("data-source-type", ""), source.get("data-source-date", ""),
                            anchor.get("href", "") if anchor else "",
                        )
                    )
                )
        if sha256_bytes("\x1e".join(records).encode("utf-8")) != expected_digest:
            issues.append(
                f"batch9-final2 source metadata changed for {slug}: ID/type/date/URL/order must remain byte-equivalent"
            )
    return issues


def final2_precision_issues(
    *,
    page_overrides: dict[str, BeautifulSoup] | None = None,
    script_override: str | None = None,
) -> list[str]:
    """Reject the human-final-review regressions in their exact language nodes."""
    issues: list[str] = []
    soups: dict[str, BeautifulSoup] = {}
    for slug, lang, target_id in FINAL2_NODE_REJECTIONS:
        soup = soups.get(slug) or (page_overrides or {}).get(slug)
        if soup is None:
            soup = BeautifulSoup(batch13_historical_post_text(slug), "html.parser")
        soups[slug] = soup
        body = body_for(soup, lang)
        node = body.select_one(f'[data-fact-id="{target_id}"]') if body else None
        if node is None:
            issues.append(f"batch9-final2 target is missing: {slug}/{lang}/{target_id}")
            continue
        visible = f" {normalize_reread_text(node.get_text(' ', strip=True))} "
        for rejected in FINAL2_NODE_REJECTIONS[(slug, lang, target_id)]:
            if rejected.casefold() in visible.casefold():
                issues.append(
                    f"batch9-final2 rejected wording remains in {slug}/{lang}/{target_id}: {rejected!r}"
                )

    script_value = script_override if script_override is not None else (ROOT / "script.js").read_text(encoding="utf-8")
    cards, parse_issues = extract_report_cards(script_value)
    cards = batch14_baseline_card_view(cards)
    issues.extend(parse_issues)
    hk = next((card for card in cards if card.get("slug") == "hong-kong-nsl"), None)
    if hk is None:
        issues.append("batch9-final2 Hong Kong homepage card is missing")
        return issues
    for lang, required in FINAL2_HK_CARD_REQUIRED.items():
        value = hk.get(f"excerpt_{lang}", "")
        for literal in required:
            if literal not in value:
                issues.append(f"batch9-final2 Hong Kong {lang} card lost required concept {literal!r}")
    if "is also enacted" in hk.get("excerpt_en", ""):
        issues.append("batch9-final2 Hong Kong English card restored the mechanical 'is also enacted'")
    if "is also in force" not in hk.get("excerpt_en", ""):
        issues.append("batch9-final2 Hong Kong English card no longer states that the 2024 ordinance is in force")
    for lang in ("de", "nl"):
        if "Secretary for Justice" in hk.get(f"excerpt_{lang}", ""):
            issues.append(f"batch9-final2 Hong Kong {lang} card falls back to English Secretary for Justice")
    if "Justizminister" not in hk.get("excerpt_de", ""):
        issues.append("batch9-final2 Hong Kong German card lacks a natural Justizminister title")
    if "minister van Justitie" not in hk.get("excerpt_nl", ""):
        issues.append("batch9-final2 Hong Kong Dutch card lacks a natural minister van Justitie title")
    return issues


