def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def exact_tsv_prefix_issues(
    path: Path,
    *,
    base_rows: int,
    expected_sha256: str,
    label: str,
) -> list[str]:
    """Keep the complete pre-final1 TSV history byte-for-byte append-only."""
    if not path.exists():
        return [f"{label} is missing: {path}"]
    lines = path.read_bytes().splitlines(keepends=True)
    required_lines = base_rows + 1
    if len(lines) < required_lines:
        return [f"{label} lost historical rows: found {max(0, len(lines) - 1)}, need at least {base_rows}"]
    prefix = b"".join(lines[:required_lines])
    if sha256_bytes(prefix) != expected_sha256:
        return [f"{label} rewrote or reordered the pre-final1 history"]
    return []


def final1_freeze_issues(
    overrides: dict[str, bytes] | None = None,
) -> list[str]:
    """Enforce the pre-edit hashes, plus the exact path set in the Git worktree.

    The Desktop delivery is intentionally a partial, non-Git mirror: the final1
    brief permits copying only the files changed in this pass.  Its pre-existing
    path set can therefore differ from the repository captured by this baseline.
    In that mirror we still authenticate the baseline and every shared frozen
    file, while exact missing/added-path enforcement remains bound to the source
    Git worktree where the scope claim was made.
    """
    issues: list[str] = []
    if not FINAL1_FREEZE_BASELINE_PATH.exists():
        return [f"final1 freeze baseline is missing: {FINAL1_FREEZE_BASELINE_PATH}"]
    baseline_bytes = FINAL1_FREEZE_BASELINE_PATH.read_bytes()
    if sha256_bytes(baseline_bytes) != FINAL1_FREEZE_BASELINE_SHA256:
        issues.append("final1 freeze baseline itself was changed after the pre-edit capture")
    with FINAL1_FREEZE_BASELINE_PATH.open(encoding="utf-8", newline="") as handle:
        reader = csv.DictReader(handle, delimiter="\t")
        rows = list(reader)
        fields = tuple(reader.fieldnames or ())
    if fields != ("relative_path", "sha256"):
        issues.append("final1 freeze baseline columns or column order changed")
        return issues
    expected: dict[str, str] = {}
    for row in rows:
        relative = row.get("relative_path", "")
        digest = row.get("sha256", "")
        if not relative or relative in expected:
            issues.append(f"final1 freeze baseline has a blank or duplicate path: {relative!r}")
            continue
        if relative in FINAL1_CAPTURE_MUTABLE_FILES or relative == ".git" or relative.startswith(".git/"):
            issues.append(f"final1 freeze baseline improperly includes a mutable or git path: {relative}")
        if not re.fullmatch(r"[0-9a-f]{64}", digest):
            issues.append(f"final1 freeze baseline has an invalid SHA-256 for {relative}")
        expected[relative] = digest
    actual_paths = {
        path.relative_to(ROOT).as_posix()
        for path in ROOT.rglob("*")
        if path.is_file()
        and ".git" not in path.relative_to(ROOT).parts
        and path.relative_to(ROOT).as_posix() not in FINAL1_MUTABLE_FILES
        and path.relative_to(ROOT).as_posix() not in BATCH11_MUTABLE_FILES
        and path.relative_to(ROOT).as_posix() not in BATCH12_SUCCESSOR_FILES
        and path.relative_to(ROOT).as_posix() not in BATCH13_NEW_AUDIT_FILES
        and path.relative_to(ROOT).as_posix() not in BATCH14_NEW_AUDIT_FILES
    }
    expected_paths = (
        set(expected)
        - BATCH10_NEW_OR_MUTABLE_FILES
        - BATCH11_MUTABLE_FILES
        - BATCH12_SUCCESSOR_FILES
        - BATCH13_NEW_AUDIT_FILES
        - BATCH14_NEW_AUDIT_FILES
    )
    if (ROOT / ".git").exists():
        for relative in sorted(expected_paths - actual_paths):
            issues.append(f"final1 frozen file is missing: {relative}")
        for relative in sorted(actual_paths - expected_paths):
            issues.append(f"final1 added a file outside the whitelist: {relative}")
    payloads = {**batch14_historical_page_bytes(), **batch13_historical_page_bytes(), **(overrides or {})}
    for relative in sorted(actual_paths & expected_paths):
        digest = sha256_bytes(
            payloads.get(relative) or (ROOT / relative).read_bytes()
        )
        if digest != expected[relative]:
            issues.append(f"final1 frozen file changed: {relative}")
    return issues


def final2_freeze_issues(
    overrides: dict[str, bytes] | None = None,
) -> list[str]:
    """Enforce the pre-final2 path set and hashes outside the final2 whitelist."""
    issues: list[str] = []
    if not FINAL2_FREEZE_BASELINE_PATH.exists():
        return [f"final2 freeze baseline is missing: {FINAL2_FREEZE_BASELINE_PATH}"]
    baseline_bytes = FINAL2_FREEZE_BASELINE_PATH.read_bytes()
    if sha256_bytes(baseline_bytes) != FINAL2_FREEZE_BASELINE_SHA256:
        issues.append("final2 freeze baseline itself was changed after the pre-edit capture")
    with FINAL2_FREEZE_BASELINE_PATH.open(encoding="utf-8", newline="") as handle:
        reader = csv.DictReader(handle, delimiter="\t")
        rows = list(reader)
        fields = tuple(reader.fieldnames or ())
    if fields != ("relative_path", "sha256"):
        issues.append("final2 freeze baseline columns or column order changed")
        return issues
    expected: dict[str, str] = {}
    for row in rows:
        relative = row.get("relative_path", "")
        digest = row.get("sha256", "")
        if not relative or relative in expected:
            issues.append(f"final2 freeze baseline has a blank or duplicate path: {relative!r}")
            continue
        if relative in FINAL2_CAPTURE_MUTABLE_FILES or relative == ".git" or relative.startswith(".git/"):
            issues.append(f"final2 freeze baseline improperly includes a mutable or git path: {relative}")
        if not re.fullmatch(r"[0-9a-f]{64}", digest):
            issues.append(f"final2 freeze baseline has an invalid SHA-256 for {relative}")
        expected[relative] = digest
    if len(expected) != 346 or ".DS_Store" not in expected or len(set(expected) - {".DS_Store"}) != 345:
        issues.append(
            "final2 freeze baseline must contain exactly 346 files including .DS_Store "
            "(345 when .DS_Store is excluded)"
        )
    actual_paths = {
        path.relative_to(ROOT).as_posix()
        for path in ROOT.rglob("*")
        if path.is_file()
        and ".git" not in path.relative_to(ROOT).parts
        and path.relative_to(ROOT).as_posix() not in FINAL2_MUTABLE_FILES
        and path.relative_to(ROOT).as_posix() not in BATCH11_MUTABLE_FILES
        and path.relative_to(ROOT).as_posix() not in BATCH12_SUCCESSOR_FILES
        and path.relative_to(ROOT).as_posix() not in BATCH13_NEW_AUDIT_FILES
        and path.relative_to(ROOT).as_posix() not in BATCH14_NEW_AUDIT_FILES
    }
    expected_paths = (
        set(expected)
        - BATCH10_NEW_OR_MUTABLE_FILES
        - BATCH11_MUTABLE_FILES
        - BATCH12_SUCCESSOR_FILES
        - BATCH13_NEW_AUDIT_FILES
        - BATCH14_NEW_AUDIT_FILES
    )
    if (ROOT / ".git").exists():
        for relative in sorted(expected_paths - actual_paths):
            issues.append(f"final2 frozen file is missing: {relative}")
        for relative in sorted(actual_paths - expected_paths):
            issues.append(f"final2 added a file outside the whitelist: {relative}")
    payloads = {**batch14_historical_page_bytes(), **batch13_historical_page_bytes(), **(overrides or {})}
    for relative in sorted(actual_paths & expected_paths):
        if sha256_bytes(
            payloads.get(relative) or (ROOT / relative).read_bytes()
        ) != expected[relative]:
            issues.append(f"final2 frozen file changed: {relative}")
    return issues


def batch10_start_freeze_issues(
    overrides: dict[str, bytes] | None = None,
) -> list[str]:
    """Authenticate the one-time batch-10 capture and enforce its protected scope.

    As with the final1/final2 freezes, exact path-set enforcement belongs to the
    source Git worktree where the start snapshot was captured.  A Desktop
    delivery is a non-Git mirror and may contain pre-existing extra files;
    there we still require every captured path, authenticate the baseline and
    hash every protected file without misclassifying mirror-only paths as
    batch-10 additions.
    """
    issues: list[str] = []
    overrides = overrides or {}
    if not BATCH10_START_FREEZE_PATH.exists():
        return [f"batch10 start freeze is missing: {BATCH10_START_FREEZE_PATH}"]
    baseline_bytes = BATCH10_START_FREEZE_PATH.read_bytes()
    if sha256_bytes(baseline_bytes) != BATCH10_START_FREEZE_SHA256:
        issues.append("batch10 start freeze was regenerated or edited after capture")
    with BATCH10_START_FREEZE_PATH.open(encoding="utf-8", newline="") as handle:
        reader = csv.DictReader(handle, delimiter="\t")
        rows = list(reader)
        fields = tuple(reader.fieldnames or ())
    if fields != ("relative_path", "sha256", "scope"):
        issues.append("batch10 start freeze columns or column order changed")
        return issues
    if len(rows) != BATCH10_START_FREEZE_FILES:
        issues.append(
            f"batch10 start freeze has {len(rows)} files, expected {BATCH10_START_FREEZE_FILES}"
        )
    expected: dict[str, dict[str, str]] = {}
    scope_counts = Counter()
    allowed_scopes = {
        "batch10-target-article",
        "batch9-final2-captured;batch10-authorized-support",
        "batch9-final2-frozen",
        "non-target-article-frozen",
        "non-target-file-frozen",
        "public-page-frozen",
        "runtime-frozen",
    }
    for row in rows:
        relative = row.get("relative_path", "")
        digest = row.get("sha256", "")
        scope = row.get("scope", "")
        if not relative or relative in expected:
            issues.append(f"batch10 start freeze has a blank or duplicate path: {relative!r}")
            continue
        if relative == ".DS_Store" or ".git" in Path(relative).parts:
            issues.append(f"batch10 start freeze contains excluded path: {relative}")
        if not re.fullmatch(r"[0-9a-f]{64}", digest):
            issues.append(f"batch10 start freeze has invalid SHA-256 for {relative}")
        if scope not in allowed_scopes:
            issues.append(f"batch10 start freeze has invalid scope {scope!r} for {relative}")
        expected[relative] = row
        scope_counts[scope] += 1
    required_scope_counts = {
        "batch10-target-article": 8,
        "batch9-final2-captured;batch10-authorized-support": 6,
        "batch9-final2-frozen": 5,
        "non-target-article-frozen": 44,
        "non-target-file-frozen": 282,
        "public-page-frozen": 9,
        "runtime-frozen": 2,
    }
    if dict(scope_counts) != required_scope_counts:
        issues.append(
            "batch10 start freeze scope cardinalities changed: "
            f"{dict(sorted(scope_counts.items()))}"
        )
    final2_expected = {
        "posts/digital-surveillance.html",
        "posts/hong-kong-nsl.html",
        "posts/hu-xinyu-disappearance.html",
        "script.js",
        "tools/check_languages.py",
        "tools/audit_zero21_semantics.py",
        "tools/data/semantic-reread-review.tsv",
        "tools/data/editorial-semantic-contract.tsv",
        "tools/data/zhonghuafreedom-fourth-pass-source-ledger.tsv",
        "tools/data/batch9-final2-card-delta.tsv",
        "tools/data/batch9-final2-freeze-baseline.tsv",
    }
    if not final2_expected.issubset(expected):
        issues.append("batch10 start freeze does not contain all eleven batch9-final2 files")
    allowed_new = {
        "tools/data/batch10-start-freeze-baseline.tsv",
        "tools/data/batch10-card-baseline.tsv",
        "tools/data/batch10-card-delta.tsv",
        "tools/data/batch10-final1-preimage.tsv",
    } | BATCH12_NEW_AUDIT_FILES | BATCH13_NEW_AUDIT_FILES | BATCH14_NEW_AUDIT_FILES
    actual_paths = {
        path.relative_to(ROOT).as_posix()
        for path in ROOT.rglob("*")
        if path.is_file()
        and ".git" not in path.relative_to(ROOT).parts
        and path.name != ".DS_Store"
    }
    if (ROOT / ".git").exists():
        unexpected = actual_paths - set(expected) - allowed_new
        for relative in sorted(unexpected):
            issues.append(f"batch10 added a file outside the whitelist: {relative}")
    for relative in sorted(set(expected) - actual_paths):
        issues.append(f"batch10 start-snapshot file is missing: {relative}")
    preimage = {**batch14_historical_page_bytes(), **batch13_historical_page_bytes()}
    for relative, row in sorted(expected.items()):
        if (
            relative in BATCH10_MUTABLE_FILES
            or relative in BATCH11_MUTABLE_FILES
            or relative in BATCH12_MUTABLE_FILES
            or relative not in actual_paths
        ):
            continue
        data = overrides.get(
            relative, preimage.get(relative) or (ROOT / relative).read_bytes()
        )
        if sha256_bytes(data) != row.get("sha256", ""):
            issues.append(f"batch10 protected file changed: {relative}")
    for relative in sorted(allowed_new - actual_paths):
        issues.append(f"batch10 required ledger is missing: {relative}")
    return issues


def batch10_final2_frozen_issues(
    overrides: dict[str, bytes] | None = None,
) -> list[str]:
    """Protect the final2-specific frozen files captured before this pass."""
    # Batch thirteen revised 49 dossiers.  This historical freeze keeps every
    # one of its digests and is replayed against the authenticated
    # pre-batch13 bytes, which batch13_page_preimage_issues proves equal the
    # recorded sha256_before.  An explicit override still wins, so the
    # historical negative tests keep working.
    caller_overrides = dict(overrides or {})
    overrides = {
        **batch14_historical_page_bytes(),
        **batch13_historical_page_bytes(),
        **caller_overrides,
    }
    # This gate pins the source-date ledger at its 293-row final2 state and
    # reconstructs that state itself further down.  The batch14 preimage of
    # that file is the 294-row base — a later state — so it must not pre-empt
    # the reconstruction.  An override the caller passed explicitly still wins,
    # so the historical negative tests keep working.
    if SOURCE_DATE_LEDGER_RELATIVE not in caller_overrides:
        overrides.pop(SOURCE_DATE_LEDGER_RELATIVE, None)
    issues: list[str] = []
    for relative, expected in BATCH10_FINAL2_FROZEN_SHA256.items():
        path = ROOT / relative
        if not path.exists():
            issues.append(f"batch10-final2 frozen file is missing: {relative}")
            continue
        payload = overrides.get(relative, path.read_bytes())
        if sha256_bytes(payload) != expected:
            if relative == "tools/data/source-date-ledger.tsv" and relative not in overrides:
                rows, _fields, load_issues = load_source_date_ledger()
                historical_rows = rows[:BATCH11_FINAL1_SOURCE_DATE_PREFIX_ROWS]
                history_issues = exact_tsv_prefix_issues(
                    SOURCE_DATE_LEDGER_PATH,
                    base_rows=BATCH11_FINAL1_SOURCE_DATE_PREFIX_ROWS,
                    expected_sha256=BATCH11_FINAL1_SOURCE_DATE_PREFIX_SHA256,
                    label="source-date batch11-final1 authenticated predecessor",
                )
                if (
                    not load_issues
                    and not history_issues
                    and not batch10_final3_source_date_transition_issues(historical_rows)
                ):
                    # Final3 authorizes exactly the two spelling fields and
                    # reconstructs this final2 hash inside the transition test.
                    # Final1 separately authenticates this 293-row prefix and
                    # its sole HK12/s6 successor row.
                    continue
            issues.append(f"batch10-final2 frozen file changed: {relative}")
    return issues


def load_batch10_card_rows(path: Path) -> tuple[list[dict[str, str]], list[str]]:
    if not path.exists():
        return [], [f"batch10 card ledger is missing: {path}"]
    with path.open(encoding="utf-8", newline="") as handle:
        reader = csv.DictReader(handle, delimiter="\t")
        rows = list(reader)
        fields = tuple(reader.fieldnames or ())
    issues = []
    if fields != REPORT_CARD_BASELINE_COLUMNS:
        issues.append(f"{path.name}: columns or column order changed")
    return rows, issues


def batch10_card_baseline_issues(text_override: str | None = None) -> list[str]:
    issues: list[str] = []
    if not BATCH10_CARD_BASELINE_PATH.exists():
        return [f"batch10 card baseline is missing: {BATCH10_CARD_BASELINE_PATH}"]
    if sha256_bytes(BATCH10_CARD_BASELINE_PATH.read_bytes()) != BATCH10_CARD_BASELINE_SHA256:
        issues.append("batch10 card baseline was regenerated or edited after capture")
    rows, load_issues = load_batch10_card_rows(BATCH10_CARD_BASELINE_PATH)
    issues.extend(load_issues)
    if load_issues:
        return issues
    expected_rows = POST_BATCH9_BASELINE_FILES * len(REPORT_CARD_FIELDS)
    if len(rows) != expected_rows:
        issues.append(f"batch10 card baseline has {len(rows)} rows, expected {expected_rows}")
    cards, card_parse_issues = extract_report_cards(
        text_override if text_override is not None else (ROOT / "script.js").read_text(encoding="utf-8")
    )
    cards = batch14_baseline_card_view(cards)
    issues.extend(card_parse_issues)
    current = {
        (index, card.get("slug", ""), field): card.get(field, "")
        for index, card in enumerate(cards, start=1)
        for field in REPORT_CARD_FIELDS
    }
    seen = set()
    target_rows = non_target_rows = 0
    for row in rows:
        try:
            index = int(row.get("card_index", ""))
        except ValueError:
            issues.append("batch10 card baseline contains a non-numeric card index")
            continue
        key = (index, row.get("slug", ""), row.get("field", ""))
        if key in seen:
            issues.append(f"batch10 card baseline duplicates {key}")
        seen.add(key)
        slug = row.get("slug", "")
        expected_scope = "target" if slug in BATCH10_TARGET_SLUGS else "non-target"
        if row.get("batch_tag") != "reread:batch10-start":
            issues.append(f"batch10 card baseline has wrong batch tag for {key}")
        if row.get("scope") != expected_scope:
            issues.append(f"batch10 card baseline has wrong scope for {key}")
        if row.get("before_value") != row.get("after_value"):
            issues.append(f"batch10 card baseline start values differ for {key}")
        if row.get("changed") != "NO" or row.get("integrity_result") != "BASELINE_CAPTURED":
            issues.append(f"batch10 card baseline start status changed for {key}")
        if expected_scope == "target":
            target_rows += 1
        else:
            non_target_rows += 1
            batch11_authorized = (
                slug in BATCH11_CARD_SLUGS
                and row.get("field", "") in BATCH11_CARD_FIELDS
            )
            batch12_authorized = (
                slug in BATCH12_CARD_SLUGS
                and row.get("field", "").startswith(
                    ("title_", "excerpt_")
                )
            )
            if not (batch11_authorized or batch12_authorized) and current.get(key) != row.get("before_value", ""):
                issues.append(f"batch10 non-target card changed: {slug} {row.get('field', '')}")
    if target_rows != 8 * len(REPORT_CARD_FIELDS) or non_target_rows != 46 * len(REPORT_CARD_FIELDS):
        issues.append(
            f"batch10 card baseline scope counts changed: target={target_rows}, non-target={non_target_rows}"
        )
    return issues


def batch10_card_delta_issues(text_override: str | None = None) -> list[str]:
    rows, issues = load_batch10_card_rows(BATCH10_CARD_DELTA_PATH)
    baseline, baseline_issues = load_batch10_card_rows(BATCH10_CARD_BASELINE_PATH)
    issues.extend(baseline_issues)
    if issues:
        return issues
    expected_rows = POST_BATCH9_BASELINE_FILES * len(REPORT_CARD_FIELDS)
    if len(rows) != expected_rows or len(baseline) != expected_rows:
        return issues + ["batch10 card delta or baseline row count changed"]
    cards, parse_issues = extract_report_cards(
        text_override if text_override is not None else (ROOT / "script.js").read_text(encoding="utf-8")
    )
    cards = batch14_baseline_card_view(cards)
    issues.extend(parse_issues)
    current = {
        (index, card.get("slug", ""), field): card.get(field, "")
        for index, card in enumerate(cards, start=1)
        for field in REPORT_CARD_FIELDS
    }
    baseline_map = {
        (int(row["card_index"]), row["slug"], row["field"]): row
        for row in baseline
    }
    seen = set()
    for row in rows:
        try:
            key = (int(row.get("card_index", "")), row.get("slug", ""), row.get("field", ""))
        except ValueError:
            issues.append("batch10 card delta contains a non-numeric card index")
            continue
        if key in seen:
            issues.append(f"batch10 card delta duplicates {key}")
        seen.add(key)
        base = baseline_map.get(key)
        if base is None:
            issues.append(f"batch10 card delta has an unknown key: {key}")
            continue
        slug = key[1]
        field = key[2]
        scope = "target" if slug in BATCH10_TARGET_SLUGS else "non-target"
        before = base.get("before_value", "")
        batch11_authorized = slug in BATCH11_CARD_SLUGS and field in BATCH11_CARD_FIELDS
        batch12_authorized = (
            slug in BATCH12_CARD_SLUGS
            and field.startswith(("title_", "excerpt_"))
        )
        # Replay batch ten against its authenticated delta for fields that a
        # later batch is expressly allowed to revise.  Batch 11 independently
        # freezes and validates the new live value below.
        after = (
            row.get("after_value", "")
            if (batch11_authorized or batch12_authorized)
            else current.get(key, "")
        )
        changed = before != after
        if row.get("batch_tag") != "reread:batch10" or row.get("scope") != scope:
            issues.append(f"batch10 card delta tag/scope changed for {slug} {field}")
        if row.get("before_value") != before or row.get("after_value") != after:
            issues.append(f"batch10 card delta is not recomputable for {slug} {field}")
        if row.get("changed") != ("YES" if changed else "NO"):
            issues.append(f"batch10 card delta changed flag is wrong for {slug} {field}")
        expected_result = "PASS_CHANGED_AUTHORIZED" if changed else "PASS_UNCHANGED"
        if row.get("integrity_result") != expected_result:
            issues.append(f"batch10 card delta result is wrong for {slug} {field}")
        if scope == "non-target" and changed:
            issues.append(f"batch10 card delta records unauthorized non-target change: {slug} {field}")
    if seen != set(baseline_map):
        issues.append("batch10 card delta key coverage differs from the immutable start baseline")
    return issues


BATCH10_FINAL1_PREIMAGE_COLUMNS = (
    "record_type", "slug", "language_or_field", "target_id",
    "preimage_value", "post_final1_value", "preimage_value_sha256",
    "post_final1_value_sha256", "preimage_file", "preimage_file_sha256",
    "post_final1_file_sha256", "snapshot_manifest_sha256", "verification",
)


def load_batch10_final1_preimage() -> tuple[list[dict[str, str]], list[str]]:
    if not BATCH10_FINAL1_PREIMAGE_PATH.exists():
        return [], ["batch10 final1 preimage artifact is missing"]
    issues: list[str] = []
    if sha256_bytes(BATCH10_FINAL1_PREIMAGE_PATH.read_bytes()) != BATCH10_FINAL1_PREIMAGE_SHA256:
        issues.append("batch10 final1 preimage artifact was regenerated or edited")
    with BATCH10_FINAL1_PREIMAGE_PATH.open(encoding="utf-8", newline="") as handle:
        reader = csv.DictReader(handle, delimiter="\t")
        rows = list(reader)
        fields = tuple(reader.fieldnames or ())
    if fields != BATCH10_FINAL1_PREIMAGE_COLUMNS:
        issues.append("batch10 final1 preimage columns or order changed")
    return rows, issues


def batch10_final1_preimage_issues(
    rows_override: list[dict[str, str]] | None = None,
) -> list[str]:
    """Persist the verified 36 metadata preimages and 21 final1 card deltas."""
    if rows_override is None:
        rows, issues = load_batch10_final1_preimage()
    else:
        rows, issues = rows_override, []
    if len(rows) != 57:
        issues.append(f"batch10 final1 preimage has {len(rows)} rows, expected 57")
    meta_rows = [row for row in rows if row.get("record_type") == "article-meta"]
    card_rows = [row for row in rows if row.get("record_type") == "card-field"]
    if len(meta_rows) != 36 or len(card_rows) != 21:
        issues.append(
            f"batch10 final1 preimage classification changed: meta={len(meta_rows)} card={len(card_rows)}"
        )
    for row in rows:
        preimage = row.get("preimage_value", "")
        post = row.get("post_final1_value", "")
        if row.get("snapshot_manifest_sha256") != BATCH10_FINAL1_SNAPSHOT_MANIFEST_SHA256:
            issues.append("batch10 final1 preimage lost the authenticated snapshot-manifest SHA")
        if sha256_bytes(preimage.encode("utf-8")) != row.get("preimage_value_sha256", ""):
            issues.append(
                f"batch10 final1 preimage value digest differs: {row.get('slug')}/{row.get('target_id')}"
            )
        if sha256_bytes(post.encode("utf-8")) != row.get("post_final1_value_sha256", ""):
            issues.append(
                f"batch10 final1 post-value digest differs: {row.get('slug')}/{row.get('target_id')}"
            )
        for field in ("preimage_file_sha256", "post_final1_file_sha256"):
            if not re.fullmatch(r"[0-9a-f]{64}", row.get(field, "")):
                issues.append(f"batch10 final1 preimage has invalid {field}")

    expected_meta = set(BATCH10_FINAL1_META_TARGETS)
    actual_meta = {
        (row.get("slug", ""), row.get("language_or_field", "")) for row in meta_rows
    }
    if actual_meta != expected_meta or len(actual_meta) != len(meta_rows):
        issues.append("batch10 final1 preimage does not contain exactly the 36 article-meta targets")
    expected_card_fields = {
        "tiananmen-1989": {f"excerpt_{lang}" for lang in LANGS},
        "falun-gong-persecution": {f"excerpt_{lang}" for lang in LANGS},
        "huang-qi": {"excerpt_no"},
    }
    actual_card_fields: dict[str, set[str]] = defaultdict(set)
    for row in card_rows:
        actual_card_fields[row.get("slug", "")].add(row.get("language_or_field", ""))
        if row.get("target_id") != f"card:{row.get('language_or_field', '')}":
            issues.append("batch10 final1 card preimage target id differs from its field")
        if row.get("verification") != "VERIFIED_FINAL1_CARD_DIFF_FROM_PREIMAGE":
            issues.append("batch10 final1 card preimage lost its verification class")
        if row.get("preimage_file") != "script.js":
            issues.append("batch10 final1 card preimage points outside script.js")
    if dict(actual_card_fields) != expected_card_fields:
        issues.append("batch10 final1 card preimage is not exactly Tian 10, Falun 10, Huang Norwegian 1")

    with SEMANTIC_REREAD_PATH.open(encoding="utf-8", newline="") as handle:
        reread_rows = list(csv.DictReader(handle, delimiter="\t"))
    final1_rows = reread_rows[SEMANTIC_REREAD_BATCH10_ROWS:BATCH10_FINAL1_REREAD_ROWS]
    earlier_keys = {
        (row.get("slug", ""), row.get("language", ""), row.get("target_id", ""))
        for row in reread_rows[:SEMANTIC_REREAD_BATCH10_ROWS]
    }
    final1_by_key = {
        (row.get("slug", ""), row.get("language", ""), row.get("target_id", "")): row
        for row in final1_rows
    }
    for row in meta_rows:
        slug, lang = row.get("slug", ""), row.get("language_or_field", "")
        key = (slug, lang, "article-meta")
        ledger = final1_by_key.get(key)
        if key in earlier_keys:
            issues.append(f"batch10 final1 article-meta unexpectedly has a ledger predecessor: {slug}/{lang}")
        if ledger is None:
            issues.append(f"batch10 final1 article-meta preimage lacks its final1 ledger row: {slug}/{lang}")
            continue
        def normalized_meta(value: str) -> str:
            # The immutable final1 ledger normalized French colon spacing;
            # the preimage artifact deliberately preserves the source bytes.
            # Compare the metadata meaning here while the artifact's own value
            # and file SHA fields continue to authenticate its exact spelling.
            return re.sub(r"\s*:\s*", ":", normalize_reread_text(value))

        if (
            normalized_meta(row.get("preimage_value", ""))
            != normalized_meta(ledger.get("original_text", ""))
            or normalized_meta(row.get("post_final1_value", ""))
            != normalized_meta(ledger.get("revised_text", ""))
        ):
            issues.append(f"batch10 final1 article-meta preimage differs from its ledger values: {slug}/{lang}")
        if row.get("verification") != "VERIFIED_PREIMAGE_WITHOUT_LEDGER_PREDECESSOR":
            issues.append(f"batch10 final1 article-meta preimage lost its verification class: {slug}/{lang}")

    prefix_tips: dict[tuple[str, str, str], dict[str, str]] = {}
    for row in reread_rows[:BATCH10_FINAL1_REREAD_ROWS]:
        prefix_tips[(row.get("slug", ""), row.get("language", ""), row.get("target_id", ""))] = row
    for row in card_rows:
        field = row.get("language_or_field", "")
        lang = field.removeprefix("excerpt_")
        tip = prefix_tips.get((row.get("slug", ""), lang, "article-dek"))
        if tip is None or tip.get("revised_text") != row.get("post_final1_value"):
            issues.append(
                f"batch10 final1 card post-value lacks matching final1 article-dek: {row.get('slug')}/{field}"
            )
    return issues


def frozen_article_issues(overrides: dict[str, bytes] | None = None) -> list[str]:
    """Enforce the pre-batch byte baseline for all dossiers and frozen controls."""
    # Batch thirteen revised 49 dossiers.  This historical freeze keeps every
    # one of its digests and is replayed against the authenticated
    # pre-batch13 bytes, which batch13_page_preimage_issues proves equal the
    # recorded sha256_before.  An explicit override still wins, so the
    # historical negative tests keep working.
    overrides = {
        **batch14_historical_article_bytes(),
        **batch14_historical_page_bytes(),
        **batch13_historical_article_bytes(),
        **batch13_historical_page_bytes(),
        **(overrides or {}),
    }
    issues = []
    current_names = {path.name for path in FILES}
    if current_names - BATCH14_NEW_FILENAMES != set(FROZEN_POST_HASHES):
        issues.append("frozen articles: filename set differs from the 54-file baseline")
    if not BATCH14_NEW_FILENAMES <= current_names:
        issues.append("frozen articles: a batch14 dossier is missing from posts/")
    for name, expected in FROZEN_POST_HASHES.items():
        if (
            name in BATCH9_TARGET_FILENAMES
            or name in BATCH10_TARGET_FILENAMES
            or name in BATCH11_TARGET_FILENAMES
            or name in BATCH12_TARGET_FILENAMES
        ):
            continue
        path = POSTS / name
        data = overrides.get(name, path.read_bytes() if path.exists() else b"")
        if sha256_bytes(data) != expected:
            issues.append(f"frozen article changed: posts/{name}")
    for relative, expected in FROZEN_CONTROL_HASHES.items():
        path = ROOT / relative
        data = overrides.get(relative, path.read_bytes() if path.exists() else b"")
        if sha256_bytes(data) != expected:
            issues.append(f"frozen control changed: {relative}")
    return issues


def public_body_for(soup: BeautifulSoup, lang: str):
    return soup.select_one(f'[data-language-body="{lang}"]')


def localized_classes(node) -> set[str]:
    result = set()
    if node is None:
        return result
    for item in node.select("[class]"):
        for klass in item.get("class") or []:
            if klass.startswith("lang-") and klass[5:] in LANGS:
                result.add(klass[5:])
    return result


def public_visible_text(soup: BeautifulSoup) -> str:
    clone = copy.copy(soup)
    for node in clone.select("script, style, template"):
        node.decompose()
    return clone.get_text(" ", strip=True)


def public_structure(body) -> tuple:
    if body is None:
        return ()
    signature = []
    for section in body.select(":scope > section[data-section]"):
        top_tags = tuple(child.name for child in section.children if getattr(child, "name", None))
        list_sizes = tuple(len(value.select(":scope > li")) for value in section.select("ul, ol"))
        signature.append((section.get("data-section"), top_tags, list_sizes))
    return tuple(signature)


def public_page_issues(soup: BeautifulSoup, path: Path) -> list[str]:
    issues = []
    bodies = soup.select("[data-language-body]")
    body_langs = [body.get("data-language-body") for body in bodies]
    if len(bodies) != len(LANGS) or set(body_langs) != set(LANGS):
        issues.append(f"public page: needs exactly ten language bodies, found {body_langs}")
    title_nodes = soup.select("h1.article-title [class]")
    dek_nodes = soup.select("p.article-dek [class]")
    for field, nodes in (("title", title_nodes), ("deck", dek_nodes)):
        present = localized_classes(BeautifulSoup("".join(str(node) for node in nodes), "html.parser"))
        if present != set(LANGS):
            issues.append(f"public {field}: language set is incomplete")
        english = soup.select_one(f"{'h1.article-title' if field == 'title' else 'p.article-dek'} .lang-en")
        english_text = english.get_text(" ", strip=True) if english else ""
        for lang in LANGS:
            node = soup.select_one(f"{'h1.article-title' if field == 'title' else 'p.article-dek'} .lang-{lang}")
            text = node.get_text(" ", strip=True) if node else ""
            if not text:
                issues.append(f"public {field}: missing {lang} text")
            elif lang != "en" and text == english_text:
                issues.append(f"public {field}: {lang} falls back to English")
    reference = public_structure(public_body_for(soup, "en"))
    zh_body = public_body_for(soup, "zh")
    zh_headings = {
        node.get_text(" ", strip=True)
        for node in (zh_body.select("h2, h3") if zh_body else [])
        if len(node.get_text(" ", strip=True)) >= 2
    }
    english_blocks = [
        node.get_text(" ", strip=True)
        for node in (public_body_for(soup, "en").select("h2, h3, p, li") if public_body_for(soup, "en") else [])
        if node.find_parent("section", attrs={"data-section": "retained-links"}) is None
    ]
    for lang in LANGS:
        body = public_body_for(soup, lang)
        if body is None:
            continue
        if public_structure(body) != reference:
            issues.append(f"{lang}: public section/list structure differs from English")
        text = body.get_text(" ", strip=True)
        if len(text) < 120:
            issues.append(f"{lang}: public page body is too short")
        if PUBLIC_BANNED.search(text):
            issues.append(f"{lang}: prohibited public disclaimer or internal wording")
        if lang != "en":
            blocks = [
                node.get_text(" ", strip=True) for node in body.select("h2, h3, p, li")
                if node.find_parent("section", attrs={"data-section": "retained-links"}) is None
            ]
            for number, value in enumerate(blocks):
                if number < len(english_blocks) and len(value) >= 24 and value == english_blocks[number]:
                    issues.append(f"{lang}: public block {number + 1} falls back to English")
                    break
        if lang not in {"zh", "ja"}:
            headings = {node.get_text(" ", strip=True) for node in body.select("h2, h3")}
            if headings & zh_headings:
                issues.append(f"{lang}: public heading falls back to Chinese")
    return issues


def privacy_issues(soup: BeautifulSoup) -> list[str]:
    issues = []
    required_sections = {"language-storage", "formspree", "email", "external-links", "safety-requests"}
    for lang in LANGS:
        body = public_body_for(soup, lang)
        if body is None:
            continue
        text = body.get_text(" ", strip=True)
        sections = {node.get("data-section") for node in body.select(":scope > section[data-section]")}
        if sections != required_sections:
            issues.append(f"privacy {lang}: required data-flow sections are incomplete")
        for literal in (
            "language.js", "localStorage", "lang", "Formspree",
            "https://formspree.io/f/xgvdozke", "name", "email", "message",
        ):
            if literal not in text:
                issues.append(f"privacy {lang}: missing {literal} disclosure")
        storage_text = (body.select_one('[data-section="language-storage"]') or body).get_text(" ", strip=True)
        expected_codes = PRIVACY_CODE_SEQUENCE_NO if lang == "no" else PRIVACY_CODE_SEQUENCE
        if expected_codes not in storage_text:
            issues.append(f"privacy {lang}: ordered ten-code language set is incomplete")
        if lang == "fr" and not re.search(r"sous la clé lang(?:[.;, ]|$)", storage_text):
            issues.append("privacy fr: localStorage key must read 'sous la clé lang'")
        if lang == "no" and not re.search(r"under nøkkelen lang(?:[.;, ]|$)", storage_text):
            issues.append("privacy no: localStorage key must read 'under nøkkelen lang'")
        if PRIVACY_HARD_ERRORS.search(text):
            issues.append(f"privacy {lang}: known French or Norwegian key/value mistranslation returned")
        formspree_text = (body.select_one('[data-section="formspree"]') or body).get_text(" ", strip=True)
        for field in ("name", "email", "message"):
            if not re.search(rf"\b{field}\b", formspree_text):
                issues.append(f"privacy {lang}: missing exact {field} form-field literal")
        if len((body.select_one('[data-section="external-links"]') or body).get_text(" ", strip=True)) < 70:
            issues.append(f"privacy {lang}: external-link disclosure is incomplete")
        if len((body.select_one('[data-section="safety-requests"]') or body).get_text(" ", strip=True)) < 100:
            issues.append(f"privacy {lang}: sensitive-data safety disclosure is incomplete")
        section_facts = {
            "language-storage": ("restore", "not_cookie", "no_transmit", "clear", "fallback"),
            "formspree": ("retention",),
            "email": ("providers",),
            "external-links": ("no_tracking",),
            "safety-requests": ("sensitive", "correction"),
        }
        for section_name, fact_names in section_facts.items():
            section = body.select_one(f'[data-section="{section_name}"]')
            section_text_value = section.get_text(" ", strip=True) if section else ""
            for fact_name in fact_names:
                if not re.search(PRIVACY_FACT_PATTERNS[lang][fact_name], section_text_value, re.I | re.S):
                    issues.append(f"privacy {lang}: {section_name} lacks {fact_name} meaning")
    return issues


def about_issues(soup: BeautifulSoup) -> list[str]:
    issues = []
    for lang in LANGS:
        body = public_body_for(soup, lang)
        mission = body.select_one('[data-section="mission"]') if body else None
        first = mission.find("p", recursive=False) if mission else None
        text = first.get_text(" ", strip=True) if first else ""
        if not text:
            issues.append(f"about {lang}: mission statement is missing")
        elif ABOUT_SERVICE_MODE.search(text):
            issues.append(f"about {lang}: archive purpose reverted to a service-provider claim")
    return issues


def terms_issues(soup: BeautifulSoup) -> list[str]:
    issues = []
    english_body = public_body_for(soup, "en")
    english_blocks = [node.get_text(" ", strip=True) for node in english_body.select("h2, p, li")]
    for lang in LANGS:
        body = public_body_for(soup, lang)
        if body is None:
            continue
        citation = body.select_one('[data-section="citation"]') if body else None
        text = citation.get_text(" ", strip=True) if citation else ""
        if TERMS_UNCERTAINTY_MARKERS.search(text):
            issues.append(f"terms {lang}: abstract uncertainty-marker wording returned")
        body_text = body.get_text(" ", strip=True)
        if TERMS_TRANSLATION_ERRORS.search(body_text):
            issues.append(f"terms {lang}: known mechanical source or stability translation returned")
        if TERMS_LATEST_AUDIT_ERRORS.search(body_text):
            issues.append(f"terms {lang}: latest audited mechanical or legal phrasing returned")
        citation_items = citation.select(":scope > ul > li") if citation else []
        corrections = body.select_one('[data-section="corrections"]')
        correction_items = corrections.select(":scope > ul > li") if corrections else []
        evidence = body.select_one('[data-section="evidence-use"]')
        evidence_paragraphs = evidence.find_all("p", recursive=False) if evidence else []
        if len(citation_items) != 3 or len(correction_items) != 3 or len(evidence_paragraphs) != 2:
            issues.append(f"terms {lang}: citation, corrections, or evidence-use structure is incomplete")
            continue
        for index, pattern in enumerate(TERMS_CORRECTIONS_PATTERNS[lang]):
            correction_text = correction_items[index].get_text(" ", strip=True)
            if not re.search(pattern, correction_text, re.IGNORECASE | re.DOTALL):
                issues.append(f"terms {lang}: corrections item {index + 1} legal meaning is incomplete")
        if lang == "no":
            safety = body.select_one('[data-section="safety"] p')
            safety_text = safety.get_text(" ", strip=True) if safety else ""
            if not re.search(
                r"utsette berørte personer, familiemedlemmer, vitner, journalister eller støttespillere for represalier",
                safety_text,
                re.IGNORECASE,
            ):
                issues.append("terms no: retaliation sentence is grammatically incomplete")
        facts = TERMS_FACT_PATTERNS[lang]
        fact_texts = {
            "limits": citation_items[1].get_text(" ", strip=True),
            "citizen": citation_items[2].get_text(" ", strip=True) + " " + evidence_paragraphs[0].get_text(" ", strip=True),
            "media": citation_items[2].get_text(" ", strip=True) + " " + evidence_paragraphs[0].get_text(" ", strip=True),
            "stability": evidence_paragraphs[1].get_text(" ", strip=True),
        }
        for fact_name, pattern in facts.items():
            if not re.search(pattern, fact_texts[fact_name], re.IGNORECASE | re.DOTALL):
                issues.append(f"terms {lang}: {fact_name} meaning is incomplete")
        if lang != "en":
            localized = [node.get_text(" ", strip=True) for node in body.select("h2, p, li")]
            if any(len(value) >= 24 and value == english_blocks[index] for index, value in enumerate(localized)):
                issues.append(f"terms {lang}: visible block falls back to English")
    return issues


def traditional_chinese_issues(soup: BeautifulSoup, page_name: str) -> list[str]:
    body = public_body_for(soup, "zh")
    if body is None:
        return []
    match = TRADITIONAL_ZH_REGRESSIONS.search(body.get_text(" ", strip=True))
    return [f"{page_name} zh: simplified or mixed Chinese returned ({match.group(0)})"] if match else []


def index_contact_issues(soup: BeautifulSoup) -> list[str]:
    issues = []
    form = soup.select_one("form.contact-form")
    if form is None:
        return ["index contact: missing contact form"]
    if form.get("action") != "https://formspree.io/f/xgvdozke" or (form.get("method") or "").upper() != "POST":
        issues.append("index contact: Formspree endpoint or method is wrong")
    controls = {node.get("name"): node for node in form.select("input[name], textarea[name]")}
    if set(controls) != {"name", "email", "message"}:
        issues.append("index contact: fields must be exactly name, email, and message")
    for name, expected in (("name", "name"), ("email", "email"), ("message", "off")):
        node = controls.get(name)
        if node is None or node.get("autocomplete") != expected:
            issues.append(f"index contact: {name} autocomplete is missing or incorrect")
            continue
        label = form.select_one(f'label[for="{node.get("id")}"]')
        if label is None or localized_classes(label) != set(LANGS):
            issues.append(f"index contact: {name} lacks ten visible labels")
    button = form.select_one('button[type="submit"]')
    if button is None or localized_classes(button) != set(LANGS):
        issues.append("index contact: submit button lacks ten labels")
    disclosures = form.select("[data-formspree-disclosure]")
    intros = soup.select("[data-contact-intro]")
    for label, nodes in (("intro", intros), ("Formspree safety", disclosures)):
        langs = {
            next((klass[5:] for klass in node.get("class") or [] if klass.startswith("lang-")), None)
            for node in nodes
        }
        if langs != set(LANGS) or any(
            len(node.get_text(" ", strip=True)) < (
                35 if next(
                    (klass[5:] for klass in node.get("class") or [] if klass.startswith("lang-")), "en"
                ) in {"zh", "ja", "ko"} else 80
            )
            for node in nodes
        ):
            issues.append(f"index contact: {label} text is incomplete")
    text = public_visible_text(soup)
    if "wuzong2025@gmail.com" not in text or "Formspree" not in text:
        issues.append("index contact: public email or Formspree is missing")
    if SOCIAL_MEDIA_FALSE_CLAIM.search(text):
        issues.append("index contact: nonexistent social-media contact claim returned")
    if CONTACT_MISSING_CHANNEL_LIST.search(text):
        issues.append("index contact: negative list of unavailable contact features returned")
    zh_contact = " ".join(node.get_text(" ", strip=True) for node in soup.select("#contact .lang-zh"))
    match = TRADITIONAL_ZH_REGRESSIONS.search(zh_contact)
    if match:
        issues.append(f"index contact zh: simplified or mixed Chinese returned ({match.group(0)})")
    return issues


def contact_page_issues(soup: BeautifulSoup) -> list[str]:
    issues = []
    english_body = public_body_for(soup, "en")
    english_blocks = [node.get_text(" ", strip=True) for node in english_body.select("h2, p, li")]
    for lang in LANGS:
        body = public_body_for(soup, lang)
        if body is None:
            continue
        text = body.get_text(" ", strip=True)
        for literal in ("wuzong2025@gmail.com", "Formspree", "https://formspree.io/f/xgvdozke"):
            if literal not in text:
                issues.append(f"contact {lang}: missing {literal}")
        safety = body.select_one('[data-section="form-data"]')
        if safety is None or len(safety.get_text(" ", strip=True)) < 180:
            issues.append(f"contact {lang}: Formspree and sensitive-data disclosure is incomplete")
            continue
        paragraphs = safety.find_all("p", recursive=False)
        if len(paragraphs) != 3:
            issues.append(f"contact {lang}: Formspree section must contain three visible paragraphs")
            continue
        flow_text = paragraphs[0].get_text(" ", strip=True)
        if CONTACT_REVERSED_FLOW.search(flow_text):
            issues.append(f"contact {lang}: Formspree data flow is reversed toward another external service")
        if not re.search(CONTACT_FLOW_PATTERNS[lang], flow_text, re.IGNORECASE | re.DOTALL):
            issues.append(f"contact {lang}: form-to-Formspree-to-site data flow is incomplete")
        for field in ("name", "email", "message"):
            if not re.search(rf"\b{field}\b", flow_text):
                issues.append(f"contact {lang}: data-flow paragraph lacks exact {field} field literal")
        control_text = paragraphs[2].get_text(" ", strip=True)
        if not re.search(CONTACT_CONTROL_PATTERNS[lang], control_text, re.IGNORECASE | re.DOTALL):
            issues.append(f"contact {lang}: Formspree storage and processing boundary is incomplete")
        if CONTACT_TRANSLATION_ERRORS.search(text):
            issues.append(f"contact {lang}: known mechanical translation returned")
        if SOCIAL_MEDIA_FALSE_CLAIM.search(text):
            issues.append(f"contact {lang}: nonexistent social-media contact claim returned")
        if CONTACT_MISSING_CHANNEL_LIST.search(text):
            issues.append(f"contact {lang}: negative list of unavailable contact features returned")
        if lang != "en":
            localized = [node.get_text(" ", strip=True) for node in body.select("h2, p, li")]
            if any(len(value) >= 24 and value == english_blocks[index] for index, value in enumerate(localized)):
                issues.append(f"contact {lang}: visible block falls back to English")
    return issues


def load_semantic_review_rows() -> tuple[list[dict[str, str]], list[str]]:
    if not SEMANTIC_REVIEW_PATH.exists():
        return [], []
    with SEMANTIC_REVIEW_PATH.open(encoding="utf-8", newline="") as handle:
        reader = csv.DictReader(handle, delimiter="\t")
        return list(reader), list(reader.fieldnames or [])


def normalized_review_note_template(note: str) -> str:
    normalized = re.sub(r"\s+", " ", note).strip().casefold()
    return REVIEW_LANGUAGE_LABEL.sub("<lang>", normalized)


def semantic_review_issues(rows_override: list[dict[str, str]] | None = None) -> list[str]:
    issues = []
    if rows_override is None:
        rows, fieldnames = load_semantic_review_rows()
    else:
        rows = rows_override
        fieldnames = list(rows[0]) if rows else []
    missing_fields = set(SEMANTIC_REVIEW_FIELDS) - set(fieldnames)
    if missing_fields:
        return [f"semantic review TSV: missing fields {', '.join(sorted(missing_fields))}"]

    expected = {
        (file_name, lang, section)
        for file_name, sections in SEMANTIC_REVIEW_SECTIONS.items()
        for lang in LANGS
        for section in sections
    }
    keys = [(row.get("file", ""), row.get("language", ""), row.get("section", "")) for row in rows]
    counts = Counter(keys)
    if set(keys) != expected:
        missing = sorted(expected - set(keys))
        extra = sorted(set(keys) - expected)
        issues.append(f"semantic review TSV: coverage differs; missing={missing[:3]} extra={extra[:3]}")
    duplicated = sorted(key for key, count in counts.items() if count != 1)
    if duplicated:
        issues.append(f"semantic review TSV: duplicate section rows {duplicated[:3]}")

    documents = {
        name: BeautifulSoup((ROOT / name).read_text(encoding="utf-8"), "html.parser")
        for name in SEMANTIC_REVIEW_SECTIONS
    }
    note_counts = Counter()
    note_template_counts = Counter()
    for row in rows:
        key = (row.get("file", ""), row.get("language", ""), row.get("section", ""))
        if key not in expected:
            continue
        file_name, lang, section = key
        node = public_body_for(documents[file_name], lang).select_one(f'[data-section="{section}"]')
        visible = node.get_text(" ", strip=True) if node else ""
        if row.get("exact_visible_text", "") != visible:
            issues.append(f"semantic review TSV: exact visible text is stale for {file_name} {lang} {section}")
        if not row.get("result", "").startswith("PASS"):
            issues.append(f"semantic review TSV: result is not PASS for {file_name} {lang} {section}")
        note = re.sub(r"\s+", " ", row.get("review_note", "")).strip()
        note_counts[note] += 1
        note_template_counts[normalized_review_note_template(note)] += 1
        if len(note) < 28:
            issues.append(f"semantic review TSV: review note is too short for {file_name} {lang} {section}")
        if GENERIC_REVIEW_NOTE.search(note):
            issues.append(f"semantic review TSV: generic review note used for {file_name} {lang} {section}")
        if file_name == "terms.html":
            quoted_phrases = re.findall(r"“([^”]{2,160})”", note)
            if not any(phrase in visible for phrase in quoted_phrases):
                issues.append(
                    f"semantic review TSV: Terms note does not quote current visible wording for {lang} {section}"
                )
            if not re.search(r"原|舊|旧|previous|former|old", note, re.IGNORECASE):
                issues.append(
                    f"semantic review TSV: Terms note does not identify the original defect for {lang} {section}"
                )
            if not re.search(r"現|现|修|改|now|replaced|restored", note, re.IGNORECASE):
                issues.append(
                    f"semantic review TSV: Terms note does not explain the repair for {lang} {section}"
                )
    repeated_notes = sorted((note, count) for note, count in note_counts.items() if note and count > 3)
    if repeated_notes:
        issues.append(f"semantic review TSV: review note repeated at scale ({repeated_notes[0][1]} rows)")
    repeated_templates = sorted(
        (template, count)
        for template, count in note_template_counts.items()
        if template and count > 3
    )
    if repeated_templates:
        issues.append(
            f"semantic review TSV: language-swapped template repeated at scale ({repeated_templates[0][1]} rows)"
        )
    return issues


def sources_issues(soup: BeautifulSoup) -> list[str]:
    issues = []
    reference_urls = None
    for lang in LANGS:
        body = public_body_for(soup, lang)
        if body is None:
            continue
        category_nodes = body.select('[data-section="categories"] li[data-source-type]')
        categories = tuple(node.get("data-source-type") for node in category_nodes)
        if categories != SOURCE_CATEGORY_CODES:
            issues.append(f"sources {lang}: source categories/order differ from the required twelve")
        labels = [node.h3.get_text(" ", strip=True) if node.h3 else "" for node in category_nodes]
        localized_labels = [label.split("—", 1)[-1].strip().casefold() for label in labels]
        if len(set(localized_labels)) != len(SOURCE_CATEGORY_CODES) or any(
            value in {"source material", "material", "资料", "資料"} for value in localized_labels
        ):
            issues.append(f"sources {lang}: source categories were generalized")
        category_floor = 38 if lang in {"zh", "ja", "ko"} else 70
        method_floor = 75 if lang in {"zh", "ja", "ko"} else 150
        for code, node in zip(SOURCE_CATEGORY_CODES, category_nodes):
            text = node.get_text(" ", strip=True)
            if code not in text or len(text) < category_floor:
                issues.append(f"sources {lang}: {code} lacks a natural visible label or explanation")
        for section_name in ("frontline-value", "preservation", "independent-support", "official-boundary"):
            section = body.select_one(f'[data-section="{section_name}"]')
            if section is None or len(section.get_text(" ", strip=True)) < method_floor:
                issues.append(f"sources {lang}: {section_name} evidence role is incomplete")
        official = body.select_one('[data-section="official-boundary"]')
        if official and re.search(r"final truth|最终真相|最終真相|endelige sannhet|vérité finale|Wahrheit letzter Instanz|verità finale|waarheid als eindpunt", official.get_text(" ", strip=True), re.I):
            issues.append(f"sources {lang}: official material is described as final truth")
        link_nodes = body.select('[data-section="retained-links"] li[data-source-url]')
        urls = tuple(node.get("data-source-url") for node in link_nodes)
        if urls != EXPECTED_SOURCE_URLS:
            issues.append(f"sources {lang}: retained source URL set/order changed")
        if any(
            node.get("data-source-type") not in SOURCE_CATEGORY_CODES
            or node.select_one("a[href]") is None
            or node.select_one("a[href]").get("href") != node.get("data-source-url")
            for node in link_nodes
        ):
            issues.append(f"sources {lang}: retained source metadata is inconsistent")
        if reference_urls is None:
            reference_urls = urls
        elif urls != reference_urls:
            issues.append(f"sources {lang}: source links differ between languages")
    return issues


def js_object_languages(block: str) -> set[str]:
    return set(re.findall(r"\b(zh|en|ja|ko|es|de|fr|no|nl|it)\s*:", block))


def protests_script_issues(text_override: str | None = None) -> list[str]:
    text = text_override if text_override is not None else (ROOT / "protests.js").read_text(encoding="utf-8")
    issues = []
    event_pattern = re.compile(
        r"date:\s*'([^']+)'\s*,\s*slug:\s*'([^']+)'\s*,\s*count:\s*(\d+)\s*,"
        r"\s*title:\s*\{(.*?)\}\s*,\s*place:\s*\{(.*?)\}\s*\}",
        re.S,
    )
    events = event_pattern.findall(text)
    if len(events) != 8:
        issues.append(f"protests.js: expected 8 events, found {len(events)}")
    total = 0
    for date, slug, count_text, titles, places in events:
        count = int(count_text)
        total += count
        if js_object_languages(titles) != set(LANGS):
            issues.append(f"protests.js: {date} title lacks a ten-language set")
        if js_object_languages(places) != set(LANGS):
            issues.append(f"protests.js: {date} place lacks a ten-language set")
        directory = ROOT / "images" / "protests" / slug
        actual_names = sorted(path.name for path in directory.glob("photo-*.jpg"))
        expected_names = [f"photo-{number:03d}.jpg" for number in range(1, count + 1)]
        if actual_names != expected_names:
            issues.append(f"protests.js: {date} count/files mismatch ({count} declared, {len(actual_names)} present)")
    if total != 254:
        issues.append(f"protests.js: declared photo total is {total}, expected 254")
    for key in ("photos", "photo", "open", "intro", "total"):
        match = re.search(rf"\b{key}:\s*\{{(.*?)\n\s*\}}", text, re.S)
        if not match or js_object_languages(match.group(1)) != set(LANGS):
            issues.append(f"protests.js: galleryLabels.{key} lacks a ten-language set")
    fixed_english = re.search(r"event\.(?:title|place)\.en|galleryLabels\.(?:photos|photo|open|intro|total)\.en", text)
    if fixed_english:
        issues.append("protests.js: dynamic gallery is fixed to English")
    required_code = (
        "event.title[lang]", "event.place[lang]", "galleryLabels.open[lang]",
        "image.alt =", "site-language-change", "event.detail.language",
    )
    if any(value not in text for value in required_code) or "setAttribute('aria-label'" not in text:
        issues.append("protests.js: dynamic alt/aria/title/place language update is incomplete")
    return issues


def language_script_issues(text_override: str | None = None) -> list[str]:
    text = text_override if text_override is not None else (ROOT / "language.js").read_text(encoding="utf-8")
    issues = []
    required = (
        'localStorage.getItem("lang")', 'localStorage.setItem("lang", lang)',
        'new CustomEvent("site-language-change"', "detail: { language:",
        'document.documentElement.setAttribute("lang"', "try {", "catch (_error)",
    )
    if any(value not in text for value in required):
        issues.append("language.js: safe persistence, html lang, or language event is incomplete")
    return issues


def nav_footer_issues() -> list[str]:
    issues = []
    for name in PUBLIC_NAV_PAGES:
        soup = BeautifulSoup((ROOT / name).read_text(encoding="utf-8"), "html.parser")
        nav = soup.select_one(".main-nav")
        footer = soup.select_one(".site-footer")
        control = soup.select_one("#lang-toggle")
        menu = soup.select_one(".mobile-menu-btn")
        if nav is None or footer is None or control is None or menu is None:
            issues.append(f"{name}: navigation, footer, mobile menu, or language control is missing")
            continue
        if any(localized_classes(link) != set(LANGS) for link in nav.select("a")):
            issues.append(f"{name}: a navigation label lacks ten languages")
        if len(control.select("option")) != len(LANGS) or {option.get("value") for option in control.select("option")} != set(LANGS):
            issues.append(f"{name}: language selector is incomplete")
        footer_groups = footer.select(".footer-links a, .footer-copy p")
        if not footer_groups or any(localized_classes(group) != set(LANGS) for group in footer_groups):
            issues.append(f"{name}: footer labels lack ten languages")
        if not menu.get("data-i18n-aria") or not nav.get("data-i18n-aria"):
            issues.append(f"{name}: mobile navigation localization hooks are missing")
    return issues


def public_page_checks() -> list[str]:
    issues = []
    documents = {}
    for name in PUBLIC_PAGES:
        path = ROOT / name
        soup = BeautifulSoup(path.read_text(encoding="utf-8"), "html.parser")
        documents[name] = soup
        issues.extend(f"{name}: {issue}" for issue in public_page_issues(soup, path))
        issues.extend(traditional_chinese_issues(soup, name))
    issues.extend(f"privacy.html: {issue}" for issue in privacy_issues(documents["privacy.html"]))
    issues.extend(f"about.html: {issue}" for issue in about_issues(documents["about.html"]))
    issues.extend(f"terms.html: {issue}" for issue in terms_issues(documents["terms.html"]))
    issues.extend(f"contact.html: {issue}" for issue in contact_page_issues(documents["contact.html"]))
    issues.extend(f"sources.html: {issue}" for issue in sources_issues(documents["sources.html"]))
    issues.extend(f"index.html: {issue}" for issue in index_contact_issues(
        BeautifulSoup((ROOT / "index.html").read_text(encoding="utf-8"), "html.parser")
    ))
    issues.extend(nav_footer_issues())
    issues.extend(protests_script_issues())
    issues.extend(language_script_issues())
    issues.extend(semantic_review_issues())
    return issues


def semantic_fact_contract_issues(soup: BeautifulSoup, path: Path) -> list[str]:
    """Validate page-specific facts independently from byte and length gates."""
    if path.name != "hu-xinyu-disappearance.html":
        return []
    issues: list[str] = []
    expected_sections = (
        "overview", "timeline", "evidence", "state-machinery",
        "rights-analysis", "protection", "sources",
    )
    expected_sources = tuple(f"hx-s{number}" for number in range(1, 12))
    expected_facts = set(HU_XINYU_FACT_SECTIONS)
    reference_fact_signature = None
    for lang in LANGS:
        body = body_for(soup, lang)
        if body is None:
            continue
        sections = tuple(node.get("data-section") for node in body.select("h2[data-section]"))
        if sections != expected_sections:
            issues.append(f"{lang}: Hu Xinyu semantic section order changed")

        source_nodes = body.select("ul.source-list > li[data-source-id]")
        source_ids = tuple(node.get("data-source-id") for node in source_nodes)
        if source_ids != expected_sources or len(source_ids) != len(set(source_ids)):
            issues.append(f"{lang}: Hu Xinyu source IDs/order/uniqueness changed")
        source_id_set = set(source_ids)

        fact_nodes = body.select("[data-fact-id]")
        counts = Counter(node.get("data-fact-id") for node in fact_nodes)
        fact_ids = set(counts)
        if fact_ids != expected_facts:
            issues.append(f"{lang}: Hu Xinyu fact-ID set changed")
        duplicated = sorted(fact_id for fact_id, count in counts.items() if count != 1)
        if duplicated:
            issues.append(f"{lang}: Hu Xinyu fact IDs are not unique: {duplicated[:3]}")

        signature = tuple(sorted((node.get("data-fact-id"), node.get("data-source-ref", "")) for node in fact_nodes))
        if reference_fact_signature is None:
            reference_fact_signature = signature
        elif signature != reference_fact_signature:
            issues.append(f"{lang}: Hu Xinyu fact/source-ref signature differs from Chinese")

        for node in fact_nodes:
            fact_id = node.get("data-fact-id")
            if fact_id not in expected_facts:
                continue
            heading = node.find_previous("h2")
            section_id = heading.get("data-section") if heading else None
            if section_id != HU_XINYU_FACT_SECTIONS[fact_id]:
                issues.append(f"{lang}: {fact_id} moved to {section_id or 'no section'}")
            refs = tuple(node.get("data-source-ref", "").split())
            if not refs or any(ref not in source_id_set for ref in refs):
                issues.append(f"{lang}: {fact_id} has a missing or unresolved source ref")
            pattern = HU_XINYU_VISIBLE_FACT_PATTERNS.get(fact_id)
            if pattern and not pattern.search(node.get_text(" ", strip=True)):
                issues.append(f"{lang}: {fact_id} lost a required visible fact chain")

        for fact_id, expected in HU_XINYU_TIMELINE_CONTRACTS.items():
            node = body.select_one(f'[data-fact-id="{fact_id}"]')
            actual = (
                node.get("data-timeline-subject") if node else None,
                node.get("data-timeline-action") if node else None,
                node.get("data-timeline-consequence") if node else None,
            )
            if actual != expected:
                issues.append(f"{lang}: {fact_id} lost subject/action/consequence")

        for fact_id, expected in HU_XINYU_DISPUTE_CONTRACTS.items():
            node = body.select_one(f'[data-fact-id="{fact_id}"]')
            matrix = set((node.get("data-dispute-matrix", "") if node else "").split())
            actual = (
                node.get("data-inference-subject") if node else None,
                node.get("data-official-response") if node else None,
                node.get("data-response-gap") if node else None,
                node.get("data-accountability") if node else None,
            )
            if matrix != {"fact", "inference-subject", "official-response", "response-gap", "accountability"}:
                issues.append(f"{lang}: {fact_id} lost the five-layer dispute matrix")
            if actual != expected:
                issues.append(f"{lang}: {fact_id} changed inference, response, gap, or accountability")
        rights = body.select_one('[data-fact-id="hu-xinyu-rights-analysis"]')
        protection = body.select_one('[data-fact-id="hu-xinyu-protection"]')
        if set((rights.get("data-rights-contract", "") if rights else "").split()) != {
            "state-protection-reversal", "second-harm", "independent-constraints",
            "targeted-international-accountability",
        }:
            issues.append(f"{lang}: Hu Xinyu rights conclusion lost responsibility logic")
        if set((protection.get("data-protection-contract", "") if protection else "").split()) != {
            "identification-pressure", "family-linkage", "cross-border-risk",
            "independent-remedy", "non-collective-accountability",
        }:
            issues.append(f"{lang}: Hu Xinyu protection conclusion lost risk or remedy logic")
    return issues


def reviewed_report_contract_issues(soup: BeautifulSoup, path: Path) -> list[str]:
    contract = REVIEWED_REPORT_CONTRACTS.get(path.name)
    if contract is None:
        return []
    issues: list[str] = []
    expected_sections = (
        "overview", "timeline", "evidence", "state-machinery",
        "rights-analysis", "protection", "sources",
    )
    expected_facts = set(contract["fact_sections"])
    expected_sources = contract["source_ids"]
    reference_signature = None
    slug = path.stem
    for lang in LANGS:
        body = body_for(soup, lang)
        if body is None:
            continue
        sections = tuple(node.get("data-section") for node in body.select("h2[data-section]"))
        if sections != expected_sections:
            issues.append(f"{lang}: {slug} semantic section order changed")
        source_nodes = body.select("ul.source-list > li[data-source-id]")
        source_ids = tuple(node.get("data-source-id") for node in source_nodes)
        if source_ids != expected_sources or len(source_ids) != len(set(source_ids)):
            issues.append(f"{lang}: {slug} source IDs/order/uniqueness changed")
        source_id_set = set(source_ids)
        fact_nodes = body.select("[data-fact-id]")
        counts = Counter(node.get("data-fact-id") for node in fact_nodes)
        if set(counts) != expected_facts:
            issues.append(f"{lang}: {slug} fact-ID set changed")
        if any(count != 1 for count in counts.values()):
            issues.append(f"{lang}: {slug} fact IDs are not unique")
        signature = tuple(sorted((node.get("data-fact-id"), node.get("data-source-ref", "")) for node in fact_nodes))
        if reference_signature is None:
            reference_signature = signature
        elif signature != reference_signature:
            issues.append(f"{lang}: {slug} fact/source-ref signature differs from Chinese")
        for node in fact_nodes:
            fact_id = node.get("data-fact-id")
            if fact_id not in expected_facts:
                continue
            heading = node.find_previous("h2")
            section_id = heading.get("data-section") if heading else None
            if section_id != contract["fact_sections"][fact_id]:
                issues.append(f"{lang}: {fact_id} moved to {section_id or 'no section'}")
            refs = tuple(node.get("data-source-ref", "").split())
            if not refs or any(ref not in source_id_set for ref in refs):
                issues.append(f"{lang}: {fact_id} has a missing or unresolved source ref")
            pattern = contract["visible"].get(fact_id)
            if pattern and not pattern.search(node.get_text(" ", strip=True)):
                issues.append(f"{lang}: {fact_id} lost a required visible fact chain")
        for fact_id, expected in contract["timeline"].items():
            node = body.select_one(f'[data-fact-id="{fact_id}"]')
            actual = (
                node.get("data-timeline-subject") if node else None,
                node.get("data-timeline-action") if node else None,
                node.get("data-timeline-consequence") if node else None,
            )
            if actual != expected:
                issues.append(f"{lang}: {fact_id} lost subject/action/consequence")
        gap = body.select_one(f'[data-fact-id="{slug}-evidence-official-gap"]')
        matrix = set((gap.get("data-dispute-matrix", "") if gap else "").split())
        actual_dispute = (
            gap.get("data-inference-subject") if gap else None,
            gap.get("data-official-response") if gap else None,
            gap.get("data-response-gap") if gap else None,
            gap.get("data-accountability") if gap else None,
        )
        if matrix != {"fact", "inference-subject", "official-response", "response-gap", "accountability"}:
            issues.append(f"{lang}: {slug} official gap lost the five-layer dispute matrix")
        if actual_dispute != contract["dispute"]:
            issues.append(f"{lang}: {slug} changed inference, response, gap, or accountability")
        rights = body.select_one(f'[data-fact-id="{slug}-rights-analysis"]')
        protection = body.select_one(f'[data-fact-id="{slug}-protection"]')
        if set((rights.get("data-rights-contract", "") if rights else "").split()) != {
            "state-protection-reversal", "second-harm", "independent-constraints",
            "targeted-international-accountability",
        }:
            issues.append(f"{lang}: {slug} rights conclusion lost responsibility logic")
        if set((protection.get("data-protection-contract", "") if protection else "").split()) != {
            "identification-pressure", "family-linkage", "cross-border-risk",
            "independent-remedy", "non-collective-accountability",
        }:
            issues.append(f"{lang}: {slug} protection conclusion lost risk or remedy logic")
    return issues


def required_section_nodes(body, section_id: str):
    heading = body.select_one(f'h2[data-section="{section_id}"]')
    if heading is None:
        return []
    nodes = [heading]
    node = heading.find_next_sibling()
    while node is not None and node.name != "h2":
        nodes.append(node)
        node = node.find_next_sibling()
    return nodes


def reviewed_section_digest(body, section_id: str) -> str:
    nodes = required_section_nodes(body, section_id)
    payload = "\n".join(re.sub(r"\s+", " ", str(node)).strip() for node in nodes)
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()[:20]


def semantic_number_tokens(text: str) -> set[str]:
    """Return translation-stable multi-digit tokens without punctuation."""
    tokens = set()
    for raw in re.findall(r"\d+(?:(?:[,.，]\s*|\s+)\d+)*", text):
        parts = re.findall(r"\d+", raw)
        tokens.update(part for part in parts if len(part) >= 2)
        is_thousands = len(parts) > 1 and len(parts[0]) <= 3 and all(
            len(part) == 3 for part in parts[1:]
        )
        is_decimal = len(parts) > 1 and len(parts[-1]) <= 2 and bool(re.search(r"[,.，]", raw))
        if is_thousands or is_decimal:
            tokens.add("".join(parts))
    return tokens


