def source_date_contract_issues(soup: BeautifulSoup, path: Path) -> list[str]:
    contract = SOURCE_DATE_CONTRACTS.get(path.name)
    if not contract:
        return []
    issues = []
    for lang in LANGS:
        body = body_for(soup, lang)
        if body is None:
            continue
        for source_id, expected_date in contract.items():
            node = body.select_one(f'ul.source-list > li[data-source-id="{source_id}"]')
            time = node.find("time") if node else None
            visible = time.get_text(" ", strip=True) if time else ""
            if (
                node is None
                or node.get("data-source-date") != expected_date
                or expected_date not in node.get_text(" ", strip=True)
                or (time is not None and (time.get("datetime") != expected_date or visible != expected_date))
            ):
                issues.append(f"{lang}: {path.stem} {source_id} source date must be {expected_date} in metadata and visible time")
    return issues


