def batch10_final3_source_date_transition_issues(
    rows: list[dict[str, str]],
) -> list[str]:
    """Authorize only the two Yang Jisheng spelling fields from final2."""
    issues: list[str] = []
    matches = [
        row for row in rows
        if (row.get("slug", ""), row.get("source_id", ""))
        == ("great-leap-famine", "s4")
    ]
    if len(matches) != 1:
        return ["source-date final3 must contain exactly one great-leap-famine/s4 row"]
    row = matches[0]
    expected_locator = (
        "https://www.publishersweekly.com/9780374277932 | article body paragraphs 1–12, "
        "including the chronology and attributed findings under "
        + BATCH10_FINAL3_GLF_S4_TITLE
    )
    if row.get("title_zh", "") != BATCH10_FINAL3_GLF_S4_TITLE:
        issues.append("source-date final3 great-leap-famine/s4 title_zh does not name 楊繼繩")
    if row.get("evidence_locator", "") != expected_locator:
        issues.append("source-date final3 great-leap-famine/s4 evidence locator does not name 楊繼繩")

    protected_records = ["\x1f".join(SOURCE_DATE_LEDGER_COLUMNS)]
    for current in rows:
        projected = dict(current)
        if (
            projected.get("slug", ""), projected.get("source_id", "")
        ) == ("great-leap-famine", "s4"):
            projected["title_zh"] = "<BATCH10_FINAL3_AUTHORIZED_TITLE>"
            projected["evidence_locator"] = "<BATCH10_FINAL3_AUTHORIZED_LOCATOR>"
        protected_records.append(
            "\x1f".join(projected.get(field, "") for field in SOURCE_DATE_LEDGER_COLUMNS)
        )
    protected_digest = sha256_bytes("\x1e".join(protected_records).encode("utf-8"))
    if protected_digest != BATCH10_FINAL3_SOURCE_DATE_PROTECTED_SHA256:
        issues.append("source-date final3 changed a field outside the two authorized name corrections")

    # Restore the two old spellings and authenticate the exact final2 file.
    # This proves an authorized transition rather than merely accepting the
    # current row as its own baseline.
    restored = [dict(current) for current in rows]
    for current in restored:
        if (
            current.get("slug", ""), current.get("source_id", "")
        ) == ("great-leap-famine", "s4"):
            current["title_zh"] = BATCH10_FINAL3_GLF_S4_OLD_TITLE
            current["evidence_locator"] = expected_locator.replace("楊繼繩", "楊繼勝")
    buffer = io.StringIO(newline="")
    writer = csv.DictWriter(
        buffer, fieldnames=SOURCE_DATE_LEDGER_COLUMNS,
        delimiter="\t", lineterminator="\n",
    )
    writer.writeheader()
    writer.writerows(restored)
    if sha256_bytes(buffer.getvalue().encode("utf-8")) != BATCH10_FINAL2_SOURCE_DATE_SHA256:
        issues.append("source-date final3 does not reconstruct the exact authenticated final2 preimage")
    return issues


def load_source_date_ledger(
    rows_override: list[dict[str, str]] | None = None,
    *,
    require_file: bool = True,
) -> tuple[list[dict[str, str]], set[str], list[str]]:
    if rows_override is not None:
        rows = rows_override
        fields = set(rows[0]) if rows else set()
    elif SOURCE_DATE_LEDGER_PATH.exists():
        with SOURCE_DATE_LEDGER_PATH.open(encoding="utf-8", newline="") as handle:
            reader = csv.DictReader(handle, delimiter="\t")
            rows = list(reader)
            fields = set(reader.fieldnames or ())
    else:
        message = f"source-date ledger missing: {SOURCE_DATE_LEDGER_PATH}"
        return [], set(), [message] if require_file else []
    missing = SOURCE_DATE_LEDGER_FIELDS - fields
    return rows, fields, ([f"source-date ledger missing fields: {', '.join(sorted(missing))}"] if missing else [])


def source_date_ledger_predecessor_bytes() -> bytes:
    """The source-date ledger as every pre-batch14 gate froze it.

    Batch fourteen appends the 51 sources first cited by its ten dossiers.  The
    294-row base stays a byte-authenticated prefix, so a predecessor freeze is
    replayed against that prefix rather than being relaxed or re-pinned.  If the
    prefix ever stops authenticating, the live bytes are returned and the
    predecessor gate fires exactly as it did before.
    """
    if not SOURCE_DATE_LEDGER_PATH.exists():
        return b""
    raw = SOURCE_DATE_LEDGER_PATH.read_bytes()
    lines = raw.decode("utf-8").split("\n")
    prefix = "\n".join(
        lines[:1 + BATCH12_SOURCE_DATE_BASE_ROWS]
    ).encode("utf-8") + b"\n"
    if sha256_bytes(prefix) == BATCH12_SOURCE_DATE_BASE_SHA256:
        return prefix
    return raw

def source_date_ledger_predecessor_rows() -> list[dict[str, str]]:
    """The source-date ledger rows as every pre-batch14 gate froze them.

    The 294-row base is a byte-authenticated prefix; batch fourteen's appended
    rows sit after it and are checked by source_date_ledger_issues and by the
    batch14 gates.  If the prefix stops authenticating, the full row list is
    returned so the predecessor count assertion fires exactly as before.
    """
    rows = load_source_date_ledger(require_file=True)[0]
    raw = SOURCE_DATE_LEDGER_PATH.read_bytes() if SOURCE_DATE_LEDGER_PATH.exists() else b""
    prefix = "\n".join(
        raw.decode("utf-8").split("\n")[:1 + BATCH12_SOURCE_DATE_BASE_ROWS]
    ).encode("utf-8") + b"\n"
    if sha256_bytes(prefix) == BATCH12_SOURCE_DATE_BASE_SHA256:
        return rows[:BATCH12_SOURCE_DATE_BASE_ROWS]
    return rows

def batch12_effective_source_date_rows(
    rows: list[dict[str, str]],
    corrections_override: list[dict[str, str]] | None = None,
) -> tuple[list[dict[str, str]], list[str]]:
    """Apply the single append-only batch12 TNR/s1 correction.

    The 294-row historical ledger remains byte-authenticated and is never
    rewritten.  This overlay is the only current conclusion allowed to
    supersede one of those rows.
    """
    issues: list[str] = []
    issues.extend(
        exact_tsv_prefix_issues(
            SOURCE_DATE_LEDGER_PATH,
            base_rows=BATCH12_SOURCE_DATE_BASE_ROWS,
            expected_sha256=BATCH12_SOURCE_DATE_BASE_SHA256,
            label="batch12 source-date 294-row base",
        )
    )
    if len(rows) < BATCH12_SOURCE_DATE_BASE_ROWS:
        issues.append(
            "batch12 source-date base must remain exactly 294 rows"
        )
    elif len(rows) > BATCH12_SOURCE_DATE_BASE_ROWS:
        # Batch fourteen appends the source-date rows for its ten new dossiers
        # after the batch12 base.  The 294-row base itself stays a
        # byte-authenticated prefix (asserted just above); every row beyond it
        # must belong to a batch14 dossier, so the append cannot be used to
        # slip a change into a historical source.
        stray = sorted({
            row.get("slug", "")
            for row in rows[BATCH12_SOURCE_DATE_BASE_ROWS:]
            if row.get("slug", "") not in BATCH14_NEW_SLUG_SET
        })
        if stray:
            issues.append(
                "batch12 source-date base gained rows outside batch14: "
                + ", ".join(stray)
            )
    if corrections_override is None:
        if not BATCH12_SOURCE_DATE_CORRECTIONS_PATH.exists():
            return rows, issues + [
                "batch12 source-date correction overlay is missing"
            ]
        raw = BATCH12_SOURCE_DATE_CORRECTIONS_PATH.read_bytes()
        if sha256_bytes(raw) != BATCH12_SOURCE_DATE_CORRECTION_SHA256:
            issues.append(
                "batch12 source-date correction overlay bytes changed"
            )
        with BATCH12_SOURCE_DATE_CORRECTIONS_PATH.open(
            encoding="utf-8", newline=""
        ) as handle:
            reader = csv.DictReader(handle, delimiter="\t")
            corrections = list(reader)
            fields = tuple(reader.fieldnames or ())
    else:
        corrections = corrections_override
        fields = (
            tuple(corrections[0])
            if corrections
            else BATCH12_SOURCE_DATE_CORRECTION_COLUMNS
        )
        if batch12_tsv_rows_sha256(corrections, fields) != (
            BATCH12_SOURCE_DATE_CORRECTION_SHA256
        ):
            issues.append(
                "batch12 in-memory source-date correction changed"
            )
    if fields != BATCH12_SOURCE_DATE_CORRECTION_COLUMNS:
        issues.append(
            "batch12 source-date correction columns or order changed"
        )
    if len(corrections) != 1:
        return rows, issues + [
            "batch12 source-date correction must contain exactly one row"
        ]
    correction = corrections[0]
    for field, expected in BATCH12_SOURCE_DATE_CORRECTION_EXPECTED.items():
        if correction.get(field, "") != expected:
            issues.append(
                f"batch12 source-date correction {field} changed"
            )
    for field in ("authority_locator", "correction_reason"):
        if len(correction.get(field, "").strip()) < 80:
            issues.append(
                f"batch12 source-date correction {field} lacks audit detail"
            )

    key = (
        BATCH12_SOURCE_DATE_CORRECTION_EXPECTED["slug"],
        BATCH12_SOURCE_DATE_CORRECTION_EXPECTED["source_id"],
    )
    matches = [
        row for row in rows
        if (row.get("slug", ""), row.get("source_id", "")) == key
    ]
    if len(matches) != 1:
        return rows, issues + [
            "batch12 source-date base lacks exactly one TNR/s1 row"
        ]
    base = matches[0]
    old_fields = {
        "source_type": "old_source_type",
        "url": "old_url",
        "title_zh": "old_title_zh",
        "audited_date": "old_audited_date",
        "verification_status": "old_verification_status",
    }
    for base_field, correction_field in old_fields.items():
        if base.get(base_field, "") != correction.get(
            correction_field, ""
        ):
            issues.append(
                "batch12 source-date correction does not reconstruct "
                f"historical TNR/s1 {base_field}"
            )

    effective = [dict(row) for row in rows]
    for row in effective:
        if (row.get("slug", ""), row.get("source_id", "")) != key:
            continue
        row["source_type"] = correction.get("new_source_type", "")
        row["url"] = correction.get("new_url", "")
        row["audited_date"] = correction.get("new_audited_date", "")
        row["precision"] = correction.get("new_precision", "")
        row["verification_status"] = correction.get(
            "new_verification_status", ""
        )
        row["evidence_locator"] = correction.get("authority_locator", "")
        row["accessed_at"] = correction.get("accessed_at", "")
        row["note"] = correction.get("correction_reason", "")
    return effective, issues


def source_date_ledger_issues(
    documents: dict[Path, BeautifulSoup] | None = None,
    rows_override: list[dict[str, str]] | None = None,
    corrections_override: list[dict[str, str]] | None = None,
    *,
    require_file: bool = True,
) -> list[str]:
    """Audit every source group against the visible ten-language DOM."""
    rows, _fields, issues = load_source_date_ledger(rows_override, require_file=require_file)
    if issues:
        return issues
    historical_base_rows = rows
    rows, correction_issues = batch12_effective_source_date_rows(
        rows, corrections_override
    )
    issues.extend(correction_issues)
    documents = documents or loaded_documents()
    # Batch11-final1 may append exactly one HK12/s6 row.  Historical final3
    # authentication must continue to review only the original 293-row file;
    # otherwise the new row would silently become part of an old baseline.
    historical_rows = historical_base_rows[
        :BATCH11_FINAL1_SOURCE_DATE_PREFIX_ROWS
    ]
    issues.extend(batch10_final3_source_date_transition_issues(historical_rows))
    protected_rows = [
        row for row in historical_rows
        if row.get("slug", "") not in BATCH10_TARGET_SLUGS
    ]
    protected_records = ["\x1f".join(SOURCE_DATE_LEDGER_COLUMNS)] + [
        "\x1f".join((row.get(field) or "") for field in SOURCE_DATE_LEDGER_COLUMNS)
        for row in protected_rows
    ]
    protected_payload = "\x1e".join(protected_records).encode("utf-8")
    if len(protected_rows) != BATCH10_SOURCE_DATE_PROTECTED_ROWS:
        issues.append(
            "source-date ledger batch10 protected-row count changed: "
            f"{len(protected_rows)} != {BATCH10_SOURCE_DATE_PROTECTED_ROWS}"
        )
    if sha256_bytes(protected_payload) != BATCH10_SOURCE_DATE_PROTECTED_SHA256:
        issues.append("source-date ledger batch10 changed a final2 or non-target row")
    row_keys = [(row.get("slug", ""), row.get("source_id", "")) for row in rows]
    row_counts = Counter(row_keys)
    duplicates = sorted(key for key, count in row_counts.items() if count != 1)
    if duplicates:
        issues.append(f"source-date ledger duplicate source groups: {duplicates[:3]}")
    ledger = {key: row for key, row in zip(row_keys, rows)}
    expected_keys: set[tuple[str, str]] = set()

    for path, soup in documents.items():
        bodies = {lang: body_for(soup, lang) for lang in LANGS}
        zh_nodes = bodies["zh"].select("ul.source-list > li[data-source-id]") if bodies["zh"] else []
        expected_keys.update((path.stem, node.get("data-source-id", "")) for node in zh_nodes)
        signatures: dict[str, list[tuple[str, str, str, str]]] = {}
        for lang, body in bodies.items():
            if body is None:
                continue
            signatures[lang] = []
            for node in body.select("ul.source-list > li[data-source-id]"):
                source_id = node.get("data-source-id", "")
                link = node.find("a")
                date_value = node.get("data-source-date", "")
                signatures[lang].append((
                    source_id,
                    node.get("data-source-type", ""),
                    link.get("href", "") if link else "",
                    date_value,
                ))
                row = ledger.get((path.stem, source_id))
                if row is None:
                    continue
                expected_date = row.get("audited_date", "")
                time = node.find("time")
                if expected_date == "UNDATED":
                    marker = node.select_one('.source-date-undated[data-date-status="UNDATED"]')
                    if date_value or time is not None or marker is None or not marker.get_text(" ", strip=True):
                        issues.append(f"{lang}: {path.stem} {source_id} must expose a localized UNDATED marker and no precise date")
                else:
                    visible = time.get_text(" ", strip=True) if time else ""
                    datetime_value = time.get("datetime", "") if time else ""
                    if date_value != expected_date:
                        issues.append(f"{lang}: {path.stem} {source_id} data-source-date differs from audited date {expected_date}")
                    if time is None or visible != expected_date:
                        issues.append(f"{lang}: {path.stem} {source_id} visible source date differs from audited date {expected_date}")
                    if time is None or datetime_value != expected_date:
                        issues.append(f"{lang}: {path.stem} {source_id} time datetime differs from audited date {expected_date}")
                if node.get("data-source-type", "") != row.get("source_type", ""):
                    issues.append(f"{lang}: {path.stem} {source_id} source type differs from the source-date ledger")
                if (link.get("href", "") if link else "") != row.get("url", ""):
                    issues.append(f"{lang}: {path.stem} {source_id} URL differs from the source-date ledger")
        baseline = signatures.get("zh", [])
        for lang in LANGS[1:]:
            if signatures.get(lang, []) != baseline:
                issues.append(f"{path.stem}: {lang} source ID/order/type/URL/date signature differs from zh")

    missing = sorted(expected_keys - set(row_keys))
    extra = sorted(set(row_keys) - expected_keys)
    if missing or extra:
        issues.append(f"source-date ledger coverage differs; missing={missing[:3]} extra={extra[:3]}")
    if len(expected_keys) != EXPECTED_SOURCE_GROUPS:
        issues.append(
            f"source-date DOM has {len(expected_keys)} unique sources, expected {EXPECTED_SOURCE_GROUPS}"
        )

    allowed_statuses = {
        "VERIFIED_SOURCE_DATE", "MANUAL_REVIEW_REQUIRED",
        "UNDATED_CONFIRMED", "CORRECTED_VERIFIED_SOURCE_DATE",
    }
    for index, row in enumerate(rows, start=2):
        date_value = row.get("audited_date", "")
        precision = row.get("precision", "")
        status = row.get("verification_status", "")
        if not SOURCE_DATE_VALUE.fullmatch(date_value):
            issues.append(f"source-date ledger row {index}: invalid audited_date {date_value!r}")
        expected_precision = "none" if date_value == "UNDATED" else {4: "year", 7: "month", 10: "day"}.get(len(date_value), "")
        if precision != expected_precision:
            issues.append(f"source-date ledger row {index}: precision {precision!r} does not match {date_value!r}")
        if status not in allowed_statuses:
            issues.append(f"source-date ledger row {index}: invalid verification_status {status!r}")
        if date_value == "UNDATED" and status != "UNDATED_CONFIRMED":
            issues.append(f"source-date ledger row {index}: UNDATED must be explicitly confirmed")
        if date_value != "UNDATED" and status == "UNDATED_CONFIRMED":
            issues.append(f"source-date ledger row {index}: precise date cannot be marked UNDATED_CONFIRMED")
        if date_value.endswith("-01-01"):
            issues.append(f"source-date ledger row {index}: suspicious unsupported YYYY-01-01 default remains")
        if any(not row.get(field, "").strip() for field in ("source_type", "url", "title_zh", "evidence_locator", "accessed_at", "note")):
            issues.append(f"source-date ledger row {index}: audit evidence or source identity is incomplete")
    return issues


def source_date_audit_statistics(documents: dict[Path, BeautifulSoup] | None = None) -> dict[str, object]:
    documents = documents or loaded_documents()
    rows, _fields, _issues = load_source_date_ledger(require_file=False)
    rows, _correction_issues = batch12_effective_source_date_rows(rows)
    status_counts = Counter(row.get("verification_status", "") for row in rows)
    stats: dict[str, object] = {
        "unique_sources": 0,
        "blank_dates": 0,
        "attr_visible_conflicts": 0,
        "datetime_visible_conflicts": 0,
        "cross_language_inconsistencies": 0,
        "suspicious_01_01": 0,
        "undated": status_counts.get("UNDATED_CONFIRMED", 0),
        "manual": status_counts.get("MANUAL_REVIEW_REQUIRED", 0),
    }
    for path, soup in documents.items():
        signatures = []
        for lang in LANGS:
            body = body_for(soup, lang)
            rows_for_lang = []
            for node in body.select("ul.source-list > li[data-source-id]") if body else []:
                source_id = node.get("data-source-id", "")
                date_value = node.get("data-source-date", "")
                time = node.find("time")
                visible = time.get_text(" ", strip=True) if time else ""
                datetime_value = time.get("datetime", "") if time else ""
                link = node.find("a")
                rows_for_lang.append((source_id, node.get("data-source-type", ""), link.get("href", "") if link else "", date_value))
                if lang == "zh":
                    stats["unique_sources"] += 1
                    stats["blank_dates"] += int(not date_value)
                    stats["attr_visible_conflicts"] += int(time is not None and date_value != visible)
                    stats["datetime_visible_conflicts"] += int(time is not None and datetime_value != visible)
                    stats["suspicious_01_01"] += int(date_value.endswith("-01-01"))
            signatures.append(rows_for_lang)
        stats["cross_language_inconsistencies"] += sum(1 for signature in signatures[1:] if signature != signatures[0])
    return stats


JIANG_COURT_VISIBLE = {
    "zh": re.compile(r"長沙市中級人民法院"),
    "en": re.compile(r"Changsha Intermediate People['’]s Court", re.I),
    "ja": re.compile(r"長沙市中級人民法院"),
    "ko": re.compile(r"창사시 중급인민법원"),
    "es": re.compile(r"Tribunal Popular Intermedio de Changsha", re.I),
    "de": re.compile(r"Mittlere(?:n|s)? Volksgericht Changsha", re.I),
    "fr": re.compile(r"tribunal populaire intermédiaire de Changsha", re.I),
    "no": re.compile(r"folkedomstolen på mellomnivå i Changsha", re.I),
    "nl": re.compile(r"intermediaire volksrechtbank van Changsha", re.I),
    "it": re.compile(r"Corte intermedia del popolo di Changsha", re.I),
}
JIANG_PLURAL_REFERENCES = {
    "zh": re.compile(r"他們|他们"),
    "en": re.compile(r"\b(?:they|them|their|themselves)\b", re.I),
    "ja": re.compile(r"彼ら|彼女ら|同人ら"),
    "ko": re.compile(r"그들(?:은|을|의|에게)?|이들(?:은|을|의|에게)?"),
    "es": re.compile(r"\b(?:ellos|ellas|los detuvieron|les condenaron)\b", re.I),
    "de": re.compile(r"\b(?:sie wurden|ihnen|deren)\b", re.I),
    "fr": re.compile(r"\b(?:ils|elles|leur ont|les ont)\b", re.I),
    "no": re.compile(r"\b(?:de ble|dem|deres)\b", re.I),
    "nl": re.compile(r"\b(?:zij werden|hen|hun)\b", re.I),
    "it": re.compile(r"\b(?:essi|loro|li hanno|sono stati)\b", re.I),
}


def jiang_tianyong_issues(soup: BeautifulSoup) -> list[str]:
    issues: list[str] = []
    venue = "changsha-intermediate-peoples-court-hunan"
    required_facts = (
        "jiang-tianyong-timeline-4", "jiang-tianyong-timeline-5",
        "jiang-tianyong-evidence-official-gap", "jiang-tianyong-state-1",
        "jiang-tianyong-rights-analysis", "jiang-tianyong-unresolved-questions",
    )
    for lang in LANGS:
        body = body_for(soup, lang)
        text = body.get_text(" ", strip=True) if body else ""
        if re.search(r"Tianjin|天津|톈진", text, re.I):
            issues.append(f"{lang}: Jiang Tianyong retains the wrong Tianjin court")
        court_pattern = JIANG_COURT_VISIBLE[lang]
        for fact_id in required_facts:
            node = body.select_one(f'[data-fact-id="{fact_id}"]') if body else None
            visible = node.get_text(" ", strip=True) if node else ""
            if node is None or not court_pattern.search(visible):
                issues.append(f"{lang}: {fact_id} lacks the visible Changsha Intermediate People's Court subject")
            if node is None or node.get("data-court-venue") != venue:
                issues.append(f"{lang}: {fact_id} court metadata does not match the Changsha venue")
        state = body.select_one('[data-fact-id="jiang-tianyong-state-1"]') if body else None
        state_text = state.get_text(" ", strip=True) if state else ""
        pattern = JIANG_PLURAL_REFERENCES.get(lang)
        if pattern and pattern.search(state_text):
            issues.append(f"{lang}: Jiang Tianyong state-machinery sentence uses a plural reference for one person")
        source = body.select_one('li[data-source-id="s2"]') if body else None
        source_link = source.find("a") if source else None
        source_text = source_link.get_text(" ", strip=True) if source_link else ""
        if not re.search(r"Changsha|長沙|창사", source_text, re.I) or not re.search(
            r"sentenc|判處|判决|判決|懲役|선고|conden|condamn|verurteil|dømt|dømte|veroordeel|condann", source_text, re.I
        ):
            issues.append(f"{lang}: Jiang Tianyong s2 title lacks both the Changsha court and sentencing action")
        timeline5 = body.select_one('[data-fact-id="jiang-tianyong-timeline-5"]') if body else None
        if timeline5 is None or timeline5.get("data-source-ref") != "s2":
            issues.append(f"{lang}: Jiang Tianyong sentencing fact must cite China Daily s2")
    return issues


def targeted_translation_issues(soup: BeautifulSoup, path: Path) -> list[str]:
    patterns = {
        "gao-yu.html": re.compile(
            r"effective relief|ayuda efectiva|wirksame Hilfe|aide efficace|sollievo efficace|"
            r"El periodista Gao Yu|Der Journalist Gao Yu|Le journaliste Gao Yu|Il giornalista Gao Yu",
            re.I,
        ),
        "jiang-tianyong.html": re.compile(r"effective relief|aiuto efficace", re.I),
        "hk-47.html": re.compile(r"Hong Kong[’']sono|effective relief|sollievo efficace", re.I),
    }
    pattern = patterns.get(path.name)
    return ([f"{path.stem}: forbidden translation or legal-remedy phrase remains"]
            if pattern and pattern.search(str(soup)) else [])


