def batch10_final2_contract_profile_name(slug: str, target_id: str) -> str | None:
    """Route a changed target to a fact requirement authored before TSV generation."""
    if slug == "liu-xiaobo":
        if target_id == "liu-xiaobo-timeline-3":
            return "liu-formal-arrest"
        if target_id == "liu-xiaobo-rights-analysis":
            return "liu-rights"
        if target_id == "liu-xiaobo-protection":
            return "liu-protection"
        return "liu-language"
    if slug == "tiananmen-1989":
        return {
            "article-title": "tian-title",
            "article-dek": "tian-dek",
            "tiananmen-1989-rights-analysis": "tian-rights",
            "tiananmen-1989-protection": "tian-protection",
            "tiananmen-1989-evidence-official-gap@data-accountability":
                "tian-accountability-attribute",
        }.get(target_id)
    if slug == "falun-gong-persecution":
        if target_id == "article-title":
            return "falun-title"
        if target_id == "article-dek":
            return "falun-dek"
        if target_id in {
            "falun-gong-persecution-evidence-1", "falun-gong-persecution-evidence-2",
        }:
            return "falun-evidence"
    if slug == "huang-qi" and target_id == "article-dek":
        return "huang-dek"
    if slug == "jiangyou-school-bullying-protests" and target_id == "article-dek":
        return "jiang-dek"
    if slug == "great-leap-famine":
        if target_id == "article-title":
            return "glf-title"
        if target_id == "article-dek":
            return "glf-dek"
        if target_id == "great-leap-famine-timeline-2":
            return "glf-policy-node"
        if target_id in {
            "great-leap-famine-evidence-1", "great-leap-famine-evidence-2",
        }:
            return "glf-evidence"
        return "glf-language"
    if slug == "land-reform-anti-rightist":
        if target_id == "article-title":
            return "land-title"
        if target_id == "article-dek":
            return "land-dek"
        if target_id == "land-reform-anti-rightist-timeline-5":
            return "land-policy-node"
        return "land-language"
    return None


def batch10_final2_contract_metadata_issues(row: dict[str, str]) -> list[str]:
    """Authenticate final2 semantic requirements without consulting live prose."""
    label = "/".join(
        row.get(field, "") for field in ("slug", "language", "target_kind", "target_id")
    )
    profile_name = batch10_final2_contract_profile_name(
        row.get("slug", ""), row.get("target_id", "")
    )
    if not profile_name or profile_name not in BATCH10_FINAL2_CONTRACT_PROFILES:
        return [f"batch10-final2 contract target has no independently authored profile: {label}"]
    required, forbidden, summary = BATCH10_FINAL2_CONTRACT_PROFILES[profile_name]
    issues: list[str] = []
    if tuple(contract_literals(row.get("required_all", ""))) != required:
        issues.append(f"batch10-final2 required invariant codes changed: {label}")
    if tuple(contract_literals(row.get("forbidden_any", ""))) != forbidden:
        issues.append(f"batch10-final2 forbidden invariant codes changed: {label}")
    if normalize_reread_text(row.get("fact_summary", "")) != normalize_reread_text(summary):
        issues.append(f"batch10-final2 authored fact summary changed: {label}")
    positive_fields = " ".join(
        row.get(field, "") for field in ("required_all", "fact_summary")
    ).casefold()
    if row.get("slug", "") == "tiananmen-1989" and "state-council" in positive_fields:
        issues.append(f"batch10-final2 Tiananmen contract restores unsupported state-council: {label}")
    return issues


def batch10_final3_contract_metadata_issues(row: dict[str, str]) -> list[str]:
    """Authenticate final3 contract duties without treating them as live text."""
    key = (
        row.get("slug", ""), row.get("language", ""),
        row.get("target_kind", ""), row.get("target_id", ""),
    )
    label = "/".join(key)
    issues: list[str] = []
    if key not in BATCH10_FINAL3_TARGETS:
        return [f"batch10-final3 contract target is outside the 15 reviewed changes: {label}"]
    required = contract_literals(row.get("required_all", ""))
    forbidden = contract_literals(row.get("forbidden_any", ""))
    summary = normalize_reread_text(row.get("fact_summary", "")).casefold()
    if key[0] == "tiananmen-1989":
        expected_required = (
            "source:state-department-chinese-government-public-figures",
            "source:amnesty-1990-foreign-media-witnesses-official-unofficial",
            "source:hrw-tiananmen-mothers-named-dead",
            "boundary:independent-records-estimates-different-sources-periods-methods",
            "consequence:public-record-incomplete-no-directly-additive-framework",
        )
        expected_forbidden = (
            "reject:imperative-no-add-or-merge",
            "reject:french-bad-prepositions-and-witness-noun",
        )
        if tuple(required) != expected_required or tuple(forbidden) != expected_forbidden:
            issues.append(f"batch10-final3 Tiananmen independent invariant profile changed: {label}")
        if not all(
            concept in summary
            for concept in (
                "state department", "amnesty", "tiananmen mothers",
                "independent", "public casualty record remains incomplete",
            )
        ):
            issues.append(f"batch10-final3 Tiananmen authored fact summary is incomplete: {label}")
    elif key[0] == "falun-gong-persecution":
        expected_required = (
            "actor:public-security-procuratorates-courts-detention-610",
            "action:detention-article300-surveillance-coercive-transformation",
            "rights:belief-life-no-torture-liberty-integrity-fair-trial-family-contact-violated",
            "attribution:human-rights-un-allegations-torture-death-testing-organs",
            "remedy:records-access-investigation-witness-protection-relief",
        )
        expected_forbidden = (
            "reject:weak-effect-language",
            "reject:allegation-upgrade-or-disclaimer",
        )
        if tuple(required) != expected_required or tuple(forbidden) != expected_forbidden:
            issues.append(f"batch10-final3 Falun independent invariant profile changed: {label}")
        if not all(
            concept in summary
            for concept in (
                "detention", "article 300", "surveillance", "violation",
                "torture and deaths in custody remain allegations", "human-rights sources",
            )
        ):
            issues.append(f"batch10-final3 Falun authored evidence boundary is incomplete: {label}")
    elif key[0] == "great-leap-famine":
        expected_required = (
            "source:publishers-weekly",
            "work:tombstone-china-great-famine-1958-1962",
            "author:yang-jisheng-correct-character",
            "boundary:metadata-identity-only",
            "consequence:source-title-and-ledger-agree",
        )
        expected_forbidden = (
            "reject:yang-name-wrong-final-character",
            "reject:source-metadata-change",
        )
        if tuple(required) != expected_required or tuple(forbidden) != expected_forbidden:
            issues.append(f"batch10-final3 Great Leap independent invariant profile changed: {label}")
        if not all(
            concept in summary
            for concept in ("publishers weekly", "traditional chinese name", "source id", "url", "date")
        ):
            issues.append(f"batch10-final3 Great Leap metadata-preservation summary is incomplete: {label}")
    elif key[0] == "land-reform-anti-rightist":
        expected_required = (
            "records:death-political-classification-property",
            "actors:work-teams-work-units-local-cadres",
            "labour:punitive-labour-labour-reform-rural-transfer",
            "remedy:education-occupation-property-reputation-restoration",
            "access:families-researchers-independent-archives",
        )
        expected_forbidden = (
            "reject:labour-punishment-calque",
            "reject:defamation-remedy-frame",
        )
        if tuple(required) != expected_required or tuple(forbidden) != expected_forbidden:
            issues.append(f"batch10-final3 Land independent invariant profile changed: {label}")
        if not all(
            concept in summary
            for concept in (
                "death", "political-classification", "property", "labour",
                "education", "occupation", "reputation-restoration", "archive-access",
            )
        ):
            issues.append(f"batch10-final3 Land authored historical/remedy summary is incomplete: {label}")
    return issues


