def final2_anchor_missing(text: str, anchors: tuple[str, ...]) -> list[str]:
    visible = normalized_contiguous_stream(text)
    return [
        anchor for anchor in anchors
        if normalized_contiguous_stream(anchor) not in visible
    ]


def batch10_final2_column_separation_issues(
    slug: str, lang: str, rights_text: str, protection_text: str,
) -> list[str]:
    """Detect sentence, fragment, and accountability-tail copying.

    This is deliberately stricter than the legacy overlap percentage: copying
    one complete final sentence must fail even when it is only one quarter of
    a longer paragraph.
    """
    issues: list[str] = []
    rights_parts = batch10_falun_sentence_parts(rights_text, lang)
    protection_parts = batch10_falun_sentence_parts(protection_text, lang)
    floor = 12 if lang in {"zh", "ja", "ko"} else 24
    rights_sentences = {
        normalized_contiguous_stream(part) for part in rights_parts
        if len(normalized_contiguous_stream(part)) >= floor
    }
    protection_sentences = {
        normalized_contiguous_stream(part) for part in protection_parts
        if len(normalized_contiguous_stream(part)) >= floor
    }
    if rights_sentences & protection_sentences:
        issues.append(
            f"{slug}/{lang}: normalized complete sentence duplicated across rights/protection"
        )

    fragment = longest_common_normalized_fragment(rights_text, protection_text)
    fragment_limit = 24 if lang in {"zh", "ja", "ko"} else 45
    if fragment >= fragment_limit:
        issues.append(
            f"{slug}/{lang}: long continuous fragment copied across rights/protection: {fragment}"
        )

    rights_last = normalized_contiguous_stream(rights_parts[-1]) if rights_parts else ""
    protection_last = normalized_contiguous_stream(protection_parts[-1]) if protection_parts else ""
    tail_floor = 18 if lang in {"zh", "ja", "ko"} else 30
    if rights_last and protection_last:
        match = difflib.SequenceMatcher(
            None, rights_last, protection_last, autojunk=False
        ).find_longest_match().size
        ratio = match / max(1, min(len(rights_last), len(protection_last)))
        if rights_last == protection_last or (match >= tail_floor and ratio >= 0.72):
            issues.append(
                f"{slug}/{lang}: same accountability ending copied across rights/protection"
            )
        common_suffix = 0
        for left, right in zip(reversed(rights_last), reversed(protection_last)):
            if left != right:
                break
            common_suffix += 1
        if common_suffix >= tail_floor:
            issues.append(
                f"{slug}/{lang}: same normalized final clause copied across rights/protection"
            )
    return issues


def batch10_final2_visible_semantic_issues(
    soup: BeautifulSoup, path: Path,
) -> list[str]:
    """Enforce final2 meanings independently of TSV rows and current hashes."""
    slug = path.stem
    if slug not in BATCH10_FINAL2_TARGET_SLUGS:
        return []
    issues: list[str] = []
    for lang in LANGS:
        body = body_for(soup, lang)
        if body is None:
            issues.append(f"{slug}/{lang}: final2 visible semantic body missing")
            continue
        title_node = soup.select_one(f".article-title .lang-{lang}")
        dek_node = soup.select_one(f".article-dek .lang-{lang}")
        title = normalize_reread_text(title_node.get_text(" ", strip=True) if title_node else "")
        dek = normalize_reread_text(dek_node.get_text(" ", strip=True) if dek_node else "")

        if slug in {"liu-xiaobo", "tiananmen-1989"}:
            rights = body.select_one(f'[data-fact-id="{slug}-rights-analysis"]')
            protection = body.select_one(f'[data-fact-id="{slug}-protection"]')
            rights_text = normalize_reread_text(rights.get_text(" ", strip=True) if rights else "")
            protection_text = normalize_reread_text(
                protection.get_text(" ", strip=True) if protection else ""
            )
            for kind, node, text, attribute in (
                ("rights", rights, rights_text, "data-rights-contract"),
                ("protection", protection, protection_text, "data-protection-contract"),
            ):
                target_id = f"{slug}-{'rights-analysis' if kind == 'rights' else 'protection'}"
                expected_attribute = BATCH10_FINAL2_COLUMN_ATTRS[(slug, target_id, attribute)]
                if node is None or node.get(attribute, "") != expected_attribute:
                    issues.append(
                        f"{slug}/{lang}/{kind}: final2 independent column attribute changed"
                    )
                missing = final2_anchor_missing(
                    text, BATCH10_FINAL2_COLUMN_ANCHORS[(slug, kind)][lang]
                )
                if missing:
                    issues.append(
                        f"{slug}/{lang}/{kind}: independent duty anchors missing: {missing[:3]}"
                    )
            issues.extend(
                batch10_final2_column_separation_issues(
                    slug, lang, rights_text, protection_text
                )
            )

        if slug == "liu-xiaobo":
            arrest = body.select_one('[data-fact-id="liu-xiaobo-timeline-3"]')
            arrest_text = normalize_reread_text(arrest.get_text(" ", strip=True) if arrest else "")
            if (
                arrest is None
                or not arrest_text.startswith("2009-06-23")
                or BATCH10_FINAL2_LIU_ARREST_ANCHORS[lang].casefold()
                not in arrest_text.casefold()
            ):
                issues.append(f"{slug}/{lang}: formal-arrest timeline fact is incomplete")
            if LIU_TIMELINE3_EDITORIAL_REJECTIONS.search(arrest_text):
                issues.append(f"{slug}/{lang}: editorial process explanation returned to timeline-3")
            if lang == "no" and re.search(r"\bvaretekt\b", body.get_text(" ", strip=True), re.I):
                issues.append(f"{slug}/{lang}: pretrial varetekt again describes sentence service")
            if lang == "ja" and "国家政権転覆扇動罪" not in body.get_text(" ", strip=True):
                issues.append(f"{slug}/{lang}: formal inciting-subversion charge grammar is incomplete")
            if lang == "es" and "fueron respondidas con" in body.get_text(" ", strip=True).casefold():
                issues.append(f"{slug}/{lang}: mechanical fueron respondidas con returned")

        elif slug == "tiananmen-1989":
            missing_title = final2_anchor_missing(
                title, BATCH10_FINAL2_TIAN_TITLE_ANCHORS[lang]
            )
            if missing_title:
                issues.append(
                    f"{slug}/{lang}: title lacks two independently bound subjects"
                )
            missing_dek = [
                concept for concept in BATCH10_FINAL2_TIAN_CARD_REQUIRED[lang]
                if concept.casefold() not in dek.casefold()
            ]
            if missing_dek:
                issues.append(
                    f"{slug}/{lang}: PLA/live-fire/protester/bystander/family-remedy deck chain missing"
                )
            for node in body.find_all(True):
                for name, value in node.attrs.items():
                    values = value if isinstance(value, list) else [str(value)]
                    if name.startswith("data-") and "state-council" in " ".join(values):
                        issues.append(
                            f"{slug}/{lang}: unsupported state-council actor returned in DOM attribute"
                        )
                        break

        elif slug == "falun-gong-persecution":
            visible = " ".join((title, dek, body.get_text(" ", strip=True)))
            if FALUN_PUBLIC_WORKFLOW_REJECTIONS.search(visible):
                issues.append(f"{slug}/{lang}: public editorial attribution workflow returned")
            if lang == "en" and ("Ban," not in title or "Banning" in title):
                issues.append(f"{slug}/{lang}: title does not use natural Ban wording")
            if lang == "ja" and "拘禁" not in title:
                issues.append(f"{slug}/{lang}: title does not use precise 拘禁 wording")
            missing_dek = [
                concept for concept in BATCH10_FINAL2_FALUN_CARD_REQUIRED[lang]
                if concept.casefold() not in dek.casefold()
            ]
            if missing_dek:
                issues.append(f"{slug}/{lang}: reader-facing allegation/remedy deck chain missing")

        elif slug == "huang-qi":
            if HUANG_ABSTRACT_REJECTIONS.search(dek):
                issues.append(f"{slug}/{lang}: abstract civil-information-space template returned")
            if not re.search(r"64\s*Tianwang|六四天網|六四天网", dek, re.I) or not all(
                date in dek for date in ("2016", "2019")
            ):
                issues.append(f"{slug}/{lang}: 64 Tianwang/2016 detention/2019 sentence chain missing")
            if lang == "no" and not all(
                term in dek.casefold()
                for term in ("mennesker som klaget", "oppsøkte myndighetene", "søke oppreisning")
            ):
                issues.append(f"{slug}/{lang}: petitioners are again abstract petition material")

        elif slug == "jiangyou-school-bullying-protests":
            sentences = batch10_falun_sentence_parts(dek, lang)
            if not any(
                all(re.search(pattern, sentence, re.I) for pattern in JIANG_POLICE_SENTENCE_TERMS[lang])
                for sentence in sentences
            ):
                issues.append(
                    f"{slug}/{lang}: police dispersal/baton/spray/removal chain missing"
                )

        elif slug == "great-leap-famine":
            full_names = {
                "de": "Großer Sprung nach vorn",
                "fr": "Grand Bond en avant",
                "nl": "Grote Sprong Voorwaarts",
                "it": "Grande balzo in avanti",
            }
            if lang in full_names and full_names[lang].casefold() not in title.casefold():
                issues.append(f"{slug}/{lang}: complete conventional program name missing")
            if GLF_EDITORIAL_REJECTIONS.search(" ".join((title, dek, body.get_text(" ", strip=True)))):
                issues.append(f"{slug}/{lang}: mortality-estimate editorial command returned")
            if lang == "de" and "staatliche Zwangsrequisitionen von Getreide".casefold() not in dek.casefold():
                issues.append(f"{slug}/{lang}: coercive grain procurement term missing")
            if lang == "no" and "statlig tvangsrekvisisjon av korn" not in dek.casefold():
                issues.append(f"{slug}/{lang}: coercive grain procurement term missing")
            policy = body.select_one('[data-fact-id="great-leap-famine-timeline-2"]')
            policy_text = policy.get_text(" ", strip=True) if policy else ""
            if policy is None or not policy_text.startswith("1958-08-29") or (
                policy.get("data-timeline-action", "")
                != "marked-important-policy-node-in-peoples-communalization"
            ):
                issues.append(f"{slug}/{lang}: 1958-08-29 policy milestone boundary missing")

        elif slug == "land-reform-anti-rightist":
            visible = " ".join((title, dek, body.get_text(" ", strip=True)))
            if LAND_MECHANICAL_REJECTIONS.search(visible):
                issues.append(f"{slug}/{lang}: mechanical movement or labour-punishment term returned")
            required_dek = {
                "es": "equipos de trabajo de la reforma agraria",
                "fr": "équipes de travail de la réforme agraire",
                "it": "squadre di lavoro della riforma agraria",
            }
            if lang in required_dek and required_dek[lang].casefold() not in dek.casefold():
                issues.append(f"{slug}/{lang}: land-reform work-team identity missing")
            required_title = {
                "de": "Bewegung gegen Rechtsabweichler",
                "no": "kampanjen mot høyreavvikere",
            }
            if lang in required_title and required_title[lang].casefold() not in title.casefold():
                issues.append(f"{slug}/{lang}: natural Anti-Rightist movement title missing")
            policy = body.select_one('[data-fact-id="land-reform-anti-rightist-timeline-5"]')
            policy_text = policy.get_text(" ", strip=True) if policy else ""
            if policy is None or not policy_text.startswith("1957-06-08") or (
                policy.get("data-timeline-action", "")
                != "published-editorial-marking-important-policy-node-in-nationwide-expansion-of-anti-rightist-movement"
            ):
                issues.append(f"{slug}/{lang}: 1957-06-08 Anti-Rightist policy milestone missing")
    return issues


# Final3's four corrections are checked from independently specified meanings,
