def batch10_final3_visible_semantic_issues(
    soup: BeautifulSoup, path: Path,
) -> list[str]:
    """Validate the four final3 human-review corrections on the live DOM."""
    slug = path.stem
    if slug not in BATCH10_FINAL3_TARGET_SLUGS:
        return []
    issues: list[str] = []
    if slug == "tiananmen-1989":
        for lang in LANGS:
            body = body_for(soup, lang)
            node = body.select_one('[data-fact-id="tiananmen-1989-evidence-2"]') if body else None
            text = normalize_reread_text(node.get_text(" ", strip=True) if node else "")
            if node is None or tuple(node.get("data-source-ref", "").split()) != ("s1", "s3", "s4"):
                issues.append(f"{slug}/{lang}: final3 evidence-2 source relationship changed")
                continue
            if BATCH10_FINAL3_TIAN_IMPERATIVE[lang].search(text):
                issues.append(f"{slug}/{lang}: final3 imperative add-or-merge instruction returned")
            missing = [
                pattern for pattern in BATCH10_FINAL3_TIAN_DECLARATIVE[lang]
                if not re.search(pattern, text, re.I)
            ]
            if missing or not {"3000", "200", "36", "1000", "202"}.issubset(
                semantic_number_tokens(text)
            ):
                issues.append(
                    f"{slug}/{lang}: final3 independent-record/incomplete-public-record explanation is incomplete"
                )
            if lang == "fr" and re.search(
                r"à partir des médias étrangers, de témoins(?: et de sources)?", text, re.I
            ):
                issues.append(f"{slug}/{lang}: final3 French source grammar regressed")
            if lang == "fr" and "à partir de médias étrangers, de témoignages et de sources officielles et non officielles" not in text:
                issues.append(f"{slug}/{lang}: final3 French natural source grammar is missing")

    elif slug == "falun-gong-persecution":
        for lang in LANGS:
            body = body_for(soup, lang)
            node = body.select_one(
                '[data-fact-id="falun-gong-persecution-rights-analysis"]'
            ) if body else None
            text = normalize_reread_text(node.get_text(" ", strip=True) if node else "")
            if node is None or not re.search(BATCH10_FINAL3_FALUN_STRONG[lang], text, re.I):
                issues.append(f"{slug}/{lang}: final3 rights conclusion weakens state violations")
            if lang not in BATCH10_FINAL3_FALUN_REQUIRED:
                continue
            weak = BATCH10_FINAL3_FALUN_WEAK[lang]
            if weak.search(text):
                issues.append(f"{slug}/{lang}: final3 weak affected/影響/영향 wording returned")
            missing = [
                concept for concept in BATCH10_FINAL3_FALUN_REQUIRED[lang]
                if concept.casefold() not in text.casefold()
            ]
            if missing:
                issues.append(
                    f"{slug}/{lang}: final3 direct-conduct/attributed-allegation boundary is incomplete"
                )
            if BATCH10_FINAL3_FALUN_DISCLAIMER.search(text):
                issues.append(f"{slug}/{lang}: final3 rejected court-finding disclaimer returned")

    elif slug == "great-leap-famine":
        body = body_for(soup, "zh")
        source = body.select_one('li[data-source-id="s4"]') if body else None
        anchor = source.find("a") if source else None
        title = anchor.get_text(" ", strip=True) if anchor else ""
        expected = "Publishers Weekly — 《墓碑：中國大饑荒，1958-1962》作者：楊繼繩"
        if title != expected or "楊繼勝" in str(soup):
            issues.append(f"{slug}/zh: final3 Publishers Weekly author name differs from 楊繼繩")

    elif slug == "land-reform-anti-rightist":
        body = body_for(soup, "ja")
        node = body.select_one(
            '[data-fact-id="land-reform-anti-rightist-unresolved-questions"]'
        ) if body else None
        text = normalize_reread_text(node.get_text(" ", strip=True) if node else "")
        required = (
            "地方の死亡記録", "政治的認定", "財産処分", "工作隊", "職場単位", "地方幹部",
            "懲罰的労働", "労働改造", "農村への下放", "教育", "職業", "財産", "名誉回復",
            "家族", "研究者", "独立", "関係記録", "手続",
        )
        if node is None or any(concept not in text for concept in required):
            issues.append(f"{slug}/ja: final3 complete historical records/remedy sentence is incomplete")
        if "労働処罰" in text:
            issues.append(f"{slug}/ja: final3 労働処罰 calque returned")
        if "名誉毀損への救済" in text:
            issues.append(f"{slug}/ja: final3 defamation-remedy framing returned")
    return issues

