def batch10_source_visible_contract_issues(
    page_overrides: dict[str, BeautifulSoup] | None = None,
) -> list[str]:
    """Check static visible source roles/titles without consulting live-derived data."""
    issues: list[str] = []
    for (slug, source_id), spec in BATCH10_SOURCE_VISIBLE_CONTRACTS.items():
        soup = (page_overrides or {}).get(slug)
        if soup is None:
            soup = BeautifulSoup(batch13_historical_post_text(slug), "html.parser")
        for lang in LANGS:
            body = body_for(soup, lang)
            nodes = body.select(f'ul.source-list > li[data-source-id="{source_id}"]') if body else []
            if len(nodes) != 1:
                issues.append(f"{slug}/{lang}/{source_id}: expected exactly one contracted visible source row")
                continue
            node = nodes[0]
            expected_type = spec.get("source_type")
            if expected_type is not None and node.get("data-source-type", "") != expected_type:
                issues.append(f"{slug}/{lang}/{source_id}: contracted source type differs")
            label = node.find("b")
            actual_label = normalize_reread_text(label.get_text(" ", strip=True) if label else "")
            if actual_label != spec["labels"][lang]:
                issues.append(f"{slug}/{lang}/{source_id}: visible source role label differs from static contract")
            expected_titles = spec.get("titles")
            if expected_titles is not None:
                anchor = node.find("a")
                actual_title = normalize_reread_text(anchor.get_text(" ", strip=True) if anchor else "")
                if actual_title != expected_titles[lang]:
                    issues.append(f"{slug}/{lang}/{source_id}: visible source title differs from static contract")
    return issues


def batch10_precision_issues(
    page_overrides: dict[str, BeautifulSoup] | None = None,
    script_override: str | None = None,
) -> list[str]:
    """Enforce the human-review regressions, timeline graph and card linkage."""
    issues: list[str] = []
    pages: dict[str, BeautifulSoup] = {}
    for slug in sorted(BATCH10_TARGET_SLUGS):
        soup = (page_overrides or {}).get(slug)
        if soup is None:
            soup = BeautifulSoup(batch13_historical_post_text(slug), "html.parser")
        pages[slug] = soup
        visible_page = normalize_reread_text(soup.get_text(" ", strip=True))
        if BATCH10_BAD_PUBLIC_PATTERNS[slug].search(visible_page):
            issues.append(f"{slug}: batch10 rejected subject, legal-term, chronology, or machine-translation phrase returned")
        expected_period = {
            "great-leap-famine": "1958—1962",
            "land-reform-anti-rightist": "1950—1980",
        }.get(slug)
        reference_sources = None
        reference_timeline_attrs = None
        for lang in LANGS:
            if expected_period is not None:
                meta = soup.select_one(f'.article-meta .lang-{lang}')
                meta_text = normalize_reread_text(meta.get_text(" ", strip=True) if meta else "")
                if meta is None or expected_period not in meta_text:
                    issues.append(
                        f"{slug}/{lang}: batch10 visible period boundary must include {expected_period}"
                    )
            body = body_for(soup, lang)
            if body is None:
                issues.append(f"{slug}/{lang}: batch10 language body missing")
                continue
            for (forbidden_slug, target_id), pattern in BATCH10_FINAL1_FORBIDDEN_TARGET_TEXT.items():
                if forbidden_slug != slug:
                    continue
                node = body.select_one(f'[data-fact-id="{target_id}"]')
                if node is None:
                    issues.append(f"{slug}/{lang}/{target_id}: batch10-final1 target missing")
                elif pattern.search(normalize_reread_text(node.get_text(" ", strip=True))):
                    issues.append(
                        f"{slug}/{lang}/{target_id}: batch10-final1 editorial disclaimer or "
                        "self-correction returned"
                    )
            source_signature = tuple(
                (
                    node.get("data-source-id", ""), node.get("data-source-type", ""),
                    node.get("data-source-date", ""),
                    (node.find("a").get("href", "") if node.find("a") else ""),
                )
                for node in body.select("ul.source-list > li[data-source-id]")
            )
            source_ids = {source_id for source_id, _source_type, _date, _url in source_signature}
            referenced_source_ids = {
                source_id
                for node in body.select("[data-fact-id][data-source-ref]")
                for source_id in node.get("data-source-ref", "").split()
            }
            if source_ids - referenced_source_ids:
                issues.append(
                    f"{slug}/{lang}: batch10 source rows are orphaned: "
                    f"{sorted(source_ids - referenced_source_ids)}"
                )
            if referenced_source_ids - source_ids:
                issues.append(
                    f"{slug}/{lang}: batch10 facts cite missing sources: "
                    f"{sorted(referenced_source_ids - source_ids)}"
                )
            if reference_sources is None:
                reference_sources = source_signature
            elif source_signature != reference_sources:
                issues.append(f"{slug}/{lang}: batch10 source ID/type/date/URL/order differs across languages")
            if slug == "land-reform-anti-rightist":
                for source in body.select("ul.source-list > li[data-source-id]"):
                    title_node = source.find("a")
                    title = title_node.get_text(" ", strip=True) if title_node else ""
                    if re.search(
                        r"\((?:archival transcription|supplemental comparative background; "
                        r"not core evidence for this page)\)",
                        title,
                        re.I,
                    ):
                        issues.append(
                            f"{slug}/{lang}/{source.get('data-source-id', '')}: internal source-title note remains"
                        )
            if slug == "falun-gong-persecution":
                falun_s2 = body.select_one('li[data-source-id="s2"]')
                if falun_s2 is None or falun_s2.get("data-source-type", "") != (
                    "state-media official-position retrospective-legal-summary"
                ):
                    issues.append(
                        f"{slug}/{lang}/s2: People’s Daily retrospective is misclassified as direct law"
                    )
            heading = body.select_one('h2[data-section="timeline"]')
            timeline = heading.find_next_sibling("ol") if heading else None
            nodes = timeline.find_all("li", recursive=False) if timeline else []
            ids = tuple(node.get("data-fact-id", "") for node in nodes)
            if ids != BATCH10_TIMELINE_IDS[slug]:
                issues.append(f"{slug}/{lang}: batch10 timeline order or fact IDs changed")
            attrs = tuple(
                (
                    node.get("data-fact-id", ""), node.get("data-timeline-subject", ""),
                    node.get("data-timeline-action", ""), node.get("data-timeline-consequence", ""),
                    node.get("data-source-ref", ""),
                ) for node in nodes
            )
            if reference_timeline_attrs is None:
                reference_timeline_attrs = attrs
            elif attrs != reference_timeline_attrs:
                issues.append(f"{slug}/{lang}: batch10 timeline subject/action/consequence/ref graph differs")
            for (required_slug, fact_id), required_refs in BATCH10_REQUIRED_REFS.items():
                if required_slug != slug:
                    continue
                node = body.select_one(f'[data-fact-id="{fact_id}"]')
                actual_refs = set(node.get("data-source-ref", "").split()) if node else set()
                if node is None or not set(required_refs).issubset(actual_refs):
                    issues.append(f"{slug}/{lang}/{fact_id}: batch10 named-source relationship missing {required_refs}")
            rights = body.select_one(f'[data-fact-id="{slug}-rights-analysis"]')
            rights_text = normalize_reread_text(rights.get_text(" ", strip=True) if rights else "")
            if slug not in {"liu-xiaobo", "tiananmen-1989"} and (
                rights is None or any(
                    not re.search(pattern, rights_text, re.I)
                    for pattern in BATCH10_ACCOUNTABILITY_TERMS[lang]
                )
            ):
                issues.append(
                    f"{slug}/{lang}: visible reliable-evidence, individualized international-accountability, "
                    "or non-collective boundary is missing"
                )
            if slug == "falun-gong-persecution":
                missing_falun_rights = [
                    concept for concept in BATCH10_FALUN_RIGHTS_REQUIRED[lang]
                    if concept.casefold() not in rights_text.casefold()
                ]
                if missing_falun_rights:
                    issues.append(
                        f"{slug}/{lang}: batch10-final1 Falun Gong rights chain is missing "
                        f"{missing_falun_rights}"
                    )
            if slug in {
                "liu-xiaobo", "tiananmen-1989", "jiangyou-school-bullying-protests",
                "huang-qi", "falun-gong-persecution",
            }:
                protection = body.select_one(f'[data-fact-id="{slug}-protection"]')
                protection_text = normalize_reread_text(
                    protection.get_text(" ", strip=True) if protection else ""
                )
                common_fragment = longest_common_normalized_fragment(
                    rights_text, protection_text
                )
                if protection is None or common_fragment >= 50:
                    issues.append(
                        f"{slug}/{lang}: rights/protection longest common normalized "
                        f"continuous fragment is {common_fragment}, expected below 50"
                    )
            if slug == "jiangyou-school-bullying-protests":
                evidence = body.select_one('[data-fact-id="jiangyou-school-bullying-protests-evidence-2"]')
                if evidence is None or not re.search(r"RFA|Radio Free Asia|自由亞洲|自由亚洲|ラジオ・フリー・アジア|자유아시아", evidence.get_text(" ", strip=True), re.I):
                    issues.append(f"{slug}/{lang}: RFA attribution is not visible in evidence-2")
            elif slug == "huang-qi":
                evidence = body.select_one('[data-fact-id="huang-qi-evidence-2"]')
                if evidence is None or "hq-s4" not in evidence.get("data-source-ref", "").split():
                    issues.append(f"{slug}/{lang}: RSF evidence-2 attribution lacks hq-s4")
            elif slug == "falun-gong-persecution":
                arrest = body.select_one('[data-fact-id="falun-gong-persecution-timeline-2"]')
                ban = body.select_one('[data-fact-id="falun-gong-persecution-timeline-2b"]')
                arrest_text = normalize_reread_text(arrest.get_text(" ", strip=True) if arrest else "")
                ban_text = normalize_reread_text(ban.get_text(" ", strip=True) if ban else "")
                if not arrest_text.startswith("1999-07-20") or not ban_text.startswith("1999-07-22"):
                    issues.append(f"{slug}/{lang}: July 20 arrest wave and July 22 formal ban were exchanged")
                evidence = body.select_one('[data-fact-id="falun-gong-persecution-evidence-2"]')
                evidence_text = evidence.get_text(" ", strip=True) if evidence else ""
                if not re.search(
                    r"UN Special Procedures|UN allegation letter|聯合國(?:特別程序|指控函)|联合国(?:特别程序|指控函)|"
                    r"国連(?:特別手続|の申立書簡)|유엔 (?:특별절차|혐의 서한|의혹 서한)|"
                    r"procedimientos especiales de la ONU|la carta (?:de alegaciones )?de la ONU|UN-Sonderverfahren|das UN-Vorwurfsschreiben|"
                    r"procédures spéciales de l[’']ONU|la lettre (?:d[’']allégations )?de l[’']ONU|FNs spesialprosedyrer|FN-brevet|"
                    r"speciale VN-procedures|de VN-brief|procedure speciali dell[’']ONU|la lettera (?:di accuse )?dell[’']ONU|la lettera ONU",
                    evidence_text, re.I,
                ):
                    issues.append(f"{slug}/{lang}: Falun Gong allegation evidence lost the UN source subject")

    issues.extend(batch10_source_visible_contract_issues(pages))

    script_value = script_override if script_override is not None else (ROOT / "script.js").read_text(encoding="utf-8")
    cards, card_load_issues = extract_report_cards(script_value)
    cards = batch14_baseline_card_view(cards)
    issues.extend(card_load_issues)
    by_slug = {card.get("slug", ""): card for card in cards}
    for slug, date in BATCH10_CARD_DATES.items():
        card = by_slug.get(slug)
        if card is None:
            issues.append(f"script.js: batch10 card missing for {slug}")
            continue
        if card.get("date", "") != date:
            issues.append(f"script.js: batch10 {slug} card event date differs from {date}")
        soup = pages[slug]
        for lang in LANGS:
            title = normalize_reread_text(soup.select_one(f".article-title .lang-{lang}").get_text(" ", strip=True))
            dek = normalize_reread_text(soup.select_one(f".article-dek .lang-{lang}").get_text(" ", strip=True))
            if card.get(f"title_{lang}", "") != title or card.get(f"excerpt_{lang}", "") != dek:
                issues.append(f"script.js: batch10 {slug}/{lang} card is not synchronized with article title/dek")
            excerpt = card.get(f"excerpt_{lang}", "")
            if slug == "tiananmen-1989" and any(
                concept.casefold() not in excerpt.casefold()
                for concept in BATCH10_FINAL2_TIAN_CARD_REQUIRED[lang]
            ):
                issues.append(
                    f"script.js: batch10-final1 Tiananmen {lang} card lacks the PLA/live-fire/"
                    "civilian-death/incomplete-records/family-remedy chain"
                )
            if slug == "falun-gong-persecution" and any(
                concept.casefold() not in excerpt.casefold()
                for concept in BATCH10_FINAL2_FALUN_CARD_REQUIRED[lang]
            ):
                issues.append(
                    f"script.js: batch10-final1 Falun Gong {lang} card lacks the July-20/July-22 "
                    "actor, source-role, allegation, or investigation/data/witness-protection chain"
                )
            if slug == "falun-gong-persecution" and BATCH10_BAD_PUBLIC_PATTERNS[slug].search(excerpt):
                issues.append(
                    f"script.js: batch10-final1 Falun Gong {lang} card restores a rejected "
                    "court-finding disclaimer or source-role error"
                )
            if slug == "huang-qi" and lang == "no":
                if any(bad in excerpt.casefold() for bad in (
                    "begjæringsmateriale", "abstrakte begjæringer",
                )) or not all(
                    concept.casefold() in excerpt.casefold()
                    for concept in (
                        "mennesker som klaget", "oppsøkte myndighetene", "søke oppreisning",
                        "2016", "2019", "forsettlig avsløring av statshemmeligheter",
                        "ulovlig overføring av statshemmeligheter til utenlandske enheter",
                        "menneskerettighetssaker", "nettstedets arkiv",
                    )
                ):
                    issues.append(
                        "script.js: batch10-final1 Huang Qi Norwegian card retains the petition-people "
                        "mistranslation or loses the specific 2019 charge/archive relationship"
                    )
    return issues


def batch10_final2_case_contract_issues(soup: BeautifulSoup, path: Path) -> list[str]:
    """Validate the sole live batch-ten structural and attribution contract.

    The hashes authenticate pre-final2 source metadata and DOM relationships;
    the Liu/Tiananmen dispute tuples are separately authored semantic rules.
    Neither set is extracted from the post-edit prose during validation.
    """
    slug = path.stem
    issues: list[str] = []
    for lang in LANGS:
        body = body_for(soup, lang)
        if body is None:
            issues.append(f"{slug}/{lang}: final2 authoritative contract lacks language body")
            continue
        sources = tuple(
            (
                node.get("data-source-id", ""), node.get("data-source-type", ""),
                node.get("data-source-date", ""),
                node.find("a").get("href", "") if node.find("a") else "",
            )
            for node in body.select("ul.source-list > li[data-source-id]")
        )
        source_payload = "\x1e".join("\x1f".join(item) for item in sources).encode("utf-8")
        if sha256_bytes(source_payload) != BATCH10_FINAL2_SOURCE_SIGNATURE_SHA256[slug]:
            issues.append(
                f"{slug}/{lang}: final2 source ID/type/date/URL/order differs from the pre-edit contract"
            )

        facts = []
        for node in body.select("[data-fact-id]"):
            if node.name in {"ol", "ul"} or node.select_one("[data-fact-id]"):
                continue
            heading = node.find_previous("h2")
            facts.append((
                node.get("data-fact-id", ""),
                heading.get("data-section", "") if heading else "",
                node.get("data-source-ref", ""),
            ))
        fact_payload = "\x1e".join("\x1f".join(item) for item in facts).encode("utf-8")
        if sha256_bytes(fact_payload) != BATCH10_FINAL2_FACT_GRAPH_SHA256[slug]:
            issues.append(
                f"{slug}/{lang}: final2 fact IDs, section duties, or source relationships changed"
            )

        heading = body.select_one('h2[data-section="timeline"]')
        timeline_list = heading.find_next_sibling("ol") if heading else None
        timeline_nodes = timeline_list.find_all("li", recursive=False) if timeline_list else []
        timeline = tuple(
            (
                node.get("data-fact-id", ""), node.get("data-timeline-subject", ""),
                node.get("data-timeline-action", ""), node.get("data-timeline-consequence", ""),
                node.get("data-source-ref", ""),
            )
            for node in timeline_nodes
        )
        hash_timeline = [list(item) for item in timeline]
        field_indexes = {"action": 2, "consequence": 3}
        by_id = {item[0]: item for item in hash_timeline}
        for fact_id, edits in BATCH10_FINAL2_AUTHORIZED_TIMELINE_EDITS.get(slug, {}).items():
            item = by_id.get(fact_id)
            if item is None:
                issues.append(f"{slug}/{lang}: authorized final2 timeline node is missing: {fact_id}")
                continue
            for field, (preimage_value, final2_value) in edits.items():
                field_index = field_indexes[field]
                if item[field_index] != final2_value:
                    issues.append(
                        f"{slug}/{lang}/{fact_id}: final2 timeline {field} differs from its "
                        "independently authorized value"
                    )
                item[field_index] = preimage_value
        timeline_payload = "\x1e".join(
            "\x1f".join(item) for item in hash_timeline
        ).encode("utf-8")
        if sha256_bytes(timeline_payload) != BATCH10_FINAL2_TIMELINE_GRAPH_SHA256[slug]:
            issues.append(
                f"{slug}/{lang}: final2 timeline graph changed outside authorized semantic fields"
            )
        if tuple(item[0] for item in timeline) != BATCH10_TIMELINE_IDS[slug]:
            issues.append(f"{slug}/{lang}: final2 authoritative timeline ID/order changed")

        dispute_expected = BATCH10_FINAL2_DISPUTE_CONTRACTS.get(slug)
        if dispute_expected is not None:
            dispute = body.select_one(f'[data-fact-id="{slug}-evidence-official-gap"]')
            dispute_actual = (
                dispute.get("data-inference-subject", "") if dispute else "",
                dispute.get("data-official-response", "") if dispute else "",
                dispute.get("data-response-gap", "") if dispute else "",
                dispute.get("data-accountability", "") if dispute else "",
            )
            if dispute_actual != dispute_expected:
                issues.append(f"{slug}/{lang}: final2 dispute actor/accountability contract changed")
        if slug == "tiananmen-1989":
            for node in body.find_all(True):
                for name, value in node.attrs.items():
                    if name.startswith("data-") and "state-council" in " ".join(
                        value if isinstance(value, list) else [str(value)]
                    ):
                        issues.append(
                            f"{slug}/{lang}: unsupported state-council actor returned in {name}"
                        )
                        break
    issues.extend(batch10_final2_visible_semantic_issues(soup, path))
    # This outer case path is mandatory for every batch-ten page.  Final3 is
    # deliberately wired here, outside the generic editorial-contract loop
    # whose invariant-code profiles use ``continue`` below.
    issues.extend(batch10_final3_visible_semantic_issues(soup, path))
    return issues


def case_semantic_contract_issues(
    soup: BeautifulSoup,
    path: Path,
    *,
    _batch12_predecessor: bool = False,
    _batch13_predecessor: bool = False,
) -> list[str]:
    """Validate the static, case-specific visible and attribution contract.

    Unlike the optional integrity hashes, this deliberately tolerates
    whitespace, punctuation, and natural translation rewrites.  It checks the
    facts that must survive those edits: case-specific fact IDs and sections,
    exact source attribution, timeline order and subject/action/consequence,
    dispute attribution, and translation-stable dates or quantities.
    """
    if (
        not _batch13_predecessor
        and path.name in BATCH13_TARGET_FILENAMES
    ):
        predecessor, rewind_issues = batch13_rewind_page(soup, path.stem)
        return (
            rewind_issues
            + case_semantic_contract_issues(
                predecessor,
                path,
                _batch13_predecessor=True,
            )
            + batch13_duty_subject_issues(soup, path.stem)
        )
    if (
        not _batch12_predecessor
        and path.name in BATCH12_TARGET_FILENAMES
    ):
        predecessor, rewind_issues = batch12_rewind_page_for_batch11(
            soup, path.stem
        )
        return (
            rewind_issues
            + case_semantic_contract_issues(
                predecessor,
                path,
                _batch12_predecessor=True,
                _batch13_predecessor=_batch13_predecessor,
            )
            + batch12_page_semantic_issues(soup, path)
        )
    if path.name == BATCH11_FINAL5_TARGET_FILENAME:
        # Final7 is the seven-node successor on the same Feng page.  Rebuild
        # the completed-final6 DOM before replaying every historical exact-text
        # duty, then validate the current final7 prose independently.
        predecessor = batch11_final7_rewind_page_for_final6(soup)
        return (
            batch11_final1_page_semantic_issues(predecessor, path)
            + batch11_final2_page_semantic_issues(predecessor, path)
            + batch11_final3_page_semantic_issues(predecessor, path)
            + batch11_final4_page_semantic_issues(predecessor, path)
            + batch11_final5_page_semantic_issues(predecessor, path)
            + batch11_final6_page_semantic_issues(predecessor, path)
            + batch11_final7_page_semantic_issues(soup, path)
        )
    if path.name in BATCH11_FINAL4_TARGET_FILENAMES:
        # Final4 is the two-node successor.  Compose every still-current
        # final1/final2/final3 duty with its own exact public-text gate.
        return (
            batch11_final1_page_semantic_issues(soup, path)
            + batch11_final2_page_semantic_issues(soup, path)
            + batch11_final3_page_semantic_issues(soup, path)
            + batch11_final4_page_semantic_issues(soup, path)
        )
    if path.name in BATCH11_FINAL3_TARGET_FILENAMES:
        # Preserve every live final1 and final2 duty while forcing the 17
        # exact-node final3 repairs independently of their ledger rows.
        return (
            batch11_final1_page_semantic_issues(soup, path)
            + batch11_final2_page_semantic_issues(soup, path)
            + batch11_final3_page_semantic_issues(soup, path)
        )
    if path.name in BATCH11_FINAL2_TARGET_FILENAMES:
        # Final2 is a narrow successor of final1.  Keep every final1 duty and
        # compose the new exact-node semantic rules on the same mandatory
        # outer route; neither pass can be bypassed by ledger metadata.
        return (
            batch11_final1_page_semantic_issues(soup, path)
            + batch11_final2_page_semantic_issues(soup, path)
        )
    if path.name in BATCH11_FINAL1_TARGET_FILENAMES:
        # Final1 is an authenticated successor of batch11.  The historical
        # batch11 contract is replayed separately against its frozen preimage;
        # the live page must satisfy the independent final1 contract instead
        # of being forced back to the superseded wording.  Any still-current
        # numeric duty is stated narrowly in that successor contract instead
        # of composing stale dates from the predecessor page.
        return batch11_final1_page_semantic_issues(soup, path)
    if path.name in BATCH11_TARGET_FILENAMES:
        # Batch11 replaces the old fact/source graph for these ten dossiers,
        # but it does not waive the previously reviewed visible quantities.
        # Compose those literal numeric duties with the new independent
        # subject/action/consequence/source/remedy validator.
        issues = batch11_page_semantic_issues(soup, path)
        contract = CASE_SEMANTIC_CONTRACTS.get(path.name)
        if contract is None:
            issues.append(f"{path.stem}: missing case-specific semantic contract")
            return issues
        for lang in LANGS:
            body = body_for(soup, lang)
            if body is None:
                issues.append(f"{lang}: {path.stem} language body is missing")
            else:
                for fact_id, required_numbers in contract["visible_numbers"].items():
                    node = body.select_one(f'[data-fact-id="{fact_id}"]')
                    actual_numbers = semantic_number_tokens(
                        node.get_text(" ", strip=True) if node else ""
                    )
                    if not set(required_numbers).issubset(actual_numbers):
                        issues.append(
                            f"{lang}: {fact_id} lost a required visible date or quantity"
                        )
        return issues
    if path.name in BATCH10_TARGET_FILENAMES:
        return batch10_final2_case_contract_issues(soup, path)
    contract = CASE_SEMANTIC_CONTRACTS.get(path.name)
    if contract is None:
        return [f"{path.stem}: missing case-specific semantic contract"]
    issues: list[str] = []
    expected_facts = contract["facts"]
    expected_timeline = contract["timeline"]
    for lang in LANGS:
        body = body_for(soup, lang)
        if body is None:
            continue
        source_ids = tuple(
            node.get("data-source-id")
            for node in body.select("ul.source-list > li[data-source-id]")
        )
        if source_ids != contract["source_ids"]:
            issues.append(f"{lang}: {path.stem} case source-ID contract changed")

        actual_facts = []
        for node in body.select("[data-fact-id]"):
            if node.name in {"ol", "ul"}:
                continue
            heading = node.find_previous("h2")
            section_id = heading.get("data-section") if heading else ""
            actual_facts.append((
                node.get("data-fact-id"),
                section_id,
                tuple(node.get("data-source-ref", "").split()),
            ))
            if len(re.sub(r"\s+", "", node.get_text(" ", strip=True))) < 5:
                issues.append(f"{lang}: {node.get('data-fact-id')} lost its visible case statement")
        if tuple(actual_facts) != expected_facts:
            issues.append(f"{lang}: {path.stem} fact, section, or source-attribution contract changed")

        heading = body.select_one('h2[data-section="timeline"]')
        timeline_list = heading.find_next_sibling("ol") if heading else None
        actual_timeline = tuple(
            (
                node.get("data-fact-id"),
                node.get("data-timeline-subject"),
                node.get("data-timeline-action"),
                node.get("data-timeline-consequence"),
            )
            for node in (timeline_list.find_all("li", recursive=False) if timeline_list else [])
        )
        if actual_timeline != expected_timeline:
            issues.append(f"{lang}: {path.stem} chronology or subject/action/consequence contract changed")

        actual_disputes = tuple(
            (
                node.get("data-fact-id"),
                tuple(node.get("data-dispute-matrix", "").split()),
                node.get("data-inference-subject"),
                node.get("data-official-response"),
                node.get("data-response-gap"),
                node.get("data-accountability"),
            )
            for node in body.select("[data-dispute-matrix]")
        )
        if actual_disputes != contract["disputes"]:
            issues.append(f"{lang}: {path.stem} fact, inference, response, gap, or accountability changed")

        for fact_id, required_numbers in contract["visible_numbers"].items():
            node = body.select_one(f'[data-fact-id="{fact_id}"]')
            actual_numbers = semantic_number_tokens(node.get_text(" ", strip=True) if node else "")
            if not set(required_numbers).issubset(actual_numbers):
                issues.append(f"{lang}: {fact_id} lost a required visible date or quantity")

        if path.name == "hu-xinyu-disappearance.html":
            reward = body.select_one('[data-fact-id="hu-xinyu-timeline-5"]')
            if reward is None or not HU_REWARD_VISIBLE.search(reward.get_text(" ", strip=True)):
                issues.append(f"{lang}: Hu Xinyu reward/search behavior disappeared from visible text")
        elif path.name == "ningbo-xiaoluoxi-medical-case.html":
            finding = body.select_one('[data-fact-id="ningbo-xiaoluoxi-medical-case-timeline-3"]')
            if finding is None or not XIAO_MEDICAL_FINDING.search(finding.get_text(" ", strip=True)):
                issues.append(f"{lang}: Xiao Luoxi medical finding, responsibility, sanctions, or investigation disappeared")
        elif path.name == "guiyang-quarantine-bus-crash.html":
            visible = " ".join(
                node.get_text(" ", strip=True)
                for node in (
                    soup.select_one(f".article-title .lang-{lang}"),
                    soup.select_one(f".article-dek .lang-{lang}"),
                    body.select_one('[data-fact-id="guiyang-quarantine-bus-crash-timeline-2"]'),
                    body.select_one('[data-fact-id="guiyang-quarantine-bus-crash-timeline-3"]'),
                    body.select_one('[data-fact-id="guiyang-quarantine-bus-crash-rights-analysis"]'),
                ) if node is not None
            )
            if not GUIYANG_BUS_VISIBLE.search(visible) or GUIYANG_WRONG_DOMAIN.search(visible):
                issues.append(f"{lang}: Guiyang bus, quarantine, casualty, or remedy semantics regressed")
        elif path.name == "liu-xia.html":
            overview = body.select_one('[data-fact-id="liu-xia-overview-1"]')
            family = " ".join(
                node.get_text(" ", strip=True)
                for node in (
                    body.select_one('[data-fact-id="liu-xia-timeline-3"]'),
                    body.select_one('[data-fact-id="liu-xia-timeline-6"]'),
                )
                if node is not None
            )
            if overview is None or not LIU_XIA_WOMAN_PATTERNS[lang].search(overview.get_text(" ", strip=True)):
                issues.append(f"{lang}: Liu Xia lost her visible identity as a woman poet and artist")
            if not LIU_XIA_BROTHER_PATTERNS[lang].search(family):
                issues.append(f"{lang}: Liu Hui is no longer visibly identified as Liu Xia's brother")
            timeline_2013 = body.select_one('[data-fact-id="liu-xia-timeline-3"]')
            if timeline_2013 is None or "2013" not in timeline_2013.get_text(" ", strip=True):
                issues.append(f"{lang}: Liu Hui's 2013 detention and sentence chronology disappeared")
            for number, pattern in enumerate(LIU_XIA_TIMELINE_VISIBLE[lang], start=1):
                node = body.select_one(f'[data-fact-id="liu-xia-timeline-{number}"]')
                if node is None or not re.search(pattern, node.get_text(" ", strip=True), re.I | re.S):
                    issues.append(f"{lang}: Liu Xia timeline {number} lost its visible case-specific action or consequence")
            if lang == "de" and LIU_XIA_BROKEN_GERMAN.search(body.get_text(" ", strip=True)):
                issues.append("de: Liu Xia broken German residual fragment returned")
        elif path.name == "pucheng-student-death-protest.html":
            official = body.select_one('[data-fact-id="pucheng-student-death-protest-timeline-2"]')
            family = body.select_one('[data-fact-id="pucheng-student-death-protest-timeline-3"]')
            reuters = body.select_one('[data-fact-id="pucheng-student-death-protest-timeline-6"]')
            if official is None or not PUCHENG_OFFICIAL_ATTRIBUTION[lang].search(official.get_text(" ", strip=True)):
                issues.append(f"{lang}: Pucheng official response lost positive visible attribution")
            family_text = family.get_text(" ", strip=True) if family else ""
            if "Human Rights in China" not in family_text or "Reuters" not in family_text:
                issues.append(f"{lang}: Pucheng family allegations lost Human Rights in China or Reuters attribution")
            reuters_text = reuters.get_text(" ", strip=True) if reuters else ""
            if not re.search(r"Reuters|路透|ロイター|로이터", reuters_text, re.I) or not re.search(r"渭南|Weinan|웨이난", reuters_text, re.I):
                issues.append(f"{lang}: Pucheng video verification or Weinan non-response attribution disappeared")
    return issues


BATCH11_FORBIDDEN_VISIBLE = re.compile(
    r"cannot replace|does not replace|only used|must not be upgraded|not a judicial finding|"
    r"must preserve (?:the )?links?(?: and|,) dates?|silence cannot prove|"
    r"不能替代|不能取代|只用[於于]|不得升級|不得升级|不得改寫成|不得改写成|"
    r"不是司法裁判|必須保存連結.{0,20}日期|必须保存链接.{0,20}日期|沉默不能證明|沉默不能证明|"
    r"置き換えることはできない|のみ使用|司法判断ではない|"
    r"Löschung der Plattform|maritime avlyttingen|海上傍受|해상 감청|"
    r"modalit[aà] di imbarco|travailleurs indépendants|"
    r"Turkish Muslims?|Turkish minority|musulmans?\s+turcs?\b|minorité turque|"
    r"türkische Minderheit|Turkse minderheid|반환\s*,\s*갱신된 보고|"
    r"public safety summons|chain of identity",
    re.I | re.S,
)

