def batch11_final3_target_node(
    soup: BeautifulSoup,
    lang: str,
    target_kind: str,
    target_id: str,
):
    """Locate one of the 17 expressly authorized final3 visible nodes."""
    return batch11_final1_target_node(soup, lang, target_kind, target_id)


def batch11_final3_page_semantic_issues(
    soup: BeautifulSoup,
    path: Path,
) -> list[str]:
    """Enforce the three final3 repairs at their exact language/fact nodes."""
    slug = path.stem
    if slug not in BATCH11_FINAL3_TARGET_SLUGS:
        return []
    issues: list[str] = []

    def node_text(lang: str, target_kind: str, target_id: str) -> str:
        node = batch11_final3_target_node(soup, lang, target_kind, target_id)
        if node is None:
            issues.append(
                f"{slug}/{lang}/{target_kind}/{target_id}: final3 target is missing"
            )
            return ""
        return node.get_text(" ", strip=True)

    def require(
        text: str,
        patterns: tuple[str, ...],
        label: str,
    ) -> None:
        for number, pattern in enumerate(patterns, start=1):
            if re.search(pattern, text, re.I | re.S) is None:
                issues.append(f"{label}: final3 semantic anchor {number} is missing")

    if slug == "2024-report":
        for target_kind, target_id in (
            ("article-dek", "article-dek"),
            ("fact", "2024-report-overview-1"),
            ("fact", "2024-report-overview-2"),
        ):
            text = node_text("ja", target_kind, target_id)
            require(
                text,
                BATCH11_FINAL3_2024_REQUIRED[target_id],
                f"{slug}/ja/{target_id}",
            )
            if BATCH11_FINAL3_2024_FORBIDDEN.search(text):
                issues.append(
                    f"{slug}/ja/{target_id}: final3 rejected Japanese calque returned"
                )
        ja_body = body_for(soup, "ja")
        ja_visible = " ".join(
            (
                soup.select_one(".article-dek .lang-ja").get_text(" ", strip=True)
                if soup.select_one(".article-dek .lang-ja") else "",
                ja_body.get_text(" ", strip=True) if ja_body else "",
            )
        )
        if BATCH11_FINAL3_2024_FORBIDDEN.search(ja_visible):
            issues.append(f"{slug}/ja: a rejected final3 phrase remains in public prose")
        if re.search(r"(?:です|ます|ました|ません|でしょう)[。！？]", ja_visible):
            issues.append(f"{slug}/ja: polite and plain formal registers are mixed")

    elif slug == "feng-county-chained-woman":
        unresolved_id = "feng-county-chained-woman-unresolved-questions"
        for lang in ("zh", "en"):
            text = node_text(lang, "fact", unresolved_id)
            require(
                text,
                BATCH11_FINAL3_FENG_UNRESOLVED_REQUIRED[lang],
                f"{slug}/{lang}/{unresolved_id}",
            )
            if BATCH11_FINAL3_FENG_UNRESOLVED_FORBIDDEN[lang].search(text):
                issues.append(
                    f"{slug}/{lang}/{unresolved_id}: rejected accountability wording returned"
                )
        timeline_id = "feng-county-chained-woman-timeline-3"
        for lang, patterns in BATCH11_FINAL3_FENG_TIMELINE_REQUIRED.items():
            text = node_text(lang, "fact", timeline_id)
            require(text, patterns, f"{slug}/{lang}/{timeline_id}")
            if BATCH11_FINAL3_FENG_TIMELINE_FORBIDDEN[lang].search(text):
                issues.append(
                    f"{slug}/{lang}/{timeline_id}: investigation team again became the questioner"
                )

    elif slug == "press-freedom-2026":
        for target_id in BATCH11_FINAL3_PRESS_IDS:
            text = node_text("fr", "fact", target_id)
            require(
                text,
                BATCH11_FINAL3_PRESS_REQUIRED[target_id],
                f"{slug}/fr/{target_id}",
            )
            if BATCH11_FINAL3_PRESS_FORBIDDEN.search(text):
                issues.append(
                    f"{slug}/fr/{target_id}: rejected broad-chefs calque returned"
                )
    return issues


def batch11_final3_live_pages(
    overrides: dict[str, BeautifulSoup] | None = None,
) -> dict[str, BeautifulSoup]:
    return {
        slug: (overrides or {}).get(slug)
        or BeautifulSoup(
            batch13_historical_post_text(slug), "html.parser"
        )
        for slug in BATCH11_FINAL3_TARGET_SLUGS
    }


def batch11_final3_predecessor_pages(
    pages: dict[str, BeautifulSoup],
    reread_rows: list[dict[str, str]] | None = None,
) -> tuple[dict[str, BeautifulSoup], list[str]]:
    """Replay final3 and its append-only successors to completed final2."""
    rows = reread_rows if reread_rows is not None else batch11_tsv_rows(SEMANTIC_REREAD_PATH)
    predecessors = {slug: copy.deepcopy(soup) for slug, soup in pages.items()}
    issues: list[str] = []
    # Reverse append order matters when a successor repairs the same node:
    # final4 must first return it to final3, and final3 then to final2.
    for row in reversed(rows[BATCH11_FINAL3_REREAD_PREFIX_ROWS:]):
        slug = row.get("slug", "")
        if slug not in predecessors or slug not in BATCH11_FINAL3_TARGET_SLUGS:
            continue
        key = (
            slug, row.get("language", ""), row.get("target_kind", ""),
            row.get("target_id", ""),
        )
        node = batch11_final3_target_node(
            predecessors[slug], key[1], key[2], key[3]
        )
        if node is None:
            issues.append(f"batch11-final3 predecessor replay target is missing: {'/'.join(key)}")
            continue
        try:
            batch11_final1_set_visible_text(
                node, row.get("original_text", ""), key[1]
            )
        except ValueError as exc:
            issues.append(f"{'/'.join(key)}: {exc}")
    return predecessors, issues


def batch11_final3_inventory(
    pages: dict[str, BeautifulSoup],
) -> dict[tuple[str, str, str, str], dict[str, str]]:
    inventory: dict[tuple[str, str, str, str], dict[str, str]] = {}
    for slug in BATCH11_FINAL3_TARGET_SLUGS:
        soup = pages[slug]
        for lang in LANGS:
            for target_id, value in extract_semantic_reread_targets(soup, lang).items():
                key = (slug, lang, value["target_kind"], target_id)
                inventory[key] = {
                    "text": value["text"],
                    "text_exact": value["text_exact"],
                    "source_refs": value["source_refs"],
                }
    return inventory


def batch11_final3_source_graph_issues(
    pages: dict[str, BeautifulSoup],
) -> list[str]:
    """Freeze all source metadata/order and all data-source-ref attributes."""
    records: list[str] = []
    for slug in BATCH11_FINAL3_TARGET_SLUGS:
        soup = pages[slug]
        for lang in LANGS:
            body = body_for(soup, lang)
            if body is None:
                continue
            for order, source in enumerate(
                body.select("ul.source-list > li[data-source-id]")
            ):
                anchor = source.find("a", href=True)
                records.append(
                    json.dumps(
                        [
                            "source", slug, lang, order,
                            source.get("data-source-id", ""),
                            source.get("data-source-type", ""),
                            source.get("data-source-date", ""),
                            anchor.get("href", "") if anchor else "",
                        ],
                        ensure_ascii=False,
                        separators=(",", ":"),
                    )
                    + "\n"
                )
        for order, node in enumerate(soup.select("[data-source-ref]")):
            records.append(
                json.dumps(
                    [
                        "ref", slug, order, node.name,
                        node.get("data-fact-id", ""),
                        node.get("data-source-ref", ""),
                    ],
                    ensure_ascii=False,
                    separators=(",", ":"),
                )
                + "\n"
            )
    issues: list[str] = []
    if len(records) != BATCH11_FINAL3_SOURCE_GRAPH_ROWS:
        issues.append(
            "batch11-final3 source graph has "
            f"{len(records)} rows, expected {BATCH11_FINAL3_SOURCE_GRAPH_ROWS}"
        )
    if sha256_bytes("".join(records).encode("utf-8")) != (
        BATCH11_FINAL3_SOURCE_GRAPH_SHA256
    ):
        issues.append(
            "batch11-final3 changed a source ID/type/date/URL/order or data-source-ref"
        )
    return issues


def batch11_final3_freeze_issues(
    overrides: dict[str, bytes | str] | None = None,
) -> list[str]:
    """Freeze every repository file outside the exact eight-file whitelist."""
    def payload_for(relative: str) -> bytes | None:
        value = (overrides or {}).get(relative)
        if isinstance(value, str):
            return value.encode("utf-8")
        if isinstance(value, bytes):
            return value
        path = ROOT / relative
        return path.read_bytes() if path.is_file() else None

    # The Desktop preview historically contains four root-level copies that
    # are absent from the deployment repository.  They are ignored only when
    # both the exact path and its authenticated bytes match; a changed copy is
    # deliberately left in the protected manifest and therefore fails the
    # 352-file path/count/digest contract.  Missing copies are the normal Repo
    # case and require no exemption.
    authenticated_desktop_extras = {
        relative
        for relative, expected_sha in BATCH11_FINAL1_DESKTOP_EXTRAS.items()
        if (payload := payload_for(relative)) is not None
        and sha256_bytes(payload) == expected_sha
    }
    candidate_paths = {
        path.relative_to(ROOT).as_posix()
        for path in ROOT.rglob("*")
        if path.is_file()
        and ".git" not in path.relative_to(ROOT).parts
        and path.name != ".DS_Store"
        and path.relative_to(ROOT).as_posix() not in BATCH11_FINAL3_MUTABLE_FILES
    }
    # Override-only paths make the negative test exercise the same real
    # path/SHA decision in the Repo environment, where Desktop extras are
    # normally absent, without writing a fixture to disk.
    candidate_paths.update(
        relative
        for relative in (overrides or {})
        if ".git" not in Path(relative).parts
        and Path(relative).name != ".DS_Store"
        and relative not in BATCH11_FINAL3_MUTABLE_FILES
    )
    paths = sorted(candidate_paths - authenticated_desktop_extras)
    records: list[str] = []
    for relative in paths:
        payload = payload_for(relative)
        if payload is None:
            # An override-only key without bytes is not a supported test
            # fixture; retaining it as an unmistakable digest mismatch is
            # safer than silently dropping the path.
            payload = b"__MISSING_FINAL3_FREEZE_PAYLOAD__"
        records.append(f"{relative}\t{sha256_bytes(payload)}\n")
    issues: list[str] = []
    if len(paths) != BATCH11_FINAL3_PROTECTED_FILES:
        issues.append(
            f"batch11-final3 protected manifest has {len(paths)} files, "
            f"expected {BATCH11_FINAL3_PROTECTED_FILES}"
        )
    if sha256_bytes("".join(records).encode("utf-8")) != (
        BATCH11_FINAL3_PROTECTED_SHA256
    ):
        issues.append("batch11-final3 changed a file outside its exact eight-file scope")
    source_date_value = (overrides or {}).get("tools/data/source-date-ledger.tsv")
    if isinstance(source_date_value, str):
        source_date_payload = source_date_value.encode("utf-8")
    elif isinstance(source_date_value, bytes):
        source_date_payload = source_date_value
    else:
        source_date_payload = source_date_ledger_predecessor_bytes()
    if sha256_bytes(source_date_payload) != BATCH11_FINAL3_SOURCE_DATE_SHA256:
        issues.append("batch11-final3 changed frozen source-date-ledger bytes")
    return issues


