def batch11_final3_contract_independence_issues(
    rows: list[dict[str, str]],
    reread_by_key: dict[tuple[str, str, str, str], dict[str, str]],
) -> list[str]:
    issues: list[str] = []
    for row in rows:
        key = (
            row.get("slug", ""), row.get("language", ""),
            row.get("target_kind", ""), row.get("target_id", ""),
        )
        label = "/".join(key)
        required = contract_literals(row.get("required_all", ""))
        forbidden = contract_literals(row.get("forbidden_any", ""))
        required_labels = {
            item.split(":", 1)[0].strip().casefold()
            for item in required if ":" in item
        }
        required_roles = (
            bool(required_labels & {"actor", "subject"}),
            "action" in required_labels,
            bool(required_labels & {"legal", "source", "evidence"}),
            "consequence" in required_labels,
            "remedy" in required_labels,
        )
        if not 5 <= len(set(required)) <= 6 or not all(required_roles):
            issues.append(
                f"batch11-final3 contract lacks its five independent duty classes: {label}"
            )
        if len(set(forbidden)) < 2 or any(
            not item.startswith("old-error:") for item in forbidden
        ):
            issues.append(f"batch11-final3 contract lacks two short old-error anchors: {label}")
        if any(len(normalized_contiguous_stream(item)) > 120 for item in forbidden):
            issues.append(f"batch11-final3 contract forbidden anchor is not short: {label}")
        summary = row.get("fact_summary", "").casefold()
        if (
            not all(marker in summary for marker in (
                "subject:", "action:", "consequence:", "remedy:",
            ))
            or not any(marker in summary for marker in ("legal", "source:"))
        ):
            issues.append(f"batch11-final3 contract summary lacks five review roles: {label}")
        revised = normalize_reread_text(
            reread_by_key.get(key, {}).get("revised_text", "")
        )
        revised_stream = normalized_contiguous_stream(revised)
        for literal in required:
            literal_stream = normalized_contiguous_stream(literal.split(":", 1)[-1])
            if len(literal_stream) >= 80 and literal_stream in revised_stream:
                issues.append(f"batch11-final3 contract copied a long DOM answer: {label}")
                break
    return issues


def batch11_final3_ledger_issues(
    *,
    page_overrides: dict[str, BeautifulSoup] | None = None,
    reread_rows_override: list[dict[str, str]] | None = None,
    contract_rows_override: list[dict[str, str]] | None = None,
    source_rows_override: list[dict[str, str]] | None = None,
) -> list[str]:
    """Authenticate final2, reconstruct its pages, and bind every final3 row."""
    issues: list[str] = []
    reread_rows = (
        reread_rows_override
        if reread_rows_override is not None
        else batch11_tsv_rows(SEMANTIC_REREAD_PATH)
    )
    contract_rows = (
        contract_rows_override
        if contract_rows_override is not None
        else batch11_tsv_rows(EDITORIAL_SEMANTIC_CONTRACT_PATH)
    )
    source_rows = (
        source_rows_override
        if source_rows_override is not None
        else batch11_tsv_rows(SOURCE_LEDGER_PATH)
    )
    for path, rows, row_count, expected_sha, label in (
        (
            SEMANTIC_REREAD_PATH, reread_rows,
            BATCH11_FINAL3_REREAD_PREFIX_ROWS,
            BATCH11_FINAL3_REREAD_PREFIX_SHA256,
            "batch11-final3 completed-final2 reread prefix",
        ),
        (
            EDITORIAL_SEMANTIC_CONTRACT_PATH, contract_rows,
            BATCH11_FINAL3_CONTRACT_PREFIX_ROWS,
            BATCH11_FINAL3_CONTRACT_PREFIX_SHA256,
            "batch11-final3 completed-final2 contract prefix",
        ),
        (
            SOURCE_LEDGER_PATH, source_rows,
            BATCH11_FINAL3_SOURCE_PREFIX_ROWS,
            BATCH11_FINAL3_SOURCE_PREFIX_SHA256,
            "batch11-final3 completed-final2 source prefix",
        ),
    ):
        prefix_issues = exact_tsv_prefix_issues(
            path,
            base_rows=row_count,
            expected_sha256=expected_sha,
            label=label,
        )
        issues.extend(prefix_issues)
        actual_prefix = batch11_tsv_rows(path)[:row_count]
        if rows[:row_count] != actual_prefix:
            issues.append(f"{label} changed in the supplied ledger state")
    source_date_payload = source_date_ledger_predecessor_bytes()
    if sha256_bytes(source_date_payload) != BATCH11_FINAL3_SOURCE_DATE_SHA256:
        issues.append("batch11-final3 changed frozen source-date-ledger bytes")
    source_date_rows = source_date_ledger_predecessor_rows()
    if len(source_date_rows) != BATCH11_FINAL3_SOURCE_DATE_ROWS:
        issues.append("batch11-final3 source-date ledger no longer has 294 data rows")

    # Final3 owns exactly its frozen 17/17/16 slice.  Later append-only rows
    # are authenticated by final4 and must not be reclassified as final3.
    reread_suffix = reread_rows[
        BATCH11_FINAL3_REREAD_PREFIX_ROWS:BATCH11_FINAL4_REREAD_PREFIX_ROWS
    ]
    contract_suffix = contract_rows[
        BATCH11_FINAL3_CONTRACT_PREFIX_ROWS:BATCH11_FINAL4_CONTRACT_PREFIX_ROWS
    ]
    source_suffix = source_rows[
        BATCH11_FINAL3_SOURCE_PREFIX_ROWS:BATCH11_FINAL4_SOURCE_PREFIX_ROWS
    ]
    current_pages = batch11_final3_live_pages(page_overrides)
    live_pages = {slug: copy.deepcopy(soup) for slug, soup in current_pages.items()}
    # Reconstruct the completed-final3 view before checking final3's own rows.
    # This preserves the historical gate after a legitimate final4 repair,
    # including the English node that both passes touch.
    for row in reversed(reread_rows[BATCH11_FINAL4_REREAD_PREFIX_ROWS:]):
        slug = row.get("slug", "")
        if slug not in live_pages:
            continue
        key = (
            slug,
            row.get("language", ""),
            row.get("target_kind", ""),
            row.get("target_id", ""),
        )
        node = batch11_final3_target_node(
            live_pages[slug], key[1], key[2], key[3]
        )
        if node is None:
            issues.append(
                "batch11-final3 successor replay target is missing: "
                + "/".join(key)
            )
            continue
        try:
            batch11_final1_set_visible_text(
                node, row.get("original_text", ""), key[1]
            )
        except ValueError as exc:
            issues.append(f"{'/'.join(key)}: {exc}")
    pre_pages = {slug: copy.deepcopy(soup) for slug, soup in live_pages.items()}

    def visible_key(row: dict[str, str]) -> tuple[str, str, str, str]:
        return (
            row.get("slug", ""), row.get("language", ""),
            row.get("target_kind", ""), row.get("target_id", ""),
        )

    for row in reread_suffix:
        key = visible_key(row)
        if key[0] not in BATCH11_FINAL3_TARGET_SLUGS:
            continue
        node = batch11_final3_target_node(pre_pages[key[0]], key[1], key[2], key[3])
        if node is None:
            issues.append(f"batch11-final3 predecessor target is missing: {'/'.join(key)}")
            continue
        live_exact = node.get_text(" ", strip=True)
        if row.get("revised_text", "") != live_exact:
            issues.append(f"batch11-final3 revised_text differs byte-for-byte from DOM: {'/'.join(key)}")
        try:
            batch11_final1_set_visible_text(node, row.get("original_text", ""), key[1])
        except ValueError as exc:
            issues.append(f"{'/'.join(key)}: {exc}")

    for slug, expected_sha in BATCH11_FINAL3_PAGE_PREIMAGE_SHA256.items():
        actual_sha = batch11_final1_page_canonical_sha(pre_pages[slug])
        if actual_sha != expected_sha:
            issues.append(f"{slug}: completed-final2 canonical page did not reconstruct")

    pre_inventory = batch11_final3_inventory(pre_pages)
    live_inventory = batch11_final3_inventory(live_pages)
    if set(pre_inventory) != set(live_inventory):
        issues.append("batch11-final3 added or removed a public semantic target")
    expected_visible = {
        key for key in set(pre_inventory) & set(live_inventory)
        if pre_inventory[key]["text_exact"] != live_inventory[key]["text_exact"]
        or pre_inventory[key]["source_refs"] != live_inventory[key]["source_refs"]
    }
    if expected_visible != BATCH11_FINAL3_ALLOWED_TARGETS:
        issues.append(
            "batch11-final3 genuine visible delta differs from its exact 17 targets: "
            f"missing={len(BATCH11_FINAL3_ALLOWED_TARGETS - expected_visible)} "
            f"extra={len(expected_visible - BATCH11_FINAL3_ALLOWED_TARGETS)}"
        )

    reread_keys = [visible_key(row) for row in reread_suffix]
    contract_keys = [visible_key(row) for row in contract_suffix]
    if len(reread_keys) != len(set(reread_keys)):
        issues.append("batch11-final3 reread suffix duplicates a target")
    if len(contract_keys) != len(set(contract_keys)):
        issues.append("batch11-final3 contract suffix duplicates a target")
    if set(reread_keys) != BATCH11_FINAL3_ALLOWED_TARGETS:
        issues.append("batch11-final3 reread coverage is not exactly 17 authorized targets")
    if set(contract_keys) != BATCH11_FINAL3_ALLOWED_TARGETS:
        issues.append("batch11-final3 contract coverage is not exactly 17 authorized targets")

    reread_by_key = {visible_key(row): row for row in reread_suffix}
    contract_by_key = {visible_key(row): row for row in contract_suffix}
    prefix_tips: dict[tuple[str, str, str], dict[str, str]] = {}
    for row in reread_rows[:BATCH11_FINAL3_REREAD_PREFIX_ROWS]:
        prefix_tips[(row.get("slug", ""), row.get("language", ""), row.get("target_id", ""))] = row
    reread_ids: set[str] = set()
    for key, row in reread_by_key.items():
        label = "/".join(key)
        expected_prefix = f"{BATCH11_FINAL3_CONTRACT_PREFIX}{':'.join(key)}:"
        contract_id = row.get("contract_id", "")
        if not contract_id.startswith(expected_prefix):
            issues.append(f"batch11-final3 reread ID is not target-bound: {label}")
        if not contract_id or contract_id in reread_ids:
            issues.append(f"batch11-final3 reread ID is blank or duplicate: {label}")
        reread_ids.add(contract_id)
        pre = pre_inventory.get(key, {"text_exact": "", "source_refs": ""})
        live = live_inventory.get(key, {"text_exact": "", "source_refs": ""})
        if row.get("result", "") != "PASS_AFTER_REVISION":
            issues.append(f"batch11-final3 reread is not a genuine revision: {label}")
        if "reread:batch11-final3" not in row.get("review_basis", ""):
            issues.append(f"batch11-final3 reread lacks its append marker: {label}")
        if row.get("original_text", "") != pre["text_exact"]:
            issues.append(f"batch11-final3 original_text differs byte-for-byte from final2: {label}")
        if row.get("revised_text", "") != live["text_exact"]:
            issues.append(f"batch11-final3 revised_text differs byte-for-byte from live DOM: {label}")
        if row.get("original_text", "") == row.get("revised_text", ""):
            issues.append(f"batch11-final3 row is PASS_NO_CHANGE or same-text: {label}")
        if row.get("source_refs", "") != live["source_refs"]:
            issues.append(f"batch11-final3 reread source refs differ from live DOM: {label}")
        issue_found = row.get("issue_found", "").casefold()
        anchors = batch11_final3_old_error_anchors(key)
        if not anchors or not all(anchor.casefold() in issue_found for anchor in anchors):
            issues.append(f"batch11-final3 issue_found does not quote the old defect: {label}")
        basis = row.get("review_basis", "").casefold()
        if not all(marker in basis for marker in ("subject:", "action:", "legal", "why")):
            issues.append(f"batch11-final3 review basis lacks subject/action/legal/fix reasoning: {label}")
        predecessor = prefix_tips.get((key[0], key[1], key[3]))
        if predecessor is None or normalize_reread_text(
            predecessor.get("revised_text", "")
        ) != normalize_reread_text(row.get("original_text", "")):
            issues.append(f"batch11-final3 predecessor chain is broken: {label}")

    contract_ids = {row.get("contract_id", "") for row in contract_suffix}
    if contract_ids != reread_ids:
        issues.append("batch11-final3 contract/reread IDs are not one-to-one")
    for key, row in contract_by_key.items():
        expected_prefix = f"{BATCH11_FINAL3_CONTRACT_PREFIX}{':'.join(key)}:"
        if not row.get("contract_id", "").startswith(expected_prefix):
            issues.append(f"batch11-final3 contract identity differs: {'/'.join(key)}")
    issues.extend(
        batch11_final3_contract_independence_issues(contract_suffix, reread_by_key)
    )

    fact_pages = batch11_final2_live_pages()
    fact_pages.update(live_pages)
    live_facts = batch11_final2_live_fact_map(fact_pages)
    pre_source_tips: dict[tuple[str, str, str], dict[str, str]] = {}
    for row in source_rows[:BATCH11_FINAL3_SOURCE_PREFIX_ROWS]:
        pre_source_tips[(row.get("slug", ""), row.get("language", ""), row.get("fact_id", ""))] = row
    expected_fact_keys = {
        (slug, lang, target_id)
        for slug, lang, kind, target_id in BATCH11_FINAL3_ALLOWED_TARGETS
        if kind == "fact"
    }
    changed_facts: set[tuple[str, str, str]] = set()
    for key, live in live_facts.items():
        predecessor = pre_source_tips.get(key)
        if predecessor is None:
            continue
        if normalize_batch11_visible_text(
            predecessor.get("current_visible_text", "")
        ) != normalize_batch11_visible_text(live["text"]) or any(
            live[current] != predecessor.get(column, "")
            for column, current in (
                ("data_source_ref", "source_refs"),
                ("timeline_subject", "timeline_subject"),
                ("timeline_action", "timeline_action"),
                ("timeline_consequence", "timeline_consequence"),
            )
        ):
            changed_facts.add(key)
    if changed_facts != expected_fact_keys:
        issues.append("batch11-final3 genuine fact delta is not exactly its 16 fact targets")

    def fact_key(row: dict[str, str]) -> tuple[str, str, str]:
        return row.get("slug", ""), row.get("language", ""), row.get("fact_id", "")

    source_keys = [fact_key(row) for row in source_suffix]
    if len(source_keys) != len(set(source_keys)):
        issues.append("batch11-final3 source suffix duplicates a fact")
    if set(source_keys) != expected_fact_keys:
        issues.append("batch11-final3 source coverage is not exactly 16 changed facts")
    for row in source_suffix:
        key = fact_key(row)
        label = "/".join(key)
        live = live_facts.get(key)
        predecessor = pre_source_tips.get(key)
        if live is None or predecessor is None:
            issues.append(f"batch11-final3 source row lacks live/final2 fact: {label}")
            continue
        if row.get("section_id", "") != predecessor.get("section_id", ""):
            issues.append(f"batch11-final3 source row changed section identity: {label}")
        for field, expected in (
            ("current_visible_text", live["text"]),
            ("data_source_ref", live["source_refs"]),
            ("timeline_subject", live["timeline_subject"]),
            ("timeline_action", live["timeline_action"]),
            ("timeline_consequence", live["timeline_consequence"]),
            ("source_date_audit", live["source_date_audit"]),
            ("visible_source_roles", live["visible_source_roles"]),
            ("reread_revision_text", live["text"]),
            ("audit_source_id", live["source_refs"]),
            ("audit_claim_compared", live["text"]),
        ):
            if normalize_batch11_visible_text(row.get(field, "")) != normalize_batch11_visible_text(expected):
                issues.append(f"batch11-final3 source {field} differs from live fact: {label}")
        if row.get("support_urls", "") != live["support_urls"]:
            issues.append(f"batch11-final3 source URLs differ: {label}")
        contract = contract_by_key.get((key[0], key[1], "fact", key[2]))
        if contract is None or row.get("baseline_issue", "") != contract.get("contract_id", ""):
            issues.append(f"batch11-final3 source marker differs from contract: {label}")
        if row.get("reread_result", "") != "PASS_AFTER_REVISION":
            issues.append(f"batch11-final3 source row is not a revision: {label}")
        if row.get("audit_decision", "") != "PASS_FINAL3_SOURCE_MAPPING":
            issues.append(f"batch11-final3 source decision differs: {label}")
        for field in (
            "audit_accessed_at", "audit_title", "audit_locator",
            "audit_support_summary", "audit_relationship", "reread_issue_found",
        ):
            if not row.get(field, "").strip():
                issues.append(f"batch11-final3 source row lacks {field}: {label}")
    return issues


def batch11_final3_wiring_issues(source_override: str | None = None) -> list[str]:
    source = source_override or Path(__file__).read_text(encoding="utf-8")
    try:
        tree = ast.parse(source)
    except SyntaxError as exc:
        return [f"batch11-final3 checker wiring is not parseable: {exc}"]
    functions = {
        node.name: node for node in tree.body
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
    }

    def called(function_name: str, callee: str) -> bool:
        function = functions.get(function_name)
        return bool(function) and any(
            isinstance(node, ast.Call)
            and isinstance(node.func, ast.Name)
            and node.func.id == callee
            for node in ast.walk(function)
        )

    issues: list[str] = []
    if not called("validate_paths", "batch11_final3_release_issues"):
        issues.append("validate_paths no longer forces batch11-final3 release validation")
    for callee in (
        "batch11_final3_page_semantic_issues",
        "batch11_final3_ledger_issues",
        "batch11_final3_source_graph_issues",
        "batch11_final3_freeze_issues",
        "batch11_final3_wiring_issues",
    ):
        if not called("batch11_final3_release_issues", callee):
            issues.append(f"batch11-final3 release gate no longer calls {callee}")
    if not called("self_tests", "batch11_final3_named_negative_tests"):
        issues.append("self_tests no longer runs batch11-final3 named mutations")
    if not called("case_semantic_contract_issues", "batch11_final3_page_semantic_issues"):
        issues.append("case semantic route no longer forces batch11-final3 page validation")
    return issues


def batch11_final3_release_issues(
    *,
    page_overrides: dict[str, BeautifulSoup] | None = None,
    reread_rows_override: list[dict[str, str]] | None = None,
    contract_rows_override: list[dict[str, str]] | None = None,
    source_rows_override: list[dict[str, str]] | None = None,
    freeze_overrides: dict[str, bytes | str] | None = None,
    checker_source_override: str | None = None,
) -> list[str]:
    issues: list[str] = []
    pages = batch11_final3_live_pages(page_overrides)
    for slug, soup in pages.items():
        issues.extend(batch11_final3_page_semantic_issues(soup, POSTS / f"{slug}.html"))
    issues.extend(batch11_final3_source_graph_issues(pages))
    issues.extend(
        batch11_final3_ledger_issues(
            page_overrides=page_overrides,
            reread_rows_override=reread_rows_override,
            contract_rows_override=contract_rows_override,
            source_rows_override=source_rows_override,
        )
    )
    if not batch12_successor_active():
        issues.extend(batch11_final3_freeze_issues(freeze_overrides))
    issues.extend(batch11_final3_wiring_issues(checker_source_override))
    return issues


