    for needle, replacement in (
        ("issues.extend(batch11_final3_release_issues())", "issues.extend([])"),
        (
            "+ batch11_final3_page_semantic_issues(predecessor, path)",
            "+ []",
        ),
        ("batch11_final3_checks = batch11_final3_named_negative_tests()", "batch11_final3_checks = []"),
        ("issues.extend(batch11_final3_source_graph_issues(pages))", "issues.extend([])"),
    ):
        if needle.startswith("+ batch11_final3_page_semantic_issues"):
            # Final4 composes final3 on its two pages while the historical
            # final3 branch covers the third.  Delete every mandatory case
            # route so this mutation genuinely tests a complete bypass.
            mutated = source.replace(needle, replacement).replace(
                "+ batch11_final3_page_semantic_issues(soup, path)",
                replacement,
            )
        else:
            position = (
                source.rfind(needle)
                if "release_issues" in needle
                or needle.startswith("batch11_final3_checks")
                else source.find(needle)
            )
            mutated = (
                source[:position]
                + replacement
                + source[position + len(needle):]
                if position >= 0
                else source
            )
        route_mutations.append(
            mutated != source and bool(batch11_final3_wiring_issues(mutated))
        )
