def batch11_final7_inventory(
    soup: BeautifulSoup,
) -> dict[tuple[str, str, str, str], dict[str, str]]:
    """Enumerate the whole page with final7's no-invented-space timeline text."""
    inventory: dict[tuple[str, str, str, str], dict[str, str]] = {}
    for lang in LANGS:
        extracted = extract_semantic_reread_targets(soup, lang)
        for target_id, value in extracted.items():
            key = (
                BATCH11_FINAL7_TARGET_SLUG,
                lang,
                value["target_kind"],
                target_id,
            )
            text_exact = value["text_exact"]
            if key in BATCH11_FINAL7_TIMELINE_TARGETS:
                node = batch11_final7_target_node(soup, key)
                if node is not None:
                    text_exact = batch11_final7_visible_text(node, key)
            inventory[key] = {
                "text_exact": text_exact,
                "source_refs": value["source_refs"],
            }
    return inventory


def batch11_final7_page_semantic_issues(
    soup: BeautifulSoup,
    path: Path,
) -> list[str]:
    """Enforce seven exact English revisions, attributes and source refs."""
    if path.name != BATCH11_FINAL7_TARGET_FILENAME:
        return []
    issues: list[str] = []
    for key in BATCH11_FINAL7_TARGETS:
        node = batch11_final7_target_node(soup, key)
        label = "/".join(key)
        if node is None:
            issues.append(f"{label}: batch11-final7 target is missing or duplicated")
        else:
            text = batch11_final7_visible_text(node, key)
            if text != BATCH11_FINAL7_EXPECTED_TEXT[key]:
                issues.append(f"{label}: batch11-final7 visible text differs")
            for number, phrase in enumerate(
                BATCH11_FINAL7_REQUIRED_PHRASES[key],
                start=1,
            ):
                if phrase.casefold() not in text.casefold():
                    issues.append(
                        f"{label}: batch11-final7 semantic anchor {number} is missing"
                    )
            if key[2] == "article-dek":
                if node.attrs != {"class": ["lang-en"]}:
                    issues.append(
                        f"{label}: batch11-final7 article-dek attributes changed"
                    )
                body = body_for(soup, "en")
                source_ids = (
                    " ".join(
                        source.get("data-source-id", "")
                        for source in body.select(
                            "ul.source-list > li[data-source-id]"
                        )
                    )
                    if body is not None
                    else ""
                )
                if "page-sources:" + source_ids != (
                    BATCH11_FINAL7_EXPECTED_REFS[key]
                ):
                    issues.append(
                        f"{label}: batch11-final7 page source relationship changed"
                    )
            else:
                expected_attrs = BATCH11_FINAL7_EXPECTED_ATTRIBUTES[key]
                actual_attrs = {
                    name: (
                        " ".join(value) if isinstance(value, list) else value
                    )
                    for name, value in node.attrs.items()
                }
                if actual_attrs != expected_attrs:
                    issues.append(
                        f"{label}: batch11-final7 fact/timeline attributes changed"
                    )
    body = body_for(soup, "en")
    all_text = (
        body.get_text(" ", strip=True)
        if body is not None
        else ""
    )
    dek = soup.select_one(".article-dek .lang-en")
    if dek is not None:
        all_text += " " + dek.get_text(" ", strip=True)
    for forbidden in (
        "restrained by a chain",
        "the chain restraint",
        "a trafficking element",
        "official handling concerns",
        "held by a chain",
        "bodies entered a case",
        "prolonged-control records",
        "differences in each notification",
    ):
        if forbidden.casefold() in all_text.casefold():
            issues.append(
                "batch11-final7 Feng/en old machine wording returned: "
                f"{forbidden}"
            )
    return issues


def batch11_final7_source_graph_issues(
    soup: BeautifulSoup,
) -> list[str]:
    """Reuse the authenticated 50-metadata/160-reference final6 graph."""
    return [
        issue.replace("batch11-final6", "batch11-final7")
        for issue in batch11_final6_source_graph_issues(soup)
    ]


def batch11_final7_freeze_issues(
    overrides: dict[str, bytes | str] | None = None,
) -> list[str]:
    """Derive 360 logical files minus the exact six-file final7 whitelist."""
    return [
        issue.replace("batch11-final6", "batch11-final7")
        for issue in batch11_final6_freeze_issues(overrides)
    ]


def batch11_final7_live_source_map(
    soup: BeautifulSoup,
) -> dict[tuple[str, str, str, str], dict[str, str]]:
    """Build seven source relationships without treating the DOM as prose truth."""
    body = body_for(soup, "en")
    if body is None:
        return {}
    source_nodes = body.select("ul.source-list > li[data-source-id]")
    dates = {
        source.get("data-source-id", ""): (
            source.get("data-source-date", "") or "UNDATED"
        )
        for source in source_nodes
    }
    roles = {
        source.get("data-source-id", ""): source.get("data-source-type", "")
        for source in source_nodes
    }
    urls = {
        source.get("data-source-id", ""): (
            source.find("a").get("href", "") if source.find("a") else ""
        )
        for source in source_nodes
    }
    titles = {
        source.get("data-source-id", ""): (
            source.find("a").get_text(" ", strip=True)
            if source.find("a")
            else ""
        )
        for source in source_nodes
    }
    live: dict[tuple[str, str, str, str], dict[str, str]] = {}
    for key in BATCH11_FINAL7_TARGETS:
        node = batch11_final7_target_node(soup, key)
        if node is not None:
            refs = BATCH11_FINAL7_SOURCE_REFS[key]
            ref_ids = refs.split()
            live[key] = {
                "text": batch11_final7_visible_text(node, key),
                "source_refs": refs,
                "timeline_subject": node.get("data-timeline-subject", ""),
                "timeline_action": node.get("data-timeline-action", ""),
                "timeline_consequence": node.get(
                    "data-timeline-consequence", ""
                ),
                "source_date_audit": " | ".join(
                    f"{source_id}={dates.get(source_id, 'MISSING')}"
                    for source_id in ref_ids
                ),
                "visible_source_roles": " | ".join(
                    f"{source_id}:{roles.get(source_id, '')}"
                    for source_id in ref_ids
                ),
                "support_urls": " | ".join(
                    urls.get(source_id, "") for source_id in ref_ids
                ),
                "audit_title": " | ".join(
                    f"{source_id}: {titles.get(source_id, '')}"
                    for source_id in ref_ids
                ),
            }
    return live


def batch11_final7_contract_issues(
    key: tuple[str, str, str, str],
    row: dict[str, str],
    reread_row: dict[str, str],
) -> list[str]:
    """Authenticate each independently handwritten final7 specification."""
    issues: list[str] = []
    required = frozenset(contract_literals(row.get("required_all", "")))
    forbidden = frozenset(contract_literals(row.get("forbidden_any", "")))
    if required != BATCH11_FINAL7_REQUIRED_CONTRACT[key]:
        issues.append(
            f"batch11-final7 contract required anchors differ: {key[3]}"
        )
    if forbidden != BATCH11_FINAL7_FORBIDDEN_CONTRACT[key]:
        issues.append(
            f"batch11-final7 contract forbidden old prose differs: {key[3]}"
        )
    if len(required) < 4 or len(forbidden) < 2:
        issues.append(
            f"batch11-final7 contract is too weak: {key[3]}"
        )
    summary = row.get("fact_summary", "")
    folded = summary.casefold()
    if summary != BATCH11_FINAL7_EXPECTED_SUMMARY[key]:
        issues.append(
            f"batch11-final7 independent fact summary differs: {key[3]}"
        )
    if not all(
        marker in folded
        for marker in ("subject:", "action:", "source:", "consequence:")
    ) or not any(
        marker in folded for marker in ("remedy:", "remedy/public gap:")
    ):
        issues.append(
            f"batch11-final7 contract lacks subject/action/source/consequence/"
            f"remedy reasoning: {key[3]}"
        )
    revised = reread_row.get("revised_text", "")
    if (
        summary.strip() == revised.strip()
        or longest_common_normalized_fragment(summary, revised)
        >= min(180, max(110, len(revised) // 2))
    ):
        issues.append(
            f"batch11-final7 contract summary is copied from DOM: {key[3]}"
        )
    return issues


def batch11_final7_ledger_issues(
    *,
    page_override: BeautifulSoup | None = None,
    reread_rows_override: list[dict[str, str]] | None = None,
    contract_rows_override: list[dict[str, str]] | None = None,
    source_rows_override: list[dict[str, str]] | None = None,
) -> list[str]:
    """Authenticate final6 and bind exactly seven genuine final7 revisions."""
    issues: list[str] = []
    reread_rows = (
        reread_rows_override
        if reread_rows_override is not None
        else batch11_tsv_rows(SEMANTIC_REREAD_PATH)
    )
    contract_rows = (
        contract_rows_override
        if contract_rows_override is not None
        else batch11_tsv_rows(EDITORIAL_SEMANTIC_CONTRACT_PATH)
    )
    source_rows = (
        source_rows_override
        if source_rows_override is not None
        else batch11_tsv_rows(SOURCE_LEDGER_PATH)
    )
    if batch12_successor_active():
        # Final7 owns the authenticated prefix ending at the exact completed
        # final7 totals.  Batch12 is a later append and is validated by its own
        # 567-row gate; do not misclassify that successor suffix as part of the
        # seven-row final7 release.
        reread_rows = reread_rows[:BATCH11_FINAL7_REREAD_ROWS]
        contract_rows = contract_rows[:BATCH11_FINAL7_CONTRACT_ROWS]
        source_rows = source_rows[:BATCH11_FINAL7_SOURCE_ROWS]
    for path, rows, count, digest, label in (
        (
            SEMANTIC_REREAD_PATH,
            reread_rows,
            BATCH11_FINAL7_REREAD_PREFIX_ROWS,
            BATCH11_FINAL7_REREAD_PREFIX_SHA256,
            "batch11-final7 completed-final6 reread prefix",
        ),
        (
            EDITORIAL_SEMANTIC_CONTRACT_PATH,
            contract_rows,
            BATCH11_FINAL7_CONTRACT_PREFIX_ROWS,
            BATCH11_FINAL7_CONTRACT_PREFIX_SHA256,
            "batch11-final7 completed-final6 contract prefix",
        ),
        (
            SOURCE_LEDGER_PATH,
            source_rows,
            BATCH11_FINAL7_SOURCE_PREFIX_ROWS,
            BATCH11_FINAL7_SOURCE_PREFIX_SHA256,
            "batch11-final7 completed-final6 source prefix",
        ),
    ):
        issues.extend(
            exact_tsv_prefix_issues(
                path,
                base_rows=count,
                expected_sha256=digest,
                label=label,
            )
        )
        authenticated = batch11_tsv_rows(path)[:count]
        if rows[:count] != authenticated:
            issues.append(f"{label} changed in the supplied in-memory state")
    if (
        len(reread_rows),
        len(contract_rows),
        len(source_rows),
    ) != (
        BATCH11_FINAL7_REREAD_ROWS,
        BATCH11_FINAL7_CONTRACT_ROWS,
        BATCH11_FINAL7_SOURCE_ROWS,
    ):
        issues.append(
            "batch11-final7 final totals are not exactly 15996/7031/10063"
        )
    source_date_payload = source_date_ledger_predecessor_bytes()
    if sha256_bytes(source_date_payload) != BATCH11_FINAL7_SOURCE_DATE_SHA256:
        issues.append("batch11-final7 changed frozen source-date-ledger bytes")
    source_date_rows = source_date_ledger_predecessor_rows()
    if len(source_date_rows) != BATCH11_FINAL7_SOURCE_DATE_ROWS:
        issues.append(
            "batch11-final7 source-date ledger no longer has 294 data rows"
        )

    reread_suffix = reread_rows[BATCH11_FINAL7_REREAD_PREFIX_ROWS:]
    contract_suffix = contract_rows[BATCH11_FINAL7_CONTRACT_PREFIX_ROWS:]
    source_suffix = source_rows[BATCH11_FINAL7_SOURCE_PREFIX_ROWS:]
    if (
        len(reread_suffix),
        len(contract_suffix),
        len(source_suffix),
    ) != (7, 7, 7):
        issues.append(
            "batch11-final7 append is not exactly 7 reread / 7 contract / "
            "7 source rows"
        )
    if min(len(reread_suffix), len(contract_suffix), len(source_suffix)) < 7:
        return issues

    def visible_key(row: dict[str, str]) -> tuple[str, str, str, str]:
        return (
            row.get("slug", ""),
            row.get("language", ""),
            row.get("target_kind", ""),
            row.get("target_id", ""),
        )

    def source_key(row: dict[str, str]) -> tuple[str, str, str, str]:
        kind = (
            "article-dek"
            if row.get("fact_id", "") == "article-dek"
            else "fact"
        )
        return (
            row.get("slug", ""),
            row.get("language", ""),
            kind,
            row.get("fact_id", ""),
        )

    expected_targets = set(BATCH11_FINAL7_TARGETS)
    reread_by_key = {visible_key(row): row for row in reread_suffix}
    contract_by_key = {visible_key(row): row for row in contract_suffix}
    source_by_key = {source_key(row): row for row in source_suffix}
    for name, mapping in (
        ("reread", reread_by_key),
        ("contract", contract_by_key),
        ("source", source_by_key),
    ):
        if len(mapping) != 7 or set(mapping) != expected_targets:
            issues.append(
                f"batch11-final7 {name} coverage is not exactly seven targets"
            )

    soup = batch11_final7_live_page(page_override)
    pre_soup = batch11_final7_rewind_page_for_final6(soup)
    if (
        batch11_final1_page_canonical_sha(pre_soup)
        != BATCH11_FINAL7_PAGE_PREIMAGE_SHA256
    ):
        issues.append(
            "batch11-final7 completed-final6 canonical page did not reconstruct"
        )
    pre_inventory = batch11_final7_inventory(pre_soup)
    live_inventory = batch11_final7_inventory(soup)
    if set(pre_inventory) != set(live_inventory):
        issues.append("batch11-final7 added or removed a public semantic target")
    changed = {
        key
        for key in set(pre_inventory) & set(live_inventory)
        if pre_inventory[key] != live_inventory[key]
    }
    if changed != expected_targets:
        issues.append(
            "batch11-final7 genuine visible delta is not exactly seven targets"
        )
    for key in set(pre_inventory) & set(live_inventory):
        if (
            pre_inventory[key]["source_refs"]
            != live_inventory[key]["source_refs"]
        ):
            issues.append(
                f"batch11-final7 changed frozen source refs: {'/'.join(key)}"
            )

    prefix_tips: dict[tuple[str, str, str], dict[str, str]] = {}
    for row in reread_rows[:BATCH11_FINAL7_REREAD_PREFIX_ROWS]:
        prefix_tips[
            (
                row.get("slug", ""),
                row.get("language", ""),
                row.get("target_id", ""),
            )
        ] = row
    prefix_source_tips: dict[tuple[str, str, str], dict[str, str]] = {}
    for row in source_rows[:BATCH11_FINAL7_SOURCE_PREFIX_ROWS]:
        prefix_source_tips[
            (
                row.get("slug", ""),
                row.get("language", ""),
                row.get("fact_id", ""),
            )
        ] = row
    live_sources = batch11_final7_live_source_map(soup)
    contract_ids: set[str] = set()

    for key in BATCH11_FINAL7_TARGETS:
        label = "/".join(key)
        reread = reread_by_key.get(key)
        contract = contract_by_key.get(key)
        source = source_by_key.get(key)
        node = batch11_final7_target_node(soup, key)
        if reread is None or contract is None or source is None or node is None:
            issues.append(f"batch11-final7 missing bound evidence: {label}")
        else:
            live_text = batch11_final7_visible_text(node, key)
            expected_id_prefix = (
                f"{BATCH11_FINAL7_CONTRACT_PREFIX}{':'.join(key)}:"
            )
            contract_id = reread.get("contract_id", "")
            if not contract_id.startswith(expected_id_prefix):
                issues.append(
                    f"batch11-final7 reread ID is not target-bound: {label}"
                )
            if not contract_id or contract_id in contract_ids:
                issues.append(
                    f"batch11-final7 reread ID is blank or duplicate: {label}"
                )
            contract_ids.add(contract_id)
            if contract.get("contract_id", "") != contract_id:
                issues.append(
                    f"batch11-final7 contract/reread IDs differ: {label}"
                )
            if source.get("baseline_issue", "") != contract_id:
                issues.append(
                    f"batch11-final7 source/contract IDs differ: {label}"
                )
            if reread.get("result", "") != "PASS_AFTER_REVISION":
                issues.append(
                    f"batch11-final7 reread is not a genuine revision: {label}"
                )
            if "PASS_NO_CHANGE" in reread.values():
                issues.append(
                    f"batch11-final7 reread contains PASS_NO_CHANGE: {label}"
                )
            if reread.get("original_text", "") != BATCH11_FINAL7_OLD_TEXT[key]:
                issues.append(
                    f"batch11-final7 original_text is not the real old DOM: {label}"
                )
            if reread.get("revised_text", "") != live_text:
                issues.append(
                    f"batch11-final7 revised_text differs byte-for-byte from DOM: "
                    f"{label}"
                )
            if live_text != BATCH11_FINAL7_EXPECTED_TEXT[key]:
                issues.append(
                    f"batch11-final7 live text is not approved: {label}"
                )
            if reread.get("original_text", "") == reread.get(
                "revised_text", ""
            ):
                issues.append(
                    f"batch11-final7 reread records no real revision: {label}"
                )
            if reread.get("source_refs", "") != (
                BATCH11_FINAL7_EXPECTED_REFS[key]
            ):
                issues.append(
                    f"batch11-final7 reread refs differ from DOM: {label}"
                )
            if not all(
                anchor.casefold() in reread.get("issue_found", "").casefold()
                for anchor in BATCH11_FINAL7_ISSUE_ANCHORS[key]
            ):
                issues.append(
                    f"batch11-final7 issue_found omits the real old defect: {label}"
                )
            basis = reread.get("review_basis", "").casefold()
            if (
                "reread:batch11-final7" not in basis
                or "subject" not in basis
                or not any(marker in basis for marker in ("action", "disclosure"))
                or "source:" not in basis
                or "consequence" not in basis
            ):
                issues.append(
                    f"batch11-final7 review basis lacks independent reasoning: "
                    f"{label}"
                )
            predecessor = prefix_tips.get((key[0], key[1], key[3]))
            predecessor_matches = (
                predecessor is not None
                and (
                    batch11_final7_timeline_text(
                        predecessor.get("revised_text", "")
                    )
                    == batch11_final7_timeline_text(
                        reread.get("original_text", "")
                    )
                    if key in BATCH11_FINAL7_TIMELINE_TARGETS
                    else predecessor.get("revised_text", "")
                    == reread.get("original_text", "")
                )
            )
            if not predecessor_matches:
                issues.append(
                    f"batch11-final7 reread predecessor chain is broken: {label}"
                )
            issues.extend(
                batch11_final7_contract_issues(key, contract, reread)
            )

            live = live_sources.get(key)
            predecessor_source = prefix_source_tips.get(
                (key[0], key[1], key[3])
            )
            if key[2] == "article-dek":
                if predecessor_source is not None:
                    issues.append(
                        "batch11-final7 article-dek unexpectedly has a prior "
                        "fact-source row"
                    )
            elif predecessor_source is None:
                issues.append(
                    f"batch11-final7 source predecessor is missing: {label}"
                )
            if live is None:
                issues.append(
                    f"batch11-final7 live source relationship is missing: {label}"
                )
            else:
                for field, expected in (
                    ("current_visible_text", live["text"]),
                    ("data_source_ref", live["source_refs"]),
                    ("support_urls", live["support_urls"]),
                    ("source_roles", live["visible_source_roles"]),
                    ("audit_final_url", live["support_urls"]),
                    ("audit_title", live["audit_title"]),
                    ("audit_source_id", live["source_refs"]),
                    ("audit_claim_compared", live["text"]),
                    ("source_date_audit", live["source_date_audit"]),
                    ("reread_revision_text", live["text"]),
                    ("visible_source_roles", live["visible_source_roles"]),
                    ("timeline_subject", live["timeline_subject"]),
                    ("timeline_action", live["timeline_action"]),
                    ("timeline_consequence", live["timeline_consequence"]),
                ):
                    if source.get(field, "") != expected:
                        issues.append(
                            f"batch11-final7 source {field} differs from live "
                            f"evidence: {label}"
                        )
            if predecessor_source is not None:
                for field in (
                    "data_source_ref",
                    "support_urls",
                    "source_roles",
                    "manual_review",
                    "source_date_audit",
                    "timeline_subject",
                    "timeline_action",
                    "timeline_consequence",
                ):
                    if source.get(field, "") != predecessor_source.get(
                        field, ""
                    ):
                        issues.append(
                            f"batch11-final7 source changed frozen mapping "
                            f"{field}: {label}"
                        )
            if source.get("section_id", "") != (
                BATCH11_FINAL7_EXPECTED_SECTIONS[key]
            ):
                issues.append(
                    f"batch11-final7 source section differs: {label}"
                )
            if source.get("visible_timeline_order", "") != (
                BATCH11_FINAL7_EXPECTED_TIMELINE_ORDER.get(key, "")
            ):
                issues.append(
                    f"batch11-final7 source timeline order differs: {label}"
                )
            if source.get("audit_decision", "") != "PASS_FINAL7_SOURCE_MAPPING":
                issues.append(
                    f"batch11-final7 source decision differs: {label}"
                )
            if source.get("reread_result", "") != "PASS_AFTER_REVISION":
                issues.append(
                    f"batch11-final7 source result differs: {label}"
                )
            if "PASS_NO_CHANGE" in source.values():
                issues.append(
                    f"batch11-final7 source contains PASS_NO_CHANGE: {label}"
                )
            if "reread:batch11-final7" not in source.get(
                "resolution_action", ""
            ) or "reread:batch11-final7" not in source.get("final_issue", ""):
                issues.append(
                    f"batch11-final7 source marker is absent: {label}"
                )
            if source.get("audit_accessed_at", "") != "2026-07-24":
                issues.append(
                    f"batch11-final7 source audit date differs: {label}"
                )
            if source.get("verification_status", "") != "VERIFIED_RETROSPECTIVE":
                issues.append(
                    f"batch11-final7 source verification differs: {label}"
                )
            if source.get("manual_review", "") != (
                BATCH11_FINAL7_EXPECTED_MANUAL_REVIEW[key]
            ):
                issues.append(
                    f"batch11-final7 source manual-review status differs: {label}"
                )
            if source.get("reread_card_current", "") != (
                BATCH11_FINAL7_FROZEN_CARD_SNAPSHOT
            ):
                issues.append(
                    f"batch11-final7 source frozen card snapshot differs: {label}"
                )
            for field, expected in (
                BATCH11_FINAL7_EXPECTED_SOURCE_AUDIT[key].items()
            ):
                if source.get(field, "") != expected:
                    issues.append(
                        f"batch11-final7 source {field} audit evidence differs: "
                        f"{label}"
                    )
            if not all(
                anchor.casefold()
                in source.get("reread_issue_found", "").casefold()
                for anchor in BATCH11_FINAL7_ISSUE_ANCHORS[key]
            ):
                issues.append(
                    f"batch11-final7 source omits the old defect: {label}"
                )
            for field in (
                "locatable_support",
                "audit_locator",
                "audit_support_summary",
                "audit_relationship",
                "reread_h1_current",
                "reread_dek_current",
                "reread_source_titles_current",
                "reread_card_current",
                "visible_subject_anchor",
                "visible_action_anchor",
                "visible_consequence_anchor",
            ):
                if not source.get(field, "").strip():
                    issues.append(
                        f"batch11-final7 source lacks {field}: {label}"
                    )
    return issues


def batch11_final7_wiring_issues(
    source_override: str | None = None,
) -> list[str]:
    source = source_override or Path(__file__).read_text(encoding="utf-8")
    try:
        tree = ast.parse(source)
    except SyntaxError as exc:
        return [f"batch11-final7 checker wiring is not parseable: {exc}"]
    functions = {
        node.name: node
        for node in tree.body
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
    }

    def called(function_name: str, callee: str) -> bool:
        function = functions.get(function_name)
        return bool(function) and any(
            isinstance(node, ast.Call)
            and isinstance(node.func, ast.Name)
            and node.func.id == callee
            for node in ast.walk(function)
        )

    issues: list[str] = []
    if not called("validate_paths", "batch11_final7_release_issues"):
        issues.append(
            "validate_paths no longer forces batch11-final7 release validation"
        )
    for callee in (
        "batch11_final7_page_semantic_issues",
        "batch11_final7_source_graph_issues",
        "batch11_final7_ledger_issues",
        "batch11_final7_freeze_issues",
        "batch11_final7_wiring_issues",
    ):
        if not called("batch11_final7_release_issues", callee):
            issues.append(
                f"batch11-final7 release gate no longer calls {callee}"
            )
    if not called("self_tests", "batch11_final7_named_negative_tests"):
        issues.append("self_tests no longer runs batch11-final7 named mutations")
    if not called(
        "case_semantic_contract_issues",
        "batch11_final7_page_semantic_issues",
    ):
        issues.append(
            "case semantic route no longer forces batch11-final7 page validation"
        )
    for historical in (
        "batch11_final4_release_issues",
        "batch11_final5_release_issues",
        "batch11_final6_release_issues",
    ):
        if not called("validate_paths", historical):
            issues.append(
                f"validate_paths no longer replays {historical} on final6 state"
            )
    if not called(
        "batch11_final7_historical_final6_state",
        "batch11_final7_rewind_page_for_final6",
    ):
        issues.append("batch11-final7 historical state no longer rewinds the page")
    return issues


def batch11_final7_release_issues(
    *,
    page_override: BeautifulSoup | None = None,
    reread_rows_override: list[dict[str, str]] | None = None,
    contract_rows_override: list[dict[str, str]] | None = None,
    source_rows_override: list[dict[str, str]] | None = None,
    freeze_overrides: dict[str, bytes | str] | None = None,
    checker_source_override: str | None = None,
) -> list[str]:
    soup = batch11_final7_live_page(page_override)
    path = POSTS / BATCH11_FINAL7_TARGET_FILENAME
    issues: list[str] = []
    issues.extend(batch11_final7_page_semantic_issues(soup, path))
    issues.extend(batch11_final7_source_graph_issues(soup))
    issues.extend(
        batch11_final7_ledger_issues(
            page_override=soup,
            reread_rows_override=reread_rows_override,
            contract_rows_override=contract_rows_override,
            source_rows_override=source_rows_override,
        )
    )
    if not batch12_successor_active():
        issues.extend(batch11_final7_freeze_issues(freeze_overrides))
    issues.extend(batch11_final7_wiring_issues(checker_source_override))
    return issues


def batch11_final7_named_negative_tests() -> list[tuple[str, bool]]:
    """Mutate real final7 DOM, attributes, ledgers, graph, scope and wiring."""
    checks: list[tuple[str, bool]] = []
    baseline = batch11_final7_release_issues()

    def record(label: str, caught: bool) -> None:
        checks.append((label, not baseline and bool(caught)))

    def clone() -> BeautifulSoup:
        return batch11_final7_live_page()

    def mutated_text(
        key: tuple[str, str, str, str],
        old: str,
        new: str,
    ) -> BeautifulSoup:
        soup = clone()
        node = batch11_final7_target_node(soup, key)
        assert node is not None
        text = batch11_final7_visible_text(node, key)
        assert old in text
        batch11_final7_set_visible_text(
            node,
            key,
            text.replace(old, new, 1),
        )
        return soup

    path = POSTS / BATCH11_FINAL7_TARGET_FILENAME
    for number, key, old, new, label in (
        (
            1,
            BATCH11_FINAL7_TARGETS[0],
            "held in chains",
            "restrained by a chain",
            "deck restrained by a chain restored",
        ),
        (
            2,
            BATCH11_FINAL7_TARGETS[2],
            "woman was held in chains",
            "the chain restraint",
            "chain-restraint noun restored",
        ),
        (
            3,
            BATCH11_FINAL7_TARGETS[4],
            "trafficking had occurred",
            "a trafficking element",
            "trafficking weakened to an element",
        ),
        (
            4,
            BATCH11_FINAL7_TARGETS[4],
            "problems in the local authorities’ initial handling",
            "official handling concerns",
            "handling problems weakened to concerns",
        ),
    ):
        soup = mutated_text(key, old, new)
        record(
            f"{number:02d} {label}",
            batch11_final7_page_semantic_issues(soup, path),
        )

    held_catches: list[bool] = []
    for key in BATCH11_FINAL7_TARGETS[:5]:
        if "held in chains" in BATCH11_FINAL7_EXPECTED_TEXT[key]:
            soup = mutated_text(key, "held in chains", "")
            held_catches.append(
                bool(batch11_final7_page_semantic_issues(soup, path))
            )
    record("05 held-in-chains deleted from any applicable node", all(held_catches))

    location_catches: list[bool] = []
    for key in (
        BATCH11_FINAL7_TARGETS[0],
        BATCH11_FINAL7_TARGETS[1],
        BATCH11_FINAL7_TARGETS[3],
    ):
        for phrase in ("Feng County", "Jiangsu"):
            soup = mutated_text(key, phrase, "Another place")
            location_catches.append(
                bool(batch11_final7_page_semantic_issues(soup, path))
            )
    record("06 Feng County or Jiangsu deleted/changed", all(location_catches))

    trafficking_catches: list[bool] = []
    for key, phrase in (
        (BATCH11_FINAL7_TARGETS[1], "human trafficking"),
        (BATCH11_FINAL7_TARGETS[2], "trafficking route"),
        (BATCH11_FINAL7_TARGETS[4], "trafficking had occurred"),
    ):
        soup = mutated_text(key, phrase, "an ordinary family dispute")
        trafficking_catches.append(
            bool(batch11_final7_page_semantic_issues(soup, path))
        )
    record(
        "07 trafficking replaced by an ordinary family dispute",
        all(trafficking_catches),
    )

    soup = mutated_text(
        BATCH11_FINAL7_TARGETS[4],
        "revised earlier accounts",
        "",
    )
    record(
        "08 revision of earlier accounts deleted",
        batch11_final7_page_semantic_issues(soup, path),
    )
    soup = mutated_text(
        BATCH11_FINAL7_TARGETS[4],
        "problems in the local authorities’ initial handling of the case",
        "",
    )
    record(
        "09 local-authority initial-handling problems deleted",
        batch11_final7_page_semantic_issues(soup, path),
    )

    timeline4_catches: list[bool] = []
    for phrase in (
        "Freedom House’s February China Media Bulletin",
        "online censorship of discussion about the case",
        "police interference",
        "citizen investigators and supporters",
    ):
        soup = mutated_text(BATCH11_FINAL7_TARGETS[5], phrase, "")
        timeline4_catches.append(
            bool(batch11_final7_page_semantic_issues(soup, path))
        )
    record(
        "10 timeline-4 source/actor/action/affected people deleted",
        all(timeline4_catches),
    )

    soup = mutated_text(
        BATCH11_FINAL7_TARGETS[6],
        "an explanation of the differences among successive public notices",
        "the explanation of the differences in each notification",
    )
    record(
        "11 unresolved old notification relation restored",
        batch11_final7_page_semantic_issues(soup, path),
    )

    ref_catches: list[bool] = []
    for key in BATCH11_FINAL7_TARGETS[1:]:
        soup = clone()
        node = batch11_final7_target_node(soup, key)
        assert node is not None
        node["data-source-ref"] = "s1"
        ref_catches.append(
            bool(batch11_final7_page_semantic_issues(soup, path))
            and bool(batch11_final7_source_graph_issues(soup))
        )
    record("12 any final7 fact data-source-ref changed", all(ref_catches))

    timeline_attr_catches: list[bool] = []
    for key in BATCH11_FINAL7_TIMELINE_TARGETS:
        for attr in (
            "data-timeline-subject",
            "data-timeline-action",
            "data-timeline-consequence",
        ):
            soup = clone()
            node = batch11_final7_target_node(soup, key)
            assert node is not None
            node[attr] = "unauthorized-final7-attribute"
            timeline_attr_catches.append(
                bool(batch11_final7_page_semantic_issues(soup, path))
            )
    record(
        "13 any final7 timeline subject/action/consequence changed",
        all(timeline_attr_catches),
    )

    date_catches: list[bool] = []
    for key in BATCH11_FINAL7_TIMELINE_TARGETS:
        expected = BATCH11_FINAL7_EXPECTED_TEXT[key][:10]
        soup = mutated_text(key, expected, "2099-12-31")
        date_catches.append(
            bool(batch11_final7_page_semantic_issues(soup, path))
        )
    record("14 any final7 timeline date changed", all(date_catches))

    reread_rows = batch11_tsv_rows(SEMANTIC_REREAD_PATH)
    contract_rows = batch11_tsv_rows(EDITORIAL_SEMANTIC_CONTRACT_PATH)
    source_rows = batch11_tsv_rows(SOURCE_LEDGER_PATH)
    for number, rows, prefix, keyword, label in (
        (
            15,
            reread_rows,
            BATCH11_FINAL7_REREAD_PREFIX_ROWS,
            "reread_rows_override",
            "reread",
        ),
        (
            16,
            contract_rows,
            BATCH11_FINAL7_CONTRACT_PREFIX_ROWS,
            "contract_rows_override",
            "contract",
        ),
        (
            17,
            source_rows,
            BATCH11_FINAL7_SOURCE_PREFIX_ROWS,
            "source_rows_override",
            "source mapping",
        ),
    ):
        catches: list[bool] = []
        for offset in range(7):
            mutated = [dict(row) for row in rows]
            del mutated[prefix + offset]
            catches.append(
                bool(
                    batch11_final7_ledger_issues(
                        **{keyword: mutated}
                    )
                )
            )
        record(
            f"{number:02d} any of seven final7 {label} rows deleted",
            all(catches),
        )

    prefix_catches: list[bool] = []
    for rows, index, field, keyword in (
        (
            reread_rows,
            BATCH11_FINAL7_REREAD_PREFIX_ROWS - 1,
            "issue_found",
            "reread_rows_override",
        ),
        (
            contract_rows,
            BATCH11_FINAL7_CONTRACT_PREFIX_ROWS - 1,
            "fact_summary",
            "contract_rows_override",
        ),
        (
            source_rows,
            BATCH11_FINAL7_SOURCE_PREFIX_ROWS - 1,
            "audit_title",
            "source_rows_override",
        ),
    ):
        mutated = [dict(row) for row in rows]
        mutated[index][field] = mutated[index].get(field, "") + " altered"
        prefix_catches.append(
            bool(batch11_final7_ledger_issues(**{keyword: mutated}))
        )
    record("18 completed-final6 prefix rewritten", all(prefix_catches))

    contract_catches: list[bool] = []
    for offset in range(7):
        mutated = [dict(row) for row in contract_rows]
        mutated[BATCH11_FINAL7_CONTRACT_PREFIX_ROWS + offset][
            "required_all"
        ] = "actor:weakened"
        contract_catches.append(
            bool(
                batch11_final7_ledger_issues(
                    contract_rows_override=mutated
                )
            )
        )
    record("19 any final7 independent contract weakened", all(contract_catches))

    summary_catches: list[bool] = []
    for offset in range(7):
        mutated = [dict(row) for row in contract_rows]
        mutated[BATCH11_FINAL7_CONTRACT_PREFIX_ROWS + offset][
            "fact_summary"
        ] = (
            "Subject: fabricated. Action: fabricated. Source: fabricated. "
            "Consequence: fabricated. Remedy: fabricated."
        )
        summary_catches.append(
            bool(
                batch11_final7_ledger_issues(
                    contract_rows_override=mutated
                )
            )
        )
    record(
        "20 any final7 fact summary replaced by labelled pseudo-evidence",
        all(summary_catches),
    )

    audit_evidence_catches: list[bool] = []
    for offset in range(7):
        for field in (
            "audit_support_summary",
            "audit_relationship",
            "visible_subject_anchor",
            "visible_action_anchor",
            "visible_consequence_anchor",
            "visible_timeline_order",
            "source_roles",
            "visible_source_roles",
            "reread_card_current",
            "manual_review",
        ):
            mutated = [dict(row) for row in source_rows]
            mutated[BATCH11_FINAL7_SOURCE_PREFIX_ROWS + offset][field] = (
                "fabricated-final7-audit-evidence"
            )
            audit_evidence_catches.append(
                bool(
                    batch11_final7_ledger_issues(
                        source_rows_override=mutated
                    )
                )
            )
    record(
        "21 any final7 audit relationship/anchor/order/card/manual field falsified",
        all(audit_evidence_catches),
    )

    freeze_catches = [
        bool(
            batch11_final7_freeze_issues(
                {
                    "posts/2024-report.html": (
                        ROOT / "posts/2024-report.html"
                    ).read_bytes() + b"\nfinal7 frozen mutation"
                }
            )
        ),
        bool(
            batch11_final7_freeze_issues(
                {
                    "script.js": (ROOT / "script.js").read_bytes()
                    + b"\nfinal7 frozen mutation"
                }
            )
        ),
        bool(
            batch11_final7_freeze_issues(
                {
                    "batch11-final7-unknown-extra.txt": b"unknown extra"
                }
            )
        ),
    ]
    record(
        "22 non-whitelist file changed or path added",
        all(freeze_catches),
    )

    graph_catches: list[bool] = []
    soup = clone()
    source = body_for(soup, "en").select_one('li[data-source-id="s4"]')
    assert source is not None
    source["data-source-type"] = "tampered-source-type"
    graph_catches.append(
        bool(batch11_final7_source_graph_issues(soup))
    )
    soup = clone()
    ref = batch11_final7_target_node(soup, BATCH11_FINAL7_TARGETS[1])
    assert ref is not None
    ref["data-source-ref"] = "s1"
    graph_catches.append(
        bool(batch11_final7_source_graph_issues(soup))
    )
    record("23 source metadata or reference graph changed", all(graph_catches))

    soup = clone()
    non_target = batch11_final6_target_node(soup, BATCH11_FINAL6_TARGETS[0])
    assert non_target is not None
    non_target.append(" unauthorized final7 page rewrite")
    record(
        "24 non-target prose changed inside the whitelisted page",
        batch11_final7_ledger_issues(page_override=soup),
    )

    source_text = Path(__file__).read_text(encoding="utf-8")
    wiring_catches: list[bool] = []
    for needle, replacement, use_last in (
        (
            "issues.extend(batch11_final7_release_issues())",
            "issues.extend([])",
            True,
        ),
        (
            "+ batch11_final7_page_semantic_issues(soup, path)",
            "+ []",
            False,
        ),
        (
            "batch11_final7_checks = batch11_final7_named_negative_tests()",
            "batch11_final7_checks = []",
            True,
        ),
        (
            "issues.extend(batch11_final7_page_semantic_issues(soup, path))",
            "issues.extend([])",
            False,
        ),
        (
            "issues.extend(batch11_final7_source_graph_issues(soup))",
            "issues.extend([])",
            False,
        ),
        (
            "        batch11_final7_ledger_issues(",
            "        batch11_final7_ledger_issues_removed(",
            False,
        ),
        (
            "issues.extend(batch11_final7_freeze_issues(freeze_overrides))",
            "issues.extend([])",
            False,
        ),
        (
            "issues.extend(batch11_final7_wiring_issues(checker_source_override))",
            "issues.extend([])",
            False,
        ),
        (
            "batch11_final7_rewind_page_for_final6(batch11_final7_live_page())",
            "batch11_final7_live_page()",
            False,
        ),
    ):
        position = source_text.rfind(needle) if use_last else source_text.find(
            needle
        )
        mutated = (
            source_text[:position]
            + replacement
            + source_text[position + len(needle):]
            if position >= 0
            else source_text
        )
        wiring_catches.append(
            mutated != source_text
            and bool(batch11_final7_wiring_issues(mutated))
        )
    record(
        "25 final7 production/page/source/ledger/freeze/self-test/rewind wiring deleted",
        all(wiring_catches),
    )
    return checks


