    # 21-33.  Browser acceptance mutations.  Every case rewrites the real
    # ledger bytes in memory and requires a *semantic* rejection, so a case
    # can never be satisfied by the byte freeze alone.
    browser_pages = batch12_live_pages()
    acceptance_text = BATCH12_BROWSER_ACCEPTANCE_PATH.read_text(
        encoding="utf-8"
    )
    fixes_text = BATCH12_BROWSER_FIXES_PATH.read_text(encoding="utf-8")
    observations_text = BATCH12_OBSERVATIONS_PATH.read_text(encoding="utf-8")
    acceptance_header, _newline, acceptance_body = acceptance_text.partition(
        "\n"
    )
    acceptance_lines = acceptance_body.rstrip("\n").split("\n")

    def browser_column(name: str) -> int:
        return BATCH12_BROWSER_COLUMNS.index(name)

    def browser_cells() -> list[list[str]]:
        return [line.split("\t") for line in acceptance_lines]

    def browser_override(
        rows: list[list[str]],
    ) -> dict[str, bytes | str]:
        body = "\n".join("\t".join(cells) for cells in rows)
        return {
            BATCH12_BROWSER_ACCEPTANCE_RELATIVE:
                f"{acceptance_header}\n{body}\n".encode("utf-8"),
        }

    def browser_edit(
        index: int, column: str, value: str,
    ) -> dict[str, bytes | str]:
        cells = browser_cells()
        cells[index][browser_column(column)] = value
        return browser_override(cells)

    def browser_semantic_caught(
        overrides: dict[str, bytes | str],
    ) -> bool:
        """Require a real gate, never merely the SHA-256 freeze, to fire."""
        return any(
            "digest changed" not in issue
            for issue in batch12_browser_issues(overrides, browser_pages)
        )

    def browser_digest_caught(
        overrides: dict[str, bytes | str],
    ) -> bool:
        return any(
            "digest changed" in issue
            for issue in batch12_browser_issues(overrides, browser_pages)
        )

    def browser_index(predicate) -> int:
        for index, cells in enumerate(browser_cells()):
            if predicate(cells):
                return index
        raise AssertionError("batch12 browser ledger lost a required row")

