def contract_literals(value: str) -> tuple[str, ...]:
    return tuple(part.strip() for part in value.split("||") if part.strip())


def normalize_reread_text(value: str) -> str:
    return " ".join((value or "").split())


def normalize_batch11_visible_text(value: str) -> str:
    """Canonicalize visible spacing, including French NBSP before punctuation."""
    collapsed = normalize_reread_text(value)
    return re.sub(r"\s+([,.;:!?，。；：！？])", r"\1", collapsed)


def normalized_contiguous_stream(value: str) -> str:
    """Collapse spacing and punctuation before measuring copied prose."""
    return re.sub(r"[\W_]+", "", (value or "").casefold(), flags=re.UNICODE)


def longest_common_normalized_fragment(left: str, right: str) -> int:
    """Return the longest continuous normalized character fragment."""
    left_stream = normalized_contiguous_stream(left)
    right_stream = normalized_contiguous_stream(right)
    if not left_stream or not right_stream:
        return 0
    return difflib.SequenceMatcher(
        None, left_stream, right_stream, autojunk=False
    ).find_longest_match().size


def final1_source_removal(row: dict[str, str]) -> bool:
    """Recognize the append-only tombstone for a verified orphan-source deletion."""
    return (
        row.get("contract_id", "").startswith(BATCH10_FINAL1_CONTRACT_PREFIX)
        and row.get("target_kind", "") == "source-title"
        and row.get("source_refs", "").startswith("source-removed:")
        and row.get("revised_text", "").startswith("[SOURCE REMOVED:")
    )


