def normalized_final3_key(row: dict[str, str]) -> tuple[str, str, str]:
    """Normalize the three ledger key fields before note-template comparisons."""
    return tuple(
        re.sub(r"[^\w]+", "-", normalize_reread_text(row.get(field, "")).casefold()).strip("-")
        for field in ("slug", "language", "target_id")
    )


def normalized_final3_note(row: dict[str, str], field: str) -> str:
    """Remove only the normalized row labels, never the language-specific defect details."""
    note = normalize_reread_text(row.get(field, "")).casefold()
    variants = set(normalized_final3_key(row))
    variants.update(
        normalize_reread_text(row.get(name, "")).casefold()
        for name in ("slug", "language", "target_id")
    )
    for value in sorted((value for value in variants if value), key=len, reverse=True):
        note = re.sub(rf"(?<!\w){re.escape(value)}(?!\w)", "<key>", note)
    return re.sub(r"\s+", " ", note).strip()


def extract_semantic_reread_targets(soup: BeautifulSoup, lang: str) -> dict[str, dict[str, str]]:
    """Enumerate visible review targets and their source relationships."""
    body = body_for(soup, lang)
    if body is None:
        return {}
    source_ids = [node.get("data-source-id", "") for node in body.select("li[data-source-id]")]
    result: dict[str, dict[str, str]] = {}
    for target_id, selector in (
        ("article-title", f".article-title .lang-{lang}"),
        ("article-dek", f".article-dek .lang-{lang}"),
    ):
        node = soup.select_one(selector)
        if node is not None:
            result[target_id] = {
                "text": normalize_reread_text(node.get_text(" ", strip=True)),
                "text_exact": node.get_text(" ", strip=True),
                "target_kind": target_id,
                "source_refs": "page-sources:" + " ".join(source_ids),
            }
    batch10_slug = next(
        (
            slug for slug in BATCH10_FINAL1_META_PERIODS
            if body.select_one(f'[data-fact-id^="{slug}-"]') is not None
        ),
        None,
    )
    if batch10_slug is not None and (batch10_slug, lang) in BATCH10_FINAL1_META_TARGETS:
        node = soup.select_one(f".article-meta .lang-{lang}")
        if node is not None:
            result["article-meta"] = {
                "text": normalize_reread_text(node.get_text(" ", strip=True)),
                "text_exact": node.get_text(" ", strip=True),
                "target_kind": "article-meta",
                "source_refs": "page-sources:" + " ".join(source_ids),
            }
    for node in body.select("[data-fact-id]"):
        if node.select_one("[data-fact-id]"):
            continue
        target_id = node.get("data-fact-id", "")
        if not target_id or target_id.endswith("-sources"):
            continue
        result[target_id] = {
            "text": normalize_reread_text(node.get_text(" ", strip=True)),
            "text_exact": node.get_text(" ", strip=True),
            "target_kind": "fact",
            "source_refs": node.get("data-source-ref", ""),
        }
    tian_gap = body.select_one(
        '[data-fact-id="tiananmen-1989-evidence-official-gap"][data-accountability]'
    )
    if tian_gap is not None:
        value = tian_gap.get("data-accountability", "")
        result["tiananmen-1989-evidence-official-gap@data-accountability"] = {
            "text": normalize_reread_text(value),
            "text_exact": value,
            "target_kind": "fact-attribute",
            "source_refs": tian_gap.get("data-source-ref", ""),
        }
    for source in body.select("li[data-source-id]"):
        source_id = source.get("data-source-id", "")
        anchor = source.find("a")
        if not source_id or anchor is None:
            continue
        result[f"source-title:{source_id}"] = {
            "text": normalize_reread_text(anchor.get_text(" ", strip=True)),
            "text_exact": anchor.get_text(" ", strip=True),
            "target_kind": "source-title",
            "source_refs": source_id,
        }
    if body.select_one('[data-fact-id="hk-12-overview-1"]') is not None:
        source = body.select_one('li[data-source-id="s4"]')
        label = source.find("b") if source else None
        if label is not None:
            result["s4"] = {
                "text": normalize_reread_text(label.get_text(" ", strip=True)),
                "text_exact": label.get_text(" ", strip=True),
                "target_kind": "source-category",
                "source_refs": "s4",
            }
    return result


def semantic_reread_key(row: dict[str, str]) -> tuple[str, str, str]:
    return (
        row.get("slug", ""),
        row.get("language", ""),
        row.get("target_id", ""),
    )


def semantic_reread_groups(
    rows: list[dict[str, str]],
) -> dict[tuple[str, str, str], list[dict[str, str]]]:
    groups: dict[tuple[str, str, str], list[dict[str, str]]] = defaultdict(list)
    for row in rows:
        groups[semantic_reread_key(row)].append(row)
    return groups


def source_ref_only_revision(
    earlier: dict[str, str] | None,
    later: dict[str, str],
) -> bool:
    """Recognize an honest batch-nine source expansion with unchanged prose.

    A page title or deck cites the page-wide source set.  Tianshui gained a
    fourth source without changing those two visible strings.  The ledger must
    retain that attribution change as a new chain tip, but it must not become a
    loophole for calling an unchanged-text row a revision.
    """
    contract_id = later.get("contract_id", "")
    issue = normalize_reread_text(later.get("issue_found", "")).casefold()
    is_batch9_page_scope = (
        later.get("target_kind", "") in {"article-title", "article-dek"}
        and contract_id.startswith(BATCH9_CONTRACT_PREFIX)
        and issue.startswith("source-ref expansion:")
    )
    is_batch10_ref_revision = (
        contract_id.startswith((
            BATCH10_CONTRACT_PREFIX, BATCH10_FINAL1_CONTRACT_PREFIX,
            BATCH10_FINAL2_CONTRACT_PREFIX,
        ))
        and issue.startswith(("source-ref expansion:", "source-ref correction:"))
    )
    if not (is_batch9_page_scope or is_batch10_ref_revision):
        return False
    if normalize_reread_text(later.get("original_text", "")) != normalize_reread_text(
        later.get("revised_text", "")
    ):
        return False
    if earlier is None:
        # A newly covered batch-ten target has no older ledger row, so retain
        # the pre-edit/current ref pair in its detailed issue and verify that
        # pair against the checked-in chain tip.  This keeps an unchanged-text
        # source correction auditable without fabricating a predecessor row.
        if not is_batch10_ref_revision:
            return False
        match = re.search(
            r"pre-edit attribution '([^']*)' did not match the verified current relationship '([^']*)'",
            issue,
        )
        if not match:
            return False
        old_value, recorded_new_value = match.groups()
        actual_new_value = later.get("source_refs", "").casefold()
        return bool(recorded_new_value) and old_value != recorded_new_value and recorded_new_value == actual_new_value
    old_value = earlier.get("source_refs", "")
    new_value = later.get("source_refs", "")
    if is_batch10_ref_revision:
        return bool(old_value) and bool(new_value) and old_value != new_value
    old_page_scope = old_value.startswith("page-sources:")
    new_page_scope = new_value.startswith("page-sources:")
    if not old_page_scope or not new_page_scope:
        return False
    old_refs = tuple(old_value.removeprefix("page-sources:").split())
    new_refs = tuple(new_value.removeprefix("page-sources:").split())
    return bool(old_refs) and set(old_refs) < set(new_refs) and tuple(
        ref for ref in new_refs if ref in set(old_refs)
    ) == old_refs


def semantic_reread_chain_issues(rows: list[dict[str, str]]) -> list[str]:
    """Validate genuine successive revisions without flattening their history."""
    issues: list[str] = []
    for key, chain in semantic_reread_groups(rows).items():
        if len(chain) < 2:
            continue
        label = "/".join(key)
        if chain[-1].get("result") != "PASS_AFTER_REVISION":
            issues.append(f"semantic reread revision chain does not end in a real revision for {label}")
        if any(row.get("result") not in {"PASS_NO_CHANGE", "PASS_AFTER_REVISION"} for row in chain):
            issues.append(f"semantic reread revision chain contains an invalid result for {label}")
        contract_ids = [
            row.get("contract_id", "") for row in chain
            if row.get("result") == "PASS_AFTER_REVISION"
        ]
        if not all(contract_ids) or len(contract_ids) != len(set(contract_ids)):
            issues.append(f"semantic reread revision chain lacks distinct contract ids for {label}")
        kinds = {row.get("target_kind", "") for row in chain}
        is_batch12_timeline_successor = (
            key[0] == "guiyang-quarantine-bus-crash"
            and key[2]
            == "guiyang-quarantine-bus-crash-timeline-5"
            and kinds == {"fact", "timeline"}
            and chain[-1].get("contract_id", "").startswith(
                BATCH12_CONTRACT_PREFIX
            )
        )
        if len(kinds) != 1 and not is_batch12_timeline_successor:
            issues.append(f"semantic reread revision chain changes target kind for {label}")
        for earlier, later in zip(chain, chain[1:]):
            same_text_revision = (
                later.get("result") == "PASS_AFTER_REVISION"
                and normalize_reread_text(later.get("original_text", ""))
                == normalize_reread_text(later.get("revised_text", ""))
            )
            if same_text_revision and not source_ref_only_revision(earlier, later):
                issues.append(
                    f"semantic reread same-text revision lacks a genuine source-ref expansion for {label}"
                )
            if later.get("contract_id", "").startswith(
                (
                    BATCH8_FINAL3_CONTRACT_PREFIX,
                    BATCH9_FINAL2_CONTRACT_PREFIX,
                    BATCH10_FINAL3_CONTRACT_PREFIX,
                )
            ):
                chain_matches = earlier.get("revised_text", "") == later.get("original_text", "")
            elif later.get("contract_id", "").startswith(
                (
                    BATCH11_CONTRACT_PREFIX,
                    BATCH11_FINAL1_CONTRACT_PREFIX,
                    BATCH11_FINAL2_CONTRACT_PREFIX,
                    BATCH11_FINAL3_CONTRACT_PREFIX,
                    BATCH11_FINAL4_CONTRACT_PREFIX,
                    BATCH11_FINAL5_CONTRACT_PREFIX,
                    BATCH11_FINAL6_CONTRACT_PREFIX,
                    BATCH11_FINAL7_CONTRACT_PREFIX,
                )
            ):
                if (
                    later.get("contract_id", "").startswith(
                        BATCH11_FINAL7_CONTRACT_PREFIX
                    )
                    and later.get("target_id", "") in {
                        key[3] for key in BATCH11_FINAL7_TIMELINE_TARGETS
                    }
                ):
                    chain_matches = batch11_final7_timeline_text(
                        earlier.get("revised_text", "")
                    ) == batch11_final7_timeline_text(
                        later.get("original_text", "")
                    )
                else:
                    chain_matches = normalize_batch11_visible_text(
                        earlier.get("revised_text", "")
                    ) == normalize_batch11_visible_text(
                        later.get("original_text", "")
                    )
            else:
                chain_matches = normalize_reread_text(
                    earlier.get("revised_text", "")
                ) == normalize_reread_text(later.get("original_text", ""))
            if not chain_matches:
                issues.append(
                    f"semantic reread revision chain is broken between successive records for {label}"
                )
    return issues


def load_semantic_reread_rows() -> tuple[list[dict[str, str]], list[str]]:
    if not SEMANTIC_REREAD_PATH.exists():
        return [], [f"missing semantic reread ledger: {SEMANTIC_REREAD_PATH}"]
    with SEMANTIC_REREAD_PATH.open(encoding="utf-8", newline="") as handle:
        reader = csv.DictReader(handle, delimiter="\t")
        fields = tuple(reader.fieldnames or ())
        rows = list(reader)
    issues: list[str] = []
    missing = set(SEMANTIC_REREAD_FIELDS) - set(fields)
    if missing:
        issues.append(f"semantic reread ledger lacks fields: {sorted(missing)}")
        return rows, issues
    issues.extend(semantic_reread_chain_issues(rows))
    issues.extend(
        exact_tsv_prefix_issues(
            SEMANTIC_REREAD_PATH,
            base_rows=SEMANTIC_REREAD_BASE_ROWS,
            expected_sha256=SEMANTIC_REREAD_BASE_SHA256,
            label="semantic reread ledger",
        )
    )
    issues.extend(
        exact_tsv_prefix_issues(
            SEMANTIC_REREAD_PATH,
            base_rows=SEMANTIC_REREAD_FINAL1_ROWS,
            expected_sha256=SEMANTIC_REREAD_FINAL1_SHA256,
            label="semantic reread final1 history",
        )
    )
    issues.extend(
        exact_tsv_prefix_issues(
            SEMANTIC_REREAD_PATH,
            base_rows=SEMANTIC_REREAD_FINAL2_ROWS,
            expected_sha256=SEMANTIC_REREAD_FINAL2_SHA256,
            label="semantic reread final2 history",
        )
    )
    issues.extend(
        exact_tsv_prefix_issues(
            SEMANTIC_REREAD_PATH,
            base_rows=SEMANTIC_REREAD_BATCH10_ROWS,
            expected_sha256=SEMANTIC_REREAD_BATCH10_SHA256,
            label="semantic reread batch10 history",
        )
    )
    issues.extend(
        exact_tsv_prefix_issues(
            SEMANTIC_REREAD_PATH,
            base_rows=BATCH10_FINAL1_REREAD_ROWS,
            expected_sha256=BATCH10_FINAL1_REREAD_SHA256,
            label="semantic reread batch10-final1 history",
        )
    )
    issues.extend(
        exact_tsv_prefix_issues(
            SEMANTIC_REREAD_PATH,
            base_rows=BATCH10_FINAL2_REREAD_ROWS,
            expected_sha256=BATCH10_FINAL2_REREAD_SHA256,
            label="semantic reread batch10-final2 history",
        )
    )
    issues.extend(
        exact_tsv_prefix_issues(
            SEMANTIC_REREAD_PATH,
            base_rows=BATCH11_REREAD_BASE_ROWS,
            expected_sha256=BATCH11_REREAD_BASE_SHA256,
            label="semantic reread pre-batch11 history",
        )
    )
    for row in rows[SEMANTIC_REREAD_BASE_ROWS:SEMANTIC_REREAD_FINAL1_ROWS]:
        if not row.get("contract_id", "").startswith(BATCH9_FINAL1_CONTRACT_PREFIX):
            issues.append("semantic reread ledger has a post-baseline row outside the batch9-final1 chain")
        if row.get("result", "") != "PASS_AFTER_REVISION":
            issues.append("semantic reread ledger has a post-baseline row that is not a real revision")
    final2_rows = rows[SEMANTIC_REREAD_FINAL1_ROWS:SEMANTIC_REREAD_FINAL2_ROWS]
    for row in final2_rows:
        if not row.get("contract_id", "").startswith(BATCH9_FINAL2_CONTRACT_PREFIX):
            issues.append("semantic reread ledger has a post-final1 row outside the batch9-final2 chain")
        if row.get("result", "") != "PASS_AFTER_REVISION":
            issues.append("semantic reread ledger has a post-final1 row that is not a real revision")
    final2_keys = {
        (
            row.get("slug", ""), row.get("language", ""),
            row.get("target_kind", ""), row.get("target_id", ""),
        )
        for row in final2_rows
    }
    if len(final2_rows) != len(BATCH9_FINAL2_TARGETS) or final2_keys != BATCH9_FINAL2_TARGETS:
        issues.append(
            "batch9-final2 reread ledger must contain exactly its 23 genuine target-language revisions"
        )
    batch10_rows = rows[SEMANTIC_REREAD_FINAL2_ROWS:SEMANTIC_REREAD_BATCH10_ROWS]
    batch10_keys = set()
    for row in batch10_rows:
        key = (
            row.get("slug", ""), row.get("language", ""),
            row.get("target_kind", ""), row.get("target_id", ""),
        )
        if key in batch10_keys:
            issues.append(f"batch10 reread ledger duplicates a target: {'/'.join(key)}")
        batch10_keys.add(key)
        if row.get("slug", "") not in BATCH10_TARGET_SLUGS:
            issues.append("batch10 reread ledger contains a non-target article")
        if "reread:batch10" not in row.get("review_basis", ""):
            issues.append(f"batch10 reread row lacks its continuous batch marker for {'/'.join(key)}")
        if row.get("result", "") == "PASS_AFTER_REVISION":
            if not row.get("contract_id", "").startswith(BATCH10_CONTRACT_PREFIX):
                issues.append(f"batch10 revision lacks a batch10 contract for {'/'.join(key)}")
        elif row.get("result", "") == "PASS_NO_CHANGE":
            if row.get("contract_id", "") or row.get("issue_found", ""):
                issues.append(f"batch10 no-change row fabricates a revision for {'/'.join(key)}")
        else:
            issues.append(f"batch10 reread row has invalid result for {'/'.join(key)}")
    batch10_groups = semantic_reread_groups(rows[:SEMANTIC_REREAD_BATCH10_ROWS])
    batch10_predecessors = {
        id(later): earlier
        for chain in batch10_groups.values()
        for earlier, later in zip(chain, chain[1:])
    }
    batch10_visible_revisions = [
        row for row in batch10_rows
        if row.get("result") == "PASS_AFTER_REVISION"
        and normalize_reread_text(row.get("original_text", ""))
        != normalize_reread_text(row.get("revised_text", ""))
    ]
    batch10_source_revisions = [
        row for row in batch10_rows
        if row.get("result") == "PASS_AFTER_REVISION"
        and normalize_reread_text(row.get("original_text", ""))
        == normalize_reread_text(row.get("revised_text", ""))
    ]
    continuous_source_revisions = [
        row for row in batch10_source_revisions
        if batch10_predecessors.get(id(row)) is not None
        and source_ref_only_revision(batch10_predecessors[id(row)], row)
    ]
    snapshot_only_source_revisions = [
        row for row in batch10_source_revisions
        if batch10_predecessors.get(id(row)) is None
        and source_ref_only_revision(None, row)
    ]
    batch10_no_change = [row for row in batch10_rows if row.get("result") == "PASS_NO_CHANGE"]
    if (
        len(batch10_visible_revisions), len(continuous_source_revisions),
        len(snapshot_only_source_revisions), len(batch10_no_change),
    ) != (1516, 180, 22, 40):
        issues.append(
            "batch10 honest classification differs from 1516 visible-text revisions, "
            "180 continuous source-relation revisions, 22 snapshot-only source-relation "
            "records, and 40 no-change records"
        )
    if len(batch10_source_revisions) != (
        len(continuous_source_revisions) + len(snapshot_only_source_revisions)
    ):
        issues.append("batch10 has an unchanged-text revision outside the two auditable source-relation classes")

    final1_rows = rows[SEMANTIC_REREAD_BATCH10_ROWS:BATCH10_FINAL1_REREAD_ROWS]
    final1_contract_ids: set[str] = set()
    for row in final1_rows:
        key = (
            row.get("slug", ""), row.get("language", ""),
            row.get("target_kind", ""), row.get("target_id", ""),
        )
        if row.get("slug", "") not in BATCH10_TARGET_SLUGS:
            issues.append("batch10-final1 reread ledger contains a non-target article")
        if "reread:batch10-final1" not in row.get("review_basis", ""):
            issues.append(f"batch10-final1 reread row lacks its append marker for {'/'.join(key)}")
        if row.get("result", "") != "PASS_AFTER_REVISION":
            issues.append(f"batch10-final1 append is not a genuine revision for {'/'.join(key)}")
        contract_id = row.get("contract_id", "")
        if not contract_id.startswith(BATCH10_FINAL1_CONTRACT_PREFIX):
            issues.append(f"batch10-final1 revision lacks its final1 contract for {'/'.join(key)}")
        if not contract_id or contract_id in final1_contract_ids:
            issues.append(f"batch10-final1 contract id is blank or duplicated for {'/'.join(key)}")
        final1_contract_ids.add(contract_id)
    final1_groups = semantic_reread_groups(rows[:SEMANTIC_REREAD_BATCH10_ROWS])
    final1_text = [
        row for row in final1_rows
        if not final1_source_removal(row)
        and normalize_reread_text(row.get("original_text", ""))
        != normalize_reread_text(row.get("revised_text", ""))
    ]
    final1_tombstones = [row for row in final1_rows if final1_source_removal(row)]
    final1_sources = [
        row for row in final1_rows
        if not final1_source_removal(row)
        and normalize_reread_text(row.get("original_text", ""))
        == normalize_reread_text(row.get("revised_text", ""))
    ]
    final1_continuous = sum(
        bool(final1_groups.get((row.get("slug", ""), row.get("language", ""), row.get("target_id", ""))))
        for row in final1_rows
    )
    final1_without_predecessor = len(final1_rows) - final1_continuous
    if (
        len(final1_rows), len(final1_text), len(final1_tombstones), len(final1_sources),
        final1_continuous, final1_without_predecessor,
    ) != (432, 392, 10, 30, 396, 36):
        issues.append(
            "batch10-final1 classification differs from 432 total, 392 live DOM text, "
            "10 source tombstones, 30 source-only, 396 continuous, and 36 preimage-backed rows"
        )

    final2_rows = rows[BATCH10_FINAL1_REREAD_ROWS:BATCH10_FINAL2_REREAD_ROWS]
    final2_seen: set[tuple[str, str, str, str]] = set()
    final2_contract_ids: set[str] = set()
    all_groups = semantic_reread_groups(rows)
    for row in final2_rows:
        key4 = (
            row.get("slug", ""), row.get("language", ""),
            row.get("target_kind", ""), row.get("target_id", ""),
        )
        label = "/".join(key4)
        if key4 in final2_seen:
            issues.append(f"batch10-final2 reread duplicates a target: {label}")
        final2_seen.add(key4)
        if row.get("slug", "") not in BATCH10_FINAL2_TARGET_SLUGS:
            issues.append(f"batch10-final2 reread contains a frozen or non-target page: {label}")
        if row.get("language", "") not in LANGS:
            issues.append(f"batch10-final2 reread contains an unsupported language: {label}")
        if row.get("target_kind", "") not in {
            "article-title", "article-dek", "fact", "source-title", "fact-attribute",
        }:
            issues.append(f"batch10-final2 reread contains an unsupported target kind: {label}")
        contract_id = row.get("contract_id", "")
        if not contract_id.startswith(BATCH10_FINAL2_CONTRACT_PREFIX):
            issues.append(f"batch10-final2 reread lacks its final2 contract: {label}")
        if not contract_id or contract_id in final2_contract_ids:
            issues.append(f"batch10-final2 contract id is blank or duplicated: {label}")
        final2_contract_ids.add(contract_id)
        if row.get("result", "") != "PASS_AFTER_REVISION":
            issues.append(f"batch10-final2 reread contains a non-revision result: {label}")
        if "reread:batch10-final2" not in row.get("review_basis", ""):
            issues.append(f"batch10-final2 reread lacks its append marker: {label}")
        chain = all_groups.get((key4[0], key4[1], key4[3]), [])
        position = chain.index(row) if row in chain else -1
        predecessor = chain[position - 1] if position > 0 else None
        if predecessor is None:
            if key4 != (
                "tiananmen-1989", key4[1], "fact-attribute",
                "tiananmen-1989-evidence-official-gap@data-accountability",
            ):
                issues.append(f"batch10-final2 existing target lacks a continuous predecessor: {label}")
        elif normalize_reread_text(predecessor.get("revised_text", "")) != normalize_reread_text(
            row.get("original_text", "")
        ):
            issues.append(f"batch10-final2 revision chain is broken: {label}")
        if normalize_reread_text(row.get("original_text", "")) == normalize_reread_text(
            row.get("revised_text", "")
        ) and not source_ref_only_revision(predecessor, row):
            issues.append(f"batch10-final2 row does not record a genuine text/attribute/source change: {label}")
    final2_kind_counts = Counter(row.get("target_kind", "") for row in final2_rows)
    if final2_kind_counts != Counter({
        "article-title": 22,
        "article-dek": 61,
        "fact": 149,
        "fact-attribute": 10,
        "source-title": 1,
    }):
        issues.append(
            "batch10-final2 reread classification differs from 243 real rows: "
            "22 titles, 61 decks, 149 facts, 10 attributes, and 1 source title"
        )
    final3_rows = rows[BATCH10_FINAL2_REREAD_ROWS:BATCH11_REREAD_BASE_ROWS]
    final3_keys: set[tuple[str, str, str, str]] = set()
    for row in final3_rows:
        key4 = (
            row.get("slug", ""), row.get("language", ""),
            row.get("target_kind", ""), row.get("target_id", ""),
        )
        label = "/".join(key4)
        final3_keys.add(key4)
        if not row.get("contract_id", "").startswith(BATCH10_FINAL3_CONTRACT_PREFIX):
            issues.append(f"batch10-final3 reread lacks its final3 contract: {label}")
        if row.get("result", "") != "PASS_AFTER_REVISION":
            issues.append(f"batch10-final3 reread contains a no-change or invalid result: {label}")
        if "reread:batch10-final3" not in row.get("review_basis", ""):
            issues.append(f"batch10-final3 reread lacks its append marker: {label}")
        chain = all_groups.get((key4[0], key4[1], key4[3]), [])
        position = chain.index(row) if row in chain else -1
        predecessor = chain[position - 1] if position > 0 else None
        if predecessor is None or predecessor.get("revised_text", "") != row.get("original_text", ""):
            issues.append(f"batch10-final3 exact revision chain is broken: {label}")
        if row.get("original_text", "") == row.get("revised_text", ""):
            issues.append(f"batch10-final3 reread did not record a real DOM/source-title change: {label}")
    if len(final3_rows) != 15 or final3_keys != BATCH10_FINAL3_TARGETS:
        issues.append("batch10-final3 reread must contain exactly its 15 genuine target revisions")
    for slug, lang, _kind, target_id in BATCH10_FINAL3_TARGETS:
        chain = all_groups.get((slug, lang, target_id), [])
        tip_id = chain[-1].get("contract_id", "") if chain else ""
        if not chain or not tip_id.startswith(
            (
                BATCH10_FINAL3_CONTRACT_PREFIX,
                BATCH11_FINAL1_CONTRACT_PREFIX,
                BATCH11_FINAL2_CONTRACT_PREFIX,
                BATCH11_FINAL3_CONTRACT_PREFIX,
                BATCH11_FINAL4_CONTRACT_PREFIX,
                BATCH11_FINAL5_CONTRACT_PREFIX,
                BATCH11_FINAL6_CONTRACT_PREFIX,
                BATCH11_FINAL7_CONTRACT_PREFIX,
                BATCH12_CONTRACT_PREFIX,
            )
        ):
            issues.append(f"batch10-final3 reread is not the chain tip for {slug}/{lang}/{target_id}")
    if {row.get("slug", "") for row in rows} != set(SEMANTIC_REREAD_SCOPE):
        issues.append("semantic reread ledger does not cover exactly the required 54 articles")
    if {row.get("language", "") for row in rows} != set(LANGS):
        issues.append("semantic reread ledger does not cover exactly the ten languages")
    final3_rows = [
        row for row in rows
        if row.get("contract_id", "").startswith(BATCH8_FINAL3_CONTRACT_PREFIX)
    ]
    final3_keys = {
        (
            row.get("slug", ""), row.get("language", ""),
            row.get("target_kind", ""), row.get("target_id", ""),
        )
        for row in final3_rows
    }
    if len(final3_rows) != 20 or final3_keys != BATCH8_FINAL3_TARGETS:
        issues.append("batch8-final3 reread ledger must contain exactly its 20 target-language revisions")
    for slug, lang, _kind, target_id in BATCH8_FINAL3_TARGETS:
        chain = semantic_reread_groups(rows).get((slug, lang, target_id), [])
        tip_id = chain[-1].get("contract_id", "") if chain else ""
        if len(chain) < 2 or not tip_id.startswith(
            (
                BATCH8_FINAL3_CONTRACT_PREFIX,
                BATCH11_FINAL1_CONTRACT_PREFIX,
                BATCH11_FINAL2_CONTRACT_PREFIX,
                BATCH11_FINAL3_CONTRACT_PREFIX,
                BATCH11_FINAL4_CONTRACT_PREFIX,
                BATCH11_FINAL5_CONTRACT_PREFIX,
                BATCH11_FINAL6_CONTRACT_PREFIX,
                BATCH11_FINAL7_CONTRACT_PREFIX,
                BATCH12_CONTRACT_PREFIX,
                BATCH13_CONTRACT_PREFIX,
            )
        ):
            issues.append(f"batch8-final3 reread is not the continuous chain tip for {slug}/{lang}/{target_id}")
    for slug, lang, _kind, target_id in BATCH9_FINAL2_TARGETS:
        chain = semantic_reread_groups(rows).get((slug, lang, target_id), [])
        tip_id = chain[-1].get("contract_id", "") if chain else ""
        if len(chain) < 2 or not tip_id.startswith(
            (
                BATCH9_FINAL2_CONTRACT_PREFIX,
                BATCH11_FINAL1_CONTRACT_PREFIX,
                BATCH11_FINAL2_CONTRACT_PREFIX,
                BATCH11_FINAL3_CONTRACT_PREFIX,
                BATCH11_FINAL4_CONTRACT_PREFIX,
                BATCH11_FINAL5_CONTRACT_PREFIX,
                BATCH11_FINAL6_CONTRACT_PREFIX,
                BATCH11_FINAL7_CONTRACT_PREFIX,
                BATCH12_CONTRACT_PREFIX,
                BATCH13_CONTRACT_PREFIX,
            )
        ):
            issues.append(f"batch9-final2 reread is not the continuous chain tip for {slug}/{lang}/{target_id}")
    return rows, issues


def semantic_reread_ledger_issues(
    *,
    rows: list[dict[str, str]] | None = None,
    contracts: list[dict[str, str]] | None = None,
    overrides: dict[str, BeautifulSoup] | None = None,
) -> list[str]:
    """Cross-check the reread ledger against live DOM and independent contracts."""
    issues: list[str] = []
    if rows is None:
        rows, load_issues = load_semantic_reread_rows()
        issues.extend(load_issues)
    else:
        issues.extend(semantic_reread_chain_issues(rows))
        if len(rows) < SEMANTIC_REREAD_BATCH10_ROWS:
            issues.append(
                f"semantic reread ledger has {len(rows)} rows, below the "
                f"{SEMANTIC_REREAD_BATCH10_ROWS}-row batch10 append baseline"
            )
        prefix_issues = exact_tsv_prefix_issues(
            SEMANTIC_REREAD_PATH,
            base_rows=BATCH11_FINAL1_REREAD_PREFIX_ROWS,
            expected_sha256=BATCH11_FINAL1_REREAD_PREFIX_SHA256,
            label="semantic reread ledger pre-final1 prefix",
        )
        issues.extend(prefix_issues)
        if not prefix_issues:
            authenticated_prefix = batch11_tsv_rows(SEMANTIC_REREAD_PATH)[
                :BATCH11_FINAL1_REREAD_PREFIX_ROWS
            ]
            if rows[:BATCH11_FINAL1_REREAD_PREFIX_ROWS] != authenticated_prefix:
                issues.append(
                    "semantic reread override changed authenticated batch11 history"
                )
    expected_batch11_rows = BATCH11_FINAL1_REREAD_PREFIX_ROWS
    if len(rows) < expected_batch11_rows:
        issues.append(
            f"semantic reread ledger must retain at least {expected_batch11_rows} "
            "rows through the authenticated batch11 append"
        )
    if contracts is None:
        contracts, contract_load_issues = load_editorial_semantic_contracts(check_reread=False)
        issues.extend(contract_load_issues)
    contract_by_id = {
        row.get("contract_id", ""): row for row in contracts if row.get("contract_id", "")
    }
    ledger_groups = semantic_reread_groups(rows)
    ledger_keys: dict[tuple[str, str, str], dict[str, str]] = {}
    for key, chain in ledger_groups.items():
        tip = chain[-1]
        if final1_source_removal(tip):
            continue
        effective_key = key
        if (
            tip.get("contract_id", "").startswith(
                BATCH12_CONTRACT_PREFIX
            )
            and key[2].startswith("source-entry:")
        ):
            effective_key = (
                key[0],
                key[1],
                "source-title:" + key[2].split(":", 1)[1],
            )
        ledger_keys[effective_key] = tip
    final1_source_rows = batch11_tsv_rows(SOURCE_LEDGER_PATH)
    final1_source_by_key = {
        (row.get("slug", ""), row.get("language", ""), row.get("fact_id", "")): row
        for row in final1_source_rows[BATCH11_FINAL1_SOURCE_PREFIX_ROWS:]
        if row.get("baseline_issue", "").startswith(
            (
                BATCH11_FINAL1_CONTRACT_PREFIX,
                BATCH11_FINAL2_CONTRACT_PREFIX,
                BATCH11_FINAL3_CONTRACT_PREFIX,
            )
        )
    }
    chain_predecessors = {
        id(later): earlier
        for chain in ledger_groups.values()
        for earlier, later in zip(chain, chain[1:])
    }
    actual_keys: set[tuple[str, str, str]] = set()
    for slug in SEMANTIC_REREAD_SCOPE:
        path = POSTS / f"{slug}.html"
        soup = (overrides or {}).get(slug)
        if soup is None:
            soup = BeautifulSoup(path.read_text(encoding="utf-8"), "html.parser")
        for lang in LANGS:
            targets = extract_semantic_reread_targets(soup, lang)
            if slug == "xinjiang-tibet-forced-labour-2026":
                targets = {
                    target_id: value
                    for target_id, value in targets.items()
                    if (slug, lang, target_id) in BATCH11_TARGETS
                }
            if slug == "transnational-repression-2026":
                batch12_target_ids = {
                    target_id
                    for (
                        target_slug, _kind, target_id, _refs, languages
                    ) in BATCH12_TARGET_SPECS
                    if target_slug == slug
                    and lang in batch12_spec_languages(languages)
                }
                targets = {
                    target_id: value
                    for target_id, value in targets.items()
                    if target_id in batch12_target_ids
                }
            for target_id, current in targets.items():
                key = (slug, lang, target_id)
                actual_keys.add(key)
                row = ledger_keys.get(key)
                if row is None:
                    continue
                is_batch12_tip = row.get(
                    "contract_id", ""
                ).startswith(BATCH12_CONTRACT_PREFIX)
                allowed_kind_transition = (
                    is_batch12_tip
                    and slug == "guiyang-quarantine-bus-crash"
                    and target_id
                    == "guiyang-quarantine-bus-crash-timeline-5"
                    and row.get("target_kind", "") == "timeline"
                    and current["target_kind"] == "fact"
                )
                if (
                    row.get("target_kind", "") != current["target_kind"]
                    and not allowed_kind_transition
                ):
                    issues.append(f"semantic reread target kind differs for {slug}/{lang}/{target_id}")
                source_overlay = final1_source_by_key.get(key)
                overlay_matches = bool(
                    source_overlay
                    and source_overlay.get("data_source_ref", "") == current["source_refs"]
                    and normalize_reread_text(
                        source_overlay.get("current_visible_text", "")
                    ) == current["text"]
                )
                batch12_page_scope = (
                    is_batch12_tip
                    and row.get("target_kind", "") == "article-dek"
                    and row.get("source_refs", "") == "page-sources"
                    and current["source_refs"].startswith("page-sources:")
                )
                if (
                    row.get("source_refs", "") != current["source_refs"]
                    and not overlay_matches
                    and not batch12_page_scope
                ):
                    issues.append(f"semantic reread source refs differ for {slug}/{lang}/{target_id}")
                current_text = current["text"]
                current_text_exact = current["text_exact"]
                if (
                    is_batch12_tip
                    and row.get("target_id", "").startswith(
                        "source-entry:"
                    )
                ):
                    source_id = row.get("target_id", "").split(
                        ":", 1
                    )[1]
                    body = body_for(soup, lang)
                    source = (
                        body.select_one(
                            f'li[data-source-id="{source_id}"]'
                        )
                        if body else None
                    )
                    if source is not None:
                        current_text_exact = source.get_text(
                            " ", strip=True
                        )
                        current_text = normalize_reread_text(
                            current_text_exact
                        )
                if row.get("contract_id", "").startswith(BATCH8_FINAL3_CONTRACT_PREFIX):
                    text_matches = (
                        row.get("revised_text", "")
                        == current_text_exact
                    )
                elif (
                    row.get("contract_id", "").startswith(
                        BATCH11_FINAL7_CONTRACT_PREFIX
                    )
                    and target_id in {
                        key[3] for key in BATCH11_FINAL7_TIMELINE_TARGETS
                    }
                ):
                    text_matches = batch11_final7_timeline_text(
                        row.get("revised_text", "")
                    ) == batch11_final7_timeline_text(
                        current_text_exact
                    )
                else:
                    text_matches = normalize_reread_text(
                        row.get("revised_text", "")
                    ) == current_text
                if not text_matches:
                    issues.append(f"semantic reread revised text differs from DOM for {slug}/{lang}/{target_id}")
    if actual_keys != set(ledger_keys):
        missing = len(actual_keys - set(ledger_keys))
        extra = len(set(ledger_keys) - actual_keys)
        issues.append(f"semantic reread DOM/ledger target coverage differs: missing={missing} extra={extra}")
    detailed_rows = [
        row for row in rows
        if row.get("contract_id", "").startswith(DETAILED_REVIEW_PREFIXES)
    ]
    issue_templates: dict[str, set[tuple[str, str, str]]] = defaultdict(set)
    basis_templates: dict[str, set[tuple[str, str, str]]] = defaultdict(set)
    final2_basis_core_templates: dict[str, set[tuple[str, str, str]]] = defaultdict(set)
    final3_basis_core_templates: dict[str, set[tuple[str, str, str]]] = defaultdict(set)
    for row in rows:
        slug, lang, target_id = row.get("slug", ""), row.get("language", ""), row.get("target_id", "")
        original = normalize_reread_text(row.get("original_text", ""))
        revised = normalize_reread_text(row.get("revised_text", ""))
        issue = normalize_reread_text(row.get("issue_found", ""))
        basis = normalize_reread_text(row.get("review_basis", ""))
        result = row.get("result", "")
        contract_id = row.get("contract_id", "")
        label = f"{slug}/{lang}/{target_id}"
        if not slug or lang not in LANGS or not target_id:
            issues.append(f"semantic reread ledger has incomplete key for {label}")
        is_final1_new_hk_source = (
            contract_id.startswith(BATCH11_FINAL1_CONTRACT_PREFIX)
            and slug == "hk-12"
            and row.get("target_kind", "") == "source-title"
            and target_id == "source-title:s6"
            and not original
        )
        if (not original and not is_final1_new_hk_source) or not revised or len(basis) < 100:
            issues.append(f"semantic reread ledger lacks original/revised text or case-specific basis for {label}")
        if (
            revised
            and not contract_id.startswith(
                (
                    BATCH11_FINAL6_CONTRACT_PREFIX,
                    BATCH11_FINAL7_CONTRACT_PREFIX,
                    BATCH12_CONTRACT_PREFIX,
                )
            )
            and revised[:40].casefold() in basis.casefold()
        ):
            issues.append(f"semantic reread review basis is copied from current text for {label}")
        if result == "PASS_AFTER_REVISION":
            if not issue:
                issues.append(f"PASS_AFTER_REVISION lacks issue detail for {label}")
            if original == revised and not source_ref_only_revision(
                chain_predecessors.get(id(row)), row
            ):
                issues.append(f"PASS_AFTER_REVISION did not change text for {label}")
            if not contract_id:
                issues.append(f"PASS_AFTER_REVISION lacks contract id for {label}")
            contract = contract_by_id.get(contract_id)
            if contract is None:
                issues.append(f"PASS_AFTER_REVISION lacks independent semantic contract for {label}")
            elif (
                contract.get("slug"), contract.get("language"), contract.get("target_kind"), contract.get("target_id")
            ) != (slug, lang, row.get("target_kind", ""), target_id):
                issues.append(f"PASS_AFTER_REVISION contract points to a different target for {label}")
            if final1_source_removal(row):
                source_id = row.get("source_refs", "").split(":", 1)[-1]
                soup = (overrides or {}).get(slug)
                if soup is None:
                    soup = BeautifulSoup(
                        (POSTS / f"{slug}.html").read_text(encoding="utf-8"), "html.parser"
                    )
                body = body_for(soup, lang)
                if body is not None and body.select_one(f'li[data-source-id="{source_id}"]') is not None:
                    issues.append(f"batch10-final1 source-removal tombstone still has a live DOM source for {label}")
            if contract_id.startswith(DETAILED_REVIEW_PREFIXES):
                normalized_key = normalized_final3_key(row)
                if FINAL3_GENERIC_NOTE.search(issue) or FINAL3_GENERIC_NOTE.search(basis):
                    issues.append(f"detailed semantic reread uses a generic issue or review template for {label}")
                quoted_old = [
                    normalize_reread_text(value)
                    for pattern in (
                        r'“([^”]{2,240})”', r'"([^"\n]{2,240})"',
                        r'„([^“]{2,240})“',
                        r'「([^」]{2,240})」', r'『([^』]{2,240})』',
                        r'«([^»]{2,240})»', r'‘([^’]{2,240})’',
                    )
                    for value in re.findall(pattern, issue)
                ]
                if not quoted_old or not any(value in original for value in quoted_old):
                    issues.append(f"detailed semantic reread issue does not quote the actual old wording for {label}")
                missing_markers = [
                    marker for marker in FINAL3_REVIEW_MARKERS
                    if marker not in basis.casefold()
                ]
                if missing_markers:
                    issues.append(
                        f"detailed semantic reread review basis lacks subject/state action/legal-medical term/"
                        f"source/accuracy detail for {label}"
                    )
                issue_templates[normalized_final3_note(row, "issue_found")].add(normalized_key)
                basis_templates[normalized_final3_note(row, "review_basis")].add(normalized_key)
                if contract_id.startswith(BATCH8_FINAL2_CONTRACT_PREFIX):
                    basis_core_row = dict(row)
                    basis_core_row["review_basis"] = re.split(
                        r"\bwhy more accurate:\s*", basis, maxsplit=1, flags=re.I,
                    )[0]
                    final2_basis_core_templates[
                        normalized_final3_note(basis_core_row, "review_basis")
                    ].add(normalized_key)
                if contract_id.startswith(BATCH8_FINAL3_CONTRACT_PREFIX):
                    basis_core_row = dict(row)
                    basis_core_row["review_basis"] = re.split(
                        r"\bwhy more accurate:\s*", basis, maxsplit=1, flags=re.I,
                    )[0]
                    final3_basis_core_templates[
                        normalized_final3_note(basis_core_row, "review_basis")
                    ].add(normalized_key)
        elif result == "PASS_NO_CHANGE":
            if issue:
                issues.append(f"PASS_NO_CHANGE carries a fabricated issue for {label}")
            if original != revised:
                issues.append(f"PASS_NO_CHANGE conceals a text change for {label}")
            if contract_id:
                issues.append(f"PASS_NO_CHANGE carries a revision contract for {label}")
        else:
            issues.append(f"semantic reread has invalid result {result!r} for {label}")
    repeated_issue = [template for template, keys in issue_templates.items() if template and len(keys) > 1]
    repeated_basis = [template for template, keys in basis_templates.items() if template and len(keys) > 1]
    repeated_basis.extend(
        template for template, keys in final2_basis_core_templates.items()
        if template and len(keys) > 1
    )
    repeated_basis.extend(
        template for template, keys in final3_basis_core_templates.items()
        if template and len(keys) > 1
    )
    if repeated_issue:
        issues.append("detailed semantic reread issue_found template is copied across normalized targets")
    if repeated_basis:
        issues.append("detailed semantic reread review_basis template is copied across normalized targets")
    expected_contract_ids = {
        row.get("contract_id", "") for row in rows if row.get("result") == "PASS_AFTER_REVISION"
    }
    actual_contract_ids = {
        row.get("contract_id", "") for row in contracts if row.get("contract_id", "").startswith("reread:")
    }
    if expected_contract_ids != actual_contract_ids:
        issues.append("semantic reread PASS_AFTER_REVISION/contract coverage differs")
    return issues


def batch9_live_target_map(
    overrides: dict[str, BeautifulSoup] | None = None,
) -> tuple[dict[tuple[str, str, str], dict[str, str]], list[str]]:
    """Dynamically enumerate every current visible target on the five pages."""
    targets: dict[tuple[str, str, str], dict[str, str]] = {}
    issues: list[str] = []
    for slug in sorted(BATCH9_TARGET_SLUGS):
        soup = (overrides or {}).get(slug)
        if soup is None:
            soup = BeautifulSoup((POSTS / f"{slug}.html").read_text(encoding="utf-8"), "html.parser")
        for lang in LANGS:
            current = extract_semantic_reread_targets(soup, lang)
            for target_id, value in current.items():
                key = (slug, lang, target_id)
                if key in targets:
                    issues.append(f"batch9 live DOM target is duplicated: {'/'.join(key)}")
                targets[key] = value
    if len(targets) != BATCH9_LIVE_TARGETS:
        issues.append(
            f"batch9 live DOM has {len(targets)} unique reread targets, expected {BATCH9_LIVE_TARGETS}"
        )
    return targets, issues


def batch9_live_reread_issues(
    *,
    rows: list[dict[str, str]] | None = None,
    overrides: dict[str, BeautifulSoup] | None = None,
) -> list[str]:
    """Require dynamic 1340/1340 coverage and a DOM-matching latest chain tip."""
    issues: list[str] = []
    live, live_issues = batch9_live_target_map(overrides)
    issues.extend(live_issues)
    if rows is None:
        rows, load_issues = load_semantic_reread_rows()
        issues.extend(load_issues)
    groups = semantic_reread_groups(rows)
    ledger_keys = {
        key for key in groups
        if key[0] in BATCH9_TARGET_SLUGS
    }
    live_keys = set(live)
    if ledger_keys != live_keys:
        issues.append(
            "batch9 dynamic reread coverage is not 1340/1340: "
            f"missing={len(live_keys - ledger_keys)} extra={len(ledger_keys - live_keys)}"
        )
    for key in sorted(live_keys & ledger_keys):
        current = live[key]
        tip = groups[key][-1]
        if tip.get("target_kind", "") != current["target_kind"]:
            issues.append(f"batch9 latest chain tip kind differs from DOM for {'/'.join(key)}")
        if tip.get("source_refs", "") != current["source_refs"]:
            issues.append(f"batch9 latest chain tip source refs differ from DOM for {'/'.join(key)}")
        if normalize_reread_text(tip.get("revised_text", "")) != current["text"]:
            issues.append(f"batch9 latest chain tip text differs from DOM for {'/'.join(key)}")
    return issues


def load_editorial_semantic_contracts(*, check_reread: bool = True) -> tuple[list[dict[str, str]], list[str]]:
    """Load editor-authored facts without deriving any anchor from live HTML."""
    if not EDITORIAL_SEMANTIC_CONTRACT_PATH.exists():
        return [], [f"missing manual editorial semantic contract: {EDITORIAL_SEMANTIC_CONTRACT_PATH}"]
    with EDITORIAL_SEMANTIC_CONTRACT_PATH.open(encoding="utf-8", newline="") as handle:
        reader = csv.DictReader(handle, delimiter="\t")
        fields = tuple(reader.fieldnames or ())
        rows = list(reader)
    issues: list[str] = []
    missing = set(EDITORIAL_SEMANTIC_FIELDS) - set(fields)
    if missing:
        issues.append(f"manual editorial semantic contract lacks fields: {sorted(missing)}")
        return rows, issues
    contract_ids = [row.get("contract_id", "") for row in rows]
    issues.extend(
        exact_tsv_prefix_issues(
            EDITORIAL_SEMANTIC_CONTRACT_PATH,
            base_rows=EDITORIAL_SEMANTIC_BASE_ROWS,
            expected_sha256=EDITORIAL_SEMANTIC_BASE_SHA256,
            label="manual editorial semantic contract",
        )
    )
    issues.extend(
        exact_tsv_prefix_issues(
            EDITORIAL_SEMANTIC_CONTRACT_PATH,
            base_rows=EDITORIAL_SEMANTIC_FINAL1_ROWS,
            expected_sha256=EDITORIAL_SEMANTIC_FINAL1_SHA256,
            label="manual editorial semantic contract final1 history",
        )
    )
    issues.extend(
        exact_tsv_prefix_issues(
            EDITORIAL_SEMANTIC_CONTRACT_PATH,
            base_rows=EDITORIAL_SEMANTIC_FINAL2_ROWS,
            expected_sha256=EDITORIAL_SEMANTIC_FINAL2_SHA256,
            label="manual editorial semantic contract final2 history",
        )
    )
    issues.extend(
        exact_tsv_prefix_issues(
            EDITORIAL_SEMANTIC_CONTRACT_PATH,
            base_rows=EDITORIAL_SEMANTIC_BATCH10_ROWS,
            expected_sha256=EDITORIAL_SEMANTIC_BATCH10_SHA256,
            label="manual editorial semantic contract batch10 history",
        )
    )
    issues.extend(
        exact_tsv_prefix_issues(
            EDITORIAL_SEMANTIC_CONTRACT_PATH,
            base_rows=BATCH10_FINAL1_CONTRACT_ROWS,
            expected_sha256=BATCH10_FINAL1_CONTRACT_SHA256,
            label="manual editorial semantic contract batch10-final1 history",
        )
    )
    issues.extend(
        exact_tsv_prefix_issues(
            EDITORIAL_SEMANTIC_CONTRACT_PATH,
            base_rows=BATCH10_FINAL2_CONTRACT_ROWS,
            expected_sha256=BATCH10_FINAL2_CONTRACT_SHA256,
            label="manual editorial semantic contract batch10-final2 history",
        )
    )
    issues.extend(
        exact_tsv_prefix_issues(
            EDITORIAL_SEMANTIC_CONTRACT_PATH,
            base_rows=BATCH11_CONTRACT_BASE_ROWS,
            expected_sha256=BATCH11_CONTRACT_BASE_SHA256,
            label="manual editorial semantic contract pre-batch11 history",
        )
    )
    # Batch thirteen appends 446 rows.  Everything before row 7598 is the
    # completed batch12 contract table and must stay byte-for-byte identical.
    issues.extend(
        exact_tsv_prefix_issues(
            EDITORIAL_SEMANTIC_CONTRACT_PATH,
            base_rows=BATCH13_CONTRACT_BASE_ROWS,
            expected_sha256=BATCH13_CONTRACT_BASE_SHA256,
            label="manual editorial semantic contract pre-batch13 history",
        )
    )
    for row in rows[EDITORIAL_SEMANTIC_BASE_ROWS:EDITORIAL_SEMANTIC_FINAL1_ROWS]:
        if not row.get("contract_id", "").startswith(BATCH9_FINAL1_CONTRACT_PREFIX):
            issues.append("manual editorial semantic contract has a post-baseline row outside batch9-final1")
    final2_rows = rows[EDITORIAL_SEMANTIC_FINAL1_ROWS:EDITORIAL_SEMANTIC_FINAL2_ROWS]
    for row in final2_rows:
        if not row.get("contract_id", "").startswith(BATCH9_FINAL2_CONTRACT_PREFIX):
            issues.append("manual editorial semantic contract has a post-final1 row outside batch9-final2")
    final2_keys = {
        (
            row.get("slug", ""), row.get("language", ""),
            row.get("target_kind", ""), row.get("target_id", ""),
        )
        for row in final2_rows
    }
    if len(final2_rows) != len(BATCH9_FINAL2_TARGETS) or final2_keys != BATCH9_FINAL2_TARGETS:
        issues.append("batch9-final2 semantic contracts must contain exactly its 23 independent target rows")
    batch10_rows = rows[EDITORIAL_SEMANTIC_FINAL2_ROWS:EDITORIAL_SEMANTIC_BATCH10_ROWS]
    for row in batch10_rows:
        if not row.get("contract_id", "").startswith(BATCH10_CONTRACT_PREFIX):
            issues.append("manual editorial semantic contract has a post-final2 row outside batch10")
        if row.get("slug", "") not in BATCH10_TARGET_SLUGS:
            issues.append("batch10 semantic contract contains a non-target article")
    final1_rows = rows[EDITORIAL_SEMANTIC_BATCH10_ROWS:BATCH10_FINAL1_CONTRACT_ROWS]
    for row in final1_rows:
        if not row.get("contract_id", "").startswith(BATCH10_FINAL1_CONTRACT_PREFIX):
            issues.append("manual editorial semantic contract has a post-batch10 row outside batch10-final1")
        if row.get("slug", "") not in BATCH10_TARGET_SLUGS:
            issues.append("batch10-final1 semantic contract contains a non-target article")
    final2_rows = rows[BATCH10_FINAL1_CONTRACT_ROWS:BATCH10_FINAL2_CONTRACT_ROWS]
    for row in final2_rows:
        if not row.get("contract_id", "").startswith(BATCH10_FINAL2_CONTRACT_PREFIX):
            issues.append("manual editorial semantic contract has a post-final1 row outside batch10-final2")
        if row.get("slug", "") not in BATCH10_FINAL2_TARGET_SLUGS:
            issues.append("batch10-final2 semantic contract contains a frozen or non-target article")
        if row.get("target_kind", "") not in {
            "article-title", "article-dek", "fact", "source-title", "fact-attribute",
        }:
            issues.append("batch10-final2 semantic contract contains an unsupported target kind")
        issues.extend(batch10_final2_contract_metadata_issues(row))
    final3_rows = rows[BATCH10_FINAL2_CONTRACT_ROWS:BATCH11_CONTRACT_BASE_ROWS]
    final3_keys = {
        (
            row.get("slug", ""), row.get("language", ""),
            row.get("target_kind", ""), row.get("target_id", ""),
        )
        for row in final3_rows
    }
    for row in final3_rows:
        if not row.get("contract_id", "").startswith(BATCH10_FINAL3_CONTRACT_PREFIX):
            issues.append("manual editorial semantic contract has a post-final2 row outside batch10-final3")
        issues.extend(batch10_final3_contract_metadata_issues(row))
    if len(final3_rows) != 15 or final3_keys != BATCH10_FINAL3_TARGETS:
        issues.append("batch10-final3 semantic contracts must contain exactly its 15 reviewed targets")
    if not all(contract_ids) or len(contract_ids) != len(set(contract_ids)):
        issues.append("manual editorial semantic contract has blank or duplicate contract ids")
    # Batch thirteen is a successor append: nineteen of its nodes were still
    # described by their original ``legacy:`` root contract, which is not a
    # reread revision.  This historical duty is therefore replayed verbatim
    # over the authenticated pre-batch13 table, and batch13_ledger_issues
    # separately proves that every one of the 446 appended rows is the reread
    # chain tip of an existing target with a matching predecessor.
    historical_rows = rows[:BATCH13_CONTRACT_BASE_ROWS]
    keys = [(row.get("slug", ""), row.get("language", ""), row.get("target_kind", ""), row.get("target_id", "")) for row in historical_rows]
    duplicate_contract_keys = {key for key in keys if keys.count(key) > 1}
    if duplicate_contract_keys:
        reread_rows, reread_load_issues = load_semantic_reread_rows()
        issues.extend(reread_load_issues)
        reread_by_contract = {
            row.get("contract_id", ""): (
                row.get("slug", ""), row.get("language", ""),
                row.get("target_kind", ""), row.get("target_id", ""),
            )
            for row in reread_rows if row.get("result") == "PASS_AFTER_REVISION"
        }
        for key in duplicate_contract_keys:
            duplicate_rows = [row for row, row_key in zip(historical_rows, keys) if row_key == key]
            if any(reread_by_contract.get(row.get("contract_id", "")) != key for row in duplicate_rows):
                issues.append(
                    "manual editorial semantic contract duplicates a target without a matching reread revision chain: "
                    f"{'/'.join(key)}"
                )
    expected_legacy = {
        (slug, lang, kind, target_id)
        for slug, kind, target_id in EDITORIAL_SEMANTIC_TARGETS
        for lang in LANGS
    }
    all_keys = [(row.get("slug", ""), row.get("language", ""), row.get("target_kind", ""), row.get("target_id", "")) for row in rows]
    actual_legacy = {
        key for key, row in zip(all_keys, rows)
        if row.get("contract_id", "").startswith("legacy:")
    }
    if actual_legacy != expected_legacy:
        issues.append("manual editorial semantic contract lost one of the protected 5 targets × 10 languages")
    final3_rows = [
        row for row in rows
        if row.get("contract_id", "").startswith(BATCH8_FINAL3_CONTRACT_PREFIX)
    ]
    final3_keys = {
        (
            row.get("slug", ""), row.get("language", ""),
            row.get("target_kind", ""), row.get("target_id", ""),
        )
        for row in final3_rows
    }
    if len(final3_rows) != 20 or final3_keys != BATCH8_FINAL3_TARGETS:
        issues.append("batch8-final3 semantic contracts must contain exactly its 20 independent target rows")
    for row in rows:
        required = contract_literals(row.get("required_all", ""))
        is_reread = row.get("contract_id", "").startswith("reread:")
        is_final_reread = is_reread and row.get("slug", "") in FINAL_REREAD_CONTRACT_SLUGS
        is_cleanup21 = row.get("contract_id", "").startswith("reread:cleanup21:")
        is_batch8_final3 = row.get("contract_id", "").startswith(BATCH8_FINAL3_CONTRACT_PREFIX)
        is_batch9 = row.get("contract_id", "").startswith(BATCH9_CONTRACT_PREFIX)
        is_batch9_final1 = row.get("contract_id", "").startswith(BATCH9_FINAL1_CONTRACT_PREFIX)
        is_batch9_final2 = row.get("contract_id", "").startswith(BATCH9_FINAL2_CONTRACT_PREFIX)
        is_batch10 = row.get("contract_id", "").startswith(BATCH10_CONTRACT_PREFIX)
        is_batch10_final1 = row.get("contract_id", "").startswith(BATCH10_FINAL1_CONTRACT_PREFIX)
        is_batch10_final2 = row.get("contract_id", "").startswith(BATCH10_FINAL2_CONTRACT_PREFIX)
        is_batch10_final3 = row.get("contract_id", "").startswith(BATCH10_FINAL3_CONTRACT_PREFIX)
        is_batch11 = row.get("contract_id", "").startswith(BATCH11_CONTRACT_PREFIX)
        is_batch11_final1 = row.get("contract_id", "").startswith(
            BATCH11_FINAL1_CONTRACT_PREFIX
        )
        is_batch11_final2 = row.get("contract_id", "").startswith(
            BATCH11_FINAL2_CONTRACT_PREFIX
        )
        is_batch11_final3 = row.get("contract_id", "").startswith(
            BATCH11_FINAL3_CONTRACT_PREFIX
        )
        is_batch11_final4 = row.get("contract_id", "").startswith(
            BATCH11_FINAL4_CONTRACT_PREFIX
        )
        is_batch11_final5 = row.get("contract_id", "").startswith(
            BATCH11_FINAL5_CONTRACT_PREFIX
        )
        is_batch11_final6 = row.get("contract_id", "").startswith(
            BATCH11_FINAL6_CONTRACT_PREFIX
        )
        is_batch11_final7 = row.get("contract_id", "").startswith(
            BATCH11_FINAL7_CONTRACT_PREFIX
        )
        is_batch12 = row.get("contract_id", "").startswith(
            BATCH12_CONTRACT_PREFIX
        )
        is_batch13 = row.get("contract_id", "").startswith(
            BATCH13_CONTRACT_PREFIX
        )
        if is_batch13:
            # Batch13 rows are duty-subject invariant codes.  Their count,
            # role prefixes, summary roles, live visibility and preimage
            # provenance are all enforced by batch13_ledger_issues, which is
            # strictly stronger than the generic minimums here because it also
            # requires each code to appear in the live DOM and each old error
            # to have been present before the revision.
            continue
        if is_batch10_final2:
            # Final2 uses an independently authored invariant-code profile,
            # validated above.  Treating those codes as substrings of the new
            # prose would recreate the exact self-certifying contract problem
            # this pass removes.
            continue
        if is_batch10_final3:
            # Final3 is likewise enforced by the mandatory outer visible
            # validator; its short contract phrases remain audit evidence, not
            # a substring answer key sampled from the revised DOM.
            continue
        minimum_required = 4 if (is_batch11_final7 or is_batch12) else (12 if is_batch11_final6 else (16 if is_batch11_final5 else (8 if is_batch8_final3 else (5 if (is_batch11 or is_batch11_final1 or is_batch11_final2 or is_batch11_final3 or is_batch11_final4) else (4 if (is_batch9_final1 or is_batch9_final2 or is_batch10 or is_batch10_final1 or is_batch10_final2) else (2 if is_batch9 else (4 if is_final_reread else (2 if is_reread else 1))))))))
        if len(set(required)) < minimum_required:
            issues.append(
                f"manual editorial semantic contract needs at least {minimum_required} independent required concepts for "
                f"{row.get('slug')}/{row.get('language')}/{row.get('target_id')}"
            )
        if is_cleanup21:
            lang = row.get("language", "")
            for literal in required:
                if lang in {"zh", "ja", "ko"}:
                    compact = re.sub(r"\s+", "", literal)
                    short_anchor = 2 <= len(compact) <= 32 and not re.search(r"[。！？.!?；;]", literal)
                else:
                    words = re.findall(r"[\wÀ-ÿ’'-]+", literal)
                    short_anchor = 2 <= len(words) <= 8 and not re.search(r"[.!?;]", literal)
                if not short_anchor:
                    issues.append(
                        "cleanup21 semantic contract required anchor must be a 2-to-8-word independent phrase for "
                        f"{row.get('slug')}/{lang}/{row.get('target_id')}: {literal!r}"
                    )
        forbidden = contract_literals(row.get("forbidden_any", ""))
        minimum_forbidden = 4 if (is_batch8_final3 or is_batch11_final5 or is_batch11_final6) else (2 if (is_batch12 or is_batch11_final3 or is_batch11_final4 or is_batch9_final1 or is_batch9_final2 or is_batch10 or is_batch10_final1 or is_batch10_final2) else (1 if is_batch9 else (2 if is_final_reread else 1)))
        if len(set(forbidden)) < minimum_forbidden:
            issues.append(
                f"manual editorial semantic contract needs at least {minimum_forbidden} short forbidden mistranslations for "
                f"{row.get('slug')}/{row.get('language')}/{row.get('target_id')}"
            )
        summary = normalize_reread_text(row.get("fact_summary", ""))
        if not summary:
            issues.append(
                f"manual editorial semantic contract has no fact summary for "
                f"{row.get('slug')}/{row.get('language')}/{row.get('target_id')}"
            )
        elif (
            not is_batch11_final3
            and not is_batch11_final6
            and not is_batch11_final7
            and not is_batch12
            and (is_final_reread or is_batch9_final1 or is_batch9_final2 or is_batch10 or is_batch10_final1 or is_batch10_final2)
            and not all(
            field in summary.casefold() for field in FINAL_REREAD_SUMMARY_FIELDS
            )
        ):
            issues.append(
                f"manual editorial semantic contract fact summary lacks subject/action/legal-term/consequence/remedy for "
                f"{row.get('slug')}/{row.get('language')}/{row.get('target_id')}"
            )
        if (is_batch11 or is_batch11_final1 or is_batch11_final2 or is_batch11_final3 or is_batch11_final4 or is_batch11_final5) and "source:" not in summary.casefold():
            issues.append(
                "batch11 manual editorial semantic contract fact summary lacks source role for "
                f"{row.get('slug')}/{row.get('language')}/{row.get('target_id')}"
            )
        if is_batch11_final6 and "source" not in summary.casefold():
            issues.append(
                "batch11-final6 manual semantic contract fact summary lacks "
                f"source role for {row.get('target_id')}"
            )
        if is_batch12 and not all(
            marker in summary.casefold()
            for marker in (
                "subject",
                "action",
                "source",
                "consequence",
                "remedy",
            )
        ):
            issues.append(
                "batch12 manual semantic contract summary lacks "
                f"subject/action/source/consequence/remedy: {row.get('target_id')}"
            )
    if check_reread:
        reread_rows, reread_issues = load_semantic_reread_rows()
        issues.extend(reread_issues)
        expected_reread = {
            row.get("contract_id", "") for row in reread_rows
            if row.get("result") == "PASS_AFTER_REVISION"
        }
        actual_reread = {
            row.get("contract_id", "") for row in rows
            if row.get("contract_id", "").startswith("reread:")
        }
        if expected_reread != actual_reread:
            issues.append("manual editorial semantic contract does not cover every reread revision")
    return rows, issues


def editorial_semantic_contract_issues(
    soup: BeautifulSoup,
    path: Path,
    *,
    contracts: list[dict[str, str]] | None = None,
) -> list[str]:
    """Validate human-defined concepts in the actual target-language DOM."""
    if contracts is None:
        contracts, load_issues = load_editorial_semantic_contracts()
        if load_issues:
            return load_issues
    issues: list[str] = []
    # Multiple rows for the same target are retained as revision history.  Only
    # the last contract in that chain describes the live DOM; earlier contracts
    # remain auditable through their ledger records and chain links.
    current_contracts: dict[tuple[str, str, str, str], dict[str, str]] = {}
    for row in contracts:
        if row.get("slug") == path.stem:
            # A batch13 successor row is a duty-subject invariant code, not
            # prose.  Letting it become the current contract would silently
            # retire the predecessor's prose literals for that node, so it is
            # never selected here; batch13_ledger_issues owns its codes.
            if row.get("contract_id", "").startswith(BATCH13_CONTRACT_PREFIX):
                continue
            key = (
                row.get("slug", ""), row.get("language", ""),
                row.get("target_kind", ""), row.get("target_id", ""),
            )
            current_contracts[key] = row
    superseded = batch13_superseded_literals()
    for row in current_contracts.values():
        lang = row.get("language", "")
        body = body_for(soup, lang)
        if body is None:
            issues.append(f"{lang}: manual semantic target has no language body")
            continue
        kind = row.get("target_kind", "")
        target_id = row.get("target_id", "")
        if row.get("contract_id", "").startswith(
            (
                BATCH11_CONTRACT_PREFIX,
                BATCH11_FINAL1_CONTRACT_PREFIX,
                BATCH11_FINAL2_CONTRACT_PREFIX,
                BATCH11_FINAL3_CONTRACT_PREFIX,
                BATCH11_FINAL4_CONTRACT_PREFIX,
                BATCH11_FINAL5_CONTRACT_PREFIX,
                BATCH11_FINAL6_CONTRACT_PREFIX,
                BATCH11_FINAL7_CONTRACT_PREFIX,
                BATCH12_CONTRACT_PREFIX,
            )
        ):
            # Batch11 values are invariant codes, not prose substrings.  Their
            # live meaning is enforced by the mandatory hand-authored release
            # validator and its AST wiring gate.
            continue
        if row.get("contract_id", "").startswith(BATCH10_FINAL2_CONTRACT_PREFIX):
            issues.extend(batch10_final2_contract_metadata_issues(row))
            continue
        if row.get("contract_id", "").startswith(BATCH10_FINAL3_CONTRACT_PREFIX):
            issues.extend(batch10_final3_contract_metadata_issues(row))
            # Live meaning is forced by batch10_final3_visible_semantic_issues
            # on the outer case path, never by matching these invariant codes
            # as though they were translated prose.
            continue
        is_source_removal_contract = (
            row.get("contract_id", "").startswith(BATCH10_FINAL1_CONTRACT_PREFIX)
            and kind == "source-title"
            and "__SOURCE_REMOVED__" in contract_literals(row.get("required_all", ""))
        )
        if is_source_removal_contract:
            source_id = target_id.split(":", 1)[1] if ":" in target_id else target_id
            if body.select_one(f'li[data-source-id="{source_id}"]') is not None:
                issues.append(f"{lang}: removed source {source_id} returned to the live DOM")
            continue
        if kind == "fact":
            node = body.select_one(f'[data-fact-id="{target_id}"]')
        elif kind == "fact-attribute":
            fact_id, _separator, attribute_name = target_id.partition("@")
            source = body.select_one(f'[data-fact-id="{fact_id}"]')
            node = source
        elif kind == "source-category":
            source = body.select_one(f'li[data-source-id="{target_id}"]')
            node = source.find("b") if source else None
        elif kind == "source-title":
            source_id = target_id.split(":", 1)[1] if ":" in target_id else target_id
            source = body.select_one(f'li[data-source-id="{source_id}"]')
            node = source.find("a") if source else None
        elif kind == "article-title":
            node = soup.select_one(f".article-title .lang-{lang}")
        elif kind == "article-dek":
            node = soup.select_one(f".article-dek .lang-{lang}")
        elif kind == "article-meta":
            node = soup.select_one(f".article-meta .lang-{lang}")
        else:
            node = None
        if node is None:
            issues.append(f"{lang}: manual semantic target {kind}/{target_id} is missing")
            continue
        if kind == "fact-attribute":
            visible = " ".join(node.get(attribute_name, "").split()).casefold()
        else:
            visible = " ".join(node.get_text(" ", strip=True).split()).casefold()
        revision = superseded.get(
            (row.get("slug", ""), lang, target_id)
        )
        for literal in contract_literals(row.get("required_all", "")):
            folded = " ".join(literal.split()).casefold()
            if (
                revision is not None
                and folded
                and folded in revision[0]
                and folded not in revision[1]
            ):
                # This exact fragment is the wording batch13 replaced with a
                # named authority.  The replacement is required by the batch13
                # contract and proved visible by batch13_ledger_issues; every
                # other predecessor literal below still has to hold.
                continue
            if folded not in visible:
                issues.append(
                    f"{lang}: manual semantic target {target_id} lost required concept {literal!r}"
                )
        for literal in contract_literals(row.get("forbidden_any", "")):
            if " ".join(literal.split()).casefold() in visible:
                issues.append(
                    f"{lang}: manual semantic target {target_id} contains rejected concept {literal!r}"
                )
    return issues


def batch8_final3_semantic_issues(soup: BeautifulSoup, path: Path) -> list[str]:
    """Independently enforce the final3 source, evidence, and timeline meanings."""
    issues: list[str] = []
    if path.name == "huang-xueqin-wang-jianbing.html":
        target_id = "huang-xueqin-wang-jianbing-evidence-official-gap"
        for lang in LANGS:
            body = body_for(soup, lang)
            nodes = body.select(f'[data-fact-id="{target_id}"]') if body else []
            if len(nodes) != 1:
                issues.append(f"{lang}: batch8-final3 Huang/Wang evidence target is missing or duplicated")
                continue
            node = nodes[0]
            visible = normalize_reread_text(node.get_text(" ", strip=True)).casefold()
            for literal in BATCH8_FINAL3_HXW_REQUIRED[lang]:
                if normalize_reread_text(literal).casefold() not in visible:
                    issues.append(f"{lang}: batch8-final3 Huang/Wang evidence lost {literal!r}")
            if BATCH8_FINAL3_HXW_DISCLAIMERS[lang].casefold() in visible:
                issues.append(f"{lang}: batch8-final3 Huang/Wang disclaimer was reintroduced")
            if node.get("data-source-ref", "") != "hxw-s1 hxw-s2 hxw-s3 hxw-s4":
                issues.append(f"{lang}: batch8-final3 Huang/Wang evidence source attribution changed")
    elif path.name == "causeway-bay-books.html":
        target_id = "causeway-bay-books-timeline-7"
        for lang in LANGS:
            body = body_for(soup, lang)
            nodes = body.select(f'[data-fact-id="{target_id}"]') if body else []
            if len(nodes) != 1:
                issues.append(f"{lang}: batch8-final3 Causeway timeline target is missing or duplicated")
                continue
            node = nodes[0]
            visible = normalize_reread_text(node.get_text(" ", strip=True)).casefold()
            for literal in BATCH8_FINAL3_CAUSEWAY_REQUIRED[lang]:
                if normalize_reread_text(literal).casefold() not in visible:
                    issues.append(f"{lang}: batch8-final3 Causeway timeline lost {literal!r}")
            if BATCH8_FINAL3_CAUSEWAY_FALSE_ACTORS[lang].casefold() in visible:
                issues.append(f"{lang}: batch8-final3 Causeway timeline reverted to the Swedish ministry")
            actual_attrs = (
                node.get("data-timeline-subject", ""),
                node.get("data-timeline-action", ""),
                node.get("data-timeline-consequence", ""),
            )
            if node.get("data-source-ref", "") != "s3":
                issues.append(f"{lang}: batch8-final3 Causeway timeline source is not s3")
            if actual_attrs != BATCH8_FINAL3_CAUSEWAY_ATTRS:
                issues.append(f"{lang}: batch8-final3 Causeway visible text and timeline attributes diverge")
            if not visible.startswith("2020-02-25"):
                issues.append(f"{lang}: batch8-final3 Causeway timeline date changed")
    return issues


def normalized_visible_anchor(value: str) -> str:
    """Normalize punctuation and whitespace without reducing a fact to its numbers."""
    # Digits remain covered by each case's visible-number contract.  Removing
    # them here keeps lexical anchors contiguous in names such as Terminus2049
    # and in prose that places a year between the reviewed words.
    return "".join(character for character in value.casefold() if character.isalpha())


def timeline_anchor_triplet(text: str, lang: str) -> tuple[str, str, str]:
    """Build three short visible-semantic anchors, never a paragraph digest.

    The date label is discarded first.  CJK contracts use three short character
    windows; the other languages use three short word windows.  These anchors
    keep natural punctuation/spacing edits possible while making a subject,
    action, or consequence deletion observable in the rendered prose.
    """
    payload = re.split(r"[:：]", text, maxsplit=1)[-1].strip()
    if lang in {"zh", "ja", "ko"}:
        content = "".join(
            character for character in payload
            if character.isalnum() and not character.isdigit()
        )
        if not content:
            return ("", "", "")
        width = min(10, max(4, len(content) // 9))
        middle = max(0, (len(content) - width) // 2)
        chunks = (content[:width], content[middle:middle + width], content[-width:])
        return tuple(normalized_visible_anchor(chunk) for chunk in chunks)
    words = re.findall(r"[^\W\d_]+(?:[’'-][^\W\d_]+)*", payload, re.UNICODE)
    if not words:
        return ("", "", "")
    width = min(4, max(3, len(words) // 8))
    middle = max(0, (len(words) - width) // 2)
    chunks = (words[:width], words[middle:middle + width], words[-width:])
    return tuple(normalized_visible_anchor(" ".join(chunk)) for chunk in chunks)


def visible_source_role_signature(body, refs: tuple[str, ...]) -> str:
    role_map = {
        node.get("data-source-id", ""): " ".join(node.get("data-source-type", "").split())
        for node in body.select("ul.source-list > li[data-source-id]")
    }
    return " | ".join(f"{source_id}:{role_map.get(source_id, '')}" for source_id in refs)


def load_dynamic_timeline_contracts() -> dict[tuple[str, str, str], dict[str, str]]:
    if not SOURCE_LEDGER_PATH.exists():
        return {}
    with SOURCE_LEDGER_PATH.open(encoding="utf-8", newline="") as handle:
        rows = csv.DictReader(handle, delimiter="\t")
        if not set(TIMELINE_VISIBLE_FIELDS).issubset(rows.fieldnames or ()):
            return {}
        return {
            (row.get("slug", ""), row.get("language", ""), row.get("fact_id", "")): row
            for row in rows if row.get("section_id") == "timeline"
        }


def dynamic_timeline_contract_issues(
    soup: BeautifulSoup,
    path: Path,
    *,
    languages: tuple[str, ...] = LANGS,
    contracts: dict[tuple[str, str, str], dict[str, str]] | None = None,
) -> list[str]:
    """Check reviewed visible timeline prose, order, source refs, and source roles."""
    contracts = contracts if contracts is not None else load_dynamic_timeline_contracts()
    issues: list[str] = []
    for lang in languages:
        rows = [
            row for (slug, row_lang, _fact_id), row in contracts.items()
            if slug == path.stem and row_lang == lang
        ]
        rows.sort(key=lambda row: int(row.get("visible_timeline_order", "0") or 0))
        if not rows:
            issues.append(f"{lang}: {path.stem} lacks a reviewed dynamic visible-timeline contract")
            continue
        body = body_for(soup, lang)
        heading = body.select_one('h2[data-section="timeline"]') if body else None
        timeline = heading.find_next_sibling("ol") if heading else None
        nodes = timeline.find_all("li", recursive=False) if timeline else []
        expected_ids = tuple(row.get("fact_id", "") for row in rows)
        actual_ids = tuple(node.get("data-fact-id", "") for node in nodes)
        if actual_ids != expected_ids:
            issues.append(f"{lang}: {path.stem} visible timeline fact order changed")
        node_map = {node.get("data-fact-id", ""): node for node in nodes}
        for row in rows:
            fact_id = row.get("fact_id", "")
            node = node_map.get(fact_id)
            if node is None:
                continue
            refs = tuple(node.get("data-source-ref", "").split())
            if node.get("data-source-ref", "") != row.get("data_source_ref", ""):
                issues.append(f"{lang}: {fact_id} visible timeline source-ref relationship changed")
            if visible_source_role_signature(body, refs) != row.get("visible_source_roles", ""):
                issues.append(f"{lang}: {fact_id} visible timeline source-role relationship changed")
            if row.get("baseline_issue", "").startswith(
                BATCH11_FINAL7_CONTRACT_PREFIX
            ):
                final7_key = (
                    path.stem,
                    lang,
                    "fact",
                    fact_id,
                )
                expected_audit = BATCH11_FINAL7_EXPECTED_SOURCE_AUDIT.get(
                    final7_key
                )
                if expected_audit is None:
                    issues.append(
                        f"{lang}: {fact_id} lacks an independent final7 "
                        "visible-timeline audit"
                    )
                    continue
                for field, label in (
                    ("visible_subject_anchor", "subject"),
                    ("visible_action_anchor", "action"),
                    ("visible_consequence_anchor", "consequence"),
                    ("visible_timeline_order", "order"),
                    ("visible_source_roles", "source-role"),
                ):
                    if row.get(field, "") != expected_audit[field]:
                        issues.append(
                            f"{lang}: {fact_id} changed its independent final7 "
                            f"visible {label} audit"
                        )
                visible = batch11_final7_visible_text(
                    node, final7_key
                ).casefold()
                for label, anchors in (
                    BATCH11_FINAL7_DYNAMIC_TEXT_ANCHORS[final7_key].items()
                ):
                    if any(
                        anchor.casefold() not in visible
                        for anchor in anchors
                    ):
                        issues.append(
                            f"{lang}: {fact_id} lost its reviewed visible "
                            f"{label} anchor"
                        )
            elif row.get("baseline_issue", "").startswith(
                BATCH12_CONTRACT_PREFIX
            ):
                # Batch12 source-ledger anchor fields are compact semantic
                # audit codes, not translation literals.  Their exact values,
                # every timeline attribute in all ten languages, and
                # independently selected English visible anchors are enforced
                # by batch12_ledger_issues and batch12_page_semantic_issues.
                # Treating the codes as ten-language substrings would make the
                # historical generic validator reject every honest successor.
                continue
            else:
                visible = normalized_visible_anchor(
                    node.get_text(" ", strip=True)
                )
                for field, label in (
                    ("visible_subject_anchor", "subject"),
                    ("visible_action_anchor", "action"),
                    ("visible_consequence_anchor", "consequence"),
                ):
                    anchor = normalized_visible_anchor(row.get(field, ""))
                    if not anchor or anchor not in visible:
                        issues.append(
                            f"{lang}: {fact_id} lost its reviewed visible "
                            f"{label} anchor"
                        )
    return issues


def validate_paths() -> list[str]:
    issues = []
    dynamic_contracts = load_dynamic_timeline_contracts()
    editorial_contracts, editorial_contract_issues = load_editorial_semantic_contracts()
    issues.extend(editorial_contract_issues)
    if len(FILES) != EXPECTED_FILES:
        issues.append(f"posts: expected {EXPECTED_FILES} public articles, found {len(FILES)}")
    for path in FILES:
        raw = path.read_text(encoding="utf-8")
        if GLOBAL_TERMS.search(raw):
            issues.append(f"posts/{path.name}: prohibited error term remains")
        soup = BeautifulSoup(raw, "html.parser")
        issues.extend(f"posts/{path.name}: {issue}" for issue in targeted_translation_issues(soup, path))
        issues.extend(f"posts/{path.name}: {issue}" for issue in issue_list(soup, path))
        issues.extend(f"posts/{path.name}: {issue}" for issue in semantic_fact_contract_issues(soup, path))
        issues.extend(f"posts/{path.name}: {issue}" for issue in reviewed_report_contract_issues(soup, path))
        issues.extend(f"posts/{path.name}: {issue}" for issue in case_semantic_contract_issues(soup, path))
        issues.extend(
            f"posts/{path.name}: {issue}"
            for issue in editorial_semantic_contract_issues(
                soup, path, contracts=editorial_contracts
            )
        )
        issues.extend(
            f"posts/{path.name}: {issue}"
            for issue in batch13_duty_subject_issues(soup, path.stem)
        )
        issues.extend(
            f"posts/{path.name}: {issue}"
            for issue in batch8_final3_semantic_issues(soup, path)
        )
        issues.extend(
            f"posts/{path.name}: {issue}"
            for issue in dynamic_timeline_contract_issues(soup, path, contracts=dynamic_contracts)
        )
        issues.extend(f"posts/{path.name}: {issue}" for issue in source_date_contract_issues(soup, path))
        if path.name == "jiang-tianyong.html":
            issues.extend(f"posts/{path.name}: {issue}" for issue in jiang_tianyong_issues(soup))
        issues.extend(f"posts/{path.name}: {issue}" for issue in full_dossier_contract_issues(soup, path))
    issues.extend(duplicate_sentence_issues())
    issues.extend(card_issues())
    issues.extend(report_card_integrity_issues())
    issues.extend(final2_card_delta_issues())
    issues.extend(final1_public_forbidden_issues())
    issues.extend(final2_precision_issues())
    issues.extend(batch10_precision_issues())
    issues.extend(final2_source_metadata_issues())
    issues.extend(frozen_article_issues())
    issues.extend(final1_freeze_issues())
    issues.extend(final2_freeze_issues())
    issues.extend(batch10_start_freeze_issues())
    issues.extend(batch10_final2_frozen_issues())
    issues.extend(batch10_card_baseline_issues())
    issues.extend(batch10_card_delta_issues())
    issues.extend(batch10_final1_preimage_issues())
    issues.extend(batch10_independent_validator_wiring_issues())
    # The later batch-eleven manifest supersedes the historical final3 release
    # freeze; the old function remains available to its historical self-test.
    batch11_history = batch11_final1_historical_state()
    batch12_pre_card_script = batch12_rewind_card_script()
    issues.extend(batch11_history[-1])
    issues.extend(
        batch11_release_issues(
            page_overrides=batch11_history[0],
            script_override=batch12_pre_card_script,
            reread_rows_override=batch11_history[1],
            contract_rows_override=batch11_history[2],
            source_rows_override=batch11_history[3],
            freeze_overrides={
                "tools/data/source-date-ledger.tsv": batch11_history[4]
            },
            source_date_override=batch11_history[4],
        )
    )
    # Each final1/final2/final3 release routine reconstructs its own
    # authenticated historical page state.  Supplying the unrelated batch12
    # page map here made live final7 Feng/2024 prose look like old final1
    # changes and produced a false successor delta.
    issues.extend(batch11_final1_release_issues())
    issues.extend(batch11_final2_release_issues())
    issues.extend(batch11_final3_release_issues())
    (
        batch11_final6_page,
        batch11_final6_reread_rows,
        batch11_final6_contract_rows,
        batch11_final6_source_rows,
    ) = batch11_final7_historical_final6_state()
    batch11_final6_page_override = {
        BATCH11_FINAL7_TARGET_SLUG: batch11_final6_page,
    }
    issues.extend(
        batch11_final4_release_issues(
            page_overrides=batch11_final6_page_override,
            reread_rows_override=batch11_final6_reread_rows,
            contract_rows_override=batch11_final6_contract_rows,
            source_rows_override=batch11_final6_source_rows,
        )
    )
    issues.extend(
        batch11_final5_release_issues(
            page_override=batch11_final6_page,
            reread_rows_override=batch11_final6_reread_rows,
            contract_rows_override=batch11_final6_contract_rows,
            source_rows_override=batch11_final6_source_rows,
        )
    )
    issues.extend(
        batch11_final6_release_issues(
            page_override=batch11_final6_page,
            reread_rows_override=batch11_final6_reread_rows,
            contract_rows_override=batch11_final6_contract_rows,
            source_rows_override=batch11_final6_source_rows,
        )
    )
    issues.extend(batch11_final7_release_issues())
    issues.extend(batch12_release_issues())
    issues.extend(batch13_release_issues())
    issues.extend(batch14_release_issues())
    # Structural article-shell gate over all 54 dossiers.  It runs on the
    # default invocation and therefore also under --matrix and --release.
    issues.extend(article_shell_gate_issues())
    issues.extend(public_page_checks())
    issues.extend(source_ledger_issues(require_file=True))
    issues.extend(source_date_ledger_issues(require_file=True))
    issues.extend(semantic_reread_ledger_issues(contracts=editorial_contracts))
    issues.extend(batch9_live_reread_issues())
    return issues


def release_text(name: str, overrides: dict[str, str | bytes] | None = None) -> str:
    value = (overrides or {}).get(name)
    if isinstance(value, bytes):
        return value.decode("utf-8")
    if isinstance(value, str):
        return value
    return (ROOT / name).read_text(encoding="utf-8")


def release_html_paths() -> tuple[Path, ...]:
    return tuple(ROOT / name for name in RELEASE_ROOT_PAGES) + FILES


def local_target_path(page: Path, raw_path: str) -> Path:
    decoded = unquote(raw_path)
    if decoded.startswith("/"):
        target = ROOT / (decoded.lstrip("/") or "index.html")
    elif decoded:
        target = page.parent / decoded
    else:
        target = page
    if target.is_dir():
        target = target / "index.html"
    return target.resolve()


def control_has_accessible_name(control, soup: BeautifulSoup) -> bool:
    if control.name == "input" and control.get("type", "").casefold() == "hidden":
        return True
    if control.get("aria-label") or control.get("aria-labelledby"):
        return True
    if control.get_text(" ", strip=True):
        return True
    if control.name == "input" and control.get("type", "").casefold() in {"submit", "button", "reset"}:
        return bool(control.get("value", "").strip())
    if control.find_parent("label"):
        return True
    control_id = control.get("id")
    return bool(control_id and soup.find("label", attrs={"for": control_id}))


def public_html_release_issues(overrides: dict[str, str | bytes] | None = None) -> list[str]:
    issues: list[str] = []
    documents: dict[str, BeautifulSoup] = {}
    for path in release_html_paths():
        relative = path.relative_to(ROOT).as_posix()
        if not path.exists() and relative not in (overrides or {}):
            issues.append(f"{relative}: public HTML file is missing")
            continue
        documents[relative] = BeautifulSoup(release_text(relative, overrides), "html.parser")

    root_resolved = ROOT.resolve()
    for relative, soup in documents.items():
        path = ROOT / relative
        raw = release_text(relative, overrides)
        if LOCAL_PATH_MARKERS.search(raw):
            issues.append(f"{relative}: local filesystem path appears in public HTML")

        head = soup.head
        if head is None:
            issues.append(f"{relative}: missing head")
        else:
            if not head.find("meta", attrs={"charset": True}):
                issues.append(f"{relative}: missing charset metadata")
            viewport = head.find("meta", attrs={"name": re.compile(r"^viewport$", re.I)})
            if not viewport or not viewport.get("content", "").strip():
                issues.append(f"{relative}: missing viewport metadata")
            if not head.title or not head.title.get_text(" ", strip=True):
                issues.append(f"{relative}: missing non-empty title")
            icon_links = [
                link for link in head.find_all("link")
                if "icon" in {item.casefold() for item in (link.get("rel") or [])}
                and link.get("href", "").strip()
            ]
            if not icon_links:
                issues.append(f"{relative}: missing favicon")

        ids = [node.get("id") for node in soup.select("[id]")]
        for duplicate, count in Counter(ids).items():
            if duplicate and count > 1:
                issues.append(f"{relative}: duplicate HTML id {duplicate!r}")

        for image in soup.find_all("img"):
            if not image.has_attr("alt"):
                issues.append(f"{relative}: image {image.get('src', '')!r} lacks alt text")
            elif not image.get("alt", "").strip() and not (
                image.get("role") == "presentation" or image.get("aria-hidden") == "true"
            ):
                issues.append(
                    f"{relative}: image {image.get('src', '')!r} has empty alt without an explicit decorative rule"
                )

        for control in soup.select("input, select, textarea, button"):
            if not control_has_accessible_name(control, soup):
                issues.append(f"{relative}: unnamed {control.name} form control")

        for anchor in soup.select('a[target="_blank"]'):
            rel_values = {item.casefold() for item in (anchor.get("rel") or [])}
            if not {"noopener", "noreferrer"}.issubset(rel_values):
                issues.append(
                    f"{relative}: new-window link lacks rel=\"noopener noreferrer\": {anchor.get('href', '')}"
                )

        referenced = [(node, "href") for node in soup.select("[href]")]
        referenced += [(node, "src") for node in soup.select("[src]")]
        for node, attribute in referenced:
            value = node.get(attribute, "").strip()
            if not value:
                continue
            parsed = urlsplit(value)
            if value.startswith("//") or parsed.scheme:
                continue
            target = local_target_path(path, parsed.path)
            try:
                target_relative = target.relative_to(root_resolved).as_posix()
            except ValueError:
                issues.append(f"{relative}: local {attribute} escapes the repository: {value}")
                continue

            parts = set(Path(target_relative).parts)
            if parts & FORBIDDEN_PUBLIC_LINK_PARTS or target_relative == "posts/template.html":
                issues.append(f"{relative}: public link targets excluded maintenance content: {value}")
            if not target.exists():
                issues.append(f"{relative}: local {attribute} target does not exist: {value}")
                continue
            if parsed.fragment and target.suffix.casefold() == ".html":
                target_soup = documents.get(target_relative)
                if target_soup is None:
                    target_soup = BeautifulSoup(release_text(target_relative, overrides), "html.parser")
                if target_soup.find(id=unquote(parsed.fragment)) is None:
                    issues.append(f"{relative}: internal anchor target does not exist: {value}")
    return issues


def expected_sitemap_urls() -> tuple[str, ...]:
    paths = SITEMAP_ROOT_PATHS + tuple(f"/posts/{path.name}" for path in FILES)
    return tuple(SITE_ORIGIN + path for path in paths)


def sitemap_issues(text_override: str | None = None) -> list[str]:
    text = text_override if text_override is not None else (ROOT / "sitemap.xml").read_text(encoding="utf-8")
    issues: list[str] = []
    try:
        root = ET.fromstring(text)
    except ET.ParseError as exc:
        return [f"sitemap.xml: invalid XML: {exc}"]
    if root.tag.rsplit("}", 1)[-1] != "urlset":
        issues.append("sitemap.xml: root element is not urlset")
    locs = [
        (node.text or "").strip()
        for node in root.iter()
        if node.tag.rsplit("}", 1)[-1] == "loc"
    ]
    if len(locs) != len(set(locs)):
        issues.append("sitemap.xml: duplicate URL")
    expected = set(expected_sitemap_urls())
    actual = set(locs)
    for missing in sorted(expected - actual):
        issues.append(f"sitemap.xml: missing public URL {missing}")
    for extra in sorted(actual - expected):
        issues.append(f"sitemap.xml: unexpected or non-public URL {extra}")
    for loc in locs:
        parsed = urlsplit(loc)
        if parsed.scheme != "https" or parsed.netloc != "zhonghuafreedom.org":
            issues.append(f"sitemap.xml: URL is not on the canonical HTTPS origin: {loc}")
            continue
        if parsed.query or parsed.fragment:
            issues.append(f"sitemap.xml: URL contains a query or fragment: {loc}")
        deployment_path = ROOT / (parsed.path.lstrip("/") or "index.html")
        if not deployment_path.is_file():
            issues.append(f"sitemap.xml: URL has no deployment file: {loc}")
    if any(node.tag.rsplit("}", 1)[-1] == "lastmod" for node in root.iter()):
        issues.append("sitemap.xml: lastmod is present without a maintained per-page date source")
    return issues


def robots_issues(text_override: str | None = None) -> list[str]:
    text = text_override if text_override is not None else (ROOT / "robots.txt").read_text(encoding="utf-8")
    lines = [line.strip() for line in text.splitlines() if line.strip() and not line.lstrip().startswith("#")]
    issues = []
    if "User-agent: *" not in lines:
        issues.append("robots.txt: missing User-agent: *")
    if "Allow: /" not in lines:
        issues.append("robots.txt: missing Allow: /")
    expected = f"Sitemap: {SITE_ORIGIN}/sitemap.xml"
    sitemap_lines = [line for line in lines if line.casefold().startswith("sitemap:")]
    if sitemap_lines != [expected]:
        issues.append("robots.txt: Sitemap URL does not exactly match CNAME")
    return issues


def parse_config_excludes(text: str) -> tuple[list[str], list[str]]:
    excludes: list[str] = []
    issues: list[str] = []
    in_exclude = False
    saw_exclude = False
    for number, raw in enumerate(text.splitlines(), 1):
        if "\t" in raw:
            issues.append(f"_config.yml:{number}: tabs are not valid indentation")
        stripped = raw.strip()
        if not stripped or stripped.startswith("#"):
            continue
        if not raw.startswith((" ", "-")):
            in_exclude = stripped == "exclude:"
            saw_exclude |= in_exclude
            continue
        if in_exclude:
            if not stripped.startswith("- "):
                issues.append(f"_config.yml:{number}: malformed exclude list item")
                continue
            value = stripped[2:].strip().strip('"\'')
            if not value:
                issues.append(f"_config.yml:{number}: empty exclude list item")
            else:
                excludes.append(value)
    if not saw_exclude:
        issues.append("_config.yml: missing exclude list")
    return excludes, issues


def config_excludes_path(pattern: str, candidate: str) -> bool:
    normalized = pattern.strip().strip("/")
    candidate = candidate.strip("/")
    return (
        candidate == normalized
        or candidate.startswith(normalized + "/")
        or fnmatch.fnmatch(candidate, normalized)
    )


def config_issues(text_override: str | None = None) -> list[str]:
    text = text_override if text_override is not None else (ROOT / "_config.yml").read_text(encoding="utf-8")
    excludes, issues = parse_config_excludes(text)
    normalized = {item.strip().strip("/") for item in excludes}
    for required in sorted(REQUIRED_CONFIG_EXCLUDES - normalized):
        issues.append(f"_config.yml: missing required exclusion {required}")
    if any(config_excludes_path(item, "CNAME") for item in excludes):
        issues.append("_config.yml: CNAME must not be excluded")
    for path in FILES:
        candidate = f"posts/{path.name}"
        if any(config_excludes_path(item, candidate) for item in excludes):
            issues.append(f"_config.yml: formal article is excluded: {candidate}")
    return issues


def cname_issues(text_override: str | None = None) -> list[str]:
    text = text_override if text_override is not None else (ROOT / "CNAME").read_text(encoding="utf-8")
    return [] if text.strip() == "zhonghuafreedom.org" else ["CNAME: must exactly equal zhonghuafreedom.org"]


def sync_script_issues(text_override: str | None = None) -> list[str]:
    text = text_override if text_override is not None else (ROOT / "tools/sync_languages.py").read_text(encoding="utf-8")
    risks = {
        "translate.googleapis.com": "network translation endpoint",
        "urllib.request": "network request module",
        "urlopen": "network request call",
        "write_text": "filesystem write capability",
        "clone_lang_blocks": "English-block cloning path",
        "translate_js_reports": "report-card translation writer",
        "replace_post_inline_script": "inline-script replacement path",
    }
    issues = [
        f"tools/sync_languages.py: contains prohibited {label}"
        for token, label in risks.items() if token.casefold() in text.casefold()
    ]
    if re.search(r"\bopen\s*\([^\n]*,['\"]\s*[wax+]", text):
        issues.append("tools/sync_languages.py: contains a write-mode open call")
    return issues


def readme_release_issues(text_override: str | None = None) -> list[str]:
    text = text_override if text_override is not None else (ROOT / "README.md").read_text(encoding="utf-8")
    issues = []
    banned = (
        "uses the English blocks as the source",
        "English blocks as the source",
    )
    if any(phrase.casefold() in text.casefold() for phrase in banned):
        issues.append("README.md: restores English-block machine-translation guidance")
    required_phrases = (
        "Traditional Chinese is the content master",
        "must each be translated by a person",
        "network translation services must not be used",
        "tools/sync_languages.py` is a read-only missing-item audit",
        "Do not commit, push, or change remote repository settings",
    )
    for phrase in required_phrases:
        if phrase.casefold() not in text.casefold():
            issues.append(f"README.md: missing maintenance rule {phrase!r}")
    commands = (
        "python3 tools/check_languages.py",
        "python3 tools/check_languages.py --matrix",
        "python3 tools/check_languages.py --self-test",
        "node --check script.js",
        "node --check language.js",
        "node --check protests.js",
        "git diff --check",
    )
    for command in commands:
        if command not in text:
            issues.append(f"README.md: missing validation command {command}")
    return issues


def gitignore_patterns(text: str) -> list[str]:
    return [
        line.strip() for line in text.splitlines()
        if line.strip() and not line.lstrip().startswith("#")
    ]


def gitignore_pattern_matches(pattern: str, candidate: str) -> bool:
    original = pattern
    pattern = pattern.lstrip("!").lstrip("/")
    candidate = candidate.lstrip("/")
    if original.endswith("/"):
        directory = pattern.rstrip("/")
        return (
            candidate == directory
            or candidate.startswith(directory + "/")
            or f"/{directory}/" in f"/{candidate}/"
        )
    if "/" not in pattern:
        return any(fnmatch.fnmatch(part, pattern) for part in candidate.split("/"))
    return fnmatch.fnmatch(candidate, pattern)


def gitignore_ignores(patterns: list[str], candidate: str) -> bool:
    ignored = False
    for pattern in patterns:
        if gitignore_pattern_matches(pattern, candidate):
            ignored = not pattern.startswith("!")
    return ignored


def gitignore_issues(text_override: str | None = None) -> list[str]:
    text = text_override if text_override is not None else (ROOT / ".gitignore").read_text(encoding="utf-8")
    patterns = gitignore_patterns(text)
    issues = []
    required = {
        ".DS_Store", "tools/.translation-cache.json", ".visual-qa/", "visual-qa/",
        "screenshots/", "__pycache__/", "*.py[cod]", "npm-debug.log*",
        "yarn-debug.log*", "yarn-error.log*", "pnpm-debug.log*", ".http-server.log",
        "http-server*.log", "local-server*.log",
    }
    for pattern in sorted(required - set(patterns)):
        issues.append(f".gitignore: missing local-artifact rule {pattern}")
    public_samples = [
        "index.html", "posts/2024-report.html", "images/protests/2025-09-03/photo-001.jpg",
        "CNAME", "sitemap.xml", "robots.txt", "404.html", "_config.yml",
    ]
    for candidate in public_samples:
        if gitignore_ignores(patterns, candidate):
            issues.append(f".gitignore: publication file would be ignored: {candidate}")
    return issues


def not_found_issues(text_override: str | None = None) -> list[str]:
    text = text_override if text_override is not None else (ROOT / "404.html").read_text(encoding="utf-8")
    soup = BeautifulSoup(text, "html.parser")
    issues: list[str] = []
    if not soup.html or soup.html.get("lang") != "zh-Hant":
        issues.append("404.html: initial html lang must be zh-Hant")
    body = soup.body
    if body is None:
        return ["404.html: missing body"]
    expected_links = {"index.html", "reports.html", "sources.html", "contact.html"}
    english_text = ""
    for lang in LANGS:
        containers = soup.select(f'[data-language-body="{lang}"]')
        if len(containers) != 1:
            issues.append(f"404.html: expected one {lang} body, found {len(containers)}")
            continue
        container = containers[0]
        headings = container.find_all("h1")
        if len(headings) != 1 or not headings[0].get_text(" ", strip=True):
            issues.append(f"404.html: {lang} must have one non-empty H1")
        paragraphs = container.find_all("p")
        if not paragraphs or not " ".join(p.get_text(" ", strip=True) for p in paragraphs).strip():
            issues.append(f"404.html: {lang} body text is empty")
        links = {urlsplit(a.get("href", "")).path for a in container.find_all("a")}
        if not expected_links.issubset(links):
            issues.append(f"404.html: {lang} lacks one or more required recovery links")
        visible = re.sub(r"\s+", " ", container.get_text(" ", strip=True)).casefold()
        if lang == "en":
            english_text = visible
        elif english_text and visible == english_text:
            issues.append(f"404.html: {lang} falls back to English")
        if not body.get(f"data-title-{lang}", "").strip():
            issues.append(f"404.html: missing localized document title for {lang}")
    options = [option.get("value") for option in soup.select("#lang-toggle option")]
    if options != list(LANGS):
        issues.append("404.html: language selector is not the exact ten-language sequence")
    scripts = {urlsplit(node.get("src", "")).path for node in soup.find_all("script", src=True)}
    if not {"language.js", "script.js"}.issubset(scripts):
        issues.append("404.html: language.js or script.js is missing")
    menu = soup.select_one(".mobile-menu-btn")
    if not menu or menu.get("aria-expanded") != "false":
        issues.append("404.html: mobile menu lacks initial aria-expanded=false")
    if soup.find("form"):
        issues.append("404.html: forms are not allowed")
    if PUBLIC_BANNED.search(soup.get_text(" ", strip=True)):
        issues.append("404.html: prohibited public wording appears")
    return issues


def release_surface_issues(overrides: dict[str, str | bytes] | None = None) -> list[str]:
    overrides = overrides or {}
    issues = public_html_release_issues(overrides)
    issues.extend(sitemap_issues(release_text("sitemap.xml", overrides)))
    issues.extend(robots_issues(release_text("robots.txt", overrides)))
    issues.extend(config_issues(release_text("_config.yml", overrides)))
    issues.extend(cname_issues(release_text("CNAME", overrides)))
    issues.extend(sync_script_issues(release_text("tools/sync_languages.py", overrides)))
    issues.extend(readme_release_issues(release_text("README.md", overrides)))
    issues.extend(gitignore_issues(release_text(".gitignore", overrides)))
    issues.extend(not_found_issues(release_text("404.html", overrides)))
    return issues


def release_surface_statistics() -> Counter:
    stats = Counter()
    for path in release_html_paths():
        soup = BeautifulSoup(path.read_text(encoding="utf-8"), "html.parser")
        stats["html"] += 1
        stats["images"] += len(soup.find_all("img"))
        stats["controls"] += len(soup.select("input, select, textarea, button"))
        for node, attribute in (
            [(item, "href") for item in soup.select("[href]")]
            + [(item, "src") for item in soup.select("[src]")]
        ):
            value = node.get(attribute, "").strip()
            parsed = urlsplit(value)
            if value and not value.startswith("//") and not parsed.scheme:
                stats["local_references"] += 1
                stats["anchors"] += int(bool(parsed.fragment))
    stats["sitemap_urls"] = len(expected_sitemap_urls())
    stats["formal_posts"] = len(FILES)
    return stats


def add_after(heading, tag):
    heading.insert_after(tag)


def dynamic_timeline_self_tests() -> list[tuple[str, bool]]:
    """Run the six required visible-prose mutations for every page/language."""
    contracts = load_dynamic_timeline_contracts()
    checks: list[tuple[str, bool]] = []
    batch12_pages = batch12_live_pages()
    batch12_reread_rows = batch11_tsv_rows(SEMANTIC_REREAD_PATH)
    batch12_contract_rows = batch11_tsv_rows(
        EDITORIAL_SEMANTIC_CONTRACT_PATH
    )
    batch12_source_rows = batch11_tsv_rows(SOURCE_LEDGER_PATH)
    routine = {
        "zh": "發布一般天氣、交通和行政通知",
        "en": "issued an ordinary weather, traffic and administrative notice",
        "ja": "通常の天気、交通、行政のお知らせを出した",
        "ko": "일상적인 날씨, 교통 및 행정 공지를 발표했다",
        "es": "publicó un aviso ordinario meteorológico, vial y administrativo",
        "de": "veröffentlichte eine gewöhnliche Wetter-, Verkehrs- und Verwaltungsmitteilung",
        "fr": "a publié un avis ordinaire sur la météo, la circulation et l’administration",
        "no": "publiserte en ordinær vær-, trafikk- og administrasjonsmelding",
        "nl": "publiceerde een gewoon weer-, verkeers- en administratief bericht",
        "it": "ha pubblicato un avviso ordinario meteorologico, stradale e amministrativo",
    }

    def restore(node, markup: str) -> None:
        node.clear()
        fragment = BeautifulSoup(markup, "html.parser")
        for child in list(fragment.contents):
            node.append(child.extract())

    def successor_caught(
        caught: bool,
        soup: BeautifulSoup,
        path: Path,
    ) -> bool:
        if caught or path.name not in BATCH12_TARGET_FILENAMES:
            return caught
        pages = dict(batch12_pages)
        pages[path.stem] = soup
        return bool(
            batch12_ledger_issues(
                pages_override=pages,
                reread_rows_override=batch12_reread_rows,
                contract_rows_override=batch12_contract_rows,
                source_rows_override=batch12_source_rows,
            )
        )

    for path in FILES:
        soup = BeautifulSoup(path.read_text(encoding="utf-8"), "html.parser")
        for lang in LANGS:
            rows = [
                row for (slug, row_lang, _fact_id), row in contracts.items()
                if slug == path.stem and row_lang == lang
            ]
            rows.sort(key=lambda row: int(row.get("visible_timeline_order", "0") or 0))
            body = body_for(soup, lang)
            heading = body.select_one('h2[data-section="timeline"]') if body else None
            timeline = heading.find_next_sibling("ol") if heading else None
            nodes = timeline.find_all("li", recursive=False) if timeline else []
            prefix = f"{path.stem}/{lang}"
            if not rows or len(nodes) < 2:
                for mutation in (
                    "weather-traffic-administration", "subject-deletion", "action-deletion",
                    "consequence-deletion", "fact-moved", "institution-only",
                ):
                    checks.append((f"{prefix} {mutation}", False))
                continue

            originals = [node.decode_contents() for node in nodes]
            numbers = [" ".join(re.findall(r"\d+", node.get_text(" ", strip=True))) for node in nodes]

            for index, (node, row) in enumerate(zip(nodes, rows)):
                node.clear()
                node.append(
                    f"{numbers[index]} {row.get('visible_subject_anchor', '')} {routine[lang]}"
                )
            caught = dynamic_timeline_contract_issues(
                soup, path, languages=(lang,), contracts=contracts
            )
            checks.append((
                f"{prefix} weather-traffic-administration",
                successor_caught(
                    any(
                        "visible action anchor" in issue
                        or "visible consequence anchor" in issue
                        for issue in caught
                    ),
                    soup,
                    path,
                ),
            ))
            for node, markup in zip(nodes, originals):
                restore(node, markup)

            targets = (
                (0, "visible_subject_anchor", "subject-deletion", "visible subject anchor"),
                (len(nodes) // 2, "visible_action_anchor", "action-deletion", "visible action anchor"),
                (len(nodes) - 1, "visible_consequence_anchor", "consequence-deletion", "visible consequence anchor"),
            )
            for index, _field, label, expected_issue in targets:
                node = nodes[index]
                markup = node.decode_contents()
                node.clear()
                node.append(f"{numbers[index]} {routine[lang]}")
                caught = dynamic_timeline_contract_issues(
                    soup, path, languages=(lang,), contracts=contracts
                )
                checks.append((
                    f"{prefix} {label}",
                    successor_caught(
                        any(expected_issue in issue for issue in caught),
                        soup,
                        path,
                    ),
                ))
                restore(node, markup)

            second = nodes[1].extract()
            nodes[0].insert_before(second)
            caught = dynamic_timeline_contract_issues(
                soup, path, languages=(lang,), contracts=contracts
            )
            checks.append((f"{prefix} fact-moved", any("fact order changed" in issue for issue in caught)))
            second.extract()
            nodes[0].insert_after(second)

            originals = [node.decode_contents() for node in nodes]
            for index, (node, row) in enumerate(zip(nodes, rows)):
                node.clear()
                node.append(f"{numbers[index]} {row.get('visible_subject_anchor', '')}")
            caught = dynamic_timeline_contract_issues(
                soup, path, languages=(lang,), contracts=contracts
            )
            checks.append((
                f"{prefix} institution-only",
                successor_caught(
                    any(
                        "visible action anchor" in issue
                        or "visible consequence anchor" in issue
                        for issue in caught
                    ),
                    soup,
                    path,
                ),
            ))
            for node, markup in zip(nodes, originals):
                restore(node, markup)
    return checks


def source_date_self_tests() -> list[tuple[str, bool]]:
    """Mutate live source DOM and the checked-in source-date ledger in memory."""
    checks: list[tuple[str, bool]] = []
    documents = loaded_documents()
    with SOURCE_DATE_LEDGER_PATH.open(encoding="utf-8", newline="") as handle:
        rows = list(csv.DictReader(handle, delimiter="\t"))
    target_path = POSTS / "henan-bank-depositor-protests.html"
    selector = '.article-body.lang-en li[data-source-id="hbd-s3"]'

    def mutate(mutator, path: Path = target_path):
        changed = dict(documents)
        soup = copy.deepcopy(documents[path])
        mutator(soup)
        changed[path] = soup
        return changed

    wrong_attr = mutate(lambda soup: soup.select_one(selector).__setitem__("data-source-date", "2022-07-11"))
    checks.append((
        "source data-source-date changed without visible date",
        any("data-source-date differs" in issue for issue in source_date_ledger_issues(wrong_attr, rows)),
    ))

    wrong_datetime = mutate(lambda soup: soup.select_one(selector).find("time").__setitem__("datetime", "2022-07-11"))
    checks.append((
        "source time datetime changed without visible date",
        any("time datetime differs" in issue for issue in source_date_ledger_issues(wrong_datetime, rows)),
    ))

    def change_visible(soup):
        soup.select_one(selector).find("time").string = "2022-07-11"

    wrong_visible = mutate(change_visible)
    checks.append((
        "visible source date changed without metadata",
        any("visible source date differs" in issue for issue in source_date_ledger_issues(wrong_visible, rows)),
    ))

    def change_type(soup):
        soup.select_one(selector)["data-source-type"] = "institutional-public"

    wrong_type = mutate(change_type)
    checks.append((
        "one-language source type changed",
        any("source type differs" in issue or "signature differs" in issue for issue in source_date_ledger_issues(wrong_type, rows)),
    ))

    def change_url(soup):
        soup.select_one(selector).find("a")["href"] = "https://example.invalid/source-date-mutation"

    wrong_url = mutate(change_url)
    checks.append((
        "one-language source URL changed",
        any("URL differs" in issue or "signature differs" in issue for issue in source_date_ledger_issues(wrong_url, rows)),
    ))

    def change_id(soup):
        soup.select_one(selector)["data-source-id"] = "hbd-s3-mutated"

    wrong_id = mutate(change_id)
    checks.append((
        "one-language source ID changed",
        any("coverage differs" in issue or "signature differs" in issue for issue in source_date_ledger_issues(wrong_id, rows)),
    ))

    def change_order(soup):
        body = body_for(soup, "en")
        nodes = body.select("ul.source-list > li[data-source-id]")
        nodes[-1].insert_after(nodes[0].extract())

    wrong_order = mutate(change_order)
    checks.append((
        "one-language source order changed",
        any("signature differs" in issue for issue in source_date_ledger_issues(wrong_order, rows)),
    ))

    def fabricate_default(soup):
        node = soup.select_one(selector)
        node["data-source-date"] = "2022-01-01"
        node.find("time")["datetime"] = "2022-01-01"
        node.find("time").string = "2022-01-01"

    default_documents = mutate(fabricate_default)
    default_rows = [dict(row) for row in rows]
    for row in default_rows:
        if row["slug"] == "henan-bank-depositor-protests" and row["source_id"] == "hbd-s3":
            row["audited_date"] = "2022-01-01"
            row["precision"] = "year"
    checks.append((
        "unsupported year-to-January-1 date fabricated in DOM and ledger",
        any("suspicious unsupported YYYY-01-01" in issue for issue in source_date_ledger_issues(default_documents, default_rows)),
    ))

    undated_path = POSTS / "china-dissent-monitor-2025.html"
    undated_selector = '.article-body.lang-en li[data-source-id="cdm25-s1"]'

    def make_undated_precise(soup):
        node = soup.select_one(undated_selector)
        node["data-source-date"] = "2026-01-01"
        marker = soup.new_tag("time")
        marker["datetime"] = "2026-01-01"
        marker.string = "2026-01-01"
        node.append(marker)

    precise_undated = mutate(make_undated_precise, undated_path)
    checks.append((
        "UNDATED source silently assigned a precise date",
        any("localized UNDATED marker and no precise date" in issue for issue in source_date_ledger_issues(precise_undated, rows)),
    ))

    deleted_rows = [row for row in rows if not (row["slug"] == "henan-bank-depositor-protests" and row["source_id"] == "hbd-s3")]
    checks.append((
        "source-date ledger source group deleted",
        any("coverage differs" in issue for issue in source_date_ledger_issues(documents, deleted_rows)),
    ))
    return checks


