    def replace_final3_text(node, old: str, new: str) -> bool:
        changed = False
        for text_node in list(node.find_all(string=True)):
            value = str(text_node)
            if old in value:
                text_node.replace_with(value.replace(old, new))
                changed = True
        return changed

