    script_text = (ROOT / "script.js").read_text(encoding="utf-8")

    def mutate_non_target_card(field: str, replacement: str) -> str:
        slug = "pucheng-student-death-protest"
        pattern = re.compile(
            r'\{[^{}]*?url:\s*"posts/' + re.escape(slug) + r'\.html"[^{}]*?\}',
            re.S,
        )
        match = pattern.search(script_text)
        if match is None:
            return script_text
        block = match.group(0)
        changed, count = re.subn(
            rf'({re.escape(field)}:\s*")[^"]*(")',
            rf'\g<1>{replacement}\g<2>',
            block,
            count=1,
        )
        if count != 1:
            return script_text
        return script_text[:match.start()] + changed + script_text[match.end():]

