_BATCH13_PREIMAGE_TEXT_CACHE: dict[str, str] = {}
_BATCH13_PREIMAGE_ISSUE_CACHE: dict[str, list[str]] = {}


def batch13_tsv_rows(path: Path) -> list[dict[str, str]]:
    """Read one ledger without any normalization, exactly as stored."""
    with path.open(encoding="utf-8", newline="") as handle:
        return list(csv.DictReader(handle, delimiter="\t"))


def batch13_rows_signature_sha256(
    rows: list[dict[str, str]],
    fields: tuple[str, ...],
) -> str:
    payload = "\x1e".join(
        "\x1f".join(row.get(field, "") for field in fields)
        for row in rows
    )
    return sha256_bytes(payload.encode("utf-8"))


def batch13_visible_text(value: str) -> str:
    """Compare visible text without depending on NBSP or wrapping."""
    return " ".join((value or "").replace(" ", " ").split())


def batch13_node_language(node: Tag) -> str:
    for parent in node.parents:
        language = parent.get("data-language-body", "")
        if language:
            return language
        for name in parent.get("class", []) or []:
            if name.startswith("lang-"):
                return name[len("lang-"):]
    return ""


def batch13_minimal_span(original: str, revised: str) -> tuple[int, int, int]:
    """Return the smallest changed window shared by both wordings."""
    head = 0
    while (
        head < len(original)
        and head < len(revised)
        and original[head] == revised[head]
    ):
        head += 1
    tail = 0
    while (
        tail < len(original) - head
        and tail < len(revised) - head
        and original[len(original) - 1 - tail] == revised[len(revised) - 1 - tail]
    ):
        tail += 1
    return head, len(original) - tail, len(revised) - tail


def batch13_reread_append(
    reread_rows: list[dict[str, str]] | None = None,
) -> list[dict[str, str]]:
    rows = (
        reread_rows
        if reread_rows is not None
        else batch13_tsv_rows(SEMANTIC_REREAD_PATH)
    )
    return rows[BATCH13_REREAD_BASE_ROWS:]


def batch13_live_page_text(slug: str) -> str:
    """The dossier as it stood at the end of batch thirteen.

    Batch thirteen's preimage is defined against its own successor state, not
    against whatever the newest batch has since written.  Batch fourteen
    advanced the style.css token on every page and removed a stray timeline
    class from three of them, so those edits are rewound first; batch
    thirteen's own rewind then runs on the text it was authenticated against
    and still reproduces its recorded sha256_before.  When no batch-14 preimage
    covers the file this is the live text, exactly as before.
    """
    relative = f"posts/{slug}.html"
    payload = batch14_historical_page_bytes().get(relative)
    if payload is not None:
        return payload.decode("utf-8")
    return (POSTS / f"{slug}.html").read_bytes().decode("utf-8")


def batch13_preimage_text(
    slug: str,
    *,
    live_text: str | None = None,
    reread_rows: list[dict[str, str]] | None = None,
) -> tuple[str, list[str]]:
    """Rebuild the byte-exact pre-batch13 markup of one revised dossier.

    Each recorded revision is undone inside the element that carries its
    data-fact-id, so mirrored ``data-critical-case`` attributes are restored
    together with the visible sentence.  The result is authenticated against
    the recorded sha256_before, so a wrong or partial rewind cannot pass.
    """
    text = live_text if live_text is not None else batch13_live_page_text(slug)
    rows = [
        row
        for row in batch13_reread_append(reread_rows)
        if row.get("slug", "") == slug
    ]
    issues: list[str] = []
    soup = BeautifulSoup(text, "html.parser")
    for row in rows:
        target_id = row.get("target_id", "")
        language = row.get("language", "")
        label = f"{slug}/{language}/{target_id}"
        order = [
            batch13_node_language(node)
            for node in soup.select(f'[data-fact-id="{target_id}"]')
        ]
        marker = f'data-fact-id="{target_id}"'
        positions = [
            match.start() for match in re.finditer(re.escape(marker), text)
        ]
        if language not in order or len(positions) != len(order):
            issues.append(f"batch13 preimage target is not addressable: {label}")
            continue
        position = positions[order.index(language)]
        start = text.rfind("<", 0, position)
        opening = re.match(r"<([A-Za-z0-9]+)", text[start:]) if start >= 0 else None
        if opening is None:
            issues.append(f"batch13 preimage element start is missing: {label}")
            continue
        closing = f"</{opening.group(1)}>"
        end = text.find(closing, position)
        if end < 0:
            issues.append(f"batch13 preimage element end is missing: {label}")
            continue
        end += len(closing)
        region = text[start:end]
        original = row.get("original_text", "")
        revised = row.get("revised_text", "")
        head, original_end, revised_end = batch13_minimal_span(original, revised)
        rewound = None
        for grow in range(0, 240, 4):
            left = max(0, head - grow)
            new_fragment = revised[left:min(len(revised), revised_end + grow)]
            old_fragment = original[left:min(len(original), original_end + grow)]
            if revised.count(new_fragment) == 1 and region.count(new_fragment) >= 1:
                rewound = region.replace(new_fragment, old_fragment)
                break
        if rewound is None:
            issues.append(f"batch13 preimage fragment is not locatable: {label}")
            continue
        text = text[:start] + rewound + text[end:]
    return text, issues


def batch13_historical_post_text(slug: str) -> str:
    """The dossier markup every pre-batch13 gate must see."""
    if slug not in BATCH13_TARGET_SLUG_SET:
        return (POSTS / f"{slug}.html").read_bytes().decode("utf-8")
    if slug not in _BATCH13_PREIMAGE_TEXT_CACHE:
        text, issues = batch13_preimage_text(slug)
        _BATCH13_PREIMAGE_TEXT_CACHE[slug] = text
        _BATCH13_PREIMAGE_ISSUE_CACHE[slug] = issues
    return _BATCH13_PREIMAGE_TEXT_CACHE[slug]


def batch13_historical_pages(
    slugs: tuple[str, ...] | frozenset[str] | None = None,
) -> dict[str, BeautifulSoup]:
    return {
        slug: BeautifulSoup(batch13_historical_post_text(slug), "html.parser")
        for slug in (slugs if slugs is not None else BATCH13_TARGET_SLUGS)
    }


def batch13_historical_page_bytes() -> dict[str, bytes]:
    """Pre-batch13 bytes keyed by repository-relative path."""
    return {
        f"posts/{slug}.html": batch13_historical_post_text(slug).encode("utf-8")
        for slug in BATCH13_TARGET_SLUGS
    }


_BATCH13_SOURCE_APPEND_KEYS: frozenset[tuple[str, str, str]] | None = None


def batch13_source_append_keys() -> frozenset[tuple[str, str, str]]:
    """The 446 source-ledger rows appended by batch thirteen."""
    global _BATCH13_SOURCE_APPEND_KEYS
    if _BATCH13_SOURCE_APPEND_KEYS is None:
        _BATCH13_SOURCE_APPEND_KEYS = frozenset(
            (
                row.get("slug", ""),
                row.get("language", ""),
                row.get("fact_id", ""),
            )
            for row in batch13_tsv_rows(SOURCE_LEDGER_PATH)[
                BATCH13_SOURCE_BASE_ROWS:
            ]
        )
    return _BATCH13_SOURCE_APPEND_KEYS


_BATCH13_SUPERSEDED_LITERALS: dict[
    tuple[str, str, str], tuple[str, str]
] | None = None


def batch13_superseded_literals() -> dict[tuple[str, str, str], tuple[str, str]]:
    """Per revised node, the (preimage, revision) visible text pair.

    A predecessor contract literal is retired only when it really is a
    fragment of the pre-batch13 sentence that the revision replaced.
    """
    global _BATCH13_SUPERSEDED_LITERALS
    if _BATCH13_SUPERSEDED_LITERALS is None:
        _BATCH13_SUPERSEDED_LITERALS = {
            (
                row.get("slug", ""),
                row.get("language", ""),
                row.get("target_id", ""),
            ): (
                batch13_visible_text(row.get("original_text", "")).casefold(),
                batch13_visible_text(row.get("revised_text", "")).casefold(),
            )
            for row in batch13_reread_append()
        }
    return _BATCH13_SUPERSEDED_LITERALS


def batch13_historical_article_bytes() -> dict[str, bytes]:
    """Pre-batch13 bytes keyed by bare dossier filename."""
    return {
        f"{slug}.html": batch13_historical_post_text(slug).encode("utf-8")
        for slug in BATCH13_TARGET_SLUGS
    }


def batch13_page_preimage_rows() -> tuple[list[dict[str, str]], list[str]]:
    if not BATCH13_PAGE_PREIMAGE_PATH.exists():
        return [], [
            "batch13 page preimage manifest is missing: "
            f"{BATCH13_PAGE_PREIMAGE_RELATIVE}"
        ]
    payload = BATCH13_PAGE_PREIMAGE_PATH.read_bytes()
    issues: list[str] = []
    if sha256_bytes(payload) != BATCH13_PAGE_PREIMAGE_SHA256:
        issues.append("batch13 page preimage manifest bytes changed")
    with BATCH13_PAGE_PREIMAGE_PATH.open(encoding="utf-8", newline="") as handle:
        reader = csv.DictReader(handle, delimiter="\t")
        rows = list(reader)
        fields = tuple(reader.fieldnames or ())
    if fields != BATCH13_PAGE_PREIMAGE_COLUMNS:
        issues.append("batch13 page preimage columns or column order changed")
        return rows, issues
    return rows, issues


def batch13_page_preimage_issues(
    page_bytes_override: dict[str, bytes] | None = None,
) -> list[str]:
    """Prove the 49 recorded page transitions really are this repository's."""
    rows, issues = batch13_page_preimage_rows()
    if not rows:
        return issues
    if len(rows) != len(BATCH13_TARGET_SLUGS):
        issues.append(
            f"batch13 page preimage has {len(rows)} rows, expected "
            f"{len(BATCH13_TARGET_SLUGS)}"
        )
    recorded = [row.get("relative_path", "") for row in rows]
    if sorted(recorded) != sorted(
        f"posts/{slug}.html" for slug in BATCH13_TARGET_SLUGS
    ):
        issues.append("batch13 page preimage does not list the 49 revised dossiers")
        return issues
    revised_slugs = {
        row.get("slug", "") for row in batch13_reread_append()
    }
    if revised_slugs != BATCH13_TARGET_SLUG_SET:
        issues.append(
            "batch13 revised dossiers differ from the reread append: "
            f"{sorted(revised_slugs ^ BATCH13_TARGET_SLUG_SET)[:3]}"
        )
    for row in rows:
        relative = row.get("relative_path", "")
        slug = Path(relative).stem
        before = row.get("sha256_before", "")
        after = row.get("sha256_after", "")
        if not re.fullmatch(r"[0-9a-f]{64}", before) or not re.fullmatch(
            r"[0-9a-f]{64}", after
        ):
            issues.append(f"batch13 page preimage digest is invalid: {relative}")
            continue
        if before == after:
            issues.append(
                f"batch13 page preimage records no change for {relative}"
            )
        live = (page_bytes_override or {}).get(relative)
        if live is None:
            live = batch13_live_page_text(slug).encode("utf-8")
        if sha256_bytes(live) != after:
            issues.append(
                f"batch13 revised dossier no longer matches sha256_after: {relative}"
            )
        text, rewind_issues = batch13_preimage_text(
            slug, live_text=live.decode("utf-8")
        )
        issues.extend(rewind_issues)
        if sha256_bytes(text.encode("utf-8")) != before:
            issues.append(
                f"batch13 preimage does not reconstruct sha256_before: {relative}"
            )
    return issues


def batch13_target_node(
    soup: BeautifulSoup,
    language: str,
    target_id: str,
) -> Tag | None:
    body = body_for(soup, language)
    if body is None:
        return None
    matches = body.select(f'[data-fact-id="{target_id}"]')
    return matches[0] if len(matches) == 1 else None


def batch13_live_inventory(
    pages: dict[str, BeautifulSoup] | None = None,
    *,
    reread_rows: list[dict[str, str]] | None = None,
) -> dict[tuple[str, str, str], dict[str, str]]:
    """Visible text and source refs of every batch13 target, live and before."""
    append = batch13_reread_append(reread_rows)
    live_pages = pages or {}
    inventory: dict[tuple[str, str, str], dict[str, str]] = {}
    parsed_live: dict[str, BeautifulSoup] = {}
    parsed_pre: dict[str, BeautifulSoup] = {}
    for row in append:
        slug = row.get("slug", "")
        language = row.get("language", "")
        target_id = row.get("target_id", "")
        if slug not in parsed_live:
            soup = live_pages.get(slug)
            if soup is None:
                soup = BeautifulSoup(
                    batch13_live_page_text(slug), "html.parser"
                )
            parsed_live[slug] = soup
            parsed_pre[slug] = BeautifulSoup(
                batch13_historical_post_text(slug), "html.parser"
            )
        node = batch13_target_node(parsed_live[slug], language, target_id)
        previous = batch13_target_node(parsed_pre[slug], language, target_id)
        if node is None or previous is None:
            continue
        inventory[(slug, language, target_id)] = {
            "text": batch13_visible_text(node.get_text(" ", strip=True)),
            "previous": batch13_visible_text(previous.get_text(" ", strip=True)),
            "source_refs": node.get("data-source-ref", ""),
            "section": next(
                (
                    name
                    for name in BATCH13_SECTIONS
                    if target_id.endswith(f"-{name}")
                ),
                "",
            ),
        }
    return inventory


def batch13_subject_spans(text: str, language: str) -> list[tuple[int, int]]:
    """Every occurrence of a named authority in one visible paragraph."""
    folded = text.casefold()
    spans: list[tuple[int, int]] = []
    for subject in BATCH13_QUALIFIED_SUBJECTS[language]:
        needle = subject.casefold()
        start = folded.find(needle)
        while start >= 0:
            spans.append((start, start + len(needle)))
            start = folded.find(needle, start + 1)
    return spans


def batch13_contract_clauses(code: str) -> list[str]:
    """A required code may bundle clauses joined by a pipe separator."""
    return [
        batch13_visible_text(part).casefold()
        for part in code.split("|")
        if batch13_visible_text(part)
    ]


def batch13_contract_codes(value: str, role: str) -> tuple[str, ...]:
    return tuple(
        literal[len(role):]
        for literal in contract_literals(value)
        if literal.startswith(role)
    )


def batch13_ledger_issues(
    *,
    pages_override: dict[str, BeautifulSoup] | None = None,
    reread_rows_override: list[dict[str, str]] | None = None,
    contract_rows_override: list[dict[str, str]] | None = None,
    source_rows_override: list[dict[str, str]] | None = None,
) -> list[str]:
    """Authenticate the batch12 prefixes and exactly 446 linked batch13 rows."""
    issues: list[str] = []
    for path, count, digest, label in (
        (
            SEMANTIC_REREAD_PATH,
            BATCH13_REREAD_BASE_ROWS,
            BATCH13_REREAD_BASE_SHA256,
            "batch13 reread completed-batch12 prefix",
        ),
        (
            EDITORIAL_SEMANTIC_CONTRACT_PATH,
            BATCH13_CONTRACT_BASE_ROWS,
            BATCH13_CONTRACT_BASE_SHA256,
            "batch13 contract completed-batch12 prefix",
        ),
        (
            SOURCE_LEDGER_PATH,
            BATCH13_SOURCE_BASE_ROWS,
            BATCH13_SOURCE_BASE_SHA256,
            "batch13 source completed-batch12 prefix",
        ),
    ):
        issues.extend(
            exact_tsv_prefix_issues(
                path,
                base_rows=count,
                expected_sha256=digest,
                label=label,
            )
        )
    for path, digest, label in (
        (SEMANTIC_REREAD_PATH, BATCH13_REREAD_FULL_SHA256, "batch13 full reread ledger"),
        (
            EDITORIAL_SEMANTIC_CONTRACT_PATH,
            BATCH13_CONTRACT_FULL_SHA256,
            "batch13 full contract ledger",
        ),
        (SOURCE_LEDGER_PATH, BATCH13_SOURCE_FULL_SHA256, "batch13 full source ledger"),
    ):
        if not path.exists():
            issues.append(f"{label} bytes changed")
            continue
        payload = path.read_bytes()
        if path == SOURCE_LEDGER_PATH and sha256_bytes(payload) != digest:
            # Batch fourteen appends rows for its ten new dossiers after batch
            # thirteen's final state.  Replay this digest against that state's
            # prefix; anything else still fires.
            lines = payload.decode("utf-8").split("\n")
            payload = "\n".join(
                lines[:1 + BATCH13_SOURCE_ROWS]
            ).encode("utf-8") + b"\n"
        if sha256_bytes(payload) != digest:
            issues.append(f"{label} bytes changed")
    reread_rows = (
        reread_rows_override
        if reread_rows_override is not None
        else batch13_tsv_rows(SEMANTIC_REREAD_PATH)
    )
    contract_rows = (
        contract_rows_override
        if contract_rows_override is not None
        else batch13_tsv_rows(EDITORIAL_SEMANTIC_CONTRACT_PATH)
    )
    source_rows = (
        source_rows_override
        if source_rows_override is not None
        else batch13_tsv_rows(SOURCE_LEDGER_PATH)
    )
    # Batch fourteen appends 1,750 source-ledger rows for its ten new dossiers
    # after batch thirteen's 11,076-row final state.  Every batch13 assertion
    # below is replayed against that final state.  The appended rows must all
    # belong to a batch14 dossier, so the append cannot be used to slip a change
    # into a node batch thirteen froze.
    if len(source_rows) > BATCH13_SOURCE_ROWS:
        stray = sorted({
            row.get("slug", "")
            for row in source_rows[BATCH13_SOURCE_ROWS:]
            if row.get("slug", "") not in BATCH14_NEW_SLUG_SET
        })
        if stray:
            issues.append(
                "batch13 source ledger gained rows outside batch14: "
                + ", ".join(stray)
            )
        source_rows = source_rows[:BATCH13_SOURCE_ROWS]
    for rows, digest, label in (
        (reread_rows, BATCH13_REREAD_ROWS_SHA256, "reread"),
        (contract_rows, BATCH13_CONTRACT_ROWS_SHA256, "contract"),
        (source_rows, BATCH13_SOURCE_ROWS_SHA256, "source mapping"),
    ):
        fields = tuple(rows[0]) if rows else ()
        if (
            any(tuple(row) != fields for row in rows)
            or batch13_rows_signature_sha256(rows, fields) != digest
        ):
            issues.append(f"batch13 in-memory {label} ledger changed")
    for rows, expected, label in (
        (reread_rows, BATCH13_REREAD_ROWS, "reread"),
        (contract_rows, BATCH13_CONTRACT_ROWS, "contract"),
        (source_rows, BATCH13_SOURCE_ROWS, "source mapping"),
    ):
        if len(rows) != expected:
            issues.append(
                f"batch13 {label} total is {len(rows)}, expected {expected}"
            )
    reread = reread_rows[BATCH13_REREAD_BASE_ROWS:]
    contracts = contract_rows[BATCH13_CONTRACT_BASE_ROWS:]
    sources = source_rows[BATCH13_SOURCE_BASE_ROWS:]
    reread_keys = [
        (row.get("slug", ""), row.get("language", ""), row.get("target_id", ""))
        for row in reread
    ]
    contract_keys = [
        (row.get("slug", ""), row.get("language", ""), row.get("target_id", ""))
        for row in contracts
    ]
    source_keys = [
        (row.get("slug", ""), row.get("language", ""), row.get("fact_id", ""))
        for row in sources
    ]
    for label, keys in (
        ("reread", reread_keys),
        ("contract", contract_keys),
        ("source mapping", source_keys),
    ):
        if len(keys) != BATCH13_APPEND_ROWS:
            issues.append(
                f"batch13 {label} append has {len(keys)} rows, expected "
                f"{BATCH13_APPEND_ROWS}"
            )
        if len(set(keys)) != len(keys):
            issues.append(f"batch13 {label} append has duplicate target keys")
    if set(reread_keys) != set(contract_keys) or set(reread_keys) != set(source_keys):
        issues.append("batch13 reread, contract and source appends cover different nodes")
    predecessors: dict[tuple[str, str, str], dict[str, str]] = {}
    for row in reread_rows[:BATCH13_REREAD_BASE_ROWS]:
        predecessors[
            (row.get("slug", ""), row.get("language", ""), row.get("target_id", ""))
        ] = row
    inventory = batch13_live_inventory(
        pages_override, reread_rows=reread_rows
    )
    contract_by_key = {
        key: row for key, row in zip(contract_keys, contracts)
    }
    source_by_key = {key: row for key, row in zip(source_keys, sources)}
    contract_ids: set[str] = set()
    for key, row in zip(reread_keys, reread):
        slug, language, target_id = key
        label = "/".join(key)
        contract_id = row.get("contract_id", "")
        expected_prefix = (
            f"{BATCH13_CONTRACT_PREFIX}{slug}:{language}:fact:{target_id}:"
        )
        if not contract_id.startswith(expected_prefix) or contract_id in contract_ids:
            issues.append(
                f"batch13 reread contract ID missing/duplicated: {label}"
            )
        contract_ids.add(contract_id)
        original = batch13_visible_text(row.get("original_text", ""))
        revised = batch13_visible_text(row.get("revised_text", ""))
        if (
            row.get("target_kind", "") != "fact"
            or row.get("result", "") != "PASS_AFTER_REVISION"
            or original == revised
            or "reread:batch13" not in row.get("review_basis", "")
            or len(row.get("issue_found", "").strip()) < 40
            or len(row.get("review_basis", "").strip()) < 100
        ):
            issues.append(
                f"batch13 reread is not a genuine recorded revision: {label}"
            )
        live = inventory.get(key)
        if live is None:
            issues.append(f"batch13 reread target has no live DOM fact: {label}")
        else:
            if revised != live["text"]:
                issues.append(
                    f"batch13 reread revision differs from live visible text: {label}"
                )
            if original != live["previous"]:
                issues.append(
                    f"batch13 reread original differs from the authenticated "
                    f"preimage: {label}"
                )
            if row.get("source_refs", "") != live["source_refs"]:
                issues.append(
                    f"batch13 reread source refs differ from live DOM: {label}"
                )
            if live["section"] not in BATCH13_SECTIONS:
                issues.append(
                    f"batch13 revised a node outside the two audited columns: {label}"
                )
        previous = predecessors.get(key)
        if previous is None:
            issues.append(f"batch13 reread lacks an authenticated predecessor: {label}")
        elif batch13_visible_text(previous.get("revised_text", "")) != original:
            issues.append(f"batch13 reread predecessor chain is broken: {label}")

        contract_row = contract_by_key.get(key, {})
        if contract_row.get("contract_id", "") != contract_id or not contract_id:
            issues.append(f"batch13 contract/reread wiring differs: {label}")
        if contract_row.get("target_kind", "") != "fact":
            issues.append(f"batch13 contract target kind is not fact: {label}")
        required = batch13_contract_codes(
            contract_row.get("required_all", ""), "required:"
        )
        forbidden = batch13_contract_codes(
            contract_row.get("forbidden_any", ""), "old-error:"
        )
        if (
            len(required) < 3
            or len(contract_literals(contract_row.get("required_all", "")))
            != len(required)
            or len({code for code in required if code.strip()}) < 2
        ):
            issues.append(
                f"batch13 contract lacks three independent required codes: {label}"
            )
        if len(set(forbidden)) < 1 or len(
            contract_literals(contract_row.get("forbidden_any", ""))
        ) != len(forbidden):
            issues.append(f"batch13 contract lacks a real old error: {label}")
        summary = normalize_reread_text(contract_row.get("fact_summary", "")).casefold()
        if not all(
            marker in summary
            for marker in ("duty subject", "obligations", "source")
        ):
            issues.append(
                f"batch13 contract summary lacks duty subject/obligations/source: {label}"
            )
        if live is not None:
            visible = live["text"].casefold()
            previous_visible = live["previous"].casefold()
            subject_spans = batch13_subject_spans(live["text"], language)
            previous_spans = batch13_subject_spans(live["previous"], language)
            if not subject_spans:
                issues.append(
                    f"batch13 revision does not name a qualified authority: {label}"
                )
            elif len(subject_spans) <= len(previous_spans):
                issues.append(
                    f"batch13 revision did not add a qualified authority: {label}"
                )
            # Every non-empty required code must be visible.  A code may bundle
            # clauses joined by a pipe, and the ledger truncates long codes, so
            # each clause is checked on its own.
            for code in required:
                clauses = batch13_contract_clauses(code)
                if clauses and any(clause not in visible for clause in clauses):
                    issues.append(
                        f"batch13 contract required concept is not visible: {label}"
                    )
                    break
            for code in forbidden:
                folded = batch13_visible_text(code).casefold()
                if not folded:
                    issues.append(f"batch13 contract old error is empty: {label}")
                    break
                if folded not in previous_visible:
                    issues.append(
                        f"batch13 contract old error was never in the preimage: {label}"
                    )
                    break
                # The old bare subject may survive only inside the new named
                # authority (Korean 국가기관은 inside 중국 국가기관은); a standalone
                # occurrence is a real regression.
                start = visible.find(folded)
                standalone = False
                while start >= 0:
                    if not any(
                        start < end and begin < start + len(folded)
                        for begin, end in subject_spans
                    ):
                        standalone = True
                        break
                    start = visible.find(folded, start + 1)
                if standalone:
                    issues.append(
                        f"batch13 contract old error is still visible: {label}"
                    )
                    break

        source_row = source_by_key.get(key, {})
        section = source_row.get("section_id", "")
        snapshot_field = {
            "protection": "reread_protection_current",
            "rights-analysis": "reread_rights_current",
        }.get(section, "")
        if not snapshot_field or not target_id.endswith(f"-{section}"):
            issues.append(f"batch13 source row section is wrong: {label}")
        elif live is not None:
            if (
                source_row.get("current_visible_text", "") != row.get("revised_text", "")
                or source_row.get("reread_revision_text", "")
                != row.get("revised_text", "")
                or source_row.get("reread_result", "") != "PASS_AFTER_REVISION"
                or source_row.get("data_source_ref", "") != live["source_refs"]
                or not source_row.get("resolution_action", "").startswith(
                    "reread:batch13"
                )
            ):
                issues.append(
                    f"batch13 source audit is not wired to the live revision: {label}"
                )
            if batch13_visible_text(source_row.get(snapshot_field, "")) != original:
                issues.append(
                    f"batch13 source snapshot is not the authenticated preimage: {label}"
                )
            anchor = batch13_visible_text(
                source_row.get("visible_subject_anchor", "")
            )
            if anchor and (
                anchor.casefold() not in live["text"].casefold()
                or not any(
                    anchor.casefold() == subject.casefold()
                    for subject in BATCH13_QUALIFIED_SUBJECTS[language]
                )
            ):
                issues.append(
                    f"batch13 source subject anchor is not a visible named "
                    f"authority: {label}"
                )
            if not source_row.get("reread_issue_found", "").strip():
                issues.append(f"batch13 source audit lacks reread_issue_found: {label}")
    return issues


def batch13_section_text(body: Tag, section: str) -> str:
    """Every visible string under one h2 column, not only its main paragraph."""
    parts: list[str] = []
    for heading in body.select(f'h2[data-section="{section}"]'):
        for sibling in heading.next_siblings:
            if isinstance(sibling, Tag):
                if sibling.name == "h2":
                    break
                parts.append(sibling.get_text(" ", strip=True))
    return " ".join(parts)


def batch13_unqualified_duty_spans(
    text: str,
    language: str,
) -> list[tuple[int, int]]:
    pattern = BATCH13_DUTY_SUBJECT_PATTERNS[language]
    allowed: list[tuple[int, int]] = []
    for phrase in BATCH13_DUTY_SUBJECT_ALLOWED.get(language, ()):
        start = text.find(phrase)
        while start >= 0:
            allowed.append((start, start + len(phrase)))
            start = text.find(phrase, start + 1)
    spans: list[tuple[int, int]] = []
    for match in pattern.finditer(text):
        if any(
            match.start() < end and start < match.end()
            for start, end in allowed
        ):
            continue
        spans.append((match.start(), match.end()))
    return spans


def batch13_duty_subject_issues(soup: BeautifulSoup, slug: str) -> list[str]:
    """No sentence in either audited column may put a duty on a bare state."""
    issues: list[str] = []
    for language in LANGS:
        body = body_for(soup, language)
        if body is None:
            issues.append(f"{language}: batch13 duty-subject body is missing")
            continue
        for section in BATCH13_SECTIONS:
            headings = body.select(f'h2[data-section="{section}"]')
            if not headings:
                issues.append(
                    f"{language}: batch13 duty-subject column {section} is missing"
                )
                continue
            text = batch13_section_text(body, section)
            for start, end in batch13_unqualified_duty_spans(text, language):
                issues.append(
                    f"{language}: {section} states a duty on an unqualified "
                    f"state subject: {text[max(0, start - 20):end + 20]!r}"
                )
    return issues


def batch13_duty_subject_statistics() -> dict[str, int]:
    dossiers = 0
    violations = 0
    for path in FILES:
        dossiers += 1
        soup = BeautifulSoup(path.read_text(encoding="utf-8"), "html.parser")
        violations += len(batch13_duty_subject_issues(soup, path.stem))
    return {
        "dossiers": dossiers,
        "languages": len(LANGS),
        "violations": violations,
        "qualified_nodes": BATCH13_APPEND_ROWS,
        "qualified_dossiers": len(BATCH13_TARGET_SLUGS),
    }


def batch13_freeze_issues(
    overrides: dict[str, bytes | str] | None = None,
) -> list[str]:
    """Recomputed 312-path freeze: everything batch13 did not legitimately touch."""
    optional_paths = set(BATCH13_OPTIONAL_AUTHENTICATED_FILES)
    paths = sorted(
        path.relative_to(ROOT).as_posix()
        for path in ROOT.rglob("*")
        if path.is_file()
        and ".git" not in path.relative_to(ROOT).parts
        and path.name != ".DS_Store"
        and path.relative_to(ROOT).as_posix() not in BATCH13_MUTABLE_FILES
        and path.relative_to(ROOT).as_posix() not in optional_paths
        and not fnmatch.fnmatch(
            path.relative_to(ROOT).as_posix(),
            "tools/data/batch13-*.tsv",
        )
        # A dossier or audit file first written in batch fourteen did not exist
        # when this freeze was captured, so it cannot belong to its path set.
        # batch14_release_issues and batch14_preimage_issues account for them.
        and path.relative_to(ROOT).as_posix() not in BATCH14_NEW_AUDIT_FILES
        and not fnmatch.fnmatch(
            path.relative_to(ROOT).as_posix(),
            "tools/data/batch14-*.tsv",
        )
    )
    issues: list[str] = []
    records: list[str] = []
    for relative in paths:
        value = (overrides or {}).get(relative)
        if isinstance(value, str):
            payload = value.encode("utf-8")
        elif isinstance(value, bytes):
            payload = value
        else:
            # batch13's rewind already runs on the batch14 preimage, so
            # prefer it; batch14's own preimage covers the files batch13
            # never touched.  Both leave the pre-batch-14 bytes here.
            payload = (
                batch13_historical_page_bytes().get(relative)
                or batch14_historical_page_bytes().get(relative)
                or (ROOT / relative).read_bytes()
            )
        records.append(f"{relative}\t{sha256_bytes(payload)}\n")
    if len(paths) != BATCH13_PROTECTED_FILES:
        issues.append(
            f"batch13 protected path count is {len(paths)}, expected "
            f"{BATCH13_PROTECTED_FILES}"
        )
    if sha256_bytes("".join(records).encode("utf-8")) != BATCH13_PROTECTED_SHA256:
        issues.append("batch13 changed a protected file")
    for relative in sorted(BATCH13_NEW_AUDIT_FILES):
        if not (ROOT / relative).is_file():
            issues.append(f"batch13 required ledger is missing: {relative}")
    extras = (
        set(overrides or {})
        - set(paths)
        - BATCH13_MUTABLE_FILES
        - optional_paths
    )
    if any(
        not fnmatch.fnmatch(value, "tools/data/batch13-*.tsv") for value in extras
    ):
        issues.append("batch13 freeze override added an unknown path")
    return issues


def batch13_wiring_issues(source_override: str | None = None) -> list[str]:
    """The batch13 gates must stay wired into the default release path."""
    source = source_override or Path(__file__).read_text(encoding="utf-8")
    try:
        tree = ast.parse(source)
    except SyntaxError as exc:
        return [f"batch13 checker wiring is not parseable: {exc}"]
    functions = {
        node.name: node
        for node in tree.body
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
    }

    def called(function_name: str, callee: str) -> bool:
        function = functions.get(function_name)
        return bool(function) and any(
            isinstance(node, ast.Call)
            and isinstance(node.func, ast.Name)
            and node.func.id == callee
            for node in ast.walk(function)
        )

    issues: list[str] = []
    if not called("validate_paths", "batch13_release_issues"):
        issues.append("validate_paths no longer forces the batch13 release gate")
    if not called("validate_paths", "batch13_duty_subject_issues"):
        issues.append("validate_paths no longer runs the duty-subject gate")
    for callee in (
        "batch13_ledger_issues",
        "batch13_page_preimage_issues",
        "batch13_freeze_issues",
        "batch13_wiring_issues",
    ):
        if not called("batch13_release_issues", callee):
            issues.append(f"batch13 release no longer calls {callee}")
    if not called("self_tests", "batch13_named_negative_tests"):
        issues.append("self_tests no longer runs batch13 mutations")
    if not called("case_semantic_contract_issues", "batch13_rewind_page"):
        issues.append("case route no longer rewinds the batch13 successor")
    if not called("batch13_historical_post_text", "batch13_preimage_text"):
        issues.append("batch13 historical projection no longer rebuilds the preimage")
    return issues


def batch13_rewind_page(
    soup: BeautifulSoup,
    slug: str,
) -> tuple[BeautifulSoup, list[str]]:
    """Return the completed-batch12 DOM of one revised dossier."""
    text, issues = batch13_preimage_text(slug, live_text=str(soup))
    return BeautifulSoup(text, "html.parser"), issues


def batch13_release_issues(
    *,
    page_bytes_override: dict[str, bytes] | None = None,
    reread_rows_override: list[dict[str, str]] | None = None,
    contract_rows_override: list[dict[str, str]] | None = None,
    source_rows_override: list[dict[str, str]] | None = None,
    freeze_overrides: dict[str, bytes | str] | None = None,
    checker_source_override: str | None = None,
) -> list[str]:
    issues: list[str] = []
    for slug in BATCH13_TARGET_SLUGS:
        batch13_historical_post_text(slug)
        issues.extend(_BATCH13_PREIMAGE_ISSUE_CACHE.get(slug, []))
    issues.extend(batch13_page_preimage_issues(page_bytes_override))
    issues.extend(
        batch13_ledger_issues(
            reread_rows_override=reread_rows_override,
            contract_rows_override=contract_rows_override,
            source_rows_override=source_rows_override,
        )
    )
    issues.extend(batch13_freeze_issues(freeze_overrides))
    issues.extend(batch13_wiring_issues(checker_source_override))
    return issues


def batch14_named_negative_tests() -> list[tuple[str, bool]]:
    """Real mutations of every batch-14 gate, plus two must-not-fire reverse tests.

    Each case mutates live text or a manifest row in memory and asserts the new
    gate reports it.  A gate that cannot be made to fire is not a gate.
    """
    checks: list[tuple[str, bool]] = []
    script = (ROOT / "script.js").read_text(encoding="utf-8")
    sample = f"posts/{BATCH14_NEW_SLUGS[0]}.html"

    # -- the decorative timeline class must never come back -------------------
    def carries_stray_class(markup: str) -> bool:
        return 'class="timeline timeline-list"' in markup

    live = (ROOT / sample).read_text(encoding="utf-8")
    checks.append((
        "01 batch14 dossier still free of the decorative timeline class",
        not carries_stray_class(live),
    ))
    checks.append((
        "02 batch14 decorative timeline class would be detected if reintroduced",
        carries_stray_class(
            live.replace('class="timeline-list"', 'class="timeline timeline-list"', 1)
        ),
    ))

    # -- the ten cards must stay one ordered block ----------------------------
    cards, _ = extract_report_cards(script)
    checks.append((
        "03 batch14 card block is where the offset expects it",
        not batch14_card_head_issues(text_override=script),
    ))
    moved = script.replace(
        f'url: "posts/{BATCH14_NEW_SLUGS[0]}.html"',
        f'url: "posts/{BATCH14_NEW_SLUGS[0]}-moved.html"',
        1,
    )
    checks.append((
        "04 batch14 card block detects a reordered or renamed card",
        any(
            "batch14 cards are not a contiguous ordered block" in issue
            for issue in batch14_card_head_issues(text_override=moved)
        ),
    ))

    # -- the preimage must actually reconstruct -------------------------------
    checks.append((
        "05 batch14 preimage reconstructs every captured digest",
        not batch14_preimage_issues(),
    ))
    payloads = batch14_historical_page_bytes()
    with BATCH14_PAGE_PREIMAGE_PATH.open(encoding="utf-8", newline="") as handle:
        manifest_paths = [
            row["relative_path"] for row in csv.DictReader(handle, delimiter="\t")
        ]
    checks.append((
        "06 batch14 preimage covers every file its manifest claims",
        len(manifest_paths) == BATCH14_PAGE_PREIMAGE_ROWS
        and all(relative in payloads for relative in manifest_paths)
        # plus the appended source-date ledger, whose preimage is its
        # authenticated 294-row prefix rather than a manifest row
        and SOURCE_DATE_LEDGER_RELATIVE in payloads,
    ))
    tampered = batch14_preimage_text(
        "style.css",
        (ROOT / "style.css").read_text(encoding="utf-8") + "\n/* stray rule */\n",
        "",
        False,
    )
    checks.append((
        "07 batch14 preimage rejects a style.css edit outside the header rule",
        sha256_bytes(tampered.encode("utf-8")) != sha256_bytes(
            batch14_historical_page_bytes().get("style.css", b"")
        ),
    ))

    # -- the baseline card view must not hide a missing dossier ---------------
    view = batch14_baseline_card_view(cards)
    checks.append((
        "08 batch14 baseline card view restores exactly the 54-card sequence",
        len(view) == POST_BATCH9_BASELINE_FILES
        and not (
            {card.get("slug", "") for card in view} & BATCH14_NEW_SLUG_SET
        ),
    ))
    dropped = [
        card for card in cards
        if card.get("slug", "") != BATCH14_NEW_SLUGS[3]
    ]
    checks.append((
        "09 batch14 baseline card view still shrinks when a batch14 card vanishes",
        len(batch14_baseline_card_view(dropped)) == POST_BATCH9_BASELINE_FILES
        and any(
            "batch14 cards are not a contiguous ordered block" in issue
            for issue in batch14_card_head_issues(
                text_override=script.replace(
                    f'url: "posts/{BATCH14_NEW_SLUGS[3]}.html"',
                    'url: "posts/not-a-batch14-card.html"',
                    1,
                )
            )
        ),
    ))

    # -- the batch11 protected-card digest, repaired in this batch ------------
    # It had been reporting a change since batch twelve rebuilt five cards
    # without extending it.  The repair replays the digest against the state it
    # was captured from, so it must now be clean AND must still fire on a real
    # edit to any of the 1,162 fields it protects.
    checks.append((
        "12 batch11 protected-card digest is clean after the batch12 replay",
        not any(
            "non-authorized report-card field" in issue
            for issue in batch11_card_issues(script_override=script)
        ),
    ))
    field_match = re.search(r'(title_zh: ")([^"]{10,60})', script)
    tampered = (
        script[:field_match.start(2)] + "TAMPERED" + script[field_match.end(2):]
        if field_match else script
    )
    checks.append((
        "13 batch11 protected-card digest still fires on a protected-field edit",
        any(
            "non-authorized report-card field" in issue
            for issue in batch11_card_issues(script_override=tampered)
        ),
    ))
    replayed = batch11_predecessor_cards(batch14_baseline_card_view(cards))
    live_by_slug = {c.get("slug", ""): c for c in batch14_baseline_card_view(cards)}
    rewound = {
        c.get("slug", "") for c in replayed
        if any(
            c.get(f, "") != live_by_slug[c.get("slug", "")].get(f, "")
            for f in REPORT_CARD_FIELDS
        )
    }
    checks.append((
        "14 batch11 replay rewinds only the five batch12 card slugs",
        bool(rewound) and rewound <= set(BATCH12_CARD_SLUGS),
    ))

    # -- the release gate must notice a missing dossier or contract -----------
    release = batch14_release_issues()
    checks.append((
        "10 batch14 release gate is clean on the live tree",
        not release,
    ))
    contracts = load_dynamic_timeline_contracts()
    thinned = {
        key: row for key, row in contracts.items()
        if not (key[0] == BATCH14_NEW_SLUGS[5] and key[1] == "de")
    }
    checks.append((
        "11 batch14 timeline contract loss is intercepted",
        any(
            "lacks a reviewed dynamic visible-timeline contract" in issue
            for issue in dynamic_timeline_contract_issues(
                BeautifulSoup(
                    (ROOT / f"posts/{BATCH14_NEW_SLUGS[5]}.html").read_text(
                        encoding="utf-8"
                    ),
                    "html.parser",
                ),
                POSTS / f"{BATCH14_NEW_SLUGS[5]}.html",
                contracts=thinned,
            )
        ),
    ))
    return checks


def batch13_named_negative_tests() -> list[tuple[str, bool]]:
    """Nine named real mutations, including one must-not-fire reverse test."""
    checks: list[tuple[str, bool]] = []
    reread = batch13_tsv_rows(SEMANTIC_REREAD_PATH)
    contracts = batch13_tsv_rows(EDITORIAL_SEMANTIC_CONTRACT_PATH)
    sources = batch13_tsv_rows(SOURCE_LEDGER_PATH)

    def reported(marker: str, **overrides) -> bool:
        return any(
            marker in issue for issue in batch13_ledger_issues(**overrides)
        )

    checks.append((
        "01 batch13 reread append loses one of its 446 rows",
        reported("append has 445 rows", reread_rows_override=reread[:-1]),
    ))

    mismatched = copy.deepcopy(reread)
    mismatched[-1]["revised_text"] = (
        mismatched[-1]["revised_text"] + " 未經覆核的補充句。"
    )
    checks.append((
        "02 batch13 revised_text no longer matches the live DOM",
        reported(
            "revision differs from live visible text",
            reread_rows_override=mismatched,
        ),
    ))

    downgraded = copy.deepcopy(reread)
    downgraded[-1]["result"] = "PASS_NO_CHANGE"
    checks.append((
        "03 batch13 reread result is not PASS_AFTER_REVISION",
        reported(
            "is not a genuine recorded revision",
            reread_rows_override=downgraded,
        ),
    ))

    fabricated = copy.deepcopy(reread)
    fabricated[-1]["original_text"] = fabricated[-1]["revised_text"]
    checks.append((
        "04 batch13 row fakes a no-op revision",
        reported(
            "original differs from the authenticated preimage",
            reread_rows_override=fabricated,
        )
        and reported(
            "is not a genuine recorded revision",
            reread_rows_override=fabricated,
        ),
    ))

    tampered_rows = copy.deepcopy(reread)
    tampered_rows[10]["revised_text"] = (
        tampered_rows[10]["revised_text"] + " tampered"
    )
    lines = SEMANTIC_REREAD_PATH.read_bytes().splitlines(keepends=True)
    lines[11] = lines[11].rstrip(b"\n") + b" \n"
    scratch = Path(tempfile.mkdtemp(prefix="batch13-prefix-")) / "reread.tsv"
    scratch.write_bytes(b"".join(lines))
    prefix_caught = bool(
        exact_tsv_prefix_issues(
            scratch,
            base_rows=BATCH13_REREAD_BASE_ROWS,
            expected_sha256=BATCH13_REREAD_BASE_SHA256,
            label="batch13 reread completed-batch12 prefix",
        )
    )
    scratch.unlink()
    scratch.parent.rmdir()
    checks.append((
        "05 batch13 authenticated pre-16563 history is rewritten",
        prefix_caught
        and reported(
            "in-memory reread ledger changed",
            reread_rows_override=tampered_rows,
        ),
    ))

    protection_soup = BeautifulSoup(
        batch13_live_page_text("2024-report"), "html.parser"
    )
    node = batch13_target_node(protection_soup, "zh", "2024-report-protection")
    node.append(NavigableString("國家必須立即公開全部記錄。"))
    checks.append((
        "06 protection column reintroduces 國家必須",
        any(
            "unqualified state subject" in issue
            for issue in batch13_duty_subject_issues(protection_soup, "2024-report")
        ),
    ))

    english_soup = BeautifulSoup(
        batch13_live_page_text("2024-report"), "html.parser"
    )
    english_node = batch13_target_node(
        english_soup, "en", "2024-report-rights-analysis"
    )
    english_node.append(
        NavigableString(" The state must publish every enforcement record.")
    )
    checks.append((
        "07 rights-analysis column reintroduces The state must",
        any(
            "unqualified state subject" in issue
            for issue in batch13_duty_subject_issues(english_soup, "2024-report")
        ),
    ))

    legitimate_soup = BeautifulSoup(
        batch13_live_page_text("2024-report"), "html.parser"
    )
    legitimate_node = batch13_target_node(
        legitimate_soup, "zh", "2024-report-protection"
    )
    legitimate_node.append(
        NavigableString("民主國家、聯合國機制及專業團體應協助保存證據。民主國家應公開其審查結論。")
    )
    checks.append((
        "08 reverse test: 民主國家...應 must not be reported",
        not batch13_duty_subject_issues(legitimate_soup, "2024-report"),
    ))

    unwired = Path(__file__).read_text(encoding="utf-8").replace(
        "issues.extend(batch13_release_issues())", "issues.extend([])", 1
    )
    unwired_duty = Path(__file__).read_text(encoding="utf-8").replace(
        "for issue in batch13_duty_subject_issues(soup, path.stem)",
        "for issue in []",
        1,
    )
    checks.append((
        "09 batch13 gate is unwired from the release path",
        bool(batch13_wiring_issues(unwired))
        and bool(batch13_wiring_issues(unwired_duty)),
    ))
    return checks


def main() -> int:
    parser = argparse.ArgumentParser(description="Validate all visible multilingual dossier columns.")
    parser.add_argument("--matrix", action="store_true", help="print the 54×10 section/critical-paragraph matrix")
    parser.add_argument("--self-test", action="store_true", help="exercise visible-node negative tests")
    parser.add_argument("--release", action="store_true", help="audit the complete public release surface")
    args = parser.parse_args()
    issues = validate_paths()
    if args.release:
        if not SOURCE_LEDGER_PATH.exists():
            issues.append(f"source ledger missing: {SOURCE_LEDGER_PATH}")
        issues.extend(release_surface_issues())
    if args.matrix:
        report_matrix()
    passed = total = 0
    if args.self_test:
        passed, total = self_tests()
        print(f"Real cross-page and critical-column negative tests: {passed}/{total} intercepted")
        if passed != total:
            issues.append(f"self-test: only {passed}/{total} mutations were intercepted")
    stats = release_statistics()
    editorial_rows, _editorial_row_issues = load_editorial_semantic_contracts()
    reread_rows, _reread_row_issues = load_semantic_reread_rows()
    reread_revisions = sum(row.get("result") == "PASS_AFTER_REVISION" for row in reread_rows)
    all_reread_groups = semantic_reread_groups(reread_rows)
    all_reread_predecessors = {
        id(later): earlier
        for chain in all_reread_groups.values()
        for earlier, later in zip(chain, chain[1:])
    }
    reread_source_only = sum(
        row.get("result") == "PASS_AFTER_REVISION"
        and normalize_reread_text(row.get("original_text", ""))
        == normalize_reread_text(row.get("revised_text", ""))
        and source_ref_only_revision(all_reread_predecessors.get(id(row)), row)
        for row in reread_rows
    )
    reread_text_revisions = reread_revisions - reread_source_only
    batch10_rows = reread_rows[SEMANTIC_REREAD_FINAL2_ROWS:SEMANTIC_REREAD_BATCH10_ROWS]
    batch10_groups = semantic_reread_groups(reread_rows[:SEMANTIC_REREAD_BATCH10_ROWS])
    batch10_predecessors = {
        id(later): earlier
        for chain in batch10_groups.values()
        for earlier, later in zip(chain, chain[1:])
    }
    batch10_visible = sum(
        row.get("result") == "PASS_AFTER_REVISION"
        and normalize_reread_text(row.get("original_text", ""))
        != normalize_reread_text(row.get("revised_text", ""))
        for row in batch10_rows
    )
    batch10_continuous_sources = sum(
        row.get("result") == "PASS_AFTER_REVISION"
        and normalize_reread_text(row.get("original_text", ""))
        == normalize_reread_text(row.get("revised_text", ""))
        and batch10_predecessors.get(id(row)) is not None
        and source_ref_only_revision(batch10_predecessors[id(row)], row)
        for row in batch10_rows
    )
    batch10_snapshot_sources = sum(
        row.get("result") == "PASS_AFTER_REVISION"
        and normalize_reread_text(row.get("original_text", ""))
        == normalize_reread_text(row.get("revised_text", ""))
        and batch10_predecessors.get(id(row)) is None
        and source_ref_only_revision(None, row)
        for row in batch10_rows
    )
    batch10_no_change = sum(row.get("result") == "PASS_NO_CHANGE" for row in batch10_rows)
    batch10_final1_rows = reread_rows[
        SEMANTIC_REREAD_BATCH10_ROWS:BATCH10_FINAL1_REREAD_ROWS
    ]
    batch10_final1_tombstones = sum(final1_source_removal(row) for row in batch10_final1_rows)
    batch10_final1_text = sum(
        not final1_source_removal(row)
        and normalize_reread_text(row.get("original_text", ""))
        != normalize_reread_text(row.get("revised_text", ""))
        for row in batch10_final1_rows
    )
    batch10_final1_sources = sum(
        not final1_source_removal(row)
        and normalize_reread_text(row.get("original_text", ""))
        == normalize_reread_text(row.get("revised_text", ""))
        for row in batch10_final1_rows
    )
    final1_history = semantic_reread_groups(reread_rows[:SEMANTIC_REREAD_BATCH10_ROWS])
    batch10_final1_continuous = sum(
        (row.get("slug", ""), row.get("language", ""), row.get("target_id", ""))
        in final1_history
        for row in batch10_final1_rows
    )
    batch10_final1_preimage = len(batch10_final1_rows) - batch10_final1_continuous
    batch10_final2_rows = reread_rows[
        BATCH10_FINAL1_REREAD_ROWS:BATCH10_FINAL2_REREAD_ROWS
    ]
    batch10_final2_relation = sum(
        row.get("target_kind", "") == "fact-attribute"
        or normalize_reread_text(row.get("original_text", ""))
        == normalize_reread_text(row.get("revised_text", ""))
        for row in batch10_final2_rows
    )
    batch10_final2_text = len(batch10_final2_rows) - batch10_final2_relation
    batch10_final3_rows = reread_rows[BATCH10_FINAL2_REREAD_ROWS:BATCH11_REREAD_BASE_ROWS]
    batch9_live, _batch9_live_issues = batch9_live_target_map()
    reread_groups = semantic_reread_groups(reread_rows)
    batch9_matching_tips = sum(
        key in reread_groups
        and reread_groups[key][-1].get("target_kind", "") == value["target_kind"]
        and reread_groups[key][-1].get("source_refs", "") == value["source_refs"]
        and normalize_reread_text(reread_groups[key][-1].get("revised_text", "")) == value["text"]
        for key, value in batch9_live.items()
    )
    card_rows, _card_row_issues = load_batch10_card_rows(BATCH10_CARD_DELTA_PATH)
    target_card_changes = sum(
        row.get("scope") == "target" and row.get("changed") == "YES"
        for row in card_rows
    )
    non_target_card_changes = sum(
        row.get("scope") == "non-target" and row.get("changed") == "YES"
        for row in card_rows
    )
    print(f"Articles/languages: {len(FILES)} × {len(LANGS)}")
    print(
        "Integrity contract: 54 article byte snapshots plus reviewed DOM order, "
        "source relationships, and visible timeline anchors."
    )
    print(
        f"Editorial semantic contract: {len(editorial_rows)} independently authored target-language rows; "
        f"semantic reread ledger: {len(reread_rows)} rows, {reread_text_revisions} text revisions, "
        f"{reread_source_only} source-reference-only expansions."
    )
    print(
        "Batch-ten honest classification: "
        f"{batch10_visible} visible-text revisions; {batch10_continuous_sources} continuous/recomputable "
        f"source-relation revisions; {batch10_snapshot_sources} pre-snapshot/current-state-only "
        f"source-relation records; {batch10_no_change} no-change records."
    )
    print(
        "Batch-ten final1 authenticated append: "
        f"{len(batch10_final1_rows)} records = {batch10_final1_text} live-DOM text revisions + "
        f"{batch10_final1_tombstones} deleted-source tombstones + {batch10_final1_sources} "
        f"source-relation-only revisions; predecessors={batch10_final1_continuous}, "
        f"snapshot-backed article-meta={batch10_final1_preimage}; 0 fabricated no-change rows."
    )
    print(
        "Batch-ten final2 append: "
        f"{len(batch10_final2_rows)} records = {batch10_final2_text} text revisions + "
        f"{batch10_final2_relation} attribute/source-relation revisions; 0 no-change rows."
    )
    print(
        "Batch-ten final3 authenticated append: "
        f"{len(batch10_final3_rows)} genuine DOM/source-title revisions; 0 no-change rows."
    )
    print(
        f"Batch-nine live DOM reread coverage: {batch9_matching_tips}/{len(batch9_live)} "
        f"latest chain tips match ({BATCH9_LIVE_TARGETS} required)."
    )
    print(
        f"Batch-ten live card delta: {POST_BATCH9_BASELINE_FILES} × {len(REPORT_CARD_FIELDS)} fields; "
        f"target-field changes={target_card_changes}; non-target-field changes={non_target_card_changes}."
    )
    print(f"Human-rights main paragraphs: {stats['rights']}; protection main paragraphs: {stats['protection']}; additional critical nodes: {stats['extra']}")
    print(f"Rights fully contained in protection: {stats['contains']}; same-page sentence overlap above 25%: {stats['overlap']}")
    print(f"Cross-case repeated CJK long sentences: {stats['duplicate_cjk']}; other-language long sentences: {stats['duplicate_other']}")
    print(f"European lowercase/residual openings: {stats['lowercase']}; abnormally long critical paragraphs: {stats['overlong']}")
    print(f"Disclaimers or applicant-guide wording in critical columns: {stats['banned']}")
    print(f"Article title/deck English fallbacks: {stats['title_fallback']}; Zhang Zhan Korean wrong-gender pronouns: {stats['zhang_gender']}")
    print(f"Japanese state-to-州 errors: {stats['state_shu']}; public visible-text editorial directives: {stats['directives']}")
    print("Public pages/languages: 6 × 10; required source categories: 12; retained external URLs: 16")
    print("Protest archive: 8 events; 254 image files; dynamic title/place/alt/aria language sets: 10")
    date_stats = source_date_audit_statistics()
    print(
        "Source-date DOM audit: "
        f"unique={date_stats['unique_sources']}; blank/UNDATED={date_stats['blank_dates']}; "
        f"attr-visible conflicts={date_stats['attr_visible_conflicts']}; "
        f"datetime-visible conflicts={date_stats['datetime_visible_conflicts']}; "
        f"ten-language inconsistencies={date_stats['cross_language_inconsistencies']}; "
        f"suspicious YYYY-01-01={date_stats['suspicious_01_01']}; "
        f"manual-review rows={date_stats['manual']}"
    )
    if args.release:
        release = release_surface_statistics()
        print(
            "Release surface: "
            f"{release['html']} public HTML files; {release['local_references']} local href/src references; "
            f"{release['anchors']} internal anchors; {release['images']} image elements; "
            f"{release['controls']} form controls"
        )
        print(
            f"Sitemap: {release['sitemap_urls']} canonical URLs including "
            f"{release['formal_posts']} formal articles"
        )
    if issues:
        print("Language check failed:", file=sys.stderr)
        for issue in issues:
            print(f"- {issue}", file=sys.stderr)
        return 1
    print("Language check passed.")
    print("Seven core sections, source metadata, and localized cards: consistent.")
    browser = batch12_browser_statistics()
    print(
        "Batch-twelve browser acceptance: "
        f"{browser['units']} units = {browser['pages']} pages × "
        f"{browser['languages']} languages × {browser['viewports']} "
        f"viewports; {browser['console_errors']} console errors; "
        f"{browser['overflow']} overflow; {browser['real_navigation']} "
        f"real-navigation reloads; {browser['fixes']} repaired defects; "
        f"{browser['observations']} recorded observations."
    )
    duty = batch13_duty_subject_statistics()
    print(
        "Duty subject: "
        f"{duty['dossiers']} dossiers × {duty['languages']} languages; "
        f"{duty['violations']} unqualified state duty subjects; "
        f"{duty['qualified_nodes']} batch-13 qualified nodes across "
        f"{duty['qualified_dossiers']} dossiers."
    )
    shell = article_shell_statistics()
    print(
        "Article shell: "
        f"{shell['pages']} dossiers × {shell['bodies'] // shell['pages']} "
        "language bodies under one shared parent; 0 loose <article> children; "
        f"0 section-less visible headings; {shell['grids']} .fact-grid blocks "
        f"holding {shell['cards']} .fact-card statistics; "
        f"{shell['phrases']} ten-language page-instruction patterns absent."
    )
    if args.self_test:
        print("All required real cross-page negative mutations were intercepted.")
    if args.release:
        print("Release surface, publication configuration, 404, robots, and sitemap checks passed.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
